(function(root){'use strict';root.INSPECTION_LAW_FULLTEXT=Object.freeze({"provenance":"PP-IA-41-7F3C9A21","version":"moj-official-snapshot-20260923044317","verifiedAt":"2026-09-23","sourcePolicy":"中央法規全文、法規名稱與修正日期一律由 law.moj.gov.tw 全國法規資料庫官方 API 直接取得；發布版本內建條文快照。附件僅在官方下載成功且驗證非錯誤頁時離線收錄，其餘保留官方連結。","officialApi":["https://law.moj.gov.tw/api/ch/law/json","https://law.moj.gov.tw/api/ch/order/json"],"lawUpdateDate":"2026/9/11 上午 12:00:00","orderUpdateDate":"2026/9/11 上午 12:00:00","entries":{"water-act":{"id":"water-act","pcode":"O0040001","name":"水污染防治法","foreword":"","histories":"1.中華民國六十三年七月十一日總統（63）台統（一）義字第 3040 號令\r\n  制定公布全文 28 條\r\n2.中華民國七十二年五月二十七日總統令修正公布\r\n3.中華民國八十年五月六日總統（80）華總（一）義字第 2238 號令修正\r\n  公布全文 63 條\r\n4.中華民國八十九年四月二十六日總統（89）華總一義字第 8900105230\r\n  號令修正公布第 3、4、6、7、9、13～15、27、29、30、35、56  條條\r\n  文\r\n5.中華民國九十一年五月二十二日總統（91）華總一義字第 09100098990\r\n  號令修正公布全文 75 條；並自公布日施行\r\n6.中華民國九十六年十二月十二日總統華總一義字第 09600168231  號令\r\n  修正公布第 40、44～46、48、56 條條文；並增訂第 66-1 條條文 \r\n7.中華民國一百零四年二月四日總統華總一義字第 10400014261  號令修\r\n  正公布第 2、10、11、14、15、20、22、27、28、31、34～37、39、40\r\n  、41、43～46、47～57、63、69、71、73  條條文；增訂第 14-1、\r\n  18-1、39-1、46-1、63-1、66-2～66-4、71-1  條條文；並刪除第 38\r\n  、65  條條文\r\n8.中華民國一百零五年十二月七日總統華總一義字第 10500150291  號令\r\n  修正公布第 39 條條文\r\n9.中華民國一百零七年六月十三日總統華總一義字第 10700062361  號令\r\n  修正公布第 11、32、36、44、53 條條文；並增訂第 57-1 條條文\r\n  中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公告\r\n  第 2  條第 7  款、第 11 款、第 16 款、第 17 款、第 3  條、第 4\r\n  條、第 6  條、第 7  條第 2  項、第 9  條第 1  項第 2  款、第 2\r\n  項、第 10 條第 1  項、第 3  項、第 4  項、第 11 條第 1  項、第\r\n  5 項、第 6  項、第 8  項、第 10 項、第 12 條第 2  項、第 13 條\r\n  、第 14 條第 2  項、第 3  項、第 14-1 條第 1  項、第 2  項、第\r\n  4 項、第 16 條、第 17 條第 4  項、第 18 條、第 18-1 條第 3  項\r\n  、第 20 條第 2  項、第 3  項、第 21 條第 2  項、第 22 條、第 \r\n  23  條、第 25 條第 2  項、第 3  項、第 26 條第 1  項序文、第 2\r\n  項、第 4  項、第 27 條第 2  項、第 3  項、第 4  項、第 28 條第\r\n  2 項、第 29 條、第 30 條第 1  項第 1  款、第 4  款、第 5  款、\r\n  第 2  項、第 31 條第 2  項、第 32 條第 1  項、第 3  項、第 4  \r\n  項、第 33 條、第 34 條、第 36 條第 4  項、第 39-1 條第 1  項、\r\n  第 4  項、第 45 條第 1  項、第 48 條第 1  項、第 53 條第 1  項\r\n  、第 55 條、第 57 條、第 59 條第 1  項序文、第 2  項第 6  款、\r\n  第 60 條、第 63 條第 1  項、第 2  項、第 3  項、第 5  項、第 \r\n  63-1  條、第 64 條、第 66 條、第 66-1 條第 2  項、第 66-2 條第\r\n  4 項、第 66-3 條第 1  項、第 67 條、第 68 條、第 69 條、第 70 \r\n  條、第 71 條第 1  項、第 71-1 條、第 72 條第 1  項、第 3  項、\r\n  第 73 條第 1  項第 5  款、第 6  款、第 7  款、第 2  項、第 74 \r\n  條所列屬「行政院環境保護署」之權責事項，自一百十二年八月二十二\r\n  日起改由「環境部」管轄","amended":"20180613","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0040001","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-with-attachments","articles":[{"type":"C","no":"","text":"第 一 章 總則","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 1 條","text":"為防治水污染，確保水資源之清潔，以維護生態體系，改善生活環境，增進國民健康，特制定本法。本法未規定者，適用其他法令之規定。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 2 條","text":"本法專用名詞定義如下：\n一、水：指以任何形式存在之地面水及地下水。\n二、地面水體：指存在於河川、海洋、湖潭、水庫、池塘、灌溉渠道、各級排水路或其他體系內全部或部分之水。\n三、地下水體：指存在於地下水層之水。\n四、污染物：指任何能導致水污染之物質、生物或能量。\n五、水污染：指水因物質、生物或能量之介入，而變更品質，致影響其正常用途或危害國民健康及生活環境。\n六、生活環境：指與人之生活有密切關係之財產、動、植物及其生育環境。\n七、事業：指公司、工廠、礦場、廢水代處理業、畜牧業或其他經中央主管機關指定之事業。\n八、廢水：指事業於製造、操作、自然資源開發過程中或作業環境所產生含有污染物之水。\n九、污水：指事業以外所產生含有污染物之水。\n十、廢（污）水處理設施：指廢（污）水為符合本法管制標準，而以物理、化學或生物方法處理之設施。\n十一、水污染防治措施：指設置廢（污）水處理設施、納入污水下水道系統、土壤處理、委託廢水代處理業處理、設置管線排放於海洋、海洋投棄或其他經中央主管機關許可之防治水污染之方法。\n十二、污水下水道系統：指公共下水道及專用下水道之廢（污）水收集、抽送、傳運、處理及最後處置之各種設施。\n十三、放流口：指廢（污）水進入承受水體前，依法設置之固定放流設施。\n十四、放流水：指進入承受水體前之廢（污）水。\n十五、涵容能力：指在不妨害水體正常用途情況下，水體所能涵容污染物之量。\n十六、水區：指經主管機關劃定範圍內之全部或部分水體。\n十七、水質標準：指由主管機關對水體之品質，依其最佳用途而規定之量度。\n十八、放流水標準：指對放流水品質或其成分之規定限度。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 3 條","text":"本法所稱主管機關：在中央為行政院環境保護署；在直轄市為直轄市政府；在縣（市）為縣（市）政府。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 4 條","text":"中央、直轄市、縣（市）主管機關得指定或委託專責機構，辦理水污染研究、訓練及防治之有關事宜。","headingPath":["第 一 章 總則"]},{"type":"C","no":"","text":"第 二 章 基本措施","headingPath":["第 二 章 基本措施"]},{"type":"A","no":"第 5 條","text":"為避免妨害水體之用途，利用水體以承受或傳運放流水者，不得超過水體之涵容能力。","headingPath":["第 二 章 基本措施"]},{"type":"A","no":"第 6 條","text":"中央主管機關應依水體特質及其所在地之情況，劃定水區，訂定水體分類及水質標準。\n前項之水區劃定、水體分類及水質標準，中央主管機關得交直轄市、縣（市）主管機關為之。\n劃定水區應由主管機關會商水體用途相關單位訂定之。","headingPath":["第 二 章 基本措施"]},{"type":"A","no":"第 7 條","text":"事業、污水下水道系統或建築物污水處理設施，排放廢（污）水於地面水體者，應符合放流水標準。\n前項放流水標準，由中央主管機關會商相關目的事業主管機關定之，其內容應包括適用範圍、管制方式、項目、濃度或總量限值、研訂基準及其他應遵行之事項。直轄市、縣（市）主管機關得視轄區內環境特殊或需特予保護之水體，就排放總量或濃度、管制項目或方式，增訂或加嚴轄內之放流水標準，報請中央主管機關會商相關目的事業主管機關後核定之。","headingPath":["第 二 章 基本措施"]},{"type":"A","no":"第 8 條","text":"事業、污水下水道系統及建築物污水處理設施之廢（污）水處理，其產生之污泥，應妥善處理，不得任意放置或棄置。","headingPath":["第 二 章 基本措施"]},{"type":"A","no":"第 9 條","text":"水體之全部或部分，有下列情形之一，直轄市、縣（市）主管機關應依該水體之涵容能力，以廢（污）水排放之總量管制方式管制之：\n一、因事業、污水下水道系統密集，以放流水標準管制，仍未能達到該水體之水質標準者。\n二、經主管機關認定需特予保護者。\n前項總量管制方式，由直轄市、縣（市）主管機關擬訂，報請中央主管機關會商相關目的事業主管機關後核定之；水體之部分或全部涉及二直轄市、縣（市）者，或涉及中央各目的事業主管機關主管之特定區域，由中央主管機關會商相關目的事業主管機關定之。","headingPath":["第 二 章 基本措施"]},{"type":"A","no":"第 10 條","text":"各級主管機關應設水質監測站，定期監測及公告檢驗結果，並採取適當之措施。\n前項水質監測站採樣頻率，應視污染物項目特性每月或每季一次為原則，必要時，應增加頻率。\n水質監測採樣之地點、項目及頻率，應考量水域環境地理特性、水體水質特性及現況，並由各級主管機關依歷年水質監測結果及水污染整治需要定期檢討。第一項監測站之設置及監測準則，由中央主管機關定之。\n各級主管機關得委託有關機關（構）及中央主管機關許可之檢驗測定機構辦理第一項水質監測。\n第一項公告之檢驗結果未符合水體分類水質標準時，各目的事業主管機關應定期監測水體中食用植物、魚、蝦、貝類及底泥中重金屬、毒性化學物質及農藥含量，如有致危害人體健康、農漁業生產之虞時，並應採取禁止採捕食用水產動、植物之措施。","headingPath":["第 二 章 基本措施"]},{"type":"A","no":"第 11 條","text":"中央主管機關對於排放廢（污）水於地面水體之事業及污水下水道系統（不含公共污水下水道系統及社區專用污水下水道系統），應依其排放之水質水量或依中央主管機關規定之計算方式核定其排放之水質水量，徵收水污染防治費。\n地方政府應對依下水道法公告之下水道使用區域內，未將污水排洩於下水道之家戶，徵收水污染防治費。\n前二項水污染防治費應專供全國水污染防治之用，其支用類別及項目如下：\n一、第一項徵收之水污染防治費：\n（一）地面水體污染整治與水質監測。\n（二）飲用水水源水質保護區水質改善。\n（三）水污染總量管制區水質改善。\n（四）水污染防治技術之研究發展、引進及策略之研發。\n（五）執行收費工作所需人員之聘僱。\n（六）其他有關水污染防治工作。\n二、第二項徵收之水污染防治費：\n（一）公共污水下水道系統主、次要幹管之建設。\n（二）污水處理廠及廢（污）水截流設施之建設。\n（三）水肥投入站及水肥處理廠之建設。\n（四）廢（污）水處理設施產生之污泥集中處理設施之建設。\n（五）公共污水下水道系統之操作維護費用。\n（六）執行收費及公共污水下水道系統建設管理相關工作所需人員之聘僱。\n（七）其他有關家戶污水處理工作之費用。\n前項第一款第五目及第二款第六目之支用比例不得高於各類別之百分之十。\n第一項水污染防治費，其中央與地方分配原則，由中央主管機關考量各直轄市、縣（市）主管機關水污染防治工作需求定之。\n第一項水污染防治費，各級主管機關應設置特種基金；其收支、保管及運用辦法，由行政院、直轄市及縣（市）政府分別定之。\n第二項水污染防治費，地方政府得設置特種基金；其收支、保管及運用辦法，由地方政府定之。\n第一項水污染防治費得分階段徵收，各階段之徵收時間、徵收對象、徵收方式、計算方式、繳費流程、繳費期限、階段用途及其他應遵行事項之收費辦法，由中央主管機關定之。水污染防治執行績效應逐年重新檢討並向立法院報告及備查。\n第二項水污染防治費之徵收時間、徵收對象、徵收方式、計算方式、繳費流程、繳費期限及其他應遵行事項之自治法規，由地方政府定之；其中水污染防治費費率應與下水道使用費費率一致。\n第一項水污染防治費，中央主管機關應成立水污染防治費費率審議委員會，其設置辦法由中央主管機關定之。","headingPath":["第 二 章 基本措施"]},{"type":"A","no":"第 12 條","text":"污水下水道建設與污水處理設施，應符合水污染防治政策之需要。\n中央主管機關應會商直轄市、縣（市）主管機關訂定水污染防治方案，每年向立法院報告執行進度。","headingPath":["第 二 章 基本措施"]},{"type":"C","no":"","text":"第 三 章 防治措施","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 13 條","text":"事業於設立或變更前，應先檢具水污染防治措施計畫及相關文件，送直轄市、縣（市）主管機關或中央主管機關委託之機關審查核准。\n前項事業之種類、範圍及規模，由中央主管機關會商目的事業主管機關指定公告之。\n第一項水污染防治措施計畫之內容、應具備之文件、申請時機、審核依據及其他應遵行事項，由中央主管機關定之。\n第一項水污染防治措施計畫，屬以管線排放海洋者，其管線之設置、變更、撤銷、廢止、停用、申請文件、程序及其他應遵行事項，由中央主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 14 條","text":"事業排放廢（污）水於地面水體者，應向直轄市、縣（市）主管機關申請核發排放許可證或簡易排放許可文件後，並依登記事項運作，始得排放廢（污）水。登記事項有變更者，應於變更前向直轄市、縣（市）主管機關提出申請，經審查核准始可變更。\n前項登記事項未涉及廢（污）水、污泥之產生、收集、處理或排放之變更，並經中央主管機關指定者，得於規定期限辦理變更。\n排放許可證與簡易排放許可文件之適用對象、申請、審查程序、核發、廢止及其他應遵行事項之管理辦法，由中央主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 14-1 條","text":"經中央主管機關指定公告之事業，於申請、變更水污染防治措施計畫、排放許可證或簡易排放許可文件時，應揭露其排放之廢（污）水可能含有之污染物及其濃度與排放量。\n事業排放之廢（污）水含有放流水標準管制以外之污染物項目，並經直轄市、縣（市）主管機關認定有危害生態或人體健康之虞者，應依中央主管機關之規定提出風險評估與管理報告，說明其廢（污）水對生態與健康之風險，以及可採取之風險管理措施。\n前項報告經審查同意者，直轄市、縣（市）主管機關應依審查結果核定其水污染防治措施計畫、排放許可證、簡易排放許可文件之污染物項目排放濃度或總量限值。\n第二項污染物項目經各級主管機關評估有必要者，應於放流水標準新增管制項目。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 15 條","text":"排放許可證及簡易排放許可文件之有效期間為五年。期滿仍繼續使用者，應自期滿六個月前起算五個月之期間內，向直轄市、縣（市）主管機關申請核准展延。每次展延，不得超過五年。\n前項許可證及簡易排放許可文件有效期間內，因水質惡化有危害生態或人體健康之虞時，直轄市、縣（市）主管機關認為登記事項不足以維護水體，或不廢止對公益將有危害者，應變更許可事項或廢止之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 16 條","text":"事業廢（污）水利用不明排放管排放者，由主管機關公告廢止，經公告一週尚無人認領者，得予以封閉或排除該排放管線。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 17 條","text":"除納入污水下水道系統者外，事業依第十三條規定檢具水污染防治措施計畫及依第十四條規定申請發給排放許可證或辦理變更登記時，其應具備之必要文件，應經依法登記執業之環境工程技師或其他相關專業技師簽證。\n符合下列情形之一者，得免再依前項規定經技師簽證：\n一、依第十四條規定申請排放許可證時，應檢具之水污染防治措施計畫，與已依第十三條規定經審查核准之水污染防治措施計畫中，其應經技師簽證事項未變更者。\n二、依第十五條規定申請展延排放許可證時，其應經技師簽證之事項未變更者。\n政府機關、公營事業機構或公法人於第一項情形，得由其內依法取得第一項技師證書者辦理簽證。\n第一項技師執行簽證業務時，其查核事項，由中央主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 18 條","text":"事業應採行水污染防治措施；其水污染防治措施之適用對象、範圍、條件、必備設施、規格、設置、操作、監測、記錄、監測紀錄資料保存年限、預防管理、緊急應變，與廢（污）水之收集、處理、排放及其他應遵行事項之管理辦法，由中央主管機關會商相關目的事業主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 18-1 條","text":"事業或污水下水道系統產生之廢（污）水，應經核准登記之收集、處理單元、流程，並由核准登記之放流口排放，或依下水道管理機關（構）核准之排放口排入污水下水道，不得繞流排放。\n前項廢（污）水須經處理始能符合本法所定管制標準者，不得於排放（入）前，與無需處理即能符合標準之水混合稀釋。\n前二項繞流排放、稀釋行為，因情況急迫，為搶救人員或經主管機關認定之重大處理設施，並於三小時內通知直轄市、縣（市）主管機關者，不在此限。\n事業或污水下水道系統設置之廢（污）水（前）處理設施應具備足夠之功能與設備，並維持正常操作。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 19 條","text":"污水下水道系統排放廢（污）水，準用第十四條、第十五條及第十八條之規定。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 20 條","text":"事業或污水下水道系統貯留或稀釋廢水，應申請直轄市或縣（市）主管機關許可後，始得為之，並依登記事項運作。但申請稀釋廢水許可，以無其他可行之替代方法者為限。\n前項申請貯留或稀釋廢水許可之適用條件、申請、審查程序、核發、廢止及其他應遵行事項之管理辦法，由中央主管機關定之。\n依第一項許可貯留或稀釋廢水者，應依主管機關規定之格式、內容、頻率、方式，向直轄市、縣（市）主管機關申報廢水處理情形。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 21 條","text":"事業或污水下水道系統應設置廢（污）水處理專責單位或人員。\n專責單位或人員之設置及專責人員之資格、訓練、合格證書之取得、撤銷、廢止及其他應遵行事項之管理辦法，由中央主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 22 條","text":"事業或污水下水道系統應依主管機關規定之格式、內容、頻率、方式，向直轄市、縣（市）主管機關申報廢（污）水處理設施之操作、放流水水質水量之檢驗測定、用電紀錄及其他有關廢（污）水處理之文件。\n中央主管機關應依各業別之廢（污）水特性，訂定應檢測申報項目，直轄市、縣（市）主管機關得依實際排放情形，增加檢測申報項目。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 23 條","text":"水污染物及水質水量之檢驗測定，除經中央主管機關核准外，應委託中央主管機關核發許可證之檢驗測定機構辦理。\n檢驗測定機構之條件、設施、檢驗測定人員之資格限制、許可證之申請、審查、核發、換發、撤銷、廢止、停業、復業、查核、評鑑等程序及其他應遵行事項之管理辦法及收費標準，由中央主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 24 條","text":"事業或污水下水道系統，其廢（污）水處理及排放之改善，由各目的事業主管機關輔導之；其輔導辦法，由各目的事業主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 25 條","text":"建築物污水處理設施之所有人、使用人或管理人，應自行或委託清除機構清理之。\n前項建築物污水處理設施之建造、管理及清理，應符合中央主管機關及目的事業主管機關之規定。\n建築物污水處理設施屬預鑄式者，其製造、審定、登記及查驗管理辦法，由中央主管機關會同相關目的事業主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 26 條","text":"各級主管機關得派員攜帶證明文件，進入事業、污水下水道系統或建築物污水處理設施之場所，為下列各項查證工作：\n一、檢查污染物來源及廢（污）水處理、排放情形。\n二、索取有關資料。\n三、採樣、流量測定及有關廢（污）水處理、排放情形之攝影。\n各級主管機關依前項規定為查證工作時，其涉及軍事秘密者，應會同軍事機關為之。\n對於前二項查證，不得規避、妨礙或拒絕。\n檢查機關與人員，對於受檢之工商、軍事秘密，應予保密。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 27 條","text":"事業或污水下水道系統排放廢（污）水，有嚴重危害人體健康、農漁業生產或飲用水水源之虞時，負責人應立即採取緊急應變措施，並於三小時內通知當地主管機關。\n前項所稱嚴重危害人體健康、農漁業生產或飲用水之虞之情形，由中央主管機關定之。\n第一項之緊急應變措施，其措施內容與執行方法，由中央主管機關定之。\n第一項情形，主管機關應命其採取必要防治措施，情節嚴重者，並令其停業或部分或全部停工。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 28 條","text":"事業或污水下水道系統設置之輸送或貯存設備，有疏漏污染物或廢（污）水至水體之虞者，應採取維護及防範措施；其有疏漏致污染水體者，應立即採取緊急應變措施，並於事故發生後三小時內，通知當地主管機關。主管機關應命其採取必要之防治措施，情節嚴重者，並令其停業或部分或全部停工。\n前項之緊急應變措施，其措施內容與執行方法，由中央主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 29 條","text":"直轄巿、縣（巿）主管機關，得視轄境內水污染狀況，劃定水污染管制區公告之，並報中央主管機關。\n前項管制區涉及二直轄巿、縣（巿）以上者，由中央主管機關劃定並公告之。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 30 條","text":"在水污染管制區內，不得有下列行為：\n一、使用農藥或化學肥料，致有污染主管機關指定之水體之虞。\n二、在水體或其沿岸規定距離內棄置垃圾、水肥、污泥、酸鹼廢液、建築廢料或其他污染物。\n三、使用毒品、藥品或電流捕殺水生物。\n四、在主管機關指定之水體或其沿岸規定距離內飼養家禽、家畜。\n五、其他經主管機關公告禁止足使水污染之行為。\n前項第一款、第二款及第四款所稱指定水體及規定距離，由主管機關視實際需要公告之。但中央主管機關另有規定者，從其規定。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 31 條","text":"事業或污水下水道系統，排放廢（污）水於劃定為總量管制之水體，有下列情形之一，應自行設置放流水水質水量自動監測系統，予以監測：\n一、排放廢（污）水量每日超過一千立方公尺者。\n二、經直轄巿、縣（巿）主管機關認定係重大水污染源者。\n前項監測結果、監測儀器校正，應作成紀錄，並依規定向直轄巿、縣（巿）主管機關或中央主管機關申報。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 32 條","text":"廢（污）水不得注入於地下水體或排放於土壤。但廢（污）水經處理至合於土壤處理標準及依第十八條所定之辦法，經直轄市、縣（市）主管機關審查核准，發給許可證並報經中央主管機關核備者，得排放於土壤。\n前項許可證有效期間內，因水質惡化有危害生態或人體健康之虞時，直轄市、縣（市）主管機關認為登記事項不足以維護水體或土壤，或不廢止對公益將有危害者，應變更許可事項或廢止之。\n第一項可排放於土壤之對象、適用範圍、項目、濃度或總量限值、管制方式及其他應遵行事項之土壤處理標準，由中央主管機關會商相關目的事業主管機關定之。\n依主管機關核定之土壤處理與作物吸收試驗及地下水水質監測計畫，排放廢（污）水於土壤者，應依主管機關規定之格式、內容、頻率、方式，執行試驗、監測、記錄及申報。\n依第一項核發之許可證有效期間為三年。期滿仍繼續使用者，應自期滿六個月前起算五個月之期間內，向直轄市、縣（市）主管機關申請核准展延。每次展延，不得超過三年。","headingPath":["第 三 章 防治措施"]},{"type":"A","no":"第 33 條","text":"事業貯存經中央主管機關公告指定之物質時，應設置防止污染地下水體之設施及監測設備，並經直轄市、縣（市）主管機關備查後，始得申辦有關使用事宜。\n前項監測設備應依主管機關規定之格式、內容、頻率、方式，監測、記錄及申報。\n第一項防止污染地下水體之設施、監測設備之種類及設置之管理辦法，由中央主管機關定之。","headingPath":["第 三 章 防治措施"]},{"type":"C","no":"","text":"第 四 章 罰則","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 34 條","text":"違反第二十七條第一項、第二十八條第一項未立即採取緊急應變措施、不遵行主管機關依第二十七條第四項、第二十八條第一項所為之命令或不遵行主管機關依本法所為停工或停業之命令者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上五百萬元以下罰金。\n不遵行主管機關依本法所為停止作為之命令者，處一年以下有期徒刑、拘役或科或併科新臺幣十萬元以上五十萬元以下罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 35 條","text":"依本法規定有申報義務，明知為不實之事項而申報不實或於業務上作成之文書為虛偽記載者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上三百萬元以下罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 36 條","text":"事業排放於土壤或地面水體之廢（污）水所含之有害健康物質超過本法所定各該管制標準者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上五百萬元以下罰金。\n事業注入地下水體之廢（污）水含有害健康物質者，處一年以上七年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上二千萬元以下罰金。\n犯第一項之罪而有下列情形之一者，處五年以下有期徒刑，得併科新臺幣二十萬元以上一千五百萬元以下罰金：\n一、無排放許可證或簡易排放許可文件。\n二、違反第十八條之一第一項規定。\n三、違反第三十二條第一項規定。\n第一項、第二項有害健康物質之種類、限值，由中央主管機關公告之。\n負責人或監督策劃人員犯第三十四條至本條第三項之罪者，加重其刑至二分之一。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 37 條","text":"犯第三十四條、前條之罪或排放廢（污）水超過放流水標準，因而致人於死者，處無期徒刑或七年以上有期徒刑，得併科新臺幣三千萬元以下罰金；致重傷者，處三年以上十年以下有期徒刑，得併科新臺幣二千五百萬元以下罰金；致危害人體健康導致疾病或嚴重污染環境者，處一年以上七年以下有期徒刑，得併科新臺幣二千萬元以下罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 38 條","text":"（刪除）","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 39 條","text":"法人之負責人、法人或自然人之代理人、受僱人或其他從業人員，因執行業務犯第三十四條至第三十七條之罪者，除依各該條規定處罰其行為人外，對該法人或自然人亦科以各該條十倍以下之罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 39-1 條","text":"事業或污水下水道系統不得因廢（污）水處理專責人員或其他受僱人，向主管機關或司法機關揭露違反本法之行為、擔任訴訟程序之證人或拒絕參與違反本法之行為，而予解僱、降調、減薪或其他不利之處分。\n事業或污水下水道系統或其行使管理權之人，為前項規定所為之解僱、降調、減薪或其他不利之處分者，無效。\n事業或污水下水道系統之廢（污）水處理專責人員或其他受僱人，因第一項規定之行為受有不利處分者，事業或污水下水道系統對於該不利處分與第一項規定行為無關之事實，負舉證責任。\n廢（污）水處理專責人員或其他受僱人曾參與依本法應負刑事責任之行為，而向主管機關揭露或司法機關自白或自首，因而查獲其他正犯或共犯者，減輕或免除其刑。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 40 條","text":"事業或污水下水道系統排放廢（污）水，違反第七條第一項或第八條規定者，處新臺幣六萬元以上二千萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者，按次處罰；情節重大者，得令其停工或停業；必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。\n畜牧業違反第七條第一項或第八條之規定者，處新臺幣六千元以上六十萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者，按次處罰；情節重大者，得令其停工或停業；必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 41 條","text":"建築物污水處理設施違反第七條第一項或第八條規定者，處新臺幣三千元以上三十萬元以下罰鍰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 42 條","text":"污水下水道系統或建築物污水處理設施違反第七條第一項或第八條規定者，處罰其所有人、使用人或管理人；污水下水道系統或建築物污水處理設施為共同所有或共同使用且無管理人者，應對共同所有人或共同使用人處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 43 條","text":"事業或污水下水道系統違反依第九條第二項所定之總量管制方式者，處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者，按次處罰；情節重大者，得令其停工或停業，必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 44 條","text":"事業或污水下水道系統（不含公共污水下水道系統及社區專用污水下水道系統）違反第十一條第八項所定辦法，未於期限內繳納費用者，應依繳納期限當日郵政儲金一年期定期存款固定利率按日加計利息一併繳納；逾期九十日仍未繳納者，處新臺幣六千元以上三十萬元以下罰鍰。\n家戶違反第十一條第九項所定自治法規，未於期限內繳納費用且逾九十日仍未繳納者，地方政府應對該家戶處新臺幣一千五百元以上三萬元以下罰鍰。\n前項處罰鍰額度應依違規情節裁處；其裁罰準則由地方政府定之，不適用第六十六條之一規定。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 45 條","text":"違反第十四條第一項未取得排放許可證或簡易排放許可文件而排放廢（污）水者，處新臺幣六萬元以上六百萬元以下罰鍰，主管機關並應令事業全部停工或停業；必要時，應勒令歇業。\n違反第十四條第一項未依排放許可證或簡易排放許可文件之登記事項運作者，處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期補正，屆期仍未補正者，按次處罰；情節重大者，得令其停工或停業；必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。\n違反第十四條第二項，處新臺幣一萬元以上六十萬元以下罰鍰，並通知限期補正，屆期仍未補正者，按次處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 46 條","text":"違反依第十三條第四項或第十八條所定辦法規定者，處新臺幣一萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰；情節重大者，得令其停工或停業；必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 46-1 條","text":"排放廢（污）水違反第十八條之一第一項、第二項或第四項規定者，處新臺幣六萬元以上二千萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者，按次處罰；情節重大者，得令其停工或停業；必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 47 條","text":"污水下水道系統違反第十九條規定者，處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 48 條","text":"事業或污水下水道系統違反第二十條第一項未取得貯留或稀釋許可文件而貯留或稀釋廢（污）水者，處新臺幣三萬元以上三百萬元以下罰鍰，主管機關並應令事業全部停工或停業；必要時，應勒令歇業。\n事業或污水下水道系統違反第二十條第一項未依貯留或稀釋許可文件之登記事項運作者，處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期補正，屆期仍未補正者，按次處罰；情節重大者，得令其停工或停業；必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。\n事業或污水下水道系統違反第二十一條第一項或依第二十一條第二項所定辦法者，處新臺幣一萬元以上十萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰。\n廢（污）水處理專責人員違反依第二十一條第二項所定辦法者，處新臺幣一萬元以上十萬元以下罰鍰；必要時，得廢止其廢水處理專責人員合格證書。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 49 條","text":"違反第二十三條第一項或依第二十三條第二項所定管理辦法者，處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰；情節重大者，得令其停業，必要時，並得廢止其許可證或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 50 條","text":"規避、妨礙或拒絕第二十六條第一項之查證者，處新臺幣三萬元以上三百萬元以下罰鍰，並得按次處罰及強制執行查證工作。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 51 條","text":"違反第二十七條第一項、第四項規定者，處新臺幣六萬元以上六百萬元以下罰鍰；必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。\n違反第二十八條第一項規定者，處新臺幣一萬元以上六百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰；必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 52 條","text":"違反第三十條第一項各款情形之一或第三十一條第一項規定者，處新臺幣三萬元以上三百萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者，按次處罰；情節重大者，得令其停止作為或停工、停業，必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 53 條","text":"違反第三十二條第一項規定，將廢（污）水注入地下水體或未取得排放土壤處理許可證而排放廢（污）水於土壤者，處新臺幣六萬元以上六百萬元以下罰鍰；主管機關並應令事業全部停工或停業；必要時，應勒令歇業。\n違反第三十二條第一項未依排放土壤處理許可證之登記事項運作者，處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期補正，屆期仍未補正者，按次處罰；情節重大者，得令其停工或停業；必要時，並得廢止其水污染防治許可證（文件）或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 54 條","text":"違反第三十三條第一項、第二項規定者，處新臺幣六萬元以上六百萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者，按次處罰；情節重大者，得令其停止貯存或停工、停業，必要時，並得勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 55 條","text":"違反本法規定，經認定情節重大者，主管機關得依本法規定逕命停止作為、停止貯存、停工或停業；必要時，並勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 56 條","text":"依第二十條第三項、第二十二條、第三十一條第二項、第三十二條第四項或第三十三條第二項有申報義務，不為申報者，處新臺幣六千元以上三百萬元以下罰鍰，並通知限期申報，屆期未申報或申報不完全者，按次處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 57 條","text":"本法所定屆期仍未補正或完成改善之按次處罰，其限期改善或補正之期限、改善完成認定查驗方式、法令執行方式及其他應遵行事項之準則，由中央主管機關定之。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 57-1 條","text":"事業及污水下水道系統於改善期間，排放之廢（污）水污染物項目超過原據以處罰之排放濃度或氫離子濃度指數更形惡化者，應按次處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 58 條","text":"同一事業設置數放流口，或數事業共同設置廢水處理設施或使用同一放流口，其排放廢水未符合放流水標準或本法其他規定者，應分別處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 59 條","text":"廢（污）水處理設施發生故障時，符合下列規定者，於故障發生二十四小時內，得不適用主管機關所定標準：\n一、立即修復或啟用備份裝置，並採行包括減少、停止生產或服務作業量或其他措施之應變措施。\n二、立即於故障紀錄簿中記錄故障設施名稱及故障時間，並向當地主管機關以電話或電傳報備，並記錄報備發話人、受話人姓名、職稱。\n三、於故障發生二十四小時內恢復正常操作或於恢復正常操作前減少、停止生產及服務作業。\n四、於五日內向當地主管機關提出書面報告。\n五、故障與所違反之該項放流水標準有直接關係者。\n六、不屬六個月內相同之故障。\n前項第四款書面報告內容，應包括下列事項：\n一、設施名稱及故障時間。\n二、發生原因及修復方法。\n三、故障期間所採取之污染防治措施。\n四、防止未來同類故障再發生之方法。\n五、前項第一款及第二款有關之證據資料。\n六、其他經主管機關規定之事項。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 60 條","text":"事業未於依第四十條、第四十三條、第四十六條或第五十三條所為通知改善之期限屆滿前，檢具符合主管機關所定標準或其他規定之證明文件，送交主管機關收受者，視為未完成改善。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 61 條","text":"依本法通知限期補正、改善或申報者，其補正、改善或申報期間，不得超過九十日。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 62 條","text":"事業、污水下水道系統或建築物污水處理設施，因天災或其他不可抗力事由，致不能於改善期限內完成改善者，應於其原因消滅後繼續進行改善，並於十五日內以書面敘明理由，檢具有關證明文件，向當地主管機關申請核定賸餘期間之起算日。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 63 條","text":"事業經停業、部分或全部停工者，應於復工（業）前，檢具水污染防治措施及污泥處理改善計畫申請試車，經審查通過，始得依計畫試車。其經主管機關命限期改善而自報停工（業）者，亦同。\n前項試車之期限不得超過三個月，且應於試車期限屆滿前，申請復工（業）。主管機關於審查試車、復工（業）申請案期間，事業經主管機關同意，在其申報可處理至符合管制標準之廢（污）水產生量下，得繼續操作。\n前項復工（業）之申請，主管機關應於一個月期間內，經十五日以上之查驗及評鑑，始得按其查驗及評鑑結果均符合管制標準時之廢（污）水產生量，作為核准其復工（業）之製程操作條件。事業並應據以辦理排放許可登記事項之變更登記。\n經查驗及評鑑不合格，未經核准復工（業）者，應停止操作，並進行改善，且一個月內不得再申請試車。\n事業於申請試車或復工（業）期間，如有違反本法規定者，主管機關應依本法規定按次處罰或命停止操作。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 63-1 條","text":"事業應將依前條第一項所提出之水污染防治措施及污泥處理改善計畫，登載於中央主管機關所指定之公開網頁供民眾查詢。\n主管機關為前條第一項審查時，應給予利害關係人及公益團體於主管機關完成審查前表示意見，作為主管機關審查時之參考；於會議後應作成會議紀錄並公開登載於前項中央主管機關指定之網頁。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 64 條","text":"本法所定之處罰，除另有規定外，在中央由行政院環境保護署為之，在直轄市由直轄市政府為之，在縣（市）由縣（市）政府為之。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 65 條","text":"（刪除）","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 66 條","text":"本法之停工或停業、撤銷、廢止許可證之執行，由主管機關為之；勒令歇業，由主管機關轉請目的事業主管機關為之。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 66-1 條","text":"依本法處罰鍰者，其額度應依污染特性及違規情節裁處。\n前項裁罰準則由中央主管機關定之。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 66-2 條","text":"違反本法義務行為而有所得利益者，除應依本法規定裁處一定金額之罰鍰外，並得於所得利益之範圍內，予以追繳。\n為他人利益而實施行為，致使他人違反本法上義務應受處罰者，該行為人因其行為受有財產上利益而未受處罰時，得於其所受財產上利益價值範圍內，予以追繳。\n行為人違反本法上義務應受處罰，他人因該行為受有財產上利益而未受處罰時，得於其所受財產上利益價值範圍內，予以追繳。\n前三項追繳，由為裁處之主管機關以行政處分為之；所稱利益得包括積極利益及應支出而未支出或減少支出之消極利益，其核算及推估辦法，由中央主管機關定之。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 66-3 條","text":"各級主管機關依第十一條第六項設置之特種基金，其來源除該條第一項水污染防治費徵收之費用外，應包括各級主管機關依前條追繳之所得利益及依本法裁處之部分罰鍰。\n前項基金來源屬追繳之所得利益及依本法裁處之罰鍰者，應優先支用於該違反本法義務者所污染水體之整治。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 66-4 條","text":"民眾得敘明事實或檢具證據資料，向直轄市、縣（市）主管機關檢舉違反本法之行為。\n直轄市、縣（市）主管機關對於檢舉人之身分應予保密；前項檢舉經查證屬實並處以罰鍰者，其罰鍰金額達一定數額時，得以實收罰鍰總金額收入之一定比例，提充獎金獎勵檢舉人。\n前項檢舉及獎勵之檢舉人資格、獎金提充比例、分配方式及其他相關事項之辦法，由直轄市、縣（市）主管機關定之。","headingPath":["第 四 章 罰則"]},{"type":"C","no":"","text":"第 五 章 附則","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 67 條","text":"各級主管機關依本法核發許可證、受理變更登記或各項申請之審查、許可，應收取審查費、檢驗費或證書費等規費。\n前項收費標準，由中央主管機關會商有關機關定之。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 68 條","text":"本法所定各項檢測之方法及品質管制事項，由中央主管機關指定公告之。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 69 條","text":"事業、污水下水道系統應將主管機關核准之水污染防治許可證（文件）、依本法申報之資料，與環境工程技師、廢水處理專責人員及環境檢驗測定機構之證號資料，公開於中央主管機關指定之網站。\n各級主管機關基於水污染防治研究需要，得提供與研究有關之事業、污水下水道系統或建築物污水處理設施之個別或統計性資料予學術研究機關（構）、環境保護事業單位、技術顧問機構、財團法人；其提供原則，由中央主管機關公告之。\n各級主管機關得於中央主管機關指定之網站，公開對事業、污水下水道系統、建築物污水處理設施、環境工程技師、廢水處理專責人員、環境檢驗測定機構查核、處分之個別及統計資訊。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 70 條","text":"水污染受害人，得向主管機關申請鑑定其受害原因；主管機關得會同有關機關查明後，命排放水污染物者立即改善，受害人並得請求適當賠償。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 71 條","text":"地面水體發生污染事件，主管機關應令污染行為人限期清除處理，屆期不為清除處理時，主管機關得代為清除處理，並向其求償清理、改善及衍生之必要費用。\n前項必要費用之求償權，優於一切債權及抵押權。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 71-1 條","text":"為保全前條主管機關代為清理之債權、違反本法規定所裁處之罰鍰及第六十六條之二追繳所得利益之履行，主管機關得免提供擔保向行政法院聲請假扣押、假處分。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 72 條","text":"事業、污水下水道系統違反本法或依本法授權訂定之相關命令而主管機關疏於執行時，受害人民或公益團體得敘明疏於執行之具體內容，以書面告知主管機關。主管機關於書面告知送達之日起六十日內仍未依法執行者，受害人民或公益團體得以該主管機關為被告，對其怠忽執行職務之行為，直接向高等行政法院提起訴訟，請求判令其執行。\n高等行政法院為前項判決時，得依職權判命被告機關支付適當律師費用、監測鑑定費用或其他訴訟費用予對維護水體品質有具體貢獻之原告。\n第一項之書面告知格式，由中央主管機關會商有關機關定之。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 73 條","text":"本法第四十條、第四十三條、第四十六條、第四十六條之一、第四十九條、第五十二條、第五十三條及第五十四條所稱之情節重大，係指下列情形之一者：\n一、未經合法登記或許可之污染源，違反本法之規定。\n二、經處分後，自報停工改善，經查證非屬實。\n三、一年內經二次限期改善，仍繼續違反本法規定。\n四、工業區內事業單位，將廢（污）水納入工業區污水下水道系統處理，而違反下水道相關法令規定，經下水道機構依下水道法規定以情節重大通知停止使用，仍繼續排放廢（污）水。\n五、大量排放污染物，經主管機關認定嚴重影響附近水體品質。\n六、排放之廢（污）水中含有有害健康物質，經主管機關認定有危害公眾健康之虞。\n七、其他經主管機關認定嚴重影響附近地區水體品質之行為。\n主管機關應公開依前項規定認定情節重大之事業，由提供優惠待遇之目的事業主管機關或各該法律之主管機關停止並追回其違規行為所屬年度之優惠待遇，並於其後三年內不得享受政府之優惠待遇。\n前項所稱優惠待遇，包含中央或地方政府依法律或行政行為所給予該事業獎勵、補助、捐助或減免之租稅、租金、費用或其他一切優惠措施。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 74 條","text":"本法施行細則，由中央主管機關定之。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 75 條","text":"本法自公布日施行。","headingPath":["第 五 章 附則"]}],"attachments":[],"attachmentNote":""},"water-measure-reg":{"id":"water-measure-reg","pcode":"O0040054","name":"水污染防治措施及檢測申報管理辦法","foreword":"","histories":"1.中華民國九十五年十月十六日行政院環境保護署環署水字第 095008018\r\n  3 號令訂定發布全文 101  條；並自發布日施行\r\n2.中華民國九十九年七月七日行政院環境保護署環署水字第 0990060084 \r\n  號令增訂第 95～109  條條文及第十二章、十三章章名；原第 95～101\r\n  條修正並遞改為第 110～114 條條文；並自發布日施行    \r\n3.中華民國一百零二年三月八日行政院環境保護署環署水字第 102001834\r\n  5 號令修正發布第 2、11、12、52、56、57、59、71、75、83、84、86\r\n  、89、90、93、95、99、101、103、105、106、108、110、114 條條文\r\n  及第十二章章名；增訂第 49-1、49-2、57-1、60-1、84-1、84-2、101\r\n  -1、113-1 條條文；刪除第 104、109、111  條條文；除第 49-1 條條\r\n  文自一百零四年一月一日施行，第 49-2 條、第 75 條第 1  項第 4\r\n  款等條文自一百零二年七月一日施行外，自發布日施行\r\n4.中華民國一百零二年五月三十一日行政院環境保護署環署水字第 10200\r\n  44374 號令修正發布第 106～108 條條文        \r\n5.中華民國一百零四年十一月二十四日行政院環境保護署環署水字第 104\r\n  0095824 號令修正發布第 2、10、12、14～17、28、37、47、50、52～\r\n  54、56～59、65～67、73、89、92、93、94、99、100、105、106、108\r\n  、114 條條文；增訂第十章之一及第 49-3、70-1～70-10、89-1、92-1\r\n  、106-1、111-1、113-2 條條文；刪除第 60-1、113、113-1 條條文；\r\n  除另定施行日期外，自發布日施行\r\n6.中華民國一百零五年十月二十八日行政院環境保護署環署水字第 10500\r\n  86697 號令修正發布第 2、14、50、56～57-1、70-1、70-2、70-4～70\r\n  -6、70-8、71、91、105～108、110、114  條條文及第十三章章名；增\r\n  訂第 49-4 條條文；刪除第 58 條條文；除另定施行日期外，自發布日\r\n  施行\r\n7.中華民國一百零六年十二月二十七日行政院環境保護署環署水字第 106\r\n  0103859 號令修正發布第 5、10、24、25、27、41、49-4、56、70-1、\r\n  70-5、70-9、70-10、79、92、94、105、114 條條文及第 106  條條文\r\n  之附表三；增訂第 43-1、46-1、49-5～49-9 條條文；刪除第 69 條條\r\n  文；並自發布日施行\r\n8.中華民國一百零八年三月八日行政院環境保護署環署水字第 108001563\r\n  2 號令修正發布第 2、10、49-5～49-8、56、65、70-1、70-2、71、83\r\n  、92-1、106、110、114 條條文、第 60 條條文之附表一及第十章之一\r\n  章名；增訂第 49-10、49-11 條條文；並自發布日施行\r\n  中華民國一百零九年四月七日行政院環境保護署環署水字第 109002395\r\n  6 號令發布第 10 條第 4  項條文有關營建工地逕流廢水污染削減計畫\r\n  之申請，採網路傳輸方式辦理之規定，定自一百零九年四月十日施行\r\n9.中華民國一百十年五月三十一日行政院環境保護署環署水字第 1101056\r\n  819 號令修正發布第 49-1、71 條條文；刪除第 44 條條文\r\n10. 中華民國一百十一年十月二十四日行政院環境保護署環署水字第 111\r\n    1134111A  號令修正發布第 70-3、70-5、70-8 條條文\r\n    中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公\r\n    告第 4  條、第 5  條第 3  項第 6  款、第 6  條、第 7  條第 2\r\n    項、第 9  條第 1  項、第 10 條第 3  項第 3  款、第 4  項、第\r\n    11  條第 1  項、第 12 條第 1  項、第 15 條第 1  項、第 17 條\r\n    第 1  項第 3  款、第 2  項、第 3  項、第 19 條第 2  項第 1  \r\n    款、第 2  款、第 3  款、第 4  款、第 21 條、第 22 條第 3  項\r\n    、第 23 條、第 28 條第 2  項第 1  款、第 4  款、第 3  項、第\r\n    29  條、第 34 條第 2  項第 1  款、第 2  款、第 3  款、第 4  \r\n    款、第 35 條第 1  款、第 3  款、第 36 條第 1  項第 2  款、第\r\n    37  條第 3  項、第 41 條第 3  項、第 43-1 條第 2  項、第 45 \r\n    條序文、第 3  款、第 46 條第 6  款、第 49-1 條第 3  項、第 \r\n    49-3  條第 1  項、第 49-4 條第 6  項、第 49-7 條第 1  項、第\r\n    49-8  條第 3  項、第 49-9 條第 1  項第 3  款、第 4  款、第 \r\n    49-11 條第 2  項第 3  款、第 4  款、第 50 條第 2  項、第 52 \r\n    條第 1  項、第 53 條第 1  項第 5  款、第 2  項、第 56 條第 1\r\n    項第 1  款、第 2  款、第 3  款、第 4  款、第 5  款、第 4  項\r\n    序文、第 2  款、第 3  款、第 5  項第 1  款序文、第 7  項、第\r\n    57  條第 1  項附表 2、第 57-1 條第 1  項、第 2  項、第 59 條\r\n    第 1  項序文、第 60 條第 1  項第 2  款、第 2  項第 3  款、第\r\n    4 款、第 61 條第 2  項、第 62 條、第 63 條、第 64 條第 2  項\r\n    、第 65 條第 3  項、第 4  項序文、第 66 條第 1  項、第 68 條\r\n    、第 70-2 條第 2  項第 2  款、第 70-3 條第 2  項、第 3  項、\r\n    第 70-8 條第 2  項、第 70-10  條第 1  項、第 83 條第 1  項附\r\n    表 1、第 2  項、第 84 條第 1  項、第 2  項附表 1、第 84-1 條\r\n    第 1  項、第 2  項第 1  款、第 2  款、第 84-2 條第 1  項、第\r\n    85  條第 1  項序文附表 1、第 3  項、第 86 條第 2  項、第 87 \r\n    條、第 89-1 條第 1  項第 1  款、第 3  款、第 7  款、第 8  款\r\n    、第 2  項、第 92 條第 1  項第 3  款、第 2  項序文、第 4  項\r\n    、第 92-1 條第 1  項、第 5  項、第 97 條第 3  項、第 99 條第\r\n    2 項、第 3  項、第 102  條第 2  項、第 3  項、第 4  項、第 \r\n    103 條第 1  項序文、第 2  款、第 3  款、第 105  條第 1  項第\r\n    5 款、第 106  條第 1  項附表 3、第 2  項附表 3、第 106-1  條\r\n    第 2  項、第 4  項、第 108  條第 1  項附件 1、附件 2、第 3  \r\n    項所列屬「行政院環境保護署」之權責事項，自一百十二年八月二十\r\n    二日起改由「環境部」管轄\r\n    中華民國一百十二年九月十三日行政院院臺規字第 1121032982 號公\r\n    告第 27 條第 1  項第 1  款、第 47 條第 1  項、第 70-6 條第 1\r\n    項第 1  款所列屬「交通部中央氣象局」之權責事項，自一百十二年\r\n    九月十五日起改由「交通部中央氣象署」管轄\r\n11. 中華民國一百十四年一月二十日環境部環部水字第 1141002990 號令\r\n    修正發布第 27、47、70-2、70-6、71、73、79、84-1、89-1、91、\r\n    114 條條文及第 60 條條文之附表一；並增訂第 49-12、84-3  條條\r\n    文；除另定施行日期者外，自發布日施行\r\n12. 中華民國一百十五年四月二十日環境部環部水字第 1151015013 號令\r\n    修正發布第 2、56、92、105、106、107、108、114 條條文及第 106\r\n    條條文之附表三；增訂第 106-2  條條文；依第 114  條規定：除另\r\n    定施行日期者外，自發布日施行","amended":"20260420","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0040054","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-text-partial-attachments","articles":[{"type":"C","no":"","text":"第 一 章 總則","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 1 條","text":"本辦法依水污染防治法（以下簡稱本法）第十八條、第十九條準用第十八條、第二十條第三項、第二十二條、第三十一條第二項及第三十二條第四項規定訂定之。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 2 條","text":"本辦法用詞，定義如下：\n一、水污染防治措施項目如下：\n（一）設置廢（污）水（前）處理設施。\n（二）納入污水下水道系統。\n（三）土壤處理。\n（四）委託與受託處理。\n（五）設置管線排放於海洋。\n（六）貯留廢（污）水。\n（七）稀釋廢（污）水。\n（八）回收使用廢（污）水。\n（九）逕流廢水污染削減措施。\n（十）排放及其他廢（污）水管理。\n（十一）沼液沼渣農地肥分使用。\n（十二）工業區集污管理。\n（十三）設置自動監測（視）設施及連線傳輸。\n（十四）維護防範措施及緊急應變措施。\n二、共同設置廢（污）水（前）處理設施：指二以上事業合資，共同興建並使用廢（污）水（前）處理設施。\n三、代操作：指受事業或污水下水道系統委託，操作管理其廢（污）水（前）處理設施。\n四、土壤處理：指以管線或溝渠輸送廢（污）水，排放、滲透於土壤，以去除水中污染物或降低其濃度之方法。\n五、委託處理廢（污）水：指以管線或溝渠輸送廢（污）水，委託他人處理（以下簡稱委託處理）。\n六、受託處理廢（污）水：指設置廢（污）水（前）處理設施，接受他人委託，處理廢（污）水（以下簡稱受託處理）。\n七、最初稀釋率：指廢（污）水自管線排入海洋後，上升達平衡狀態時，廢（污）水水柱中心與周遭海水混合所得之稀釋倍數。\n八、廢（污）水以海洋放流管線（以下簡稱海放管）排放於海洋：指以管線輸送廢（污）水排放於海洋，其最初稀釋率達一百倍以上。\n九、貯留：指將廢（污）水送至貯留設施，後續採回收使用、委託處理、以桶裝、槽車或其他非管線、溝渠，清除、運送廢（污）水至作業環境外，或廢棄物掩埋場返送滲出水至掩埋面之行為。\n十、廢（污）水回收使用：指將未排放至水體且未以土壤處理之廢（污）水，收集作為其他水資源用途。\n十一、非連續性排放：指放流水非每日二十四小時持續自放流口排放至承受水體，或自下水道管理機關（構）核准之排放口排入污水下水道。\n十二、單純泡湯廢水：指未添加其他物質之泡湯廢水。\n十三、沼液沼渣農地肥分使用：指畜牧業產生之糞尿，或畜牧糞尿資源化處理中心（或沼氣再利用中心）之經營管理業者收集之畜牧糞尿，經厭氧發酵後或再經曝氣處理後之沼液、沼渣，施灌於農地，作為農地肥分使用。\n十四、TUa：生物急毒性檢測時之半數致死濃度LC50（Lethal Concentration 50％）之倒數。\n十五、農地：指供作農作、森林、養殖、畜牧及保育使用之土地。\n十六、自動監測設施服務機構（以下簡稱監測服務機構）：指受事業或污水下水道系統委託，提供水量自動監測設施、水質自動監測設施、攝錄影自動監視設施、連線傳輸設施（以下簡稱自動監測（視）設施）及其廢（污）水（前）處理設施獨立專用電子式電度表（以下簡稱電子式電度表）設置、維護及相關技術支援服務之機構。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 3 條","text":"事業廢水類別如下：\n一、作業廢水：指事業於製造、加工、修理、處理、操作、冷卻、沖洗、逆洗、治療、提供服務、畜殖、自然資源開發過程或其他作業時，與人或物直接接觸之廢水。\n二、洩放廢水：指自事業循環用水中洩放，以減低循環過程累積於用水中污染物含量之廢水。\n三、未接觸冷卻水：指於熱交換管線內專供溫度交換之水。\n四、逕流廢水：指因雨水沖刷戶外設施、建築物表面或戶外作業環境之地面、原料及物料，而產生之廢水。\n前項第一款所稱之物，包括原料、中間產物、產品、副產品、廢棄物、廢氣、動物、植物或其他物品。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 4 條","text":"事業或污水下水道系統應採行經直轄市、縣（市）主管機關或中央主管機關委託之機關（以下簡稱核發機關）核准之水污染防治措施（以下簡稱水措），並依核准之水措內容運作。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 5 條","text":"事業或污水下水道系統有疏漏污染物或廢（污）水至水體、土壤之虞者，應採取維護及防範措施，其疏漏至作業環境之污染物或廢（污）水應收集處理，並記錄疏漏日期、時間、原因、水量及收集處理情形，保存三年。\n事業或污水下水道系統有疏漏污染物或廢（污）水致污染水體、土壤者，應立即採取緊急應變措施，於事件發生後三小時內，通知直轄市、縣（市）主管機關，並記錄疏漏日期、時間、原因、污染物種類、數量、水質、水量、通知主管機關方式、對象、日期、時間及應變措施。應變後十日內，應提報緊急應變紀錄及處理報告，報直轄市、縣（市）主管機關備查，並保存三年。\n前項緊急應變紀錄及處理報告應記載事項，規定如下：\n一、前項應記錄事項。\n二、應變內容及其排除、清理之方法。\n三、參與應變之人員及任務。\n四、因應緊急事故之水體、土壤監測計畫。\n五、後續因應改善之方法。\n六、其他經主管機關規定之事項。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 6 條","text":"天然災害或緊急事故發生時，事業或污水下水道系統應依主管機關之命令處理廢（污）水。","headingPath":["第 一 章 總則"]},{"type":"C","no":"","text":"第 二 章 逕流廢水管理","headingPath":["第 二 章 逕流廢水管理"]},{"type":"A","no":"第 7 條","text":"事業或污水下水道系統所產生之廢（污）水，應於作業環境內以溝渠、管線或容器收集，不得與雨水合流收集。但逕流廢水，不在此限。\n前項規定，既設事業或污水下水道系統於工程技術上難以達成者，得提出證明，並有防止合流後之廢（污）水直接排放之設施，經主管機關同意後，始得合流收集。","headingPath":["第 二 章 逕流廢水管理"]},{"type":"A","no":"第 8 條","text":"事業或污水下水道系統貯存或堆置下列物質，其逕流廢水含有其貯存或堆置之物質、成分者，應收集處理其逕流廢水：\n一、廢（污）水處理產生之污泥。\n二、煤渣、煤灰、飛灰、爐石、底渣。\n三、經雨水沖刷後，會溶出或產生本法公告有害健康物質之原料、物料、下腳料、產品或副產品。\n四、有害事業廢棄物。\n五、廢照明光源、廢乾電池、農藥廢容器、特殊環境衛生用藥廢容器、廢鉛蓄電池、廢潤滑油、廢機動車輛，及其處理過程產生之再生料或衍生之廢棄物。","headingPath":["第 二 章 逕流廢水管理"]},{"type":"A","no":"第 9 條","text":"採礦業、土石採取業、土石加工業、水泥業、土石方堆（棄）置場及營建工地，應於開挖面或堆置場所，舖設足以防止雨水進入之遮雨、擋雨及導雨設施。但遮雨、擋雨設施設置有困難，並經主管機關同意者，不在此限。\n前項之水泥業指將水泥、混凝土粒料及摻料，以水充分拌合後供運至工地澆鑄用者。\n第一項事業應設置沉砂池，收集及處理初期降雨及洗車平台產生之廢水，其沉砂池應符合下列規定：\n一、總設計容量應為工地或作業場所範圍總面積乘以○．○二五公尺以上。\n二、非下雨期間最高液面距池頂高度應大於池深之二分之一。\n三、應採不透水材質。\n擋雨、遮雨、導雨設施及沉砂池應定期維護、清理淤砂，並記錄清理維護時間及方法；其紀錄應保存三年，以備查閱。\n第一項事業依核發機關核准之內容採行第一項、第三項規定者，其逕流廢水經沉砂池處理後，得自核准之逕流廢水放流口排放。\n雨量大於第三項第一款規定沉砂池總設計容量時，超過總設計容量之逕流廢水量，得以繞流排放。\n第一項事業之辦公場所、員工宿舍產生之生活污水，應妥善收集處理。","headingPath":["第 二 章 逕流廢水管理"]},{"type":"A","no":"第 10 條","text":"營建工地應於施工前，檢具逕流廢水污染削減計畫（以下簡稱削減計畫），報請直轄市、縣（市）主管機關核准，並據以實施。\n削減計畫應記載事項，規定如下：\n一、基本資料。\n二、前條規定之污染削減措施及其工程圖說。\n三、目的事業主管機關核發之證明文件影本。\n削減計畫有下列情形之一者，營建工地應依其規定期限提出削減計畫之變更，報請直轄市、縣（市）主管機關核准，並據以實施：\n一、變更前項第一款或第三款記載事項，應自事實發生之翌日起三十日內辦理。須經目的事業主管機關核准者，自核准後三十日內為之。\n二、變更前項第二款記載事項，應於變更前辦理。\n三、經主管機關查核發現削減計畫內容不足以維護水體水質，而有污染之虞，經限期改善者，應於改善期限內辦理。\n營建工地之削減計畫應於中央主管機關指定之日起，採網路傳輸方式辦理。","headingPath":["第 二 章 逕流廢水管理"]},{"type":"A","no":"第 11 條","text":"非屬第九條及第十條之事業及污水下水道系統，應依其污染特性採取逕流廢水污染削減措施（以下簡稱削減措施）；其削減措施內容有變更，或經主管機關查核發現有不足以維護水體水質，而有污染之虞者，應於變更前或主管機關規定之期限內提出修正，報經審查核准後，據以實施。\n依前項規定採取削減措施之事業及污水下水道系統；其逕流廢水水質仍未能符合放流水標準，且經直轄市、縣（市）主管機關認定有污染水體水質之虞者，應收集處理逕流廢水。\n前項及屬第八條規定應收集處理逕流廢水之事業及污水下水道系統，其應收集處理逕流廢水量依個案許可審查核准。雨量大於應收集處理逕流廢水量時，始得繞流排放。\n前項事業及污水下水道系統，其逕流廢水收集設施之可收集量，於降雨停止五日後，應達許可核准之應收集處理量。","headingPath":["第 二 章 逕流廢水管理"]},{"type":"C","no":"","text":"第 三 章 廢（污）水（前）處理設施","headingPath":["第 三 章 廢（污）水（前）處理設施"]},{"type":"A","no":"第 12 條","text":"廢（污）水回收使用、稀釋、受託處理或經主管機關指定者，應於廢（污）水處理設施前，設置進流水獨立專用累計型水量計測設施。\n共同設置廢（污）水（前）處理設施處理廢（污）水者，其廢（污）水之輸送方式，應以管線或溝渠為之。","headingPath":["第 三 章 廢（污）水（前）處理設施"]},{"type":"A","no":"第 13 條","text":"事業或污水下水道系統產生廢（污）水之生產設施具有備用電力者，其廢（污）水（前）處理設施亦應具備足供運轉之備用電力。","headingPath":["第 三 章 廢（污）水（前）處理設施"]},{"type":"A","no":"第 14 條","text":"事業或污水下水道系統之廢（污）水（前）處理設施產生之污泥，應採行減量措施。\n廢（污）水（前）處理設施，應定期實施保養及適時維修，並作成紀錄，保存五年，以備查閱。","headingPath":["第 三 章 廢（污）水（前）處理設施"]},{"type":"A","no":"第 15 條","text":"事業或污水下水道系統設置之廢（污）水（前）處理設施未維持正常操作，經主管機關命限期改善者，於限期改善期間內，應維持既有設施正常操作，採行減少、停止生產或服務作業量，或改善廢（污）水（前）處理設施等措施，並不得超過主管機關據以通知限期改善之操作參數，且其他操作參數亦應符合正常範圍；違反者，按次處罰。\n前項改善措施，必須拆除既有設施，方能繼續施工者，應向核發機關辦理變更登記後，始得為之。","headingPath":["第 三 章 廢（污）水（前）處理設施"]},{"type":"A","no":"第 16 條","text":"事業或污水下水道系統於廢（污）水（前）處理設施裝置之獨立專用電度表，及操作參數量測設施，屬連續自動紀錄者，應依計測、量測設施之設計規格及頻率記錄；非屬連續自動紀錄者，應每日記錄其累計用電度數及操作參數值一次；廢（污）水（前）處理設施使用之藥品量，及污泥之產生、貯存、清運量，應按次記錄，每月統計。\n水措計畫及許可證（文件）核准登記有特殊情形之操作處理流程者，如原廢（污）水水質較佳、原廢（污）水水量偏低、暴雨或停電等情形，於特殊情形發生時，應記錄發生之特殊情形內容、起訖時間及期間，並依前項規定記錄相關數據。\n前二項紀錄及單據或發票之影本，應保存五年，以備查閱。","headingPath":["第 三 章 廢（污）水（前）處理設施"]},{"type":"A","no":"第 17 條","text":"事業或污水下水道系統設置之廢（污）水（前）處理設施獨立專用電度表，應符合下列事項：\n一、規格應符合度量衡法規之相關規定，並應能量測廢（污）水（前）處理設施之全部用電量。\n二、應有透明視窗。\n三、應由主管機關鉛封，或由電力業者鉛封，經主管機關確認，不得任意破壞。\n四、進出電路應標明來源及去處。\n維護更換前項電度表前，應向主管機關報備，始得拆封。維護更換期間之用電度數仍應加以記錄；其記錄方式應取得主管機關之同意。維護更換後一週內，應向主管機關報備。\n無法於廢（污）水（前）處理設施設置獨立專用電度表者，得經主管機關同意，以具有自動控制量測記錄功能之設施，量測記錄用電量。","headingPath":["第 三 章 廢（污）水（前）處理設施"]},{"type":"A","no":"第 18 條","text":"事業或污水下水道系統廢（污）水（前）處理設施發生故障超過二十四小時，應將無法處理之廢（污）水，妥善貯存，不得排放；修復時間超過三十日者，應暫時停止產生廢（污）水。\n事業或污水下水道系統應記錄前項故障時間、設施名稱、發生原因、廢（污）水產生量及其收集情形、修復方法及進度，並保存三年，以備查閱。","headingPath":["第 三 章 廢（污）水（前）處理設施"]},{"type":"A","no":"第 19 條","text":"事業或污水下水道系統得委託代操作者，代為操作廢（污）水（前）處理設施。\n代操作者代其他事業或污水下水道系統操作期間，致該事業或污水下水道系統，於最近一年內有下列情形之一者，事業或污水下水道系統不得委託其代為操作廢（污）水（前）處理設施：\n一、經主管機關查獲繞流排放。\n二、大量排放污染物，經主管機關認定嚴重影響附近水體水質。\n三、排放之廢（污）水含本法公告有害健康物質，經主管機關認定有危害公眾健康之虞。\n四、受主管機關裁處停工（業）。\n事業或污水下水道系統應置廢水處理專責人員者，其所委託之代操作人員，應具同一等級廢水處理專責人員資格；應設廢（污）水處理專責單位者，其所委託之代操作人員，應具甲級廢水處理專責人員資格。\n事業或污水下水道系統現場應置放代操作人員到達、離開之時間及操作維護情形之紀錄，並簽名確認；其紀錄應保存三年，以備查閱。","headingPath":["第 三 章 廢（污）水（前）處理設施"]},{"type":"C","no":"","text":"第 四 章 納入污水下水道系統","headingPath":["第 四 章 納入污水下水道系統"]},{"type":"A","no":"第 20 條","text":"污水下水道系統區域內之事業，未將其產生之廢（污）水納入污水下水道系統（以下簡稱納管）者，應經下水道管理機關（構）同意，並於取得廢（污）水排放地面水體許可證或簡易排放許可文件後，始得排放於地面水體。","headingPath":["第 四 章 納入污水下水道系統"]},{"type":"A","no":"第 21 條","text":"前條事業所產生之廢（污）水，不得排放於該排水區域內之專用雨水下水道。但經下水道管理機關（構）與主管機關同意者，不在此限。","headingPath":["第 四 章 納入污水下水道系統"]},{"type":"A","no":"第 22 條","text":"下水道管理機關（構）查獲區內納管事業未符合下水道水質標準，通知納管事業限期改善時，納管事業如採取納管以外之水措，應向核發機關提出許可證（文件）之申請。\n前項事業無法於規定期間內完成改善，經下水道管理機關（構）依下水道法規定，拒絕納入或通知停止使用者，於未取得核發機關核准之許可證（文件）前，應停止產生廢（污）水。\n下水道管理機關（構）通知事業限期改善及拒絕納入時，應同時通知主管機關。","headingPath":["第 四 章 納入污水下水道系統"]},{"type":"C","no":"","text":"第 五 章 土壤處理","headingPath":["第 五 章 土壤處理"]},{"type":"A","no":"第 23 條","text":"事業或污水下水道系統採土壤處理者，應併同採行其他經主管機關核准之水措，作為暫停土壤處理時之替代措施。但已依廢棄物清理法規定辦理，得以桶裝、槽車或其他非管線、溝渠，清除未符合放流水標準之廢（污）水，至作業環境外者，不在此限。","headingPath":["第 五 章 土壤處理"]},{"type":"A","no":"第 24 條","text":"事業或污水下水道系統產生之廢（污）水，應經前處理至符合土壤處理標準，始得採行土壤處理。","headingPath":["第 五 章 土壤處理"]},{"type":"A","no":"第 25 條","text":"事業或污水下水道系統有下列情形之一者，不適用本章規定：\n一、依農業事業廢棄物再利用管理辦法，取得農業主管機關核發畜牧糞尿水施灌農作個案再利用許可。\n二、依本辦法取得農業主管機關核准畜牧業沼液、沼渣作為農地肥分使用計畫。\n三、畜牧業及畜牧糞尿或生質能資源化處理中心（或沼氣再利用中心）經直轄市、縣（市）主管機關核准輸（運）送符合放流水標準之畜牧廢（污）水，作為植物澆灌。\n四、前款以外之事業或污水下水道系統，經直轄市、縣（市）主管機關核准輸（運）送符合放流水標準之廢（污）水，作為花木澆灌。\n五、設置不透水材質設施，隔絕廢（污）水與土壤接觸。","headingPath":["第 五 章 土壤處理"]},{"type":"A","no":"第 26 條","text":"事業或污水下水道系統應於土壤處理之適用土地區段下坡處設置攔水渠，妥善收集處理溢流之廢（污）水。但土壤處理後無溢流水者，不在此限。","headingPath":["第 五 章 土壤處理"]},{"type":"A","no":"第 27 條","text":"事業或污水下水道系統應依廢（污）水排放土壤處理許可證登記之排放期間，排放廢（污）水。但有下列情形之一者，應暫停排放廢（污）水：\n一、自中央氣象署發布大雨、豪雨特報日起，至解除日後三日之期間。\n二、土壤飽和萃取液導電度於二十五攝氏度，達每公分四毫西門。\n三、土壤監測結果達土壤污染監測標準之限值。\n四、地下水監測結果達地下水污染監測標準之限值。但地下水氨氮背景值高於地下水污染監測標準之限值，且地下水之氨氮監測值低於背景值者，不在此限。\n依前項第二款至第四款規定暫停排放廢（污）水者，應檢具檢測合格報告送直轄市、縣（市）主管機關核准後，始得繼續排放廢（污）水於土壤。","headingPath":["第 五 章 土壤處理"]},{"type":"A","no":"第 28 條","text":"事業或污水下水道系統採土壤處理者，應於排放廢（污）水於土壤前，設置採樣口。\n前項採樣口應符合下列規定：\n一、可供主管機關人員進出至採樣口之道路。\n二、設置獨立專用累計型水量計測設施，量測排放於土壤之廢（污）水水量。\n三、設置告示牌，並標示座標。\n四、可供直接採樣，未經直轄市、縣（市）主管機關核准，不得設置規避、妨礙或拒絕主管機關直接採樣之設施。\n事業或污水下水道系統經主管機關查獲有繞流排放情事、或經主管機關指定之非連續性排放廢（污）水者，其採樣口應設置於主管機關指定之位置。\n第二項第三款告示牌之設置，應符合下列規定：\n一、依核准內容記載事業或污水下水道系統名稱、管制編號、採樣口編號、座標、最大日排放水量。\n二、告示牌之規格，長度應為三十二公分以上、寬度應為十五公分以上；牌面底色為白色，標示文字應為黑色，文字字體應為一．五公分見方以上，且須清晰可見，並不得擅加其他圖案（如附圖一）。\n三、告示牌應固定於採樣口旁明顯處，設置高度應介於地面上五十公分至二公尺之間。\n四、告示牌之材質須堅固耐用。\n五、告示牌之安裝應穩固，不輕易移動。","headingPath":["第 五 章 土壤處理"]},{"type":"C","no":"","text":"第 六 章 委託與受託處理","headingPath":["第 六 章 委託與受託處理"]},{"type":"A","no":"第 29 條","text":"事業或污水下水道系統取得之水措計畫核准文件或許可證（文件），有餘裕量之登記事項，且符合下列情形者，得向核發機關申請並完成受託處理變更登記，始得受託處理廢（污）水：\n一、申請日前一年內，未因違反本法第七條規定，受主管機關裁處超過二次。但納管事業，於申請日前一年內，未受下水道管理機關（構）拒絕納入或通知停止使用。\n二、申請日前三年內，未經主管機關認定排放含本法公告有害健康物質之廢（污）水，危害公眾健康。\n三、申請日前三年內，未因違反本法規定，受主管機關裁處停工（業）。\n四、申請日前三年內，未經主管機關查獲繞流排放。","headingPath":["第 六 章 委託與受託處理"]},{"type":"A","no":"第 30 條","text":"事業或污水下水道系統受託處理廢（污）水（以下簡稱受託者），應符合下列規定：\n一、以受託處理同業別或同類型之廢（污）水為限。但經核發機關同意者，不在此限。\n二、每日受託處理之廢（污）水量，不得超過核准每日最大餘裕量。\n三、收受廢（污）水後，應於二十四小時內處理。","headingPath":["第 六 章 委託與受託處理"]},{"type":"A","no":"第 31 條","text":"委託事業或污水下水道系統處理廢（污）水（以下簡稱委託者），應設置廢（污）水（前）處理設施或貯留設施，貯存廢（污）水。\n委託者及受託者應於管線或溝渠之進流水、出流水端，設置獨立專用累計型水量計測設施。","headingPath":["第 六 章 委託與受託處理"]},{"type":"A","no":"第 32 條","text":"受託者因廢（污）水（前）處理設施故障，致無法處理受委託之廢（污）水時，應告知委託者停止輸送，並進行改善。無法受託處理廢（污）水期間超過三十日者，應停止受託處理，並向核發機關辦理水措計畫核准文件或許可證（文件）變更。\n受託者未依前項規定辦理變更，核發機關得逕行變更許可登記項目。\n受託者應記錄無法接受委託之原因、通知委託者停止輸送之時間、改善之狀況，並保存三年，以備查閱。","headingPath":["第 六 章 委託與受託處理"]},{"type":"A","no":"第 33 條","text":"委託者接獲受託者通知停止委託處理時，應收集貯留其廢（污）水；廢（污）水貯留超過三十日，且未取得經核發機關核准之其他水措，應停止產生廢（污）水。但已依廢棄物清理法規定辦理，得以桶裝、槽車或其他非管線、溝渠，清除未符合放流水標準之廢（污）水，至作業環境外者，不在此限。\n委託者應記錄受託者通知停止輸送之時間、每日廢（污）水產生量及貯留量、貯留設施之編號及數量，並保存三年，以備查閱。","headingPath":["第 六 章 委託與受託處理"]},{"type":"A","no":"第 34 條","text":"受託者於受託處理期間，一年內違反本法相關規定二次以上者，於第二次違反日起一年內，不得增加受託處理水量及對象。\n受託者於受託處理期間，有下列情形之一者，應停止受託處理：\n一、違反本法第七條規定，受主管機關裁處超過二次。但納管事業，經下水道管理機關（構）拒絕納入或通知停止使用。\n二、排放之廢（污）水含本法公告有害健康物質，經主管機關認定危害公眾健康。\n三、違反本法規定，受主管機關裁處停工（業）。\n四、經主管機關查獲繞流排放。","headingPath":["第 六 章 委託與受託處理"]},{"type":"C","no":"","text":"第 七 章 以管線排放海洋","headingPath":["第 七 章 以管線排放海洋"]},{"type":"A","no":"第 35 條","text":"事業或污水下水道系統以海放管排放廢（污）水於海洋者，應依下列規定辦理：\n一、海放管設置或變更施工應於完工後三十日內，報請主管機關備查。\n二、每年應定期檢視海放管結構，確認最初稀釋率達一百倍以上之功能，作成紀錄，並保存三年，以備查閱。\n三、海放管因故障、損壞，有影響排放或船舶航行安全之虞者，應立即進行修復或清除，並於發現故障、損壞後三小時內，通知主管機關。","headingPath":["第 七 章 以管線排放海洋"]},{"type":"A","no":"第 36 條","text":"事業或污水下水道系統以海放管排放廢（污）水於海洋者，海放管因故障或損壞，致其最初稀釋率無法達一百倍以上時，應依下列規定辦理：\n一、排放之廢（污）水，應符合放流水標準。\n二、無法排放於海洋時，得由主管機關許可之放流口，排放於地面水體。但排放期間超過九十日者，應向核發機關辦理許可證（文件）之變更。\n事業或污水下水道系統應記錄海放管故障或損壞之發生時間、通知時間、發生原因、修復狀況，並保存三年，以備查閱。","headingPath":["第 七 章 以管線排放海洋"]},{"type":"C","no":"","text":"第 八 章 貯留與稀釋","headingPath":["第 八 章 貯留與稀釋"]},{"type":"A","no":"第 37 條","text":"事業或污水下水道系統廢（污）水經許可採行稀釋者，應於廢（污）水（前）處理設施單元之調勻設施混合稀釋。\n前項調勻設施應設置獨立專用進流水累計型水量計測設施。\n有本法第十八條之一第三項所定之情形，因情況急迫，為搶救人員或經主管機關認定之重大處理設施而稀釋時，應記錄稀釋之起訖時間、原因、水量及通報時間，且於二十日內向直轄市、縣（市）主管機關及核發機關提出稀釋期間因應作為書面報告。\n前項書面報告應記載下列事項：\n一、稀釋發生原因及時間。\n二、通報對象、方式及時間。\n三、稀釋期間之因應作為。\n四、參與因應之人員及任務。\n五、因應稀釋之水體監測結果。\n六、後續因應改善作法。\n七、其他。","headingPath":["第 八 章 貯留與稀釋"]},{"type":"A","no":"第 38 條","text":"事業或污水下水道系統以桶裝、槽車或其他非管線、溝渠，清除、運送廢（污）水，至作業環境外者，應於作業環境內設置貯留設施，貯存尚未清除、運送前之廢（污）水。\n廢棄物掩埋場將滲出水返送至掩埋面者，應設置收集滲出水之貯留設施、抽水設施及逕流廢水之截流溝。","headingPath":["第 八 章 貯留與稀釋"]},{"type":"A","no":"第 39 條","text":"事業或污水下水道系統採貯留者，其貯留設施應設置進流水及出流水之獨立專用累計型水量計測設施，或自動記錄液位及顯示貯留水量之計測設施。\n事業或污水下水道系統，應逐日逐批記錄廢（污）水貯留時間、輸（運）送方式、水量及處理水量，並保存三年，以備查閱。\n依第十八條第一項或第三十三條第一項規定，因應緊急應變時之貯存設施，應依前二項規定辦理。\n廢（污）水貯留後，以桶裝、槽車或其他非管線、溝渠，清除未符合放流水標準之廢（污）水，至作業環境外者，於作業環境內，貯留期間超過三十日以上，且未取得經核發機關核准之其他水措，應停止產生廢（污）水。","headingPath":["第 八 章 貯留與稀釋"]},{"type":"A","no":"第 40 條","text":"事業或污水下水道系統貯留設施之容量應可容納緊急應變之需。","headingPath":["第 八 章 貯留與稀釋"]},{"type":"C","no":"","text":"第 九 章 回收使用","headingPath":["第 九 章 回收使用"]},{"type":"A","no":"第 41 條","text":"事業或污水下水道系統產生之廢（污）水，應處理至符合放流水標準始得回收使用，並於回收使用前，設置採樣口。但有下列情形之一者，不在此限：\n一、產生之廢（污）水作為製程之用。\n二、產生之廢（污）水回收作為洗滌塔或其他污染防治設備之用，且其回收使用後之水經設置之廢（污）水（前）處理設施處理。\n事業或污水下水道系統回收使用未符合放流水標準之廢（污）水，依下列規定辦理：\n一、未設置廢（污）水（前）處理設施處理回收使用後之水者，不得將未符合放流水標準之廢（污）水作為製程以外之用。\n二、以無須處理即能符合放流水標準之水源作為補充混合使用者，應提出下列資料，經直轄市、縣（市）主管機關核准，始得為之，並應按日記錄補充之水量，保存三年。\n（一）補充之必要性、補充水之來源、每日最大補充水量及其計算量測方式。\n（二）屬未設置廢（污）水（前）處理設施處理回收使用後之水者或經直轄市、縣（市）主管機關認定有必要者，應另提出質量平衡說明。\n主管機關查核事業或污水下水道系統有不符前項第二款經核准之情形者，應通知事業或污水下水道系統不得採行以無須處理即能符合放流水標準之水源作為補充用水。直轄市、縣（市）主管機關並應限期通知事業或污水下水道系統辦理水措計畫或許可證（文件）變更，逾期未辦理者，依違反本法規定處分。","headingPath":["第 九 章 回收使用"]},{"type":"A","no":"第 42 條","text":"前條回收使用後之水應符合放流水標準，始得排放於地面水體。但回收使用作為沖洗作業環境內辦公場所、員工宿舍及其他活動場所之室內用水，應符合建築物污水處理設施之放流水標準。\n前項回收使用之廢（污）水應避免與人體接觸影響健康。","headingPath":["第 九 章 回收使用"]},{"type":"A","no":"第 43 條","text":"回收使用廢（污）水者，應於廢（污）水產生及處理後，設置獨立專用累計型水量計測設施；回收前，設置回收使用之獨立專用累計型水量計測設施。\n廢（污）水回收使用者，應於回收使用前，設置廢（污）水（前）處理設施或貯留設施，貯存廢（污）水。","headingPath":["第 九 章 回收使用"]},{"type":"A","no":"第 43-1 條","text":"事業或污水下水道系統有下列情形之一者，不適用本章規定：\n一、廢（污）水尚未進入廢（污）水（前）處理設施，僅於製程循環。\n二、於放流池（槽、口）前之廢（污）水（前）處理設施各單元間迴流、返送。\n三、設置淨化原廢水回收系統，淨化後循環至製程使用，其淨化系統與後續廢（污）水處理設施可獨立分割，且回收系統無廢（污）水直接排放至地面水體或土壤。\n前項第三款淨化原廢水後回收至製程之行為，經主管機關認有未具淨化原廢水水質之功能之虞，直轄市、縣（市）主管機關應限期通知事業或污水下水道系統提出淨化回收系統減少原廢水污染量之說明資料。屆期未提出說明資料或主管機關認定未具淨化原廢水水質之功能者，直轄市、縣（市）主管機關應通知事業或污水下水道系統依本章規定辦理，並限期辦理水措計畫或許可證（文件）變更，逾期未辦理者，依違反本法規定處分。","headingPath":["第 九 章 回收使用"]},{"type":"C","no":"","text":"第 十 章 排放及其他廢（污）水管理","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 44 條","text":"（刪除）","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 45 條","text":"船舶解體業應於拆解場所四週設置截流設施，並採取下列措施。但設置截流設施有困難者，經主管機關同意，得以足以防堵廢水污染水體之設施為之：\n一、於作業區域周圍水面，佈設浮油攔除設備。\n二、於作業區域，設置適當廢油、廢水及其他污染物收受設施。\n三、其他經主管機關指定之措施。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 46 條","text":"畜牧業採漁牧綜合經營者，應依下列規定辦理：\n一、每日排放至每公頃魚池之廢水量，在四立方公尺以下。\n二、每公頃魚池容納二百頭豬隻以下之廢水量。\n三、魚池溶氧應達一．○毫克／公升以上。\n四、魚池最高液面距魚池四周池頂高度維持三十公分以上。但雨季期間，不在此限。\n五、記錄清洗畜舍時間、廢水排放於魚池之水量及魚池廢水排放時間；其紀錄應保存三年，以備查閱。\n六、排放前三日應主動通知主管機關。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 46-1 條","text":"飼養豬隻或牛隻之畜牧業，應採行下列畜牧糞尿資源化處理措施之一：\n一、經農業主管機關依農業事業廢棄物再利用管理辦法規定，核准畜牧糞尿水施灌農作個案再利用。\n二、經農業主管機關依本辦法規定，核准沼液、沼渣作為農地肥分使用。\n三、經直轄市、縣（市）主管機關核准輸（運）送符合放流水標準之廢（污）水，作為植物澆灌。\n前項畜牧糞尿資源化處理比率規定如下：\n一、於本辦法中華民國一百零六年十二月二十七日修正施行後始取得畜牧場登記證者，應達總廢水產生量之百分之十。\n二、於本辦法中華民國一百零六年十二月二十七日修正施行前已取得畜牧場登記證，且已採行排放畜牧廢水於地面水體者：\n（一）飼養豬隻二千頭以上或牛隻五百頭以上之畜牧業，其畜牧糞尿資源化處理比率，自中華民國一百零六年十二月二十七日起五年內應達總廢水產生量百分之五、十年內應達總廢水產生量百分之十。\n（二）飼養豬隻二十頭以上未滿二千頭或牛隻四十頭以上未滿五百頭之畜牧業，其畜牧糞尿資源化處理比率，自中華民國一百零六年十二月二十七日起八年內應達總廢水產生量百分之五、十二年內應達總廢水產生量百分之十。\n前項總廢水產生量係指核准許可證（文件）或廢（污）水管理計畫登記之原廢水產生量。但實際在養頭數低於登記飼養頭數時，畜牧業得提出實際在養頭數經直轄市、縣（市）主管機關認定後，核定其總廢水產生量。\n第二項第二款之畜牧業，於本辦法中華民國一百零六年十二月二十七日修正施行前已採行第一項畜牧糞尿資源化處理措施者，其畜牧糞尿資源化處理比率得納入計算。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 47 條","text":"自來水廠為維持正常供水，於中央氣象署發布豪雨特報或天然災害發生時，其原水懸浮固體濃度超過每公升二千毫克或濁度超過二千濁度單位（NTU），致廢水處理設施無法正常操作，得採取緊急應變措施，直接排放。\n自來水廠應將前項緊急應變措施，納入水措計畫核准文件或許可證（文件），並依下列規定辦理：\n一、沉澱池及污泥濃縮池，應先淨空。\n二、排放前應先通知下游用水者，及通報當地主管機關。\n三、排放期間應按日檢測並記錄原水濁度、懸浮固體濃度及放流水懸浮固體濃度；其檢測紀錄應保存五年，以備查閱。\n自來水廠因採取緊急應變措施所造成之淤積或損害，應負責清除或修復。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 48 條","text":"餐飲業、觀光旅館（飯店）提供餐飲服務者，應設置油脂截留設施，去除餐飲廢水中之油脂。\n餐飲業、觀光旅館（飯店）提供溫泉泡湯服務者，其既設事業之大眾池，及新設事業之泡湯設施所產生之單純泡湯廢水，應與其他作業廢水分流收集處理。\n前項單純泡湯廢水，應經毛髮過濾設施及懸浮固體過濾設施處理。但泥漿泉質者，不在此限。\n前項處理後之放流水，除水溫外，其他項目水質雖超過放流水標準，但未超過原水水質者，得直接放流至該溫泉泉源所屬之地面水體。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49 條","text":"餐飲業、觀光旅館（飯店）設置之油脂截留設施、毛髮過濾設施及懸浮固體過濾設施，應定期清理維護，並記錄清理維護時間及方法；其紀錄應保存三年，以備查閱。\n前項油脂截留設施，應依建築物污水處理設施設計技術規範辦理。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-1 條","text":"事業運作之物質為地下水污染管制標準污染物項目中之有機物者，其貯存與輸送前述物質之設施，應視滲漏潛勢，選用足以防止滲漏之適當材質，並定期巡查檢視，以預防污染土壤、地下水。\n前項定期巡查檢視應作成紀錄，並保存三年備查。\n第一項事業屬貯存系統，且貯存本法第三十三條第一項經中央主管機關公告指定之有機物者，應依本法第三十三條第二項及第三項所定辦法辦理。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-2 條","text":"事業收容處理淤泥或含水量大於百分之三十之土壤、連續壁產生之皂土等營建剩餘土石方者，應每日記錄前述營建剩餘土石方之載運車輛進出情形、收容處理之土質種類、收容量及處理量，並作成紀錄，保存三年備查。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-3 條","text":"營建工地施工期間，於其周圍排水溝排放管線底部、進入水體處及其周圍環境，形成可見之沉積污泥時，營建業主應予以清除，或依主管機關之命令，於三天內清除。\n施工機具、車輛維修、保養所棄置或溢洩之廢機油、潤滑油、柴油等，營建業主應以適當之儲存設備收集處理，不得隨廢（污）水或逕流廢水排放或溢流於作業環境外。\n前二項沉積污泥之清除、廢油之收集處理，營建業主應每次記錄清除、收集處理時間及方法，其紀錄及妥善處理證明文件，應保存至營建工地完工，且經直轄市、縣（市）主管機關解除本法管制，以備查閱。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-4 條","text":"事業屬設置洗腎治療（血液透析）床（台）之診所（以下簡稱洗腎診所）應於營運前，檢具廢（污）水管理計畫，報請直轄市、縣（市）主管機關核准，並據以實施，始得排放廢（污）水。直轄市、縣（市）主管機關於核准廢（污）水管理計畫前，應進行現場勘察。\n洗腎診所之廢（污）水得以建築物污水處理設施處理，其廢（污）水管理計畫應記載事項，規定如下：\n一、基本資料。\n二、用水來源與用水量、廢（污）水及污泥產生、處理及排放資料。\n三、放流口。\n四、同意廢止已取得水污染防治措施計畫或許可證（文件）之承諾書。\n廢（污）水管理計畫有變更者，洗腎診所應依下列規定期限辦理廢（污）水管理計畫之變更，報請直轄市、縣（市）主管機關核准，並據以實施。必要時，直轄市、縣（市）主管機關應於核准前進行現場勘察確認：\n一、變更前項第一款記載事項者，應自事實發生之翌日起三十日內辦理。須經目的事業主管機關核准者，自核准後三十日內為之。\n二、變更前項第二款記載事項，應於變更前辦理。但屬下列記載事項之變更者，應自事實發生之翌日起三十日內辦理：\n（一）廢（污）水水量、污泥量之計測設施、計量方式及其校正維護方法。\n（二）核准餘裕量內委託者及其委託廢（污）水量。\n（三）廢（污）水處理設施單元汰舊換新，且其規格條件及功能皆與原核准計畫相符。\n（四）僅變更廢（污）水處理設施單元之附屬機具設施。\n三、變更前項第三款記載事項，應於變更前辦理。\n已取得水措計畫或許可證（文件）之洗腎診所，其廢（污）水管理計畫尚未經直轄市、縣（市）主管機關核准前，應依原核准事項辦理。其廢（污）水管理計畫經直轄市、縣（市）主管機關核准後，得請求廢止水措計畫或許可證（文件）。\n已取得水措計畫或許可證（文件）之洗腎診所，得免辦理變更或展延水污染防治措施計畫或許可證（文件），逕依第一項規定申請核准廢（污）水管理計畫。\n洗腎診所之廢（污）水管理計畫應於中央主管機關指定之日起，採網路傳輸方式辦理。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-5 條","text":"飼養豬隻二十頭以上未滿二百頭之畜牧業，於本辦法中華民國一百零六年十二月二十七日修正施行後始取得畜牧場登記證者，應於營運前，檢具廢（污）水管理計畫，報請直轄市、縣（市）主管機關核准，始得營運產生廢（污）水。直轄市、縣（市）主管機關於核准廢（污）水管理計畫前，應進行現場勘察；其涉及沼液沼渣農地肥分使用者，直轄市、縣（市）主管機關應邀請農業主管機關參與審查。\n飼養豬隻二十頭以上未滿二百頭之畜牧業，於本辦法中華民國一百零六年十二月二十七日修正施行前之既設者，應依下列規定之對象及期限檢具廢（污）水管理計畫，並依前項規定辦理：\n一、飼養豬隻一百頭以上未滿二百頭之畜牧業：應於中華民國一百零八年十二月三十一日前完成。\n二、飼養豬隻二十頭以上未滿一百頭之畜牧業：應於中華民國一百零九年十二月三十一日前完成。\n前二項廢（污）水管理計畫應記載下列事項：\n一、基本資料。\n二、用水來源與用水量、廢（污）水及污泥產生、處理及排放資料。\n三、放流口。\n四、依第四十六條之一規定應符合之畜牧糞尿資源化處理比率。\n五、沼液沼渣農地肥分使用者，其沼液沼渣農地肥分使用資料。\n前項沼液沼渣農地肥分使用者應檢具下列內容及文件：\n一、畜牧場登記證書或畜禽飼養登記證影本。但未領有畜牧場登記證書或畜禽飼養登記證者，免檢附。\n二、沼液、沼渣作為農地肥分之場址（以下簡稱施灌農地）所有權證明文件；施灌農地非申請者所有，應檢附所有人、管理人或使用人使用同意書影本。\n三、施灌農地地號、地籍謄本影本、面積及作物別。\n四、沼液沼渣輸（運）送方式及路線。\n五、施灌作業，應含沼液沼渣施灌數量、方式、頻率、用途。\n飼養豬隻二十頭以上未滿二百頭之畜牧業廢（污）水管理計畫，涉及沼液沼渣農地肥分使用資料應符合第七十條之一第一項各款規定。\n廢（污）水管理計畫應採網路傳輸方式辦理。但經直轄市、縣（市）主管機關同意者，得採書面方式辦理。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-6 條","text":"前條第三項廢（污）水管理計畫第一款至第三款、第五款記載事項有變更者，飼養豬隻二十頭以上未滿二百頭之畜牧業應依下列規定之期限檢具修正之廢（污）水管理計畫，報請直轄市、縣（市）主管機關核准，並據以實施。涉及第五款之沼液沼渣農地肥分使用資料者，直轄市、縣（市）主管機關應邀請農業主管機關參與審查；必要時，直轄市、縣（市）主管機關應於核准前進行現場勘察確認：\n一、變更前條第三項第一款記載事項者，應自事實發生之翌日起三十日內辦理。但須經目的事業主管機關核准者，自核准後三十日內為之。\n二、變更前條第三項第二款記載事項，應於變更前辦理。但屬下列記載事項之變更者，應自事實發生之翌日起三十日內辦理：\n（一）廢（污）水水量、污泥量之計測設施、計量方式及其校正維護方法。\n（二）核准餘裕量內委託者及其委託廢（污）水量。\n（三）廢（污）水處理設施單元汰舊換新，且其規格條件及功能皆與原核准計畫相符。\n（四）僅變更廢（污）水處理設施單元之附屬機具設施。\n（五）厭氧沼氣收集袋或貯存槽。\n三、變更前條第三項第三款記載事項，應於變更前辦理。\n四、變更前條第三項第五款記載事項，應於變更前辦理。但變更或終止前條第四項第二款之施灌農地使用同意書，或變更施灌者名稱、地址、負責人，應自事實發生之翌日起三十日內辦理。\n僅涉及增加施灌農地，且位於原核准施灌農地周界三公里範圍內者，直轄市、縣（市）主管機關得免檢測施灌農地區域地下水水質、土壤品質之背景值。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-7 條","text":"飼養豬隻二十頭以上未滿二百頭之畜牧業，委託經地方政府補助設置畜牧糞尿資源化處理設施處理其他畜牧場畜牧糞尿者，其廢（污）水管理計畫之申請、變更相關規定，應依中央主管機關補助地方政府之計畫辦理。\n直轄市、縣（市）主管機關依前項計畫之規定，於竣工查驗通過後，應將畜牧糞尿資源化處理設施處理其他畜牧場畜牧糞尿計畫內容納入廢（污）水管理計畫，並通知該畜牧業確認記載事項後，核准或換發其廢（污）水管理計畫。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-8 條","text":"使用燃煤之發電廠，應於中華民國一百零七年一月一日起，記錄下列事項，並保存三年：\n一、每批次採購燃煤來源及總汞含量。\n二、每日（次）燃煤使用量及每月統計量。\n前項第一款之總汞含量，得以採購驗收資料或分析資料為之。\n使用燃煤之發電廠應依中央主管機關規定之格式，於每年一月及七月底前，以網路傳輸方式向直轄市、縣（市）主管機關申報前半年採購燃煤來源、總汞含量及每月燃煤使用量。\n第一項事業單次採購燃煤之總汞含量高於乾基每公斤濃度零點四五毫克或前一年採購燃煤之總汞含量加權平均值高於乾基每公斤濃度零點三毫克者，應提出汞總量管理計畫，經直轄市、縣（市）主管機關審查核准，依核准內容執行。採購燃煤之總汞含量加權平均值，依下列公式計算：\nΣ（Mi×Ci）\n──────\n    ΣMi\n一、i ：指採購燃煤批次。\n二、Mi：每批次採購之燃煤量。\n三、Ci：每批次採購之燃煤總汞含量。\n前項汞總量管理計畫應包括下列項目：\n一、基本資料表。\n二、廢（污）水排放特性。\n三、汞總量管理之目標及期程。\n四、汞總量管理之具體執行措施及內容。\n五、汞總量管理之成效評估及驗證方法。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-9 條","text":"晶圓製造及半導體製造業、光電材料及元件製造業、印刷電路板製造業、電鍍業和金屬表面處理業符合下列情形之一者，其作業廢水應分流收集處理：\n一、中華民國一百零六年十二月二十七日前尚未完成工程招標。\n二、中華民國一百零六年十二月二十七日後新增製程單元及廢（污）水處理設施。\n三、經主管機關查獲有繞流排放之情事涉及應進行工程改善。\n四、違反本法相關規定，經主管機關裁處停工（業）或於限期改善期間內自報停工（業）、其申請復工（業）。\n前項事業應分流收集處理作業廢水，規定如下：\n一、晶圓製造及半導體製造業、光電材料及元件製造業和印刷電路板製造業：\n（一）研磨或切割廢水。\n（二）氟系（含氟）廢水。\n（三）氫氧化四甲基銨（TMAH）有機廢水。\n（四）氰系（含氰）廢水。\n（五）鉻系（含鉻）廢水。\n（六）銅系（含銅）廢水。\n二、電鍍業、金屬表面處理業：\n（一）氰系（含氰）廢水。\n（二）鉻系（含鉻）廢水。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-10 條","text":"經直轄市、縣（市）主管機關審查核定沼液沼渣農地肥分使用資料者，有第七十條之六第一項各款情形之一時，應暫停沼液沼渣農地肥分使用。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-11 條","text":"直轄市、縣（市）主管機關審查及核准飼養豬隻二十頭以上未滿二百頭之畜牧業廢（污）水管理計畫之沼液沼渣農地肥分使用資料時，依下列規定辦理：\n一、應提供施灌紀錄表格式及暫停沼液沼渣作為農地肥分期間之因應措施。\n二、應依沼液沼渣品質，核准第七十條之一第二項各款事項。其沼液沼渣品質以前一年通過審查之平均值為之。\n三、核准之記載事項，應符合第七十條之四第一款、第二款及第四款規定。\n直轄市、縣（市）主管機關查獲未依廢（污）水管理計畫之沼液沼渣農地肥分使用資料執行者，應要求業者改善；有下列情形之一，應停止其沼液沼渣農地肥分使用：\n一、申請資料內容與事實不符。\n二、未依核准之沼液沼渣農地肥分使用資料進行農地肥分使用。\n三、未依第四十九條之六條第一項規定辦理變更，經主管機關通知限期改善或補正，屆期仍未改善或補正。\n四、其他違法情形，經主管機關認定情節重大。\n直轄市、縣（市）主管機關應於核准沼液沼渣農地肥分使用資料後，每二年執行一次區域性之沼液沼渣品質、土壤品質及地下水水質監測，其監測項目如下：\n一、沼液、沼渣品質應包含總氮、總磷、銅、鋅等項目。\n二、地下水水質應包含氨氮等項目。\n三、施灌農地土壤品質應包含銅、鋅等項目及土壤質地。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 49-12 條","text":"自中華民國一百十五年一月一日起，事業或污水下水道系統符合附表五所列業別及規模者，於申請、變更或展延水措計畫或許可證（文件）時，其廢（污）水或污泥處理評估優先採行附表五所列之最佳可行控制技術。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 50 條","text":"事業或污水下水道系統設置之下列水污染防治設施及管線，應清楚及正確標示其名稱與管線內流體名稱及流向，其標示並應符合水污染防治措施計畫或許可證（文件）核准之內容：\n一、用水、廢（污）水之收集、前處理、處理、迴流、排放、貯存等管線及處理單元。\n二、緊急應變之繞流管線。\n三、貯留、稀釋、回收使用之管線及貯槽單元。\n四、獨立專用累計型水量計測設施、廢（污）水（前）處理設施獨立專用電度表。\n五、污泥之收集、處理及貯存等管線及處理單元。\n主管機關查獲事業或污水下水道系統未依前項規定標示，應命其於一定期限完成改正，事業或污水下水道系統未於期限內完成改正，依違反本辦法處分。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 51 條","text":"事業或污水下水道系統自水體取水作為冷卻或循環之用，其屬未接觸冷卻水者，除水溫及氫離子濃度指數外，其他水質項目雖超過放流水標準，但未超過進水水質，得直接排放於原取水區位之地面水體。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 52 條","text":"事業或污水下水道系統有本法第十八條之一第三項所定之情形，因情況急迫，為搶救人員或經主管機關認定之重大處理設施而繞流排放時，應記錄繞流排放之起訖時間、原因、水量及通報時間，且於二十日內向直轄市、縣（市）主管機關及核發機關提出繞流排放期間因應作為書面報告。\n前項書面報告應記載下列事項：\n一、繞流排放發生原因及時間。\n二、通報對象、方式及時間。\n三、繞流排放期間之因應作為。\n四、參與因應之人員及任務。\n五、因應繞流排放之水體監測結果。\n六、後續因應改善作法。\n七、其他。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 53 條","text":"事業或污水下水道系統之放流口應符合下列規定：\n一、應設置於作業環境外，進入承受水體前之地面。\n二、作業環境外應有供採樣人員進出至放流口之道路，並設置一平方公尺以上之採樣平台。\n三、應設置獨立專用累計型水量計測設施量測放流水量。但逕流廢水放流口，不在此限。\n四、設置告示牌，並標示座標。\n五、可供直接採樣，未經主管機關核准，不得設置規避、妨礙或拒絕主管機關直接採樣之設施。\n六、放流口為陰井者，應使陰井之水質充分均勻混合。\n前項第一款、第二款規定，實際設置有困難，並經主管機關核准者，依核准之規定辦理。但有第五十六條第一項各款情形之一情事或非連續性排放廢（污）水，且有繞流排放之虞，經主管機關指定者，其放流口應設置於作業環境外主管機關指定之位置。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 54 條","text":"事業或污水下水道系統共同以海放管排放廢（污）水於海洋者，應於共同之廢（污）水（前）處理設施至海放管線間適當位置，設置放流口；無共同廢（污）水（前）處理設施者，應分別於各事業或污水下水道系統作業環境外至海放管線間適當位置，設置放流口。\n事業或污水下水道系統沿灌溉渠道或各級排水路以掛管方式排放廢（污）水，其放流口應設置於廢（污）水進入承受水體前之注入點；以共同排放管線排放廢（污）水者，應分別於各事業或污水下水道系統作業環境外至共同排放管線間適當位置，設置採樣口。\n前項採樣口之設置，應準用前條規定辦理。自採樣口排放廢（污）水者，依繞流排放處分。\n本辦法中華民國一百零四年十一月二十四日修正施行前已採共同排放者，應於一百零五年三月三十一日前完成採樣口之設置及水污染防治許可證（文件）之變更。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 55 條","text":"放流口告示牌之設置，準用第二十八條第四項之規定。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 56 條","text":"事業或污水下水道系統有下列情形之一者，應依規定期限向直轄市、縣（市）主管機關申請並完成自動監測（視）設施、電子式電度表之設置。除電子式電度表外，均應與直轄市、縣（市）主管機關維持正常連線傳輸功能：\n一、經主管機關查獲有繞流排放之情事。\n二、違反本法相關規定，經主管機關裁處停工（業）或於限期改善期間內自報停工（業），其申請復工（業）。\n三、大量排放污染物，經主管機關認定嚴重影響附近水體水質。\n四、排放之廢（污）水含本法公告有害健康物質，經主管機關認定有危害公眾健康之虞。\n五、申請水措計畫或許可證（文件）日前二年內，同一地址、座落位置或土地區段，曾有業者違反本法相關規定，經主管機關裁處停工（業）、於限期改善期間內自報停工（業）或查獲繞流排放。\n六、廢（污）水（前）處理設施功能不足。\n事業或污水下水道系統有前項第一款違規情事，且放流口設置於作業環境內者，應依規定期限向直轄市、縣（市）主管機關申請及完成設置放流水水量、水質自動顯示看板（以下簡稱顯示看板），並應與直轄市、縣（市）主管機關維持正常連線傳輸功能。\n事業或污水下水道系統有第一項第一款至第四款或第六款違規情事者，以下簡稱重大違規者；有第五款情形者，以下簡稱強制設置者。\n有下列情形之一者，於各款規定期間不得排放廢（污）水。取得核發機關核准之許可證（文件）者，未完成設置前，亦不得排放廢（污）水。但依主管機關核定執行相對誤差測試及連續一百六十八個小時傳輸測試之期間，不在此限：\n一、未依第一項、第二項規定期限完成設置，自規定期限屆滿之翌日起至完成設置之期間。\n二、依第六項申請延長設置期限經主管機關同意，自延長設置期限之起始日至完成設置之期間。\n三、經主管機關依本法處分並通知限期完成設置，其限期改善期間，及逾限期改善期限仍未完成設置，自期限屆滿之翌日起至完成設置之期間。\n第一項、第二項之規定期限如下：\n一、重大違規者，以接獲主管機關裁處書或書面通知之日起一百八十日內為之。但有下列情形之一者，依其規定：\n（一）屬申請復工（業）之事業，應於核准復工（業）前完成設置。\n（二）對裁處書提起行政救濟，於原處分確定維持之日起一百八十日內為之。\n二、強制設置者，應於水措計畫或許可證（文件）申請之日起一百八十日內為之。但第一項第五款規定之曾受裁處業者對裁處書提起行政救濟時，強制設置者應依前款第二目規定辦理。\n無法依前項所定之期限完成設置之重大違規者或強制設置者，除前項第一款第一目情形外，得於期限屆滿十四日前向直轄市、縣（市）主管機關申請延長設置期限，並依直轄市、縣（市）主管機關同意之期限辦理。直轄市、縣（市）主管機關延長設置期限，累計總日數不得超過一百八十日。\n第五項之裁處書或書面通知由中央主管機關開立者，重大違規者應向直轄市、縣（市）主管機關辦理自動監測（視）設施、電子式電度表及顯示看板之申請設置或展延。\n依第一項或第二項規定設置之設施，設置時檢具之自動監測（視）設施確認報告書（以下簡稱確認報告書）經直轄市、縣（市）主管機關審查確認之日起，累計正常日數達三百六十五日以上，且無第一項任一款情事或其他監測數據虛偽不實或造假紀錄者，得向直轄市、縣（市）主管機關申請經同意後，免除設置。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 57 條","text":"重大違規者或強制設置者依前條規定設置自動監測（視）設施、電子式電度表及顯示看板，應依附表二規定辦理，並維持其正常功能。\n依前條第二項設置顯示看板之重大違規者，其顯示看板發生故障時，應立即以電話或傳真向直轄市、縣（市）主管機關報備，並記錄故障時間、報備發話人、受話人姓名、職稱。故障或校正維護期間，應依直轄市、縣（市）主管機關同意之替代方式公布監測數據。\n前項顯示看板故障無法於二十四小時內，恢復正常功能者，應於故障發生之日起二日內，向直轄市、縣（市）主管機關報備預定採取之修護措施及修護完成日期。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 57-1 條","text":"主管機關查證事業或污水下水道系統之廢（污）水處理、排放或委託處理輸送之水量，發現有未依核准登記之頻率、時段等情事，得命限期提報相關說明與佐證資料。\n事業或污水下水道系統未依期限提報或提報資料經主管機關認定無正當理由者，主管機關得命其依指定位置及期限設置水量自動監測設施及連線傳輸設施，並與直轄市、縣（市）主管機關維持正常連線傳輸功能。\n依前項規定設置之設施，於設置時檢具之水量自動監測設施確認報告書經直轄市、縣（市）主管機關審查確認之日起，累計正常日數達三百六十五日以上，且已依核准登記之頻率、時段，處理、排放或委託處理輸送，經直轄市、縣（市）主管機關同意後，得免除設置。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 58 條","text":"（刪除）","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 59 條","text":"事業或污水下水道系統採廢（污）水（前）處理設施且有下列情形之一者，應依主管機關規定期限，進行功能測試：\n一、第五十六條第一項第一款。\n二、操作參數異常。\n三、水質水量平衡異常。\n四、有未經許可稀釋之虞。\n五、廢（污）水（前）處理設施有功能不足之虞。\n前項功能測試完成後，事業或污水下水道系統應提報功能測試報告；涉及水措計畫核准文件或許可證（文件）之變更者，應依規定辦理變更；應經技師簽證者，該功能測試報告應由共同參與功能測試之技師簽證。\n事業或污水下水道系統功能測試結果，其水質未符合本法所定管制標準者，應採行減少、停止生產、服務或其他應變措施。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 60 條","text":"事業或污水下水道系統依前條規定進行功能測試時，應依下列規定辦理：\n一、依核發機關核准之每日最大廢（污）水產生量，測試其廢（污）水（前）處理設施或污泥處理設施。但操作條件未達核准之每日最大廢（污）水產生量者，應以定期檢測申報或實際已達之經常最大廢（污）水產生量為準。\n二、功能測試期間應為五個工作天以上；檢測當日應於功能測試前三日通知主管機關會同進行。\n前項第二款功能檢測當日應進行之工作內容，規定如下：\n一、量測原廢（污）水及處理後之水量各一次、檢測原廢（污）水水質一次、檢測各設施單元操作參數一次。\n二、處理後之水質檢測方式：\n（一）屬二十四小時連續排放者，應每四小時採樣一次，共採樣六次，每連續二次採樣混合成一個樣品，共計混合成三個樣品進行檢測，取其平均值。\n（二）非屬二十四小時連續排放者，依每日排放時間，平均分成四次採樣，每連續二次採樣混合成一個樣品，共計混合成二個樣品進行檢測，取其平均值。\n三、功能測試時應檢驗之水質項目，依附表一規定各業別之申報項目為之。但主管機關另有指定者，依指定項目辦理。\n四、水量及水質之採樣及檢測，應委託中央主管機關核發許可證之環境檢驗測定機構辦理。\n五、功能測試參與單位應包含：製程操作單位、處理程序操作單位、取樣單位、檢測單位。屬應經技師簽證者，其簽證技師應共同參與。\n六、有二股廢（污）水水源及二套以上之廢（污）水（前）處理設施者，應就各股及各套進行量測及檢測。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 60-1 條","text":"（刪除）","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 61 條","text":"事業或污水下水道系統之廢（污）水排入灌溉渠道者，應先取得灌溉渠道管理機關（構）或所有人同意，始得排入。\n前項之管理機關（構）或所有人拒絕事業或污水下水道系統之廢（污）水排入時，應同時通知主管機關。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 62 條","text":"事業或污水下水道系統有未經許可之廢（污）水排放、貯留、稀釋、注入地下水體、土壤處理、繞流排放或未符規定之管線、設施者，應依主管機關限期改善命令，封閉、拆移該管線或設施。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 63 條","text":"事業或污水下水道系統排放廢（污）水，於排放管線底部、進入水體處及其周圍環境，形成可見之沉積污泥時，應予以清除，或依主管機關之命令，於限期內清除。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 64 條","text":"事業或污水下水道系統有二種以上不同業別或同一業別有不同製程，其廢水混合處理及排放者，應符合各該業別之放流水標準。相同之管制項目有不同管制限值者，應符合較嚴之限值標準。\n前項各業別中之一種業別廢水水量達總廢水量百分之七十五以上，並裝設有獨立專用累計型水量計測設施者，得向主管機關申請對共同管制項目以該業別放流水標準管制。\n前項廢水量所佔比例，以申請日前半年之紀錄計算之。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 65 條","text":"事業或污水下水道系統設置之累計型水量計測設施，應妥善維護，維持其正常功能，並應依其廠牌規定之頻率校正。但廠牌規定之校正頻率大於一年者，應每年至少校正一次。\n前項累計型水量計測設施之性能規格，於可量測流量範圍內之準確度應在正負百分之五以內。但非循環使用之未接觸冷卻水，以馬達之運轉時間計算流量者，不在此限。\n事業或污水下水道系統於校正維護累計型水量計測設施時，應記錄其校正維護日期、校正維護期間之水量及校正維護結果，並保存五年。校正維護期間水量之記錄方式應依主管機關同意之方式為之。\n主管機關查核事業或污水下水道系統有下列情形之一者，得以實際量測或由其各項用水來源之憑證、水量平衡圖推估核算其廢（污）水排放量：\n一、累計型水量計測設施異常者。\n二、廢（污）水排放量與許可登記量差距過大。\n三、未依第一項規定校正、維護累計型水量計測設施。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 66 條","text":"事業或污水下水道系統依本辦法規定設置之獨立專用累計型水量計測設施，有設置困難，經主管機關同意者，得以足以證明水量之計測設施或計量方式為之。\n前項設施為連續自動記錄者，事業或污水下水道系統應依計測設施之設計規格及頻率記錄；非為連續自動記錄者，應每日記錄其累計水量讀數，並保存五年，以備查閱。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 67 條","text":"事業作業環境內之辦公場所、員工宿舍及其他活動場所、建築物所產生之污水，管理方式如下：\n一、污水與事業廢水合併處理者，依事業廢水管理方式辦理。\n二、污水未與事業廢水合併處理者，依建築物污水處理設施管理方式辦理，並應設置放流口。\n前項第二款之放流口應依第五十三條規定辦理。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 68 條","text":"事業或污水下水道系統經主管機關裁處或自行停工（業）、歇業者，其作業環境之剩餘廢（污）水應由該事業負責人或污水下水道系統之所有人、使用人或管理人，依本法規定處理及排放。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 69 條","text":"（刪除）","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"A","no":"第 70 條","text":"事業經下水道主管機關指定為應設置專用污水下水道系統之地區或場所者，應符合本法及相關法規所定事業應遵行之規定。","headingPath":["第 十 章 排放及其他廢（污）水管理"]},{"type":"C","no":"","text":"第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-1 條","text":"沼液沼渣農地肥分使用者，應檢具沼液沼渣作為農地肥分使用計畫（以下簡稱沼液沼渣農地肥分使用計畫），向農業主管機關提出申請，經農業主管機關審查同意後，報直轄市、縣（市）環保主管機關備查，並依登記事項運作，其沼液、沼渣作為肥分，應符合下列規定：\n一、畜牧糞尿排入厭氧發酵設施，應能妥善收集沼氣，厭氧發酵天數，其為非草食性動物之畜牧業十天以上；其為草食性動物之畜牧業五天以上，並應定期排出沼液、沼渣。但農業主管機關依個別計畫審查結果另為核定厭氧發酵天數者，依其核定之厭氧發酵天數。\n二、施灌農地非沼液沼渣農地肥分使用者所有，應與施灌農地所有人、管理人或使用人簽訂共同執行沼液沼渣農地肥分使用計畫之合約或出具同意書。\n三、沼液、沼渣應於施灌後一小時內，完全滲入土壤，施灌農地表面不得積留沼液。但以灌溉水混合溝灌或漫灌，不在此限。\n四、厭氧發酵後或再經曝氣處理後產生之沼液、沼渣，全量施灌於農地，作為農地肥分者，應備有暫停施灌期間之應變緩衝容量。該應變緩衝容量十天以上，得由厭氧發酵設施、曝氣處理設施（以採再經曝氣處理者為限）或其他貯存設施提供，厭氧發酵設施容量超出第一款規定之容量，得計入應變緩衝容量。\n農業主管機關審查沼液沼渣農地肥分使用計畫時，應邀請直轄市、縣（市）環保主管機關參與審查，必要時，應現場勘查。審查時，應依沼液沼渣品質，核定下列事項：\n一、單位面積施灌之沼液沼渣總量。\n二、厭氧發酵設施、曝氣處理設施（以採再經曝氣處理者為限）、貯存設施及其設計容量。\n三、沼液沼渣排出頻率、輸（運）送方式。\n四、施灌農地之場址及面積。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-2 條","text":"沼液沼渣農地肥分使用者，應檢具下列沼液沼渣農地肥分使用計畫之內容及文件，送農業主管機關審查：\n一、畜牧業者，其畜牧場登記證書或畜禽飼養登記證影本；畜牧糞尿資源化處理中心（或沼氣再利用中心）之經營業者，其目的事業主管機關核發之相關許可、登記、執照或其他證明文件影本。\n二、沼液、沼渣檢測報告，應包含氫離子濃度指數、導電度、總氮、總磷、銅、鋅等項目。\n三、施灌農地所有權證明文件，施灌農地非沼液沼渣農地肥分使用者所有，沼液沼渣農地肥分使用者應檢附其與農地所有權人、管理人或使用人簽訂於施灌農地共同執行沼液沼渣農地肥分使用計畫之合約或同意書影本。\n四、施灌農地地號、地籍謄本影本、面積及作物別。未能提供地籍謄本影本者，應檢附與農地所有權人簽訂於施灌農地共同執行沼液沼渣農地肥分使用計畫之合約或同意書影本。\n五、施灌農地區域地下水水質背景值檢測報告，應包含導電度、銨態氮（NH4+-N）或氨氮等項目，以及地下水井座標資料。其地下水井得以施灌農地區域位址之民井或地下水水質監測井為之。\n六、施灌農地土壤品質背景值檢測報告，應包含土壤飽和萃取液導電度、銅、鋅等項目及土壤質地，並以地圖標示採樣地點。\n七、沼液沼渣輸（運）送方式及路線。\n八、施灌作業，應含沼液沼渣施灌數量、方式、頻率、用途、施灌紀錄表格式及暫停沼液沼渣作為農地肥分期間之因應措施。\n九、承諾監測地下水水質及土壤品質。監測項目除土壤質地外，其餘項目同第五款及第六款之施灌農地地下水水質及土壤品質背景值檢測報告項目；監測頻率依附表四辦理。\n前項第五款、第六款及第九款地下水水質及土壤品質之監測，有下列情形之一者，依其規定：\n一、施灌農地之地下水氨氮達地下水污染監測標準時，應監測施灌農地範圍上下游之地下水背景值。\n二、施灌農地之地下水水流方向不明確或施灌農地區域位址之民井地下水位太低，代表性不足者，得以附近環保主管機關、水利主管機關、地方農田水利會或專家學者所屬監測井之監測資料為佐證。\n三、同一沼液沼渣農地肥分使用者，施灌於二以上之鄰近農地，其地下水水質得以一施灌農地之監測值為之；土壤品質得採個別施灌區域內之土壤個別樣品混合物代表此區域之土壤平均濃度值。\n沼液沼渣農地肥分使用者應於地下水水質及土壤品質檢測報告完成後一個月內，送農業主管機關及當地環保主管機關備查，並保存五年。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-3 條","text":"沼液沼渣農地肥分使用計畫有效期限五年，期滿仍繼續使用者，應自期滿六個月前起算三個月之期間內，向農業主管機關申請展延，每次展延，不得超過五年。\n依前項規定申請展延者，應檢具前條第一項第五款、第六款以外規定之文件、內容。但於沼液沼渣農地肥分使用計畫有效期間未有農業主管機關或環保主管機關認定情節重大違規情形者，得逕出具切結書聲明與原審查同意文件相符申請展延。\n農業主管機關或環保主管機關審查前項但書規定之申請，認有必要時，得進行現勘或沼液、沼渣品質採樣，查證切結內容或沼液、沼渣品質。經查證與切結內容不符，申請展延者應併同申請變更。\n第一項展延之申請程序及效力，準用水污染防治措施計畫及許可申請審查管理辦法第三十一條第二項及第三項之規定。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-4 條","text":"沼液沼渣農地肥分使用計畫，審查同意文件應記載下列事項：\n一、沼液沼渣農地肥分使用者及施灌者名稱、地址、負責人。\n二、施灌作業有關之農地地號、面積、沼液沼渣施灌數量、沼液沼渣品質、方式、頻率及用途。\n三、核發日期及計畫有效期限。\n四、其他必要記載事項。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-5 條","text":"沼液沼渣農地肥分使用計畫有變更者，應檢具相關變更文件，向農業主管機關申請變更，經農業主管機關審查同意後，依登記事項運作。\n變更沼液沼渣農地肥分使用計畫，應依下列規定期間及方式辦理：\n一、變更或終止第七十條之二第一項第三款施灌農地共同執行沼液沼渣農地肥分使用計畫之合約或同意書，應於變更或終止之次日起三十日內，檢具變更後之合約書或終止合約文件影本送農業主管機關備查。\n二、變更前條第一款之記載事項或前條第二款農地地號、面積因地政主管機關辦理地籍測量且完成土地標示變更登記者，應自事實發生之次日起三十日內申請變更。\n三、第二款以外之前條第二款記載事項有變更時，應於變更前，檢具相關文件申請變更。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-6 條","text":"經農業主管機關審查同意沼液沼渣農地肥分使用計畫，沼液沼渣農地肥分使用者有下列情形之一時，應暫停沼液沼渣作為農地肥分：\n一、自中央氣象署發布大雨、豪雨特報日起，至解除日後三日之期間。\n二、沼液沼渣作為農地肥分使用期間，地下水水質監測結果各項污染物指標有明顯上升趨勢或土壤品質檢測結果達土壤污染監測標準之限值。\n前項暫停沼液沼渣作為農地肥分期間之因應措施，應納入沼液沼渣農地肥分使用計畫併同審查。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-7 條","text":"直轄市、縣（市）環保主管機關查獲未依農業主管機關審查同意之沼液沼渣農地肥分使用計畫內容執行者，應通知農業主管機關，要求業者改善。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-8 條","text":"取得沼液沼渣農地肥分使用計畫之沼液沼渣農地肥分使用者有下列違法情形之一，農業主管機關得廢止其使用計畫：\n一、申請資料內容與事實不符。\n二、未依核定計畫書內容進行農地肥分使用。\n三、有效期間內未依第七十條之五第二項規定辦理變更，經農業主管機關通知限期改善或補正，屆期仍未改善或補正。\n四、其他違法情形。\n前項各款違法情形，經農業主管機關或環保主管機關認定情節重大者，農業主管機關應廢止其使用計畫。\n農業主管機關依前二項辦理廢止沼液沼渣農地肥分使用計畫，應將辦理情形副知直轄市、縣（市）環保主管機關。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-9 條","text":"有下列情形之一者，以違反本辦法，依本法規定處分：\n一、違反第七十條之一第一項及第七十條之五未依農業主管機關審查同意之沼液沼渣農地肥分使用計畫登記事項運作。\n二、違反第七十條之六未暫停沼液、沼渣作為農地肥分。\n有前項規定情形，於施灌過程所衍生之環境污染情事，依相關環保法規處分。\n未取得沼液沼渣農地肥分使用計畫審查同意，逕將畜牧糞尿或沼液、沼渣作為農地肥分使用者，依違反本法規定處分。\n畜牧糞尿非全量作為農地肥分而有排放於地面水體者，或不符合本章規定而排放於土壤或地面水體者，其排放地面水體或土壤應依本法規定辦理。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"A","no":"第 70-10 條","text":"農業主管機關依農業事業廢棄物再利用管理辦法，核發畜牧糞尿水施灌農作個案再利用許可，或依本辦法規定核發沼液沼渣農地肥分使用計畫時，應一併將申請、變更及展延之核准資料，通知各級主管機關。\n沼液沼渣農地肥分使用者或畜牧糞尿水施灌農作個案再利用許可者，於農業主管機關核准沼液沼渣農地肥分使用計畫或畜牧糞尿水施灌農作個案再利用許可日起，依核准計畫或許可內容施灌。\n農業主管機關應將沼液沼渣農地肥分使用計畫執行之監測及檢測等情形錄案管理，並將資訊提供直轄市、縣（市）環保主管機關。","headingPath":["第 十 章之一 沼液沼渣農地肥分使用（不包含飼養豬隻未滿二百頭之畜牧業）"]},{"type":"C","no":"","text":"第 十一 章 檢測申報管理","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 71 條","text":"下列事業或污水下水道系統免依本辦法規定辦理檢測申報：\n一、未附設洗車場之加油站。\n二、營建工地。\n三、飼養豬未滿二百頭之畜牧業。\n四、貯存系統。\n五、事業或污水下水道系統廢（污）水納入公共污水下水道系統者。\n六、洗腎診所。\n七、水庫總磷削減總量管制區之事業，且非屬本法公告之其他事業。\n八、畜牧業及畜牧糞尿或生質能資源化處理中心（或沼氣再利用中心），依農業事業廢棄物再利用管理辦法，取得農業主管機關核發畜牧糞尿水施灌農作個案再利用許可，或依本辦法取得農業主管機關核准畜牧業沼液、沼渣作為農地肥分使用計畫，全量作為農地肥分使用，檢附實際採行全量資源化證明文件向直轄市、縣（市）主管機關申請並經核准者。\n九、畜牧業將畜牧糞尿水全量委託畜牧糞尿或生質能資源化處理中心（或沼氣再利用中心），或資源化處理比率達百分之七十五以上畜牧業處理，檢附全量委託證明文件向直轄市、縣（市）主管機關申請並經核准者。\n事業或污水下水道系統廢（污）水納入前項第五款以外之污水下水道系統者，應先向污水下水道系統管理機關（構）申報，再由污水下水道系統管理機關（構）彙整後，向直轄市、縣（市）主管機關申報。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 72 條","text":"事業或污水下水道系統採貯留廢（污）水者，申報內容如下：\n一、每月與廢（污）水、污泥產生量有關之製程設施及生產或服務規模。\n二、原廢（污）水水質與檢測當日之水量、每月廢（污）水來源、產生量及貯留量。\n三、貯留設施之放置地點、數量。\n四、貯留後之後續處理行為，應依採行各水措規定之內容申報。\n五、貯留設施之自動液位計測設施或計量方式之校正維護日期及方法。但已設置進流水及出流水之獨立專用累計型水量計測設施者，不在此限。\n前項事業為廢棄物掩埋場返送滲出水至掩埋面者，應申報其每月返送至掩埋面之廢水量。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 73 條","text":"事業或污水下水道系統採廢（污）水（前）處理設施處理廢（污）水者，申報內容如下：\n一、每月與廢（污）水、污泥產生量有關之製程設施及生產或服務規模。\n二、原廢（污）水與（前）處理後之水質及檢測當日之水量。\n三、每月用水來源、用水量、廢（污）水產生量、廢（污）水（前）處理設施之處理水量。廢（污）水產生量應依各股不同製程或來源分別申報。\n四、廢（污）水（前）處理設施操作方式及每月操作維護費用。\n五、每月使用藥劑名稱及使用量。\n六、申報期間主要處理單元正常操作之參數及其最大值、最小值、平均值。\n七、廢（污）水（前）處理設施獨立專用電度表之維護、更換日期及每月用電量。\n八、每月污泥產生量、含水率及操作頻率。\n九、依第十二條第一項設置之進流水水量計測設施或計量方式之校正維護日期與方法及每月讀數或量測值。\n十、依第四十九條之十二廢（污）水評估優先採行最佳可行控制技術之厭氧處理者，其厭氧處理設施之甲烷氣體回收處理方式及流量。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 74 條","text":"事業或污水下水道系統採廢（污）水（前）處理設施處理廢（污）水，且有下列情形之一者，除依前條規定申報外，並應依下列規定辦理：\n一、以餘裕量受託處理非屬其自行產生之廢（污）水者，申報內容如下：\n（一）每月處理自行產生之廢（污）水量及其餘裕量。\n（二）每月收受廢（污）水來源之業別及已累積受託處理之廢（污）水量。\n二、採稀釋廢（污）水者，申報內容如下：\n（一）稀釋用水之水質及檢測當日之水量。\n（二）每月稀釋用水之來源、水量。\n（三）稀釋管線、稀釋口之數量、位置。\n三、委託代操作者，其代操作者之名稱、代操作人員姓名及異動情形。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 75 條","text":"事業或污水下水道系統採廢（污）水（前）處理設施且有下列情形之一者，除依第七十三條規定申報外，並應依下列規定辦理：\n一、事業或污水下水道系統依第八條或第十一條第二項規定應收集處理逕流廢水者，應申報每月收集處理之逕流廢水水量。\n二、第九條之事業，應申報下列事項：\n（一）每月收集洗車台產生之廢水進入沉砂池處理之水量。\n（二）每月沉砂池最高液面距沉砂池四周池頂之高度，及其量測方法。\n（三）擋雨、遮雨、導雨設施及沉砂池之維護狀況、收集初期降雨量進入沉砂池處理之水量。\n三、餐飲業、觀光旅館（飯店）提供泡湯服務，應申報每月毛髮過濾設施、懸浮固體過濾設施之維護日期及方法；提供餐飲服務，應申報每月油脂截留設施之維護日期及方法。\n四、第四十九條之二之事業，應申報淤泥或含水量大於百分之三十之土壤、連續壁產生之皂土等營建剩餘土石方之每月載運車輛進出情形、收容處理之土質種類、收容量及處理量。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 76 條","text":"事業廢（污）水納入工業區專用污水下水道系統者，申報內容如下：\n一、每月與廢（污）水、污泥產生量有關之製程設施及生產或服務規模。\n二、排入污水下水道系統之水質與檢測當日之水量、每月用水來源、用水量及排入污水下水道系統之水量。\n三、設置廢（污）水前處理設施者，應另依第七十三條至第七十五條規定之內容申報。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 77 條","text":"事業或污水下水道系統採委託處理廢（污）水者，申報內容如下：\n一、每月與廢（污）水、污泥產生量有關之製程設施及生產或服務規模。\n二、原廢（污）水水質與檢測當日之水量、每月用水來源、用水量及廢（污）水產生量。\n三、委託處理之頻率、水質與檢測當日之水量及每月委託處理之水量。\n四、受託者名稱及業別。\n五、出流水端之水量計測設施或計量方式之校正維護日期與方法及每月讀數或量測值。\n六、廢（污）水委託處理前於作業環境內設置之貯留設施，依第七十二條規定之內容申報。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 78 條","text":"事業或污水下水道系統以海放管排放廢（污）水於海洋者，申報內容如下：\n一、每月與廢（污）水、污泥產生量有關之製程設施及生產或服務規模。\n二、海放管管線修護方式及頻率。\n三、海域環境監測之採樣位置、頻率、監測項目及監測結果。\n四、設置廢（污）水（前）處理設施者，應另依第七十三條至第七十五條規定之內容申報。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 79 條","text":"畜牧業以外之事業或污水下水道系統採廢（污）水回收使用者，申報內容如下：\n一、每月與廢（污）水、污泥產生量有關之製程設施及生產或服務規模。\n二、原廢（污）水水質與檢測當日之水量、每月用水來源、用水量及廢（污）水產生量。\n三、回收用水之來源、輸（運）送方式，及其回收之用途。\n四、回收用水之水質與檢測當日之水量及每月回收使用之水量。但符合下列情形之一者，免檢測申報回收用水之水質與檢測當日之水量：\n（一）廢（污）水回收作為製程之用。\n（二）廢（污）水回收作為洗滌塔或其他污染防治設備之用，且其回收使用後之水經設置之廢（污）水（前）處理設施處理。\n五、回收使用之水量計測設施或計量方式之校正維護日期與方法及每月讀數或量測值。\n六、經核准設置貯留設施者，應另依第七十二條規定之內容申報。\n七、設置廢（污）水（前）處理設施者，應另依第七十三條至第七十五條規定之內容申報。\n畜牧業採廢（污）水回收使用者，申報內容如下：\n一、每月依輸（運）送方式分別統計之回收使用水量。\n二、回收使用之水量計測設施或計量方式，其校正維護日期、方法、每月讀數或量測值。\n第九條之事業，僅採沉澱處理後回收使用者，除依第一項規定申報外，並應依下列規定申報：\n一、每月礦物、砂、石或預拌混凝土之產量。\n二、每月用水量、沉砂池產生之污泥量。\n三、每月沉沙池處理之水量、去除率。\n四、沉沙池或污泥濃縮池污泥之清除頻率、方式。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 80 條","text":"畜牧業採漁牧綜合經營者，申報內容如下：\n一、魚池面積與實際飼養頭數。\n二、每月清洗畜舍之頻率及水量。\n三、每月排放魚池廢水量與計量方式。\n四、每月魚池曝氣機用電量。\n五、魚池溶氧檢測值及檢測日期。\n六、每月經漁牧綜合經營後之廢（污）水放流日期及處置方式。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 81 條","text":"事業或污水下水道系統採廢（污）水排放於地面水體者，申報內容如下：\n一、每月與廢（污）水、污泥產生量有關之製程設施及生產或服務規模。\n二、排放廢（污）水之水質與檢測當日之水量及每月排放水量。\n三、放流水水量計測設施或計量方式之校正維護日期與方法及每月讀數或量測值。\n四、設置廢（污）水（前）處理設施者，應另依第七十三條至第七十五條規定之內容申報。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 82 條","text":"事業或污水下水道系統採土壤處理廢（污）水者，除應依第七十三條至第七十五條規定申報外，並應依下列規定辦理：\n一、每月作物種類、每公頃飼養頭數及土壤處理面積。\n二、排放於土壤之水質與檢測當日之水量及每月排放土壤之水量。\n三、土壤及地下水監測資料。\n四、每月固液分離設施之操作頻率。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 83 條","text":"事業或污水下水道系統申報之水質、水量、監測資料，其檢測、量測、監測頻率依附表一規定辦理。\n主管機關得視實際需要，命事業或污水下水道系統增加全部或部分申報項目之檢測、量測、監測頻率；必要時並得命其依指定位置、頻率及項目，檢測申報逕流廢水或監測申報承受水體。\n事業或污水下水道系統執行第一項檢測時，其操作條件規定如下：\n一、事業應符合許可證（文件）核准登記之每日最大廢（污）水產生量之百分之六十以上。但定期檢測申報期間之操作條件未達核准登記之每日最大廢（污）水產生量之百分之六十以上者，應以當次定期檢測申報期間實際廢（污）水產生量之平均水量為準。\n二、污水下水道系統應符合許可證（文件）核准登記之每日最大納管水量之百分之六十以上。但定期檢測申報期間之操作條件未達核准登記之每日最大納管水量之百分之六十以上者，應以當次定期檢測申報期間實際納管水量之平均水量為準。\n前項廢（污）水產生量，以作業廢水、洩放廢水及未接觸冷卻水之產生量計算。生活污水與作業廢水、洩放廢水或未接觸冷卻水合併處理者，其生活污水產生量亦應合併計算；納管水量包含排水區域內、外之納管水量。\n事業或污水下水道系統經直轄市、縣（市）主管機關認定未能符合第三項規定之檢測操作條件者，應重新檢測。但得提出書面文件，仍屬正常操作者，不在此限。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 84 條","text":"事業或污水下水道系統申報之水質或監測資料，應依附表一應申報之水質項目進行檢測、監測。但主管機關得依實際需要，增加申報項目。\n事業或污水下水道系統之製程及廢（污）水處理程序中，不使用且不產出附表一應申報之水質項目，或附表一應申報之水質項目檢測結果低於方法偵測極限者，得檢具證明文件，向直轄市、縣（市）主管機關申請免檢測申報該項目。\n工業區專用污水下水道系統或屬晶圓製造及半導體製造業、光電材料及元件製造業、印刷電路板製造業、石油化學業、化工業、造紙業之事業，核准許可廢（污）水排放量達每日二萬立方公尺以上者，應檢測申報放流水水質之生物急毒性。但原水來源為海水或放流水為高濃度鹵離子廢水，且排入之承受水體為海洋者，不在此限。\n前項廢（污）水排放量，以作業廢水及洩放廢水之排放量計算。生活污水與作業廢水、洩放廢水合併處理者，其生活污水排放量亦應合併計算。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 84-1 條","text":"事業或污水下水道系統辦理放流水水質之生物急毒性檢測，應於鯉魚、羅漢魚、斑馬魚胚胎擇一選定及水蚤、米蝦擇一選定，進行二種生物檢測，並依中央主管機關公告之檢測方法執行。主管機關進行稽查採樣時，亦同。\n依前條第三項規定檢測申報者，其頻率為每六個月一次，並應符合下列規定：\n一、檢測申報或主管機關稽查採樣數據，任一次二種生物TUa值均超過一．四三時，應每三個月檢測申報一次；於數據累計連續三次以上，二種生物TUa值均低於一．四三時，檢測及申報頻率回復為每六個月一次。\n二、檢測申報或主管機關稽查採樣數據，累計連續六次以上，二種生物TUa值均低於一．四三時，得調整為每年檢測申報一次。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 84-2 條","text":"事業或污水下水道系統檢測申報或主管機關稽查採樣放流水生物急毒性連續六次數據中，累計三次水樣之二種生物TUa值均超過一．四三時，水質已具有生物急毒性之虞，直轄市、縣（市）主管機關得命其執行毒性鑑定及毒性減量程序，並提報毒性鑑定及毒性減量計畫備查。\n前項毒性鑑定及毒性減量程序執行期間以二年為限，期間免依第八十四條規定檢測申報生物急毒性。屆期無法完成毒性鑑定及毒性減量程序者，得於屆滿前三十日向直轄市、縣（市）主管機關提出展延申請，展延申請以一次為限，展延期限最長不超過兩年。\n毒性鑑定及毒性減量程序執行期間屆滿後十五日內，事業或污水下水道系統應將成果報告提送直轄市、縣（市）主管機關認定，未於限期內提送或經認定未完成改善者，予以處分。毒性鑑定及毒性減量程序成果報告不完全者，直轄市、縣（市）主管機關應通知限期補正，屆期未補正者，駁回其成果報告，視為未完成改善。\n前項成果報告內容應包括：基本資料、執行期間、廢（污）水排放特性與急毒性檢測結果、毒性鑑定和減量評估步驟及毒性鑑定和減量評估成效。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 84-3 條","text":"經中央主管機關指定之事業或污水下水道系統依附表六規定辦理新興關注項目檢測。\n前項放流水檢測項目數據連續二次超過附表六規定數值者，應於三個月內提出該項目之自主削減管理計畫，並送直轄市、縣（市）主管機關備查後，據以執行；自主削減管理計畫執行期間以二年為限，該項目執行期間免依附表六規定檢測。\n前項自主削減管理計畫執行期間屆滿後三十日內，事業或污水下水道系統應向直轄市、縣（市）主管機關提送改善情形報告。\n第一項放流水檢測項目數據累計連續三次以上未超過附表六規定數值者，該項目得免檢測申報。但經主管機關稽查採樣，數據超過規定數值者，該項目應回復依第一項規定辦理。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 85 條","text":"事業或污水下水道系統採土壤處理者，其土壤及地下水監測，除依附表一規定辦理外，應另依下列規定辦理：\n一、土壤處理土地總面積未達一公頃者，於地下水流之上、下游中間處，設置一口地下水監測井，採取一個土壤樣品。\n二、土壤處理土地總面積達一公頃以上，未達二十五公頃者，於地下水流之上、下游處，各設置一口地下水監測井，各採取一個土壤樣品。\n三、土壤處理土地總面積達二十五公頃以上，未達一百公頃者，於地下水流之上、中、下游處，各設置一口地下水監測井，各採取一個土壤樣品。\n四、土壤處理土地總面積達一百公頃以上者，應設置五口以上之地下水監測井及採取五個以上土壤樣品；其地下水監測井及土壤樣品應於地下水流之上、中、下游及四週設置及採取。\n前項土壤採樣應採淺層混合樣品。\n主管機關得依地下水水文、水質狀況等實際需要，命事業或污水下水道系統增加地下水監測井及土壤採樣數量。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 86 條","text":"事業或污水下水道系統申報頻率為每六個月一次。但下列事業或污水下水道系統、申報項目及頻率，規定如下：\n一、免設置廢（污）水處理專責人員之社區專用污水下水道系統，每年申報一次。\n二、應設置廢（污）水處理專責單位或甲級廢（污）水處理專責人員之事業或污水下水道系統，且其廢（污）水排放於地面水體者，每三個月申報一次。\n三、採土壤處理者，其土壤樣品，每年申報一次。\n四、以海放管排放廢（污）水於海洋者，每三個月申報一次。\n主管機關得依實際需要，命事業或污水下水道系統增加全部或部分申報項目之申報頻率。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 87 條","text":"事業或污水下水道系統位於總量管制區內，設有自動監測系統，且中央主管機關對自動監測項目有連線作業規定者，其申報內容、格式及頻率依中央主管機關之規定。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 88 條","text":"事業或污水下水道系統同時採行二種以上水措者，應分別申報。\n事業或污水下水道系統共同設置廢（污）水（前）處理設施處理者，應共同辦理申報。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 89 條","text":"事業或污水下水道系統申報之水質、水量，應於同一日採樣及量測。但逕流廢水之水質、水量，不在此限。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 89-1 條","text":"事業或污水下水道系統申報之資料，應符合下列情形：\n一、依中央主管機關規定之格式、內容、頻率，且應申報之項目未有缺漏。\n二、水質、水量之檢測符合本法第二十三條及本法第六十八條規定。\n三、申報資料及其數據，與所檢具之單據或發票、檢測報告、紀錄、照片及其他主管機關要求檢具之證明文件或資料相符。\n四、申報資料及其數據，與現場之製程設施、生產或服務規模、用電、加藥量、水量量測、操作參數紀錄相符。\n五、申報水質之項目，與第八十四條規定相符。\n六、申報之水污染防治措施方式與現場之實際設置狀況相符。\n七、申報資料及文件應依規定公開於中央主管機關指定之網站。\n八、其他經主管機關認定之情形。\n事業或污水下水道系統申報之資料，經主管機關審查認定其申報資料不符前項規定者，主管機關應通知限期補正，屆期未補正或經補正仍未符合前項規定者，視為申報不完全，主管機關應依本法第五十六條規定處分，並再次通知限期補正，屆期未補正或經補正仍未符合前項規定之申報不完全者，按次處分。\n前項限期補正涉及水質不可回溯性之數據者，應重新檢測，其重新檢測之數據不得兼作為檢測時當期申報之用。\n申報資料不符第一項規定，屬以詐術或其他不正當的方法，如造假數據、假證明、假單據等，視為申報不實。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 90 條","text":"事業或污水下水道系統申報之水質、水量有下列情形之一者，得免委託環境檢驗測定機構辦理：\n一、原廢（污）水水質及水量、回收使用之水量、逕流廢水水質及水量、溫泉廢水分流處理水量。\n二、已設置獨立專用累計型水量計測設施，且依第六十五條第一項進行校正維護者之水量。\n三、納入污水下水道系統之水質、水量，以下水道管理機關（構）之檢測、量測數據為之。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 91 條","text":"事業或污水下水道系統申報之原廢（污）水水質應於調勻設施採樣。但有二股以上廢（污）水混合排入，且含本法公告有害健康物質者，其採樣依下列規定為之：\n一、有害健康物質之項目，應分別於各股廢（污）水進入調勻設施前適當地點採樣，其餘項目應於調勻設施採樣。\n二、前款屬同一有害健康物質項目，依其是否設置有害健康物質項目之廢（污）水收集池：\n（一）有設置者，得於該有害健康物質之廢（污）水收集池採樣。\n（二）未設置者，得依序擇一股原廢（污）水於進入調勻池前適當地點採樣，每次採樣時各股原廢（污）水應輪流辦理。\n廢（污）水含本法公告有害健康物質之項目，屬直接生產與有害健康物質相關製程所產生者，應依前項各款辦理；非屬直接生產與有害健康物質有關製程所產生者，得於調勻設施合併採樣。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 92 條","text":"事業或污水下水道系統應於申報時檢具下列申報表及資料：\n一、水質水量檢測報告。\n二、以海放管排放廢（污）水於海洋者，其海域環境監測紀錄。\n三、其他經主管機關指定事項。\n事業或污水下水道系統申報時，當次應申報月份首日前一年內有違反本法情事經主管機關處分者，除檢具前項規定之申報表及資料外，應另檢具下列資料：\n一、廢（污）水自行或委託清運之處理單據或發票影本。\n二、污泥自行或委託清運之單據或發票影本。\n三、採樣人員進廠起訖日期及時間、採樣起訖日期及時間、會同事業人員採樣照片，並清楚標示採樣點位置及拍攝日期、時間。\n四、藥品採購之單據或發票影本。\n五、累計型水量計測設施校正維護之紀錄及單據或發票之影本。\n六、各水措設施單元及放流口之現況照片，並清楚標示其名稱及拍攝日期。但不包括工業區專用污水下水道系統納管事業之水措設施單元。\n前二項規定之資料，事業或污水下水道系統應保存五年。\n第二項違反本法情事經主管機關處分，以主管機關開立裁處書之日或移送地方檢察署偵查之日認定之。但提起行政救濟者，以原處分確定之日認定之。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 92-1 條","text":"事業或污水下水道系統檢具前條規定之申報紀錄及資料文件，向直轄市、縣（市）主管機關申報時，其申報、補正之各項資料及文件，於隱匿個人資料及採購價格後，應公開於中央主管機關指定之網站。\n事業或工業區專用污水下水道系統以外之污水下水道系統應於每年一月底前；工業區專用污水下水道系統管理機關（構）應於每年二月底前，申報上傳前條第二項第六款之資料文件。\n第一項所稱個人資料，包括姓名、身分證或護照字號、個人照片、出生日期、聯絡電話、行動電話、傳真電話、電子郵件、戶籍所在地址或其他得以直接或間接方式識別該個人之資料。\n第一項資料及文件涉及工商機密者，於提出符合下列要件之證明文件，向直轄市、縣（市）主管機關申請保密並經核准後，得隱匿不公開：\n一、非一般涉及該類資訊之人所知者。\n二、因其秘密性而具有實際或潛在之經濟價值者。\n三、所有人已採取合理之保密措施者。\n事業或污水下水道系統應於中央主管機關指定上網公開日起三個月內，於中央主管機關指定之網站公開最近一次申報之資料及文件。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 93 條","text":"事業或污水下水道系統應於每年一月底前，申報前一年七月至十二月之資料；每年七月底前，申報當年一月至六月之資料。但下列事業或污水下水道系統申報期間及申報資料，規定如下：\n一、第七十一條第二項之工業區專用污水下水道系統管理機關（構），且非屬第八十六條第一項第二款者，應於每年二月底前，申報前一年七月至十二月之資料；每年八月底前，申報當年一月至六月之資料。\n二、第八十六條第一項第二款之事業、工業區專用污水下水道系統以外之污水下水道系統應於每年一月、四月、七月、十月底前，申報前一季之資料。\n三、第八十六條第一項第二款之工業區專用污水下水道系統管理機關（構），應於每年二月底前，申報前一年十月至十二月之資料；每年五月底前，申報當年一月至三月之資料；每年八月底前，申報當年四月至六月之資料；每年十一月底前，申報當年七月至九月之資料。\n四、免設置廢（污）水處理專責人員之社區專用污水下水道系統，應於每年一月底前，申報前一年一月至十二月之資料。\n新申請水措計畫或許可證（文件）之事業或污水下水道系統，以核發機關核准水措計畫核准文件或許可證（文件）之日，為其申報之起始日。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"A","no":"第 94 條","text":"事業或污水下水道系統應採網路傳輸方式申報。但經直轄市、縣（市）主管機關同意者，得以書面方式申報。","headingPath":["第 十一 章 檢測申報管理"]},{"type":"C","no":"","text":"第 十二 章 工業區集污管理","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 95 條","text":"本章所指之污水下水道系統為工業區專用污水下水道系統。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 96 條","text":"污水下水道系統應以專用之溝渠或管線，收集區域內之廢（污）水。但依第二十條規定取得廢（污）水排放地面水體許可證或簡易排放許可文件事業之廢（污）水，不在此限。\n污水下水道系統應以專用之雨水溝渠或管線，收集區域內之雨水及第八條以外之逕流廢水。前述溝渠或管線，不得混雜收集前項之廢（污）水。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 97 條","text":"污水下水道系統應定期巡查檢修前條之溝渠及管線。\n前項定期巡查檢修，每三年應完成全部廢（污）水收集溝渠或管線巡查檢修至少一次；每年應完成全部雨水收集溝渠或管線巡查檢修至少一次；每月應完成全部納管用戶廢（污）水、雨水排水設備巡查至少一次；每半年應完成全部僅產生生活污水納管用戶之排水設備巡查至少一次。巡查檢修結果應作成紀錄，並保存三年備查。\n第一項巡查結果，無法維持第九十六條分流收集功能者，應於巡查後一週內，向主管機關通報巡查結果及改善措施。有採行工程改善措施之必要者，應於一年內完成改善。必要時，得向主管機關報請同意展延一年完成改善。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 98 條","text":"污水下水道系統應查核納管用戶之用水量及廢（污）水量是否維持合理平衡。查核結果應作成報告，並保存三年備查。\n前項查核結果，用水量及廢（污）水量未維持合理平衡者，污水下水道系統應查明原因，並採取適當管理措施。\n第一項查核，發現納管用戶有未經水利主管機關核准，而抽用地下水者，應向所在地水利主管機關舉發。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 99 條","text":"污水下水道系統應考量納管用戶之廢（污）水特性及污水處理廠處理能力，規定核准排入污水下水道系統之納管水質，且應定期採樣檢測納管用戶納管水質，並依檢測結果，採行適當管理並作成紀錄，保存五年備查。但對僅產生生活污水納管用戶納管水質，得排除本項規定。\n前項之採樣檢測，得以自行設置之水質實驗室為之，並應依中央主管機關公告之檢測方法執行檢測。\n第一項之定期採樣檢測，應依納管用戶之水量及水質特性分項檢測。但主管機關依實際需要，命污水下水道系統增加對納管用戶採樣檢測之項目或頻率者，從其規定。\n前項之分項檢測，規定如下：\n一、科學工業園區污水下水道系統、石油化學專業區污水下水道系統：應定期檢測申報之水質項目，每季至少採樣檢測一次。\n二、前款以外之工業區專用污水下水道系統：氫離子濃度指數、水溫、化學需氧量及懸浮固體，每季至少採樣檢測一次；其餘應定期檢測申報之水質項目，每六個月至少採樣檢測一次。\n污水下水道系統納管用戶之納管水質，除氫離子濃度指數、水溫、化學需氧量及懸浮固體外，其餘項目經連續二次檢測結果低於放流水標準者，該項水質項目得免再檢測。\n污水下水道系統應定期輔導及巡查納管用戶設置之廢（污）水前處理設施功能及操作情形，視巡查結果，採行適當管理措施，並作成紀錄，保存五年備查。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 100 條","text":"污水下水道系統應於廢（污）水收集溝渠或管線之適當匯流點，定期採樣檢測廢（污）水之水質，並作成紀錄，保存五年備查。\n前項水質採樣檢測應符合前條第二項之規定。\n第一項水質採樣檢測結果，有廢（污）水超過前條第一項納管水質規定者，污水下水道系統應查明原因，要求相關納管用戶改善，並應採行進流水質水量緩衝調勻因應措施，維持進流處理水質在廢（污）水處理設施正常處理功能範圍內。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 101 條","text":"污水下水道系統應每月分析檢討水量及水質變化，並評估污水下水道系統收集及處理能力。經評估檢討有收集及處理能力不足之虞者，應以書面通知直轄市、縣（市）主管機關，並採取因應措施。有採行工程改善措施之必要者，應於一年內完成改善。必要時，得向直轄市、縣（市）主管機關報請同意展延一年完成改善。\n前項每月水量及水質變化檢討分析、收集及處理能力評估及因應措施執行情形應作成紀錄，並保存三年備查。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 101-1 條","text":"工業區專用污水下水道系統應自中華民國一百零四年起，於每年六月底前，向直轄市、縣（市）主管機關提出前一年度之自評報告，其內容至少應包含下列事項：\n一、污水處理廠進、放流水質、用藥量、用電量、產生污泥量與許可證（文件）登記事項及近三年數據之比對檢核結果。\n二、區內事業家數、納管事業家數、自行排放事業家數。\n三、處理水量之許可利用率、設計利用率及收費率。\n四、設備妥善率、設備損害之應變作為、年度維修及工程改善內容。\n五、年度受處分內容及改善作為。\n六、依本章規定應辦理事項之執行情形。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 102 條","text":"污水下水道系統為搶救人員或處理設施，得以緊急應變放流口進行排放。該緊急應變放流口，以污水處理廠原始設計之進流井溢流口或其他具相同功能之設施為限，並應經核發機關許可後，始得排放廢（污）水。\n前項緊急應變放流口，應設置累計型水量計測設施和制水閥。制水閥應經主管機關鉛封，不得拆除破壞；遇有緊急應變排放需要時，始得拆除制水閥鉛封。\n污水下水道系統以第一項緊急應變放流口排放廢（污）水，應於排放後一小時內通報主管機關，並作成紀錄，保存三年備查。\n污水下水道系統之緊急應變放流口於六個月內使用二次以上時，應以書面提報異常進流改善計畫，報請主管機關審查核准，並依核准內容執行之。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"A","no":"第 103 條","text":"污水下水道系統有下列情形之一者，應依主管機關規定期限，提報污染總量削減管理計畫，經中央主管機關會商中央目的事業主管機關及直轄市、縣（市）主管機關審查核准，依核准內容執行之：\n一、排放之廢（污）水含有害健康物質，且連續五年排放總量逐年增加者。\n二、六個月內實際平均排放之廢（污）水水量達五萬立方公尺／日以上，且放流水承受水體經主管機關認定屬嚴重污染程度者。\n三、其他經主管機關進行承受水體相關環境污染調查，其結果經主管機關認定，污水下水道系統之廢（污）水排放，有造成嚴重污染之虞者。\n前項污染總量削減管理計畫之內容應包括下列項目：\n一、廢（污）水排放特性。\n二、承受水體影響分析。\n三、集污管理措施分析。\n四、污水處理廠設施功能及操作情形評估。\n五、污染總量削減管理之減量目標及期程。\n六、污染總量削減管理之具體執行措施及內容。\n七、污染總量削減管理之成效評估及驗證方法。","headingPath":["第 十二 章 工業區集污管理"]},{"type":"C","no":"","text":"第 十三 章 自動監測（視）設施管理","headingPath":["第 十三 章 自動監測（視）設施管理"]},{"type":"A","no":"第 104 條","text":"（刪除）","headingPath":["第 十三 章 自動監測（視）設施管理"]},{"type":"A","no":"第 105 條","text":"事業或污水下水道系統有下列情形之一者，應依本章規定設置自動監測（視）設施及電子式電度表，並應維持正常功能，與直轄市、縣（市）主管機關連線傳輸：\n一、工業區專用污水下水道系統排放廢（污）水至地面水體，且核准許可廢（污）水排放量每日一千五百立方公尺以上。\n二、發電廠以外之事業排放廢（污）水至地面水體，且核准許可廢（污）水排放量每日一千五百立方公尺以上。\n三、發電廠排放廢（污）水至地面水體，且有排放未接觸冷卻水或採海水排煙脫硫空氣污染防制設施。\n四、公共污水下水道系統排放廢（污）水至地面水體，且核准許可廢（污）水排放量每日一千五百立方公尺以上。\n五、其他經中央主管機關指定。\n前項第二款其排放量以作業廢水及洩放廢水之排放量加總計算。生活污水、未接觸冷卻水或逕流廢水與作業廢水、洩放廢水合併處理者，其排放水量應合併計算。但裝設累計型水量計測設施，或經直轄市、縣（市）主管機關核准之計測設施或計量方式得以分別量測合併處理之各股水量者，其生活污水、未接觸冷卻水或逕流廢水排放量得免納入計算。","headingPath":["第 十三 章 自動監測（視）設施管理"]},{"type":"A","no":"第 106 條","text":"應設置自動監測（視）設施者，其自動監測（視）設施及電子式電度表之設置規定及完成期限應依附表三辦理。\n事業或污水下水道系統因新申請或變更許可證（文件）而符合前條第一項應設置自動監測（視）設施及電子式電度表之規定，其核准時間逾前項附表三規定之期限者，應依下列規定期間完成設置。核發機關並應於核准時，通知事業或污水下水道系統：\n一、新申請許可證（文件）者：自許可核准之日起一百八十日內完成設置。\n二、變更許可證（文件）者：自許可變更核准之日起一百八十日內完成設置。\n前項設施實際設置有困難或放流水為高濃度鹵離子廢水者，得經直轄市、縣（市）主管機關核准採行替代措施，並依核准之替代措施辦理。","headingPath":["第 十三 章 自動監測（視）設施管理"]},{"type":"A","no":"第 106-1 條","text":"依本辦法規定設置之自動監測（視）設施、電子式電度表及顯示看板，應於設施裝設前，檢具自動監測（視）設施措施說明書（以下簡稱措施說明書），送直轄市、縣（市）主管機關核准，並於裝設後，應執行相對誤差測試查核及連續一百六十八個小時傳輸測試，測試完成後，再檢具確認報告書，經直轄市、縣（市）主管機關審查及現場勘查確認。\n違反本法相關規定，經主管機關裁處停工（業）或於限期改善期間內停工（業），依本法第六十三條申請復工（業）者，應於檢具水污染防治措施及污泥處理改善計畫申請試車時，併同檢具前項措施說明書，送直轄市、縣（市）主管機關核准，於完成裝設後申請復工（業）前，應執行連續一百六十八個小時傳輸測試，測試完成後，再檢具確認報告書，經直轄市、縣（市）主管機關審查及現場勘查確認。\n第一百零五條第一項第一款之工業區專用污水下水道系統，於中華民國一百零五年一月一日前已完成自動監測（視）設施之裝設者，其措施說明書得與確認報告書一併檢具。\n措施說明書及確認報告書應於中央主管機關指定之日起，採網路傳輸方式辦理。","headingPath":["第 十三 章 自動監測（視）設施管理"]},{"type":"A","no":"第 106-2 條","text":"事業或污水下水道系統應將委託之監測服務機構相關資料記載於確認報告書。\n受託之監測服務機構於受託期間有虛偽不實或造假紀錄情事，致事業或污水下水道系統受有處分者，主管機關應於中央主管機關指定之網站公開與處分相關之受託監測服務機構資料。\n事業或污水下水道系統設置自動監測（視）設施連線傳輸資料有虛偽不實或造假情事者，其監測（視）設施應每月進行至少一次相對誤差測試查核，並向直轄巿、縣（巿）主管機關提報測試查核結果文件。事業或污水下水道系統連續三年之測試查核結果均符合本辦法規定者，得檢具相關證明文件報經直轄市、縣（市）主管機關核可後，得免辦理。\n事業或污水下水道系統現場應置放校正、維護及相對準確度測試查核等操作紀錄。\n第二項受託之監測服務機構有虛偽不實或造假紀錄，以事業或污水下水道系統受有處分確定之日認定其行為日。","headingPath":["第 十三 章 自動監測（視）設施管理"]},{"type":"A","no":"第 107 條","text":"依本辦法規定設置之自動監測（視）設施及電子式電度表，其主機、數據採擷及處理系統汰換與原設置之廠牌或型號不同時，應於汰換十五日前，檢具措施說明書，送直轄市、縣（市）主管機關核准，並於裝設後，應執行相對誤差測試查核及連續一百六十八個小時傳輸測試，測試完成後，再檢具確認報告書，經直轄市、縣（市）主管機關審查及現場勘查確認。\n前項以外之變更，應於事實發生後三十日內，檢具確認報告書向直轄市、縣（市）主管機關辦理變更。","headingPath":["第 十三 章 自動監測（視）設施管理"]},{"type":"A","no":"第 108 條","text":"事業或污水下水道系統依本辦法規定設置自動監測（視）設施及電子式電度表，應依規定之數據類別、格式進行傳輸，並應依附件一之作業規定辦理；自動監測設施及電子式電度表量測及監測紀錄值之處理規範，應依附件二辦理；水質自動監測設施及攝錄影監視設施之設置、相對誤差測試查核等規定，應依附件三辦理。\n符合前項規定者，辦理本法規定之申報時，得以傳輸之水質水量資料為之。\n直轄市、縣（市）主管機關應將事業或污水下水道系統傳輸之水質水量資料，彙整成可供民眾查閱之數據，公開於中央主管機關指定之網站。","headingPath":["第 十三 章 自動監測（視）設施管理"]},{"type":"A","no":"第 109 條","text":"（刪除）","headingPath":["第 十三 章 自動監測（視）設施管理"]},{"type":"C","no":"","text":"第 十四 章 附則","headingPath":["第 十四 章 附則"]},{"type":"A","no":"第 110 條","text":"事業或污水下水道系統以桶裝、槽車或其他非管線、溝渠，運送符合放流水標準之廢（污）水，至作業環境外者，應於為運送行為二十四小時前，以電話或傳真通知直轄市、縣（市）主管機關後，始得為之。\n事業或污水下水道系統為提升廢（污）水（前）處理設施生物處理效率，以桶裝、槽車或其他非管線、溝渠，運送植種污泥，至作業環境外或收受他廠植種污泥，投入廢（污）水（前）處理設施者，免辦理水污染防治措施計畫、許可證（文件）之登記及變更。但應於運送及收受行為二十四小時前，以電話或傳真通知直轄市、縣（市）主管機關後，始得為之。\n事業或污水下水道系統以桶裝、槽車或其他非管線、溝渠，清除未符合放流水標準之廢（污）水，至作業環境外者，其清除及後續處理行為，應依廢棄物清理法相關規定辦理。\n下列對象以桶裝、槽車或其他非管線、溝渠運送沼液、沼渣，其清除及後續處理行為，免依廢棄物清理法有關事業廢棄物再利用規定辦理：\n一、經農業主管機關審查同意之沼液沼渣農地肥分使用者，依沼液沼渣農地肥分使用計畫記載之事項辦理沼液、沼渣輸（運）送。\n二、經直轄市、縣（市）主管機關於廢（污）水管理計畫核准沼液沼渣農地肥分使用資料者，依廢（污）水管理計畫記載之事項辦理沼液、沼渣輸（運）送。","headingPath":["第 十四 章 附則"]},{"type":"A","no":"第 111 條","text":"（刪除）","headingPath":["第 十四 章 附則"]},{"type":"A","no":"第 111-1 條","text":"本辦法定有期限日數規定之認定，以日曆天為準。","headingPath":["第 十四 章 附則"]},{"type":"A","no":"第 112 條","text":"事業或污水下水道系統將部分廠（場）或設備供他人使用，或委託他人操作水污染防治設備，仍應負水污染防治措施管理及檢測申報之責。","headingPath":["第 十四 章 附則"]},{"type":"A","no":"第 113 條","text":"（刪除）","headingPath":["第 十四 章 附則"]},{"type":"A","no":"第 113-1 條","text":"（刪除）","headingPath":["第 十四 章 附則"]},{"type":"A","no":"第 113-2 條","text":"事業或污水下水道系統於本辦法中華民國一百零四年十一月二十四日修正施行前已依第二十八條第二項第三款設置之採樣口告示牌，或依第五十三條第一項第四款規定設置之放流口告示牌，應於一百零五年三月三十一日前確認並完成採樣口或放流口座標之標示，經確認之座標與許可證（文件）登記不符者，應於該期限內完成許可證（文件）之變更。","headingPath":["第 十四 章 附則"]},{"type":"A","no":"第 114 條","text":"本辦法除中華民國一百零二年三月八日修正發布之第四十九條之一自一百零四年一月一日施行、第四十九條之二及第七十五條第一項第四款自一百零二年七月一日施行外，自發布日施行。\n本辦法中華民國一百十四年一月二十日、一百十五年四月二十日修正發布之條文，除另定施行日期者外，自發布日施行。","headingPath":["第 十四 章 附則"]}],"attachments":[{"name":"附圖一：採樣口或放流口告示牌格式.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000169772","localPath":null},{"name":"附表一、事業或污水下水道系統檢測申報項目及檢測頻率.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000383480","localPath":"data/law-assets/O0040054/02.pdf","sha256":"13bf3c32a4eb9e01db10d55b2bf2b60b66d66aafdb6fc94ddc60e0c378c8861a","size":228381},{"name":"附表二：重大違規者或強制設置應自動監測（視）設施、電子式電度表及顯示看板之規定.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000186515","localPath":"data/law-assets/O0040054/03.pdf","sha256":"f36a33b315f963cdd83f61b94124da9df62fc6edbcd31e8b57b1df717cd4eebd","size":150335},{"name":"附表三、應設置自動監測（視）設施及電子式電度表者之設置規定及設.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000416518","localPath":"data/law-assets/O0040054/04.pdf","sha256":"3217587d5f16c200704fa46b6e3ebd005928d807584a0d0faf062c35a9a106ea","size":128799},{"name":"附表四、沼液沼渣農地肥分使用者，地下水水質及土壤品質監測頻率.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000383481","localPath":"data/law-assets/O0040054/05.pdf","sha256":"b7fbf8ec14564f88446c6bf6d6fe85e915c9db996927e1645ae4388fb5d99797","size":189166},{"name":"附表五、事業或污水下水道系統廢（污）水或污泥之最佳可行控制技術.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000383482","localPath":"data/law-assets/O0040054/06.pdf","sha256":"449a8376e8564697d900c7865d11777f3624ff34ea362eed004f9b0853ed221d","size":189220},{"name":"附表六、事業或污水下水道系統應檢測申報新興關注項目及頻率.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000383483","localPath":null},{"name":"附件一、自動監測（視）設施及電子式電度表作業規定.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000416519","localPath":null},{"name":"附件二、自動監測設施及電子式電度表量測及監測紀錄值處理規範.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000416520","localPath":null},{"name":"附件三、水質自動監測設施及攝錄影監視設施設置、相對誤差測試查核規定.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000416521","localPath":null}],"attachmentNote":"附件／附表共 10 件；本版已離線收錄 5 件，其餘保留全國法規資料庫官方連結。"},"water-permit-reg":{"id":"water-permit-reg","pcode":"O0040055","name":"水污染防治措施計畫及許可申請審查管理辦法","foreword":"","histories":"1.中華民國九十五年十月十六日行政院環境保護署環署水字第 095007997\r\n  4 號令訂定發布全文 44 條；並自發布日施行\r\n2.中華民國一百零一年一月三日行政院環境保護署環署水字第 100011567\r\n  5 號令修正發布第 3、9、10、14、17、19、20、22、23、28、29 條條\r\n  文；增訂第 14-1、14-2、43-1 條條文；並刪除第 40～42 條條文\r\n3.中華民國一百零五年一月十九日行政院環境保護署環署水字第 1050004\r\n  626 號令修正發布名稱及全文 53 條；除另定施行日期外，自發布日施\r\n  行\r\n  （原名稱：水污染防治措施計畫及許可申請審查辦法；新名稱：水污染\r\n  防治措施計畫及許可申請審查管理辦法）\r\n4.中華民國一百零五年十月二十八日行政院環境保護署環署水字第 10500\r\n  86361 號令修正發布第 3、5～7、10、14～16、18、19、22～25、27、\r\n  28～31、36、37、50  條條文；增訂第 27-1、27-2、37-1 條條文；並\r\n  刪除第 20 條條文\r\n5.中華民國一百零七年六月十九日行政院環境保護署環署水字第 1070046\r\n  494 號令修正發布全文 62 條；並自發布日施行\r\n6.中華民國一百十年五月三十一日行政院環境保護署環署水字第 1101059\r\n  481 號令修正發布第 3  條條文\r\n  中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公告\r\n  第 2  條、第 4  條附表 1、附表 2、第 8  條附表 3、第 12 條附表\r\n  4 、第 13 條第 1  項第 1  款附表 1、第 2  款附表 1、第 3  款附\r\n  表 2、第 16 條第 1  項序文、第 2  項、第 3  項、第 17 條第 2  \r\n  項第 4  款、第 20 條第 2  項、第 21 條第 1  項第 3  款、第 9  \r\n  款、第 22 條第 2  項、第 24 條第 1  款、第 3  款、第 25 條、第\r\n  26  條第 1  款、第 28 條第 5  項、第 6  項、第 29 條第 3  項第\r\n  1 款、第 30 條第 3  項、第 32 條第 1  項第 1  款、第 12 款、第\r\n  33  條第 2  項第 2  款、第 4  項附表 5、第 34 條第 1  項、第 5\r\n  項、第 35 條、第 36 條附表 1、第 3  項、第 38 條第 3  項、第 \r\n  39  條第 1  項第 2  款、第 3  款、第 2  項第 2  款序文、第 41\r\n  條第 4  項、第 46 條第 1  項第 1  款、第 2  款、第 2  項序文、\r\n  第 47 條序文、第 3  款、第 48 條第 1  項序文、第 2  項、第 54 \r\n  條第 1  項、第 3  項序文、第 56 條第 1  項、第 1  款、第 3  項\r\n  、第 6  項、第 57 條、第 58 條第 1  項、第 59 條第 1  項、第 \r\n  60  條所列屬「行政院環境保護署」之權責事項，自一百十二年八月二\r\n  十二日起改由「環境部」管轄\r\n7.中華民國一百十三年一月十一日環境部環部水字第 1121334208 號令修\r\n  正發布第 45、56 條條文；增訂第 49-1 條條文\r\n8.中華民國一百十五年三月二十四日環境部環部水字第 1151015556 號令\r\n  修正發布第 31、46、57、62 條條文及第 4  條條文之附表二；依第\r\n  62  條規定：除第 57 條自發布日施行外，第 31、46 條條文及第 4\r\n  條條文之附表二自一百十五年十月一日施行\r\n  中華民國一百十五年四月一日環境部環部水字第 1151020104 號函勘誤\r\n  對照表\r\n  中華民國一百十五年四月九日環境部環部水字第 1151020909 號函勘誤\r\n  對照表及附表二","amended":"20260324","effectiveDate":"20261001","effectiveNote":"一百十五年三月二十四日修正發布第 31、46、57、62 條條文及第 4  條\r\n條文之附表二；依第 62 條規定：除第 57 條自發布日施行外，第 31、\r\n46 條條文及第 4  條條文之附表二自一百十五年十月一日施行。","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0040055","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-text-partial-attachments","articles":[{"type":"C","no":"","text":"第 一 章 總則","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 1 條","text":"本辦法依水污染防治法（以下簡稱本法）第十三條第三項、第四項、第十四條第三項、第十九條準用第十四條及第二十條第二項規定訂定之。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 2 條","text":"本辦法所稱水污染防治措施（以下簡稱水措），指下列各款防治水污染之方法：\n一、設置廢（污）水處理設施。\n二、設置廢（污）水前處理設施。\n三、納入污水下水道系統。\n四、委託處理。\n五、設置管線排放於海洋。\n六、受託處理。\n七、貯留廢（污）水。\n八、稀釋廢（污）水。\n九、回收使用廢（污）水。\n十、逕流廢水污染削減措施。\n十一、沼液沼渣農地肥分使用或畜牧糞尿再利用。\n十二、畜牧廢水作為漁牧綜合經營。\n本辦法所稱核發機關，指直轄市、縣（市）主管機關或中央主管機關委託之機關。\n核發機關依本辦法審查核准之文件包括水污染防治措施計畫（以下簡稱水措計畫）及廢（污）水排放地面水體、貯留、稀釋之許可證（文件）（以下簡稱許可證（文件））。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 3 條","text":"下列事業，免依本辦法規定申請水措計畫及許可證（文件）：\n一、未附設洗車場之加油站。\n二、營建工地。\n三、飼養豬未滿二百頭之畜牧業。\n四、貯存系統。\n五、畜牧業及畜牧糞尿或生質能資源化處理中心（或沼氣再利用中心），依農業事業廢棄物再利用管理辦法，取得農業主管機關核發畜牧糞尿水施灌農作個案再利用許可，或依水污染防治措施及檢測申報管理辦法，取得農業主管機關核准畜牧業沼液、沼渣作為農地肥分使用計畫，全量作為農地肥分使用者。\n六、設置洗腎治療（血液透析）床（台）之診所。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 4 條","text":"事業或污水下水道系統應依附表一所列之特定、一般及簡要三類對象申請水措計畫或許可證（文件），並依其採行之水措方法，依附表二規定，申請許可證（文件）。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 5 條","text":"依本法第十三條第二項公告之事業（以下簡稱應先檢具水措計畫之事業），申請審查水措計畫或許可證（文件）之程序分為設立階段、營運前階段及營運階段。各階段所指期間如下：\n一、設立階段：指辦理水措之規劃、設計，至水措計畫經審查核准之期間。\n二、營運前階段：指依審查核准之水措計畫辦理設施之建造、裝置，至申請、取得核發許可證（文件）之期間。\n三、營運階段：指取得許可證（文件），開始營運產生廢（污）水之期間。\n前項事業廢（污）水納入污水下水道系統（以下簡稱納管），且無排放於地面水體者，申請審查水措計畫之程序分為設立階段及營運階段。各階段所指期間如下：\n一、設立階段：指辦理水措之規劃、設計，至水措計畫經審查核准之期間。\n二、營運階段：指依審查核准之水措計畫辦理設施之建造、裝置，至完工後檢具相關證明文件，完成水措計畫之登記，及營運產生廢（污）水之期間。\n污水下水道系統及非屬前二項之事業，申請審查許可證（文件）之程序分為營運前階段及營運階段。各階段所指期間如下：\n一、營運前階段：指辦理水措設施之建造、裝置，並於完工後，申請、取得核發許可證（文件）之期間。\n二、營運階段：指取得許可證（文件），開始營運產生廢（污）水之期間。\n第一項及前項事業或社區專用污水下水道系統以外之污水下水道系統，設置廢（污）水處理設施且排放廢（污）水於地面水體者（以下簡稱應執行試車者），應於營運前階段之申請核發許可證（文件）期間執行試車。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 6 條","text":"應先檢具水措計畫之事業，於設立階段，應先檢具水措計畫送核發機關審查核准後，始得進行水措設施之建造、裝置。\n前條第一項事業，於營運前階段應檢具申請書送核發機關審查，於取得許可證（文件）後，始得採行各項水措；其原已取得之水措計畫核准文件，失其效力。\n前條第二項事業，於營運階段應檢具下水道管理機關（構）核准聯接使用之證明文件（以下簡稱聯接使用證明），其部分廢（污）水委託處理者，並應檢具委託處理契約書送核發機關審查，完成水措計畫核准文件之登記後，始得營運產生廢（污）水。但施工期間產生之廢（污）水，依下水道管理機關（構）規定，應納入污水下水道系統者，於施工時，應向核發機關報備，該施工期間免辦理核准文件之登記。\n污水下水道系統及非應先檢具水措計畫之事業，於營運前階段，應檢具申請書，送核發機關審查，於取得許可證（文件）後，始得採行各項水措。\n第二項至第四項之事業或污水下水道系統，其以桶裝、槽車或其他非管線、溝渠，清除未符合放流水標準之廢（污）水，至作業環境外者，應同時依廢棄物清理法之規定，申請審查事業廢棄物清理計畫書。","headingPath":["第 一 章 總則"]},{"type":"C","no":"","text":"第 二 章 設立階段","headingPath":["第 二 章 設立階段"]},{"type":"A","no":"第 7 條","text":"應先檢具水措計畫之事業，申請審查水措計畫之時機如下：\n一、設置廢（污）水（前）處理設施前。\n二、納管事業於取得核准同意納入污水下水道系統文件（以下簡稱同意納管文件）後，未取得聯接使用證明前。\n三、簽定廢（污）水委託處理契約前。\n四、設置海洋放流管線前。\n五、設置貯留設施前。\n六、設置稀釋設施前。\n七、設置回收使用設施前。\n八、設置逕流廢水污染削減設施前。","headingPath":["第 二 章 設立階段"]},{"type":"A","no":"第 8 條","text":"事業申請水措計畫審查時，應填具申請表，並檢附附表三規定之文件。","headingPath":["第 二 章 設立階段"]},{"type":"A","no":"第 9 條","text":"核發機關審查核准之水措計畫，應登記事項如下：\n一、核准日期、字號。\n二、事業名稱、業別。\n三、負責人姓名、身分證明文件字號。\n四、地址或座落位置。\n五、核准水措方法及有效期間。\n六、核准事項。","headingPath":["第 二 章 設立階段"]},{"type":"C","no":"","text":"第 三 章 營運前階段","headingPath":["第 三 章 營運前階段"]},{"type":"A","no":"第 10 條","text":"應先檢具水措計畫，且依規定應申請許可證（文件）之事業，其水措設施之建造、裝置，與原核准之水措計畫登記事項不同，而須辦理變更水措計畫者，應於申請許可證（文件）時，一併辦理。","headingPath":["第 三 章 營運前階段"]},{"type":"A","no":"第 11 條","text":"事業申請許可證（文件）之時機如下：\n一、廢（污）水處理設施或海洋放流管線設置完成後，排放廢（污）水於地面水體前。\n二、部分廢（污）水納入污水下水道系統者，取得聯接使用證明後，納入污水下水道系統前。\n三、廢（污）水委託處理契約簽訂後，委託處理前。\n四、貯留設施設置完成後，廢（污）水貯留前。\n五、稀釋設施設置完成後，稀釋廢（污）水前。\n六、回收使用設施設置完成後，進行廢（污）水回收使用前。\n前項事業應設置逕流廢水污染削減設施者，應於設施設置完成後，依前項各款規定之時機辦理。\n事業同時具有第一項各款之情形，應於符合各款規定後，始得提出申請許可證（文件）。\n污水下水道系統申請許可證（文件）之時機如下：\n一、公共污水下水道系統及工業區專用污水下水道系統，準用前三項之規定。\n二、新開發社區專用污水下水道系統及其他指定地區或場所專用污水下水道系統，於申領建築使用執照前。","headingPath":["第 三 章 營運前階段"]},{"type":"A","no":"第 12 條","text":"事業或污水下水道系統申請許可證（文件）審查時，應填具申請表，並檢附附表四規定之文件。","headingPath":["第 三 章 營運前階段"]},{"type":"A","no":"第 13 條","text":"應執行試車者，應於核發機關通知之試車期限內，依審查核准之試車計畫書完成試車及功能測試，並於試車期間屆滿前，提功能測試報告送核發機關審查。但下列事業或污水下水道系統，得以功能測試檢測當日之放流水水質檢測報告替代之（以下簡稱簡易功能測試者）：\n一、附表一所列一般對象（二）。\n二、附表一所列簡要對象。\n三、附表二所列應申請簡易排放地面水體許可文件（以下簡稱簡易排放許可文件）者。\n前項核准之試車計畫書內容因調整，致與依前條檢附之申請表或文件內容不一致者，應於功能測試報告送核發機關審查時，檢附修正後之申請表或文件及調整內容說明，送核發機關。但試車計畫書內容涉及採樣頻率、位置、水質項目、製程操作條件、排放廢（污）水水量、所含之污染物及其應符合濃度限值之變更者，應先檢具相關資料，經核發機關同意後，始得變更。\n應執行試車者依第一項提送之功能測試報告或放流水水質檢測報告，其污染物及其濃度檢測結果符合放流水標準及較放流水標準加嚴之水質項目與限值者，得於核發機關完成排放地面水體許可證（以下簡稱排放許可證）或簡易排放許可文件（以下合稱排放許可證（文件））准駁前，繼續進行試車。\n事業違反本法經主管機關撤銷或廢止排放許可證（文件）者，依第一項提送功能測試報告後，核發機關應於一個月期間內，經十五日以上之查驗及評鑑，並依其查驗及評鑑結果均符合管制標準時之廢（污）水產生量，登記於排放許可證（文件）。\n前項經核發機關查驗及評鑑不合格者，應停止試車進行改善，並於一個月內提出試車計畫書變更。依審查核准之試車計畫書完成試車、功能測試及提送功能測試報告，經核發機關查驗及評鑑。逾期未提出試車計畫書變更或經查驗及評鑑仍不合格者，核發機關應駁回其申請。","headingPath":["第 三 章 營運前階段"]},{"type":"A","no":"第 14 條","text":"前條核發機關核准之試車計畫書，試車期間最長不超過九十日。但經核發機關核准者，不在此限。\n應執行試車者無法依前項試車計畫書完成試車者，得於試車期間屆滿前，向核發機關申請展延，展延試車期間以一次為限，最長不超過九十日。但經核發機關核准者，不在此限。","headingPath":["第 三 章 營運前階段"]},{"type":"A","no":"第 15 條","text":"應執行試車者，依第十三條規定提送之功能測試報告應經技師簽證，其內容包括下列資料文件：\n一、水質水量平衡計算及示意圖。\n二、功能測試期間製程操作條件。\n三、廢（污）水處理設施處理程序及操作條件。\n四、採樣紀錄。\n五、水質檢測結果。\n前項第二款功能測試期間製程操作條件如下：\n一、事業應包含用水量、與廢（污）水產生量有關之製程設施、生產或服務規模、廢（污）水產生量及其有關之原料名稱及用量。\n二、污水下水道系統應包含納管用戶類別、家數及廢（污）水量。","headingPath":["第 三 章 營運前階段"]},{"type":"A","no":"第 16 條","text":"應執行試車者，有本法第七十三條第一項第五款至第七款之情形，核發機關應駁回其許可證（文件）申請。進行試車而有下列情形之一時，主管機關應要求改善或停止試車：\n一、依試車計畫書內容進行試車而有違反本法規定。\n二、未依試車計畫書內容進行試車。\n應執行試車者有前項第二款情形，且屬第十三條第二項但書規定應經核發機關同意後始得變更之事項，主管機關應按其違反情節，分別依本法相關規定處分。\n事業或污水下水道系統經主管機關令停止試車者，應重新提出試車計畫書報請主管機關同意後，始得試車，其試車期間重新起算。但原核准之試車計畫書內容未涉及第十三條第二項但書規定應經核發機關同意後始得變更之事項，事業或污水下水道系統應提出應改善事項及措施、所需試車期間，及原核准之試車計畫書報請主管機關同意，另行核定試車期間。","headingPath":["第 三 章 營運前階段"]},{"type":"A","no":"第 17 條","text":"應執行試車者進行廢（污）水處理設施及污泥處理設施之功能測試時，應依下列規定辦理：\n一、應依許可證（文件）申請之每日最大廢（污）水產生量百分之八十以上之水量測試；無法達百分之八十以上之水量者，依測試時實際最大水量為之。\n二、功能測試期間應為五個工作天以上，期間至少一日進行檢測，檢測當日之起訖時間應於功能測試前三日通知核發機關會同進行，並應依檢測當日之起訖時間進行檢測。\n前項第二款功能測試檢測當日應進行之工作內容規定如下。但簡易功能測試者，得免執行第一款及第二款工作內容，以檢測放流水水質替代：\n一、量測原廢（污）水及處理後之水量各一次、檢測原廢（污）水水質一次、檢測各設施單元操作參數一次。\n二、處理後之水質檢測方式：\n（一）二十四小時連續排放者，應每四小時採樣一次，共採樣六次，每連續二次採樣混合成一個樣品，共計混合成三個樣品進行檢測，取其平均值。\n（二）非二十四小時連續排放者，依每日排放時間，平均分成四次採樣，每連續二次採樣混合成一個樣品，共計混合成二個樣品進行檢測，取其平均值。\n三、功能測試時應依試車計畫書所記載之污染物項目進行水質檢驗。\n四、水量及水質之採樣及檢測，應委託中央主管機關核發許可證之環境檢驗測定機構辦理。\n五、功能測試參與單位應包含：製程操作單位、處理程序操作單位、取樣單位、檢測單位。但污水下水道系統不包含製程操作單位。屬應經技師簽證者，簽證技師應共同參與。\n六、有二股廢（污）水水源或二套以上之廢（污）水處理設施者，應就各股水源或各套設施分別進行廢（污）水量測及檢測。\n前項第二款所定處理後之水質檢測方式，檢測水質項目屬事業放流水採樣方法規定不適宜混樣之檢測項目者，應依下列規定辦理：\n一、二十四小時連續排放者，應每八小時採樣一次，共計採集三個樣品進行檢測，取其平均值。\n二、非二十四小時連續排放者，應依每日排放時間，平均分成二次採樣，共計採集二個樣品進行檢測，取其平均值。","headingPath":["第 三 章 營運前階段"]},{"type":"A","no":"第 18 條","text":"核發機關審查許可證（文件）應登記事項如下：\n一、核准日期、字號。\n二、事業或污水下水道系統名稱、業別。\n三、負責人姓名、身分證明文件字號。\n四、地址或座落位置。\n五、許可水措方法及有效期間。\n六、許可事項。","headingPath":["第 三 章 營運前階段"]},{"type":"C","no":"","text":"第 四 章 營運階段","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 19 條","text":"納管事業且無排放廢（污）水於地面水體者，依第六條第三項規定申請水措計畫核准文件之登記，應填具申請表，並檢附下列文件：\n一、原水措計畫核准文件正本。\n二、聯接使用證明影本。\n三、委託處理者，其廢（污）水委託處理契約書影本。\n四、採廢（污）水（前）處理設施委託代操作者，其契約書影本；其屬應設置廢（污）水處理專責單位或人員者，並應檢附實際執行代操作業務人員之專責人員合格證書影本。\n五、申請資料確認書。\n六、其他經核發機關指定之文件。\n前項事業，其水措設施之建造、裝置與原核准之水措計畫登記事項不同者，於辦理前項之登記時，應另檢具變更後之相關文件。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 20 條","text":"事業或污水下水道系統辦理變更許可證（文件）時，應填具申請表，並檢附與變更有關之文件及申請資料確認書，送核發機關審查。納管事業且無排放廢（污）水於地面水體者，辦理變更水措計畫時，亦同。\n違反本法經主管機關處停工（業）或令限期改善而自報停工（業）之事業，須繼續營運時，領有排放許可證（文件）者，應依本法第六十三條規定辦理復工（業）；未依規定領有水措計畫或許可證（文件）者，應依本辦法申請水措計畫或許可證（文件）。\n依本法第六十三條第三項規定申請復工（業）者，應併同提出排放許可證（文件）登記事項變更，直轄市、縣（市）主管機關應按其查驗及評鑑結果核准登記事項，核准復工（業）。\n第一項及第三項水措計畫核准文件或許可證（文件）之變更，涉及變更廢（污）水（前）處理設施或污泥處理設施，且須進行工程改善或功能測試者，經審查核准之水措計畫核准文件或許可證（文件），有效期限重新起算，最長不超過五年。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 21 條","text":"事業或污水下水道系統，變更下列水措計畫核准文件或許可證（文件）登記事項，應於事實發生之翌日起三十日內，向核發機關辦理變更：\n一、基本資料。\n二、廢（污）水水量、污泥量之計測設施、計量方式及其校正維護方法。\n三、除中央主管機關依本法第十四條之一第一項指定公告之事業外，其增加或變更作業系統用水來源、產生廢（污）水之主要製程設施，或其每日最大生產或服務規模，且未增加用水量、廢（污）水產生量，及未變更廢（污）水（前）處理設施及污泥處理設施功能。\n四、受託處理同業別之廢（污）水者，於核准餘裕量內之委託者及其委託廢（污）水量。\n五、廢（污）水處理設施單元汰舊換新，且其規格條件及功能皆與原許可證（文件）登記相符。\n六、僅變更廢（污）水處理設施單元之附屬機具設施，未涉及廢（污）水處理設施或其操作參數變更。\n七、畜牧業設置之厭氧沼氣收集袋或貯存槽。\n八、縮減每日最大用水量、廢（污）水產生量，且未涉及廢（污）水處理設施、操作參數或其他登記事項之變更。\n九、其他未涉及廢（污）水、污泥之產生、收集、處理或排放之變更，經中央主管機關認定者。\n前項登記事項之變更，應依下列規定辦理：\n一、第一款基本資料，須先經目的事業主管機關核准者，自核准之翌日起三十日內為之。\n二、第一款基本資料，大門口、採樣口、排放口及放流口之座標與許可證（文件）不符，未涉及位置之變更者，應於其知有不符之翌日起三十日內為之。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 22 條","text":"事業或污水下水道系統變更前條以外之水措計畫核准文件或許可證（文件）登記事項，應於變更前，送核發機關審查，經核准後，始得變更。\n事業或污水下水道系統設置廢（污）水處理設施且取得排放許可證（文件）者，其變更涉及廢（污）水處理設施或其操作參數、廢（污）水每日最大處理量或其他經主管機關認定之事項者，應進行功能測試。\n前項事業或污水下水道系統符合下列情形之一者，免進行功能測試：\n一、新增廢（污）水處理設施單元或擴大處理設施容量，且未涉及下列情形之一：\n（一）原許可證（文件）其廢（污）水每日最大處理量增加。\n（二）原廢（污）水水質超過上限值或氫離子濃度指數超過核准範圍值。\n（三）因應管制標準加嚴或新增管制項目。\n二、縮減每日最大用水量、廢（污）水產生量或改善原廢（污）水水質。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 23 條","text":"事業或污水下水道系統變更許可證（文件）涉及工程改善、功能測試者，其應檢附之相關文件及程序如下：\n一、涉及工程改善者，應同時檢具規劃設計及運轉測試內容之水措工程計畫書，送核發機關審查。\n二、事業或污水下水道系統應依核發機關同意變更之內容及期間執行。有調整變更內容之必要者，應於辦理許可證（文件）變更登記程序時，併同檢附修正後之申請表或文件及調整內容說明，送核發機關審查。但涉及製程操作條件、排放廢（污）水水量、所含之污染物及其應符合濃度限值之變更者，應檢具相關資料，經核發機關同意後，始得變更。涉及應進行功能測試者，應依第十七條規定，進行功能測試。功能測試時應依核發機關核定之污染物項目進行水質檢驗。\n三、事業或污水下水道系統完成工程改善或功能測試後，應檢具水措設施完工及標示完妥之照片、證明文件。涉及變更前款之內容，應檢具修正後之變更申請文件及調整內容說明。涉及應進行功能測試者，應檢具功能測試合格報告。但辦理變更排放許可證（文件）之簡易功能測試者，得以功能測試當日之放流水水質檢測報告替代之。送核發機關辦理許可證（文件）變更，據以完成許可證（文件）變更登記程序。\n四、事業或污水下水道系統無法依第二款規定於核發機關同意變更之期限內，完成變更登記程序者，應向核發機關申請延長期限，延長期限不超過九十日，屆期仍無法完成者，應依原許可證（文件）登記事項辦理。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 24 條","text":"事業或污水下水道系統屬廢（污）水處理設施功能不足，經主管機關令限期改善，依規定提送改善計畫書，涉及工程改善、功能測試，應辦理水措計畫核准文件或許可證（文件）登記事項之變更者，其應檢附之相關文件及程序如下：\n一、改善計畫書經主管機關同意後，應依同意之內容執行。有調整改善內容之必要者，應檢具相關資料，經主管機關同意後，始得調整改善。\n二、涉及應進行功能測試者，應依第十七條規定，進行功能測試。功能測試時應依核發機關同意之改善計畫書所核定之污染物項目進行水質檢驗。\n三、經主管機關查驗認定完成改善後，事業或污水下水道系統應檢具申請表、申請資料確認書、水措設施完工及標示完妥之照片、證明文件及功能測試合格報告，送核發機關辦理水措計畫核准文件或許可證（文件）變更，據以完成水措計畫核准文件或許可證（文件）變更登記程序。但辦理變更排放許可證（文件）之簡易功能測試者，功能測試合格報告得以功能測試檢測當日之放流水水質檢測報告替代之。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 25 條","text":"工業區專用污水下水道系統設有聯合污水處理廠者，其處理量超過原許可核准量時，不得再新增納管廢（污）水量，並應於主管機關規定之期限內，完成改善及辦理變更。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 26 條","text":"事業或污水下水道系統設置有廢（污）水（前）處理設施，有下列情形之一者，應檢附申請日前三十日內之功能測試合格報告，辦理水措計畫核准文件或許可證（文件）變更：\n一、經主管機關查獲繞流排放之情事。\n二、操作參數異常。\n三、水質水量平衡異常。\n四、有未經許可稀釋之虞。\n五、廢（污）水（前）處理設施有功能不足之虞。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 27 條","text":"事業辦理排放許可證登記事項變更，有下列情形之一者，其申請文件應經技師簽證：\n一、增加或變更與廢（污）水產生量有關之製程設施及其每日最大生產或服務規模，致變更廢（污）水（前）處理設施。\n二、水措之方法與許可證（文件）不同，且涉及第二十二條第二項，應進行功能測試。\n三、原廢（污）水所含之水質項目與原核准登記不同；用水量、廢（污）水產生量、污泥產生量、（前）處理水量、委託處理水量、貯留水量、稀釋用水量或排放水量等超過原核准之每日最大量。\n四、變更回收使用率、回收使用之核准每日最大量或減少回收使用水量，致採行之其他水措超過核准之每日最大量。\n五、廢（污）水及污泥之產生、收集、（前）處理之方式、流程、（前）處理單元名稱、容量、數量或操作參數與許可證（文件）不同，且涉及第二十二條第二項，應進行功能測試。\n六、以餘裕量受託處理非自行產生，且屬不同業別之廢（污）水。\n特定對象及一般對象之事業依第二十三條第三款、第二十四條第三款及前條規定辦理變更排放許可證者，其檢附之功能測試合格報告，應經技師簽證。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 28 條","text":"事業或污水下水道系統規劃以試驗提升廢（污）水處理設施功能之技術或措施者，得於試驗前檢具廢（污）水處理技術試驗計畫書（以下簡稱試驗計畫書），報經直轄市、縣（市）主管機關備查後，依備查內容及期間執行試驗。\n前項試驗計畫書內容，至少包括基本資料、試驗目的、試驗內容、試驗期間及試驗期間廢（污）水流向示意圖。涉及試驗目的、試驗內容、試驗期間及廢（污）水流向者，應檢具相關資料，報經直轄市、縣（市）主管機關備查後，始得調整試驗內容。\n第一項試驗不得變更水措計畫核准文件或許可證（文件）登記之處理設施單元，亦不得超過廢（污）水每日最大處理量。\n事業或污水下水道系統無法依第一項規定於直轄市、縣（市）主管機關備查之期限內完成試驗，且無第二十九條第一項之情事，得於期限屆滿前申請延長期限。\n主管機關受理試驗計畫書申請、變更或展延，認定應補正資料者，主管機關應通知限期補正，總補正日數不得超過四十二日；必要時經主管機關同意得延長，並以三十日為限。\n試驗計畫書應於中央主管機關指定之日起，採網路傳輸方式辦理。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 29 條","text":"經前條第一項試驗後之廢（污）水仍應依水措計畫核准文件或許可證（文件）登記之收集、處理單元、流程，並由核准登記之放流口排放，或依下水道管理機關（構）核准之排放口排入污水下水道，違者依本法規定處分。執行試驗而有本法第七十三條第一項第五款至第七款之情形時，直轄市、縣（市）主管機關應命停止試驗。但未依試驗計畫書內容進行試驗者，直轄市、縣（市）主管機關應按其違反情節，分別依本法相關規定處分。\n事業或污水下水道系統經直轄市、縣（市）主管機關命停止試驗，或試驗期間已屆滿且未申請延長期限者，應依規定期限移除試驗設施及管線。有重新執行試驗之必要者，應重新檢具試驗計畫書，報經直轄市、縣（市）主管機關備查後，始得重新執行試驗。\n前項移除試驗設施及管線之規定期限如下：\n一、經命停止試驗者，自接獲主管機關裁處書通知之翌日起三十日。\n二、試驗期間已屆滿且未申請延長期限者，自試驗期間屆滿之翌日起三十日。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 30 條","text":"事業或污水下水道系統於試驗期間有取消試驗必要者，應向直轄市、縣（市）主管機關報備取消試驗原因、取消試驗日期及移除試驗設施及管線之期限；該期限為向直轄市、縣（市）主管機關報備後之翌日起三十日。\n事業或污水下水道系統，未能於第一項及前條第三項規定期限內完成試驗設施及管線之移除，得於規定期限屆滿前申請暫緩移除試驗設施管線；其暫緩期間以六個月為限。屆期未申請重新試驗且未拆除原備查試驗之設施及管線，視為未經許可或未符合規定之管線、設施。\n水措計畫申請、變更由中央主管機關委託之機關受理者，直轄市、縣（市）主管機關應於試驗計畫書確認備查、停止或取消試驗時，一併通知中央主管機關委託之機關。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 31 條","text":"許可證（文件）及納管事業且無排放廢（污）水於地面水體者之水措計畫核准文件，有效期間為五年。期滿仍繼續使用者，應自期滿六個月前起算五個月之期間內，向核發機關申請核准展延，每次展延，不得超過五年。但許可證（文件）或水措計畫核准文件有效期間內，事業或污水下水道系統有下列情形之一者，其展延之有效期間不得超過三年，於展延後之有效期間內依本辦法辦理變更者，不適用第二十條第四項有效期間重新起算之規定：\n一、違反本法第十八條之一第一項規定繞流排放。\n二、違反本法第十八條之一第四項規定廢（污）水（前）處理設施功能與設備不足或未維持正常操作。\n事業或污水下水道系統依前項規定申請展延之文件，不符規定或未能補正者，核發機關應於許可證（文件）、水措計畫核准文件期限屆滿前，駁回其申請；因核發機關之審查致許可證（文件）、水措計畫核准文件期限屆滿前無法完成展延准駁者，事業或污水下水道系統於屆滿後至完成審查期間內，得依原登記事項操作營運。\n未依第一項規定期間申請展延者，核發機關尚未作成准駁之決定時，應於許可證（文件）、水措計畫核准文件期限屆滿之翌日起，停止營運及產生廢（污）水；未於許可證（文件）、水措計畫核准文件期限屆滿前申請展延者，於許可證（文件）、水措計畫核准文件期限屆滿之翌日起，其許可證（文件）、水措計畫核准文件失其效力。如需繼續營運者，應重新申請。\n事業或污水下水道系統依第一項規定辦理許可證（文件）、水措計畫核准文件展延，涉及變更者，除第一項但書另有規定外，應依第二十條至第二十七條規定，併同辦理。\n申請許可證（文件）展延，因程序不備，經核發機關駁回重新申請者，原技師簽證之文件未涉及第二十七條第一項各款情事者，免再經技師簽證。\n事業或污水下水道系統同時取得排放許可證（文件）及土壤處理許可證者，其排放許可證（文件）與土壤處理許可證有效期間一致，均為三年。","headingPath":["第 四 章 營運階段"]},{"type":"A","no":"第 32 條","text":"事業或污水下水道系統申請許可證（文件）展延時，應填具申請表，並檢附下列文件：\n一、主管機關或目的事業主管機關核發之相關許可、登記、執照或其他證明文件影本。\n二、放流水排入專用雨水下水道、灌排使用渠道或私有水體者，該管理機關（構）或所有人之同意文件影本。\n三、部分廢（污）水納入污水下水道系統之納管事業，其聯接使用證明影本。\n四、污水下水道區域內採專管排放者，該下水道管理機關（構）同意專管排放之文件影本。\n五、委託處理者，其廢（污）水委託處理契約書影本。\n六、採廢（污）水（前）處理設施委託代操作者，該代操作者之契約書影本。其屬應設置廢（污）水處理專責單位或人員者，並應檢附實際執行代操作業務人員之專責人員合格證書影本。\n七、水措設施設置於他人土地者，事業應檢附該土地所有人或管理人同意文件影本；污水下水道系統應檢附下水道主管機關核准文件影本。\n八、相關水質檢測報告。\n九、相關水措設施之現況照片。\n十、以桶裝、槽車或其他非管線、溝渠，清除未符合放流水標準之廢（污）水，至作業環境外者，其事業廢棄物清理計畫書影本。\n十一、申請資料確認書。\n十二、設置廢（污）水處理設施且排放廢（污）水於地面水體者，經主管機關認定有功能不足之虞者，應檢具一年內最近一次之功能測試合格報告。\n十三、其他經核發機關指定之文件。\n納管事業且無排放廢（污）水於地面水體者，申請水措計畫核准文件展延時，應填具申請表，並檢附下列文件：\n一、聯接使用證明影本。\n二、前項第一款、第五款至第七款、第九款至第十一款及第十三款之文件。","headingPath":["第 四 章 營運階段"]},{"type":"C","no":"","text":"第 五 章 審查","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 33 條","text":"核發機關受理水措計畫或許可證（文件）申請、變更時，有下列情形之一者，其經環境工程技師查核之簽證事項，免再審查：\n一、屬應先檢具水措計畫之事業，申請或變更水措計畫或排放許可證時。\n二、非屬應先檢具水措計畫之事業或污水下水道系統，申請或變更許可證（文件）時。\n前項經環境工程技師查核之簽證事項，核發機關免再審查之規定，有下列情形之一，核發機關仍應審查：\n一、依本法第六十三條第三項規定申請復工（業）者。\n二、簽證之環境工程技師涉及違反本法第十七條第四項所定查核事項，經主管機關或技師公會移送技師懲戒委員會懲戒，懲戒結果尚未確定者。\n三、前款經移送技師懲戒委員會懲戒之環境工程技師，經懲戒確定有下列情形之一者：\n（一）經懲戒警告者，自懲戒確定之日起二個月內。\n（二）經懲戒申誡者，自懲戒確定之日起三個月內。\n（三）經懲戒停止業務者，自懲戒確定之日起懲戒停止業務期間二倍時間內。\n（四）經懲戒廢止執業執照或廢止技師證書。\n環境工程技師執行依本法所定應經技師簽證文件之查核時，應查核廢（污）水或污泥處理設施是否具備足夠之功能及設備，並應共同參與功能測試。\n核發機關受理水措計畫或許可證（文件）之申請、變更或展延，應依附表五規定邀請專家學者協助審查。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 34 條","text":"事業依本法第六十三條申請復工（業），應於提出水污染防治措施及污泥處理改善計畫送交直轄市、縣（市）主管機關時，一併將該計畫經隱匿個人資料後，公開於中央主管機關指定之網頁。未依規定公開者，直轄市、縣（市）主管機關應通知限期補正，屆期未補正，應駁回申請。\n直轄市、縣（市）主管機關應於前項計畫公開後三日內，將計畫（含自動監測（視）及連線傳輸措施說明書）送專家學者進行書面審查，並明定應於七日內完成書面審查。\n利害關係人或公益團體得於第一項計畫公開日起七日內以書面提出意見，作為直轄市、縣（市）主管機關審查時之參考。\n直轄市、縣（市）主管機關應於收受專家學者審查意見後，將利害關係人或公益團體之書面意見、相關機關及專家學者書面審查意見，提供申請者，於七日內召開審查會議，並將會議之時間公開於資訊網路。申請者應於會議前或當日，就該相關意見詳實說明。\n直轄市、縣（市）主管機關應審酌專家學者、相關機關及利害關係人或公益團體之意見及申請者說明之內容，作成試車之准駁。審查會議之紀錄及經核定之水污染防治措施及污泥處理改善計畫，應於完成審查之日起二十日內，於隱匿個人資料後公開登載於中央主管機關指定之網頁。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 35 條","text":"水措計畫之申請、變更，由中央主管機關委託之機關審查者，屬附表一所列特定對象之事業，應揭露之排放廢（污）水污染物含有放流水標準管制以外之污染物項目，中央主管機關委託之機關應將其污染物項目及其濃度與排放量資料與文件送直轄市、縣（市）主管機關依本法第十四條之一第二項審查認定。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 36 條","text":"附表一所列特定對象之事業，排放廢（污）水之污染物項目，經直轄市、縣（市）主管機關認定有危害生態或人體健康之虞者，其水措計畫或排放許可證（文件）申請、變更，核發機關應先依本辦法相關規定予以准駁。直轄市、縣（市）主管機關並應通知事業於十八個月內提出風險評估與管理報告，屆期無法提出者，得於屆滿前三十日向直轄市、縣（市）主管機關提出展延申請，展延申請以一次為限，展延期限最長不得超過六個月。未依規定期間提出風險評估與管理報告者，涉及放流水標準管制以外之污染物項目部分，不得運作。\n直轄市、縣（市）主管機關完成風險評估與管理報告之審查後，應通知事業限期換發水措計畫或排放許可證（文件），依審查結果於事業之水措計畫或排放許可證（文件）登記該放流水標準管制以外之污染物項目排放濃度或總量限值。未換發登記者，涉及放流水標準管制以外之污染物項目部分，不得運作。\n水措計畫申請、變更由中央主管機關委託之機關受理者，直轄市、縣（市）主管機關應將風險評估與管理報告審查結果通知中央主管機關委託之機關納入水措計畫登記。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 37 條","text":"核發機關審查水措計畫或許可證（文件）之申請、變更或展延，應依附表六規定辦理現場勘察。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 38 條","text":"核發機關核准廢（污）水每日最大量及生產或服務規模，應依附表七之原則辦理，必要時得辦理現場勘察，並參考現勘結果核准。\n應實施環境影響評估或應執行總量管制者，核發機關應依審查通過之環境影響評估書件（以下簡稱環評書件）及審查結論或總量管制方式及相關規定核准。但環評書件及審查結論載明之各項污染物排放限值較本法更嚴格者，核發機關核准各項污染物排放限值時，不得高於該限值。\n附表一所列特定對象之事業，屬本法第十四條之一第二項規定應提出風險評估與管理報告者，主管機關應依審查結果核定。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 39 條","text":"廢（污）水水質項目核准登記原則及規定如下：\n一、製程使用原物料成分或廢（污）水處理程序添加之藥劑，其產出之放流水標準管制項目，應予以登記。但事業或污水下水道系統提出原廢（污）水濃度未達放流水標準限值百分之九十之檢測報告，經核發機關確認者，免納入登記事項。\n二、非屬製程使用原物料成分或廢（污）水處理程序添加之藥劑，其產出之放流水標準管制項目，經主管機關檢測結果，原廢（污）水水質檢測數值達放流水標準限值百分之九十，直轄市、縣（市）主管機關應限期通知辦理水措計畫或許可證（文件）變更；逾期未辦理，依本法未依登記事項運作處分。\n三、本法第十四條之一第一項經中央主管機關指定公告之事業，其運作或變更運作之原物料屬該公告附表所列之化學品，應登記該污染物項目。\n原廢（污）水或各處理單元進出水質限值核准登記原則及規定如下：\n一、原廢（污）水水質限值以廢（污）水處理設計之範圍值或最大值作為核准登記之數值，涉及功能測試者，以其檢測數值之範圍值或最大值作為核准登記之數值。\n二、主管機關查核事業或污水下水道系統有下列情形之一者，依其規定：\n（一）原廢（污）水收集設施之原廢（污）水水質項目（除氫離子濃度指數外）數值，低於核准範圍最小值，或各處理單元進出水質數值，未符合許可核准數值，直轄市、縣（市）主管機關應限期通知辦理水措計畫或許可證（文件）變更。\n（二）原廢（污）水收集設施之原廢（污）水水質項目數值超過核准最大值；氫離子濃度指數未符合核准範圍，依本法未依登記事項運作處分。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 40 條","text":"核發機關核准廢（污）水處理設施操作參數之原則，依功能測試結果認定。無須辦理功能測試者，依設計操作參數核定。\n放流水符合本法所定標準，但前項操作參數數值未符合學理數值者，核發機關應請業者說明操作條件原因，並納入許可條件。\n水措計畫核准文件或許可證（文件）登記之操作參數得有正負百分之十之容許差值。但氫離子濃度指數以登記數值上限加一、下限減一為容許範圍。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 41 條","text":"事業或污水下水道系統座落於直轄市、縣（市）主管機關公告應特予保護農地水體之排放總量管制區（以下簡稱總量管制區）者，直轄市、縣（市）主管機關應依下列規定辦理：\n一、第一級總量管制區\n（一）對於製程及廢（污）水處理程序使用或產生，或原廢水、放流水水質檢測報告結果含銅、鋅、鎳、總鉻、六價鉻、鎘者，不得核發新申請之水措計畫及許可證（文件）。\n（二）對於變更增加排放含銅、鋅、鎳、總鉻、六價鉻、鎘之重金屬廢水量或總量者，不得同意變更排放許可證（文件）。\n（三）因違反本法規定，經撤銷或廢止水措計畫及許可證（文件）者，不得再核發水措計畫及許可證（文件）。\n（四）放流水管制限值施行後五年，總量管制區水體所含之銅、鋅、鎳、總鉻、六價鉻、鎘重金屬，仍未符合灌溉用水水質標準，對於製程及廢（污）水處理程序使用或產生，或原廢水、放流水水質檢測報告結果含銅、鋅、鎳、總鉻、六價鉻、鎘且該事業及污水下水道系統於水措計畫及許可證（文件）有效期間內，有違反本法第七十三條第一項所定情節重大者，其水措計畫及許可證（文件）有效期間屆滿後，不得再核發。\n二、第二級總量管制區：因違反本法規定，經撤銷或廢止水措計畫及許可證（文件）者，不得再核發水措計畫及許可證（文件）。\n工業區專用污水下水道系統設有聯合污水處理廠，增加排放含銅、鋅、鎳、總鉻、六價鉻、鎘之重金屬廢水量，有下列情形之一者，不受前項第一款第二目不得同意變更排放許可證（文件）之限制：\n一、受託處理總量管制區內事業廢水，致處理量超過原許可核准量。\n二、新排放總量小於或等於原排放總量的百分之九十：\n（一）新排放總量＝變更後廢（污）水每日最大量×削減後重金屬排放濃度\n（二）原排放總量＝原核准廢（污）水每日最大量×總量管制區內放流水管制限值\n第一項總量管制區內之事業或污水下水道系統沿灌排使用渠道或各級排水路以掛管方式排放廢（污）水，或以共同排放管線共同排放廢（污）水，將放流口設置於總量管制區外，未排放廢水於總量管制區內者，應依第一項各款規定辦理。\n事業或污水下水道系統隱匿其有第一項之情形而取得水措計畫及許可證（文件）者，主管機關應撤銷其水措計畫及許可證（文件）。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 42 條","text":"核發機關受理第三十四條水污染防治措施及污泥處理改善計畫以外之各項水措計畫或許可證（文件）申請、變更或展延，應進行文件完整性之程序審查，及內容合理性之實體審查；其審查期間依附表八規定。\n經審查認定應補正資料者，核發機關應通知限期補正；補正日數不算入審查期間，且總補正日數不得超過四十二日；有下列情形之一者，經核發機關同意得延長，並以三十日為限。但風險評估與管理報告之補正日數，依每次審查結論核定之。\n一、於獲通知限期補正期間內申請釋示與本辦法所定相關審查規定。\n二、新增前次通知限期補正時，未列明之審查意見。但因申請者補正資料文件而新增之意見，不在此限。\n三、其他核發機關認定之事項。\n未依前項期間補正者，核發機關應駁回其申請。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 43 條","text":"前條所定審查期間有下列情形之一者，其經過之時間不予計入：\n一、受理應執行試車者申請排放許可證（文件），自通知試車日起至收到功能測試報告。\n二、核發機關完成審核，以網路傳送核准之文件，至申請者確認。\n三、申請釋示與本辦法所定相關審查規定。\n四、依第十三條第四項或第五項規定，核發機關收到功能測試報告後至完成查驗及評鑑期間。\n五、依第四十五條第二款提供審查意見時之諮詢。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 44 條","text":"核發機關受理第四十二條第一項水措計畫及許可證（文件）變更申請，有下列情形之一者，其審查及補正日數應分別計算：\n一、變更併同展延之申請。\n二、涉及工程改善、功能測試，事業或污水下水道系統提出變更資料之審查，與依同意變更之內容，完成工程改善、功能測試，提出變更登記之審查。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 45 條","text":"核發機關受理各項水措計畫或許可證（文件）申請、變更或展延案件，依第四十二條進行文件完整性之程序審查，及內容合理性之實體審查，其審查範圍不得及於申請、變更或展延內容以外之事項，並不得以任何形式之處分增加法規所未明定之義務。\n核發機關發現核發之水措計畫或許可證（文件）有誤寫、誤算或其他類此未符合本法及相關規定之顯然錯誤者，得隨時更正之，並通知事業或污水下水道系統。\n核發機關審查水措計畫或許可證（文件）展延案件，除符合下列情形之一外，不得逕行變更原核准登記事項：\n一、主管機關依本法第七條規定，增訂或加嚴放流水標準，致與原核准登記事項不符。\n二、直轄巿、縣（巿）主管機關依本法第九條第二項規定，擬訂總量管制方式，致與原核准登記事項不符。\n三、依本法第十五條第二項或第三十二條第二項規定變更許可事項。\n第一項審查經認定應補正資料時，依下列規定辦理：\n一、審查意見應以一次性提供為原則，內容應符合本法所定法規，並與申請、變更或展延內容事項有關。除因申請者補正之資料文件而新增之審查意見外，後續通知限期補正時，不宜有前次通知限期補正未列明之審查意見。\n二、核發機關第一次提供之審查意見，應於通知申請者限期補正前七日內，以電話或面談方式提供諮詢，並作成紀錄。\n三、核發機關應依諮詢結果，以書面方式通知申請者限期補正。\n四、申請者未能於第二款期限內以電話或面談方式參與諮詢，核發機關應以書面方式通知申請者限期補正，並通知提供諮詢之方式。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 46 條","text":"事業於最近三年內有下列情形之一者，經直轄市、縣（市）主管機關廢止其水措計畫或許可證（文件）後，自廢止之日起三年內不得再申請水措計畫或許可證（文件）：\n一、因違反本法規定，經主管機關裁處停工（業）二次以上。\n二、經主管機關依本法規定裁處且認有本法第七十三條第一項所稱情節重大之情形二次以上。\n事業或工業區專用污水下水道系統於水措計畫或許可證（文件）有效期間內，有下列情形之一者，自主管機關開立裁處書之日起三年內，不得變更增加廢（污）水每日最大產生量或與廢（污）水產生量有關之每日最大生產或服務規模：\n一、事業有前項第一款或第二款之情形。\n二、工業區專用污水下水道系統有前項第二款之情形。\n事業排放廢（污）水之承受水體下游，其距離最近之中央主管機關所設置河川水質監測站，測得承受水體之污染程度屬中度污染或嚴重污染，於該事業許可證（文件）有效期間內，有下列情形之一，且原廢（污）水中含有水質項目生化需氧量、懸浮固體、氨氮之一者，直轄市、縣（市）主管機關應令事業於接獲裁處書或書面通知之日起一百八十日內提出許可證（文件）登記之廢（污）水每日最大產生量及與廢（污）水產生量有關之每日最大生產或服務規模變更。但經主管機關核准者，得不受一百八十日之限制：\n一、廢（污）水（前）處理設施功能與設備不足。\n二、繞流排放且廢（污）水（前）處理設施未正常操作。\n事業依前項提出許可證（文件）登記之廢（污）水每日最大產生量及與廢（污）水產生量有關之每日最大生產或服務規模變更，應不得超過原許可證（文件）核准量之百分之八十，且自直轄市、縣（市）主管機關核准之日起三年內不得變更增加。未依前項規定期限內提出變更者，直轄市、縣（市）主管機關得逕依本法第十五條第二項變更其許可事項。\n第一項之廢止處分或第二項、第三項裁處書經提起行政救濟者，以原處分未經撤銷或變更確定之日認定之。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 47 條","text":"事業有下列情形之一者，主管機關得廢止其水措計畫核准文件：\n一、新設事業已停止設置主要生產設備或經目的事業主管機關認定無繼續設廠（場）事實。\n二、事業停工（業）一年以上。但有正當理由無法復工、復業，報經目的事業主管機關核准者，不在此限。\n三、事業遷移，或主要生產、服務設備已搬遷，經目的事業主管機關或主管機關認定無繼續生產、製造、加工或服務之事實。\n四、事業改變生產製程，致無廢水產生。\n五、經下水道管理機關（構）通知，拒絕納入污水下水道系統，自下水道管理機關（構）通知日起一個月內，仍未補正。","headingPath":["第 五 章 審查"]},{"type":"A","no":"第 48 條","text":"事業或污水下水道系統有下列情形之一者，主管機關得廢止其排放許可證（文件）：\n一、依本法第十五條第二項規定。\n二、前條第二款至第四款。\n三、放流水排入專用雨水下水道、灌排使用渠道或私有水體，經管理機關（構）或所有人提出異議，終止其放流水排入，自管理機關（構）或所有人提出異議之日起一個月內，仍未補正。\n四、經下水道管理機關（構）通知，撤銷同意專管排放，自下水道管理機關（構）通知之日起一個月內，仍未補正。\n事業或污水下水道系統有前條第二款至第四款之情形，主管機關得廢止其貯留或稀釋許可文件。","headingPath":["第 五 章 審查"]},{"type":"C","no":"","text":"第 六 章 附則","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 49 條","text":"新設立且應先檢具水措計畫之事業，於未取得目的事業主管機關之相關證明文件前，由核發機關先核准水措計畫者，依下列規定辦理：\n一、納管事業且無排放廢（污）水於地面水體者，應於依第六條第三項規定申請水措計畫核准文件之登記時，補齊相關證明文件，或於取得證明文件後三十日內，辦理變更。\n二、前款以外之事業，應於申請許可證（文件）時，補齊相關證明文件。\n新設立之事業或污水下水道系統因目的事業主管機關定有設立許可、試車、會勘或登記之制度，非以證明文件申請許可證（文件），由核發機關先核發許可證（文件）者，應於取得該登記證明文件後三十日內，辦理變更。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 49-1 條","text":"事業或污水下水道系統辦理水措計畫或許可證（文件）之申請、變更或展延前，須先繪製全廠（場）空氣、水、廢棄物、毒性及關注化學物質污染流向示意圖，檢視污染在不同介質間之流向及在各類環保許可證（文件）間之關連。\n事業或污水下水道系統向核發機關提出水措計畫或許可證（文件）之申請、變更或展延，有涉及其他類環保許可證（文件）之申請、變更、異動或展延者，須同時依各該環保法規規定提出其他類環保許可證（文件）之申請、變更、異動或展延。但可提出未實質涉及其他類環保許可證（文件）之申請、變更、異動或展延者，不在此限。\n經核發機關確認有涉及其他類環保許可證（文件）之申請、變更、異動或展延而未同時提出者，核發機關得續依本辦法規定審查，並通知事業或污水下水道系統應提出其他類環保許可證（文件）之申請、變更、異動或展延。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 50 條","text":"數事業或污水下水道系統共同採用同一水措方法者，應共同申請水措計畫、許可證（文件）。\n事業或污水下水道系統採委託處理者，其申請、變更或展延涉及受託處理者資料之變更時，委託者及受託者，應共同申請之。\n前項受理機關不同時，由受託者之核發機關邀集委託者之核發機關參與審查。\n事業或污水下水道系統採行二種以上水措方法者，應同時檢具各該水措方法之相關資料。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 51 條","text":"事業或污水下水道系統將其部分廠（場）或設備供他人使用，或委託他人操作水污染防治設備，仍應負申請、變更、展延水措計畫或許可證（文件）之責。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 52 條","text":"事業或污水下水道系統申請許可證（文件）之審查、變更及展延，得與本法第三十二條規定之申請，併同提出。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 53 條","text":"水措計畫、許可證（文件）於有效期間內毀損或滅失者，應於事實發生後三十日內，以書面敘明原因，向核發機關申請換發或補發。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 54 條","text":"事業或污水下水道系統因天然災害或緊急事故發生時，依主管機關之命令所採行之水措，免依本辦法規定申請或變更水措計畫、許可證（文件）。\n自來水事業減少供水或輪流供水、停水期間，事業以槽車或其他方式補充其用水來源，且未超出原登記之總用水量時，免依本辦法規定變更水措計畫、許可證（文件）。\n事業或污水下水道系統，於作業環境內因土壤、地下水污染整治所產生之水，符合下列規定，且經主管機關依土壤及地下水污染整治法之規定審查同意，應納入廢（污）水處理設施處理者，其所採行之水措，免依本辦法規定申請或變更水措計畫、許可證（文件）：\n一、不超過廢（污）水處理設施設計容量，且不超過水措計畫核准文件、許可證（文件）登記之每日最大核准量之百分之十。\n二、整治所產生之水超過放流水標準。\n三、該廢（污）水處理設施應有足夠功能，處理整治所產生之水所含之污染物。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 55 條","text":"事業或污水下水道系統應採網路傳輸方式辦理水措計畫或許可證（文件）之申請、變更及展延。但經直轄市、縣（市）主管機關同意者，得以書面方式為之。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 56 條","text":"事業或污水下水道系統依本辦法規定辦理水措計畫、許可證（文件）之申請、變更或展延，其檢具與後續補正之申請表及經核發機關核准之水措計畫核准文件、許可證（文件），應依中央主管機關規定公開之內容，隱匿個人資料後，公開於中央主管機關指定之網站。未依規定公開於資訊網路，核發機關應通知限期補正，屆期未補正，應駁回申請。\n前項核准文件，核發機關應將核准內容上傳於水污染源管制資料管理系統，並於核准後十四日內以書面掛號送達或作成電話紀錄方式通知事業或污水下水道系統下列事項：\n一、應於通知之日起十四日內將水措計畫核准文件、許可證（文件）核准內容公開於中央主管機關指定之網站，並繳交證書費及領取水措計畫核准文件、許可證（文件）。\n二、告知第四項及第五項規定。\n核發機關確認事業或污水下水道系統將水措計畫核准文件、許可證（文件）核准內容公開於中央主管機關指定之網站及完成繳費後，始得核發水措計畫核准文件、許可證（文件）核准文件。核發機關核發水措計畫核准文件、許可證（文件）核准文件後，應將許可證（文件）首頁公開於中央主管機關指定之網站。\n核發機關依第二項通知領取水措計畫核准文件、許可證（文件）後，事業或污水下水道系統應完成領證，並依登記事項運作，始得貯留、稀釋或排放廢（污）水。\n事業或污水下水道系統於核發機關通知領證日達一年始辦理領證者，核發機關應現場確認符合原核准事項後，始得發證，如未符合原核准事項，應通知限期補正。\n事業或污水下水道系統於本辦法中華民國一百零五年一月十九日修正施行前，取得水措計畫及許可證（文件）者，應於中央主管機關指定公開於資訊網路日起三個月內，於中央主管機關指定之網站公開最近一次經核發機關核准之文件。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 57 條","text":"事業或污水下水道系統依本辦法規定辦理水措計畫、許可證（文件）之申請、變更或展延，於申請日前一年內有違反本法情事經主管機關處分者，依前條第一項規定辦理時，應另將檢具與後續補正檢附之文件公開於資訊網路。\n前項違反本法情事經主管機關處分，以主管機關開立裁處書之日或移送地方檢察署偵查之日認定之。但提起行政救濟者，以原處分確定之日認定之。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 58 條","text":"直轄市、縣（市）主管機關於本辦法中華民國一百零五年一月十九日修正施行前，已受理依本法第六十三條第一項規定申請復工（業）者提出之水污染防治措施及污泥處理改善計畫，但尚未完成復工（業）准駁者，應於完成審查之日起二十日內，將審查會議紀錄及經核定之水污染防治措施及污泥處理改善計畫，公開登載於中央主管機關指定之網頁。\n前項經核定之水污染防治措施及污泥處理改善計畫，直轄市、縣（市）主管機關應隱匿個人資料後公開。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 59 條","text":"申請水措計畫或許可證（文件）審查時，依附表三及附表四檢具之依規定應揭露之排放廢（污）水污染物之水措資料及其相關書面文件，已依新化學物質及既有化學物質資料登錄辦法向中央主管機關申請保密且經核准者，不予公開。\n第三十四條、第五十六條及第五十八條所稱個人資料，包括姓名、身分證或護照字號、個人照片、出生日期、聯絡電話、行動電話、傳真電話、電子郵件、戶籍所在地址或其他得以直接或間接方式識別該個人之資料。\n第三十四條、第五十六條及第五十八條應公開於資訊網路之資料及文件涉及工商機密者，於提出符合下列要件之證明文件，向直轄市、縣（市）主管機關申請保密並經核准後，得隱匿不公開：\n一、非一般涉及該類資訊之人所知者。\n二、因其秘密性而具有實際或潛在之經濟價值者。\n三、所有人已採取合理之保密措施者。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 60 條","text":"經地方政府補助設置畜牧糞尿資源化設備處理其他畜牧場畜牧糞尿之事業，或委託上述事業處理畜牧糞尿之其他畜牧業，其許可證（文件）申請、變更之相關規定，應依中央主管機關補助地方政府之計畫辦理。\n直轄市、縣（市）主管機關依前項計畫之規定，於竣工查驗通過後，應將畜牧糞尿資源化設備處理其他畜牧場畜牧糞尿計畫內容納入許可證（文件）登記，並通知事業確認登記事項後，核准或換發其許可證（文件），及依第五十六條第一項及第二項規定隱匿個人資料後公開於中央主管機關指定之網站，完成許可證（文件）領證。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 61 條","text":"水污染防治法事業分類及定義公告新增之事業，應於公告施行日起一年內取得水措計畫核准文件或許可證（文件）核准文件。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 62 條","text":"本辦法自發布日施行。\n本辦法中華民國一百十五年三月二十四日修正發布之條文，除第五十七條自發布日施行外，自一百十五年十月一日施行。","headingPath":["第 六 章 附則"]}],"attachments":[{"name":"附表一、應申請水措計畫或許可證（文件）對象之分類.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000220718","localPath":null},{"name":"附表二、事業或污水下水道系統應申請許可證（文件）之種類及適用條件.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000414665","localPath":null},{"name":"附表三、事業申請水措計畫應檢附文件.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000220720","localPath":"data/law-assets/O0040055/03.pdf","sha256":"97a650cd5c7113402051650e0d00e1564f8069b834cc059ffd82e3156c1a6e09","size":188714},{"name":"附表四、事業或污水下水道系統申請許可證（文件）應檢附文件.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000220721","localPath":"data/law-assets/O0040055/04.pdf","sha256":"5ca610cf0a8b878eb02b2cfa1ba9a2e2a950a784b17cf425f515c814216cbb42","size":208731},{"name":"附表五、核發機關應邀請專家學者協助審查之情形.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000220722","localPath":null},{"name":"附表六、核發機關應現場勘察之情形及項目.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000220723","localPath":null},{"name":"附表七、核發機關核准廢（污）水每日最大量及生產或服務規模核定原則.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000220724","localPath":null},{"name":"附表八、核發機關受理各項申請審查期間規定.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000220725","localPath":null}],"attachmentNote":"附件／附表共 8 件；本版已離線收錄 2 件，其餘保留全國法規資料庫官方連結。"},"effluent-standard":{"id":"effluent-standard","pcode":"O0040004","name":"放流水標準","foreword":"","histories":"1.中華民國七十六年五月五日行政院衛生署（76）衛署環字第 654798 號\r\n  令訂定發布全文 4  條\r\n2.中華民國八十年一月十六日行政院環境保護署（80）環署法字第 00359\r\n  號令修正發布\r\n3.中華民國八十年十一月二十九日行政院環境保護署（80）環署法字第 4\r\n  6873  號令修正發布\r\n4.中華民國八十六年三月十九日行政院環境保護署（86）環署水字第 099\r\n  53  號令修正發布全文 10 條\r\n5.中華民國八十六年十二月二十四日行政院環境保護署（86）環署水字第\r\n  78804 號令修正發布全文 12 條\r\n6.中華民國八十八年九月二十四日行政院環境保護署（88）環署水字第 0\r\n  060545  號令修正發布第 6  條條文\r\n7.中華民國八十九年二月九日行政院環境保護署（89）環署水字第 00041\r\n  91  號令修正發布全文 8  條；並自發布日起施行\r\n8.中華民國九十年二月七日行政院環境保護署（90）環署水字第 0004055\r\n  號令修正發布第 2、6 條條文\r\n9.中華民國九十年十一月二十一日行政院環境保護署（90）環署水字第 0\r\n  069097  號令修正發布第 2  條條文\r\n10. 中華民國九十二年十一月二十六日行政院環境保護署環署水字第 092\r\n    0084786 號令修正發布第 2  條條文\r\n11. 中華民國九十六年九月三日行政院環境保護署環署水字第 096006574\r\n    0 號令修正發布全文 8  條；並自發布日施行\r\n12. 中華民國九十八年七月二十八日行政院環境保護署環署水字第 09800\r\n    65341 號令修正發布第 2、4 條條文\r\n13. 中華民國九十九年十二月十五日行政院環境保護署環署水字第 09901\r\n    12348F  號令修正發布全文 9  條；本標準除另定施行日期者外，自\r\n    發布日施行\r\n14. 中華民國一百年十二月一日行政院環境保護署環署水字第 100010386\r\n    0 號令修正發布第 2  條條文\r\n15. 中華民國一百零一年十月十二日行政院環境保護署環署水字第 10100\r\n    90770 號令修正發布第 2、5、6  條條文\r\n16. 中華民國一百零三年一月二十二日行政院環境保護署環署水字第 103\r\n    0005842 號令修正發布第 2  條條文\r\n17. 中華民國一百零五年一月六日行政院環境保護署環署水字第 1040110\r\n    356 號令修正發布第 2  條條文\r\n18. 中華民國一百零六年十二月二十五日行政院環境保護署環署水字第 1\r\n    060101625 號令修正發布第 2、5  條條文；並增訂第 2-1 條條文\r\n19. 中華民國一百零八年四月二十九日行政院環境保護署環署水字第 108\r\n    0028628 號令修正發布第 2、2-1 條條文\r\n    中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公\r\n    告第 2  條第 1  項第 1  款第 8  目附表 8、第 8  條第 1  項所\r\n    列屬「行政院環境保護署」之權責事項，自一百十二年八月二十二日\r\n    起改由「環境部」管轄\r\n20. 中華民國一百十三年十二月十八日環境部環部水字第 1131081975 號\r\n    令修正發布第 2  條條文之附表一至附表十一、附表十四、附表十五","amended":"20241218","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0040004","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-text-partial-attachments","articles":[{"type":"A","no":"第 1 條","text":"本標準依水污染防治法（以下簡稱本法）第七條第二項規定訂定之。","headingPath":[]},{"type":"A","no":"第 2 條","text":"事業、污水下水道系統及建築物污水處理設施之放流水標準，其水質項目及限值之規定如下：\n一、事業\n（一）晶圓製造及半導體製造業適用附表一。\n（二）光電材料及元件製造業適用附表二。\n（三）石油化學業適用附表三。\n（四）化工業適用附表四。\n（五）金屬基本工業、金屬表面處理業、電鍍業和印刷電路板製造業適用附表五。\n（六）發電廠適用附表六。\n（七）海水淡化廠適用附表七。\n（八）前七款以外之事業適用附表八。\n二、污水下水道系統\n（一）科學工業園區專用污水下水道系統適用附表九。\n（二）石油化學專業區專用污水下水道系統適用附表十。\n（三）其他工業區專用污水下水道系統適用附表十一。\n（四）社區專用污水下水道系統適用附表十二。\n（五）其他指定地區或場所專用污水下水道系統適用附表十三。\n（六）公共污水下水道系統適用附表十四。\n三、建築物污水處理設施適用附表十五。\n事業、污水下水道系統排放廢（污）水於經直轄市、縣（市）主管機關公告應特予保護農地水體之排放總量管制區（以下稱總量管制區）內之特定承受水體者，其銅、鋅、總鉻、鎳、鎘、六價鉻之限值適用附表十六。但總量管制區內之事業或污水下水道系統，未排放廢（污）水於總量管制區內特定承受水體者，不適用附表十六規定。\n特定業別、區域之事業、污水下水道系統及建築物污水處理設施，另定有排放標準者，或直轄市、縣（市）主管機關依據本法第七條第二項增訂或加嚴轄內之放流水標準者，依其規定。","headingPath":[]},{"type":"A","no":"第 2-1 條","text":"工業區污水下水道系統，其石油化學業和化工業許可核准納管水量達許可核准排放水量百分之五十以上者，適用附表十之規定；其石油化學業和化工業許可核准納管水量未達許可核准排放水量百分之五十者，適用附表十一之規定。\n海水淡化廠排放之廢（污）水適用之放流水標準依下列規定：\n一、以海水為原水，排放鹵水及過濾反洗廢水、薄膜清洗廢水或其他與海水淡化有關作業廢水混合排放者，適用附表七。\n二、產生之廢（污）水採海洋放流管線排放於海洋者，適用海洋放流管線放流水標準。","headingPath":[]},{"type":"A","no":"第 3 條","text":"事業及其所屬公會或環境保護相關團體得隨時提出具體科學性數據、資料，供檢討修正之參考。","headingPath":[]},{"type":"A","no":"第 4 條","text":"本標準所定之化學需氧量限值，係以重鉻酸鉀氧化方式檢測之；真色色度，係以真色色度法檢測之。","headingPath":[]},{"type":"A","no":"第 5 條","text":"本標準用詞，定義如下：\n一、總毒性有機物：指 1,2- 二氯苯、1,3-二氯苯、1,4-二氯苯、1,2,4-三氯苯、甲苯、乙苯、三氯甲烷、1,2-二氯乙烷、二氯甲烷、1,1,1-三氯乙烷、1,1,2-三氯乙烷、二氯溴甲烷、四氯乙烯、三氯乙烯、1,1-二氯乙烯、2-氯酚、2,4-二氯酚、4-硝基酚、五氯酚、2-硝基酚、酚、2,4,6-三氯酚、鄰苯二甲酸乙己酯、鄰苯二甲酸二丁酯、鄰苯二甲酸丁苯酯、蒽、1,2-二苯基聯胺、異佛爾酮、四氯化碳及萘，計三十種化合物之濃度總和。\n二、石油化學業高含氮製程：指下列含氮製程，且作業廢水水量達放流口許可核准之排放水量百分之四十以上者：\n（一）三氟化氮與電子級液氨製造程序。\n（二）甲基丙烯酸酯類（MMA） 化學製造程序。\n（三）丙烯腈製造程序。\n（四）丙烯腈－丁二烯共聚合物（AB）化學製造程序。\n（五）丙烯腈－丁二烯－苯乙烯共聚合物（ABS） 化學製造程序。\n（六）丙烯腈－苯乙烯共聚合物（AS）化學製造程序。\n（七）己內醯胺製造程序。\n（八）硫酸銨化學製造程序。\n（九）聚醯胺塑膠（尼龍）製造程序。\n三、化工業高含氮製程：指下列含氮製程，且作業廢水水量達放流口許可核准之排放水量百分之四十以上之化工業者：\n（一）氨化學製造程序。\n（二）氮肥製造程序。\n（三）銨肥化學製造程序。\n（四）磷酸銨鹽肥料製造程序。\n（五）含氮複肥製造程序。\n（六）三氟化氮製造程序。\n（七）硫酸銨化學製造程序。\n（八）乙二胺四醋酸鹽（EDTA）化學製造程序。\n（九）其他銨鹽製造程序。\n（十）丙烯腈製造程序。\n（十一）尿素化學製造程序。\n（十二）苯胺製造程序。\n（十三）己內醯胺製造程序。\n（十四）乙醇胺化學製造程序。\n（十五）酸胺化學製造程序。\n（十六）其他合成胺及腈合物製造程序。\n（十七）甲基丙烯酸酯類（MMA） 化學製造程序。\n（十八）氨基甲酸酯製造程序。\n（十九）尿素甲醛樹脂製造程序。\n（二十）三聚氰胺樹脂製造程序。\n（二十一）聚丙烯腈纖維製造程序。\n（二十二）聚醯胺塑膠（尼龍）製造程序。\n（二十三）丙烯腈－丁二烯共聚合物（AB）化學製造程序。\n（二十四）丙烯腈－丁二烯－苯乙烯共聚合物（ABS） 化學製造程序。\n（二十五）丙烯腈－苯乙烯共聚合物（AS）化學製造程序。\n（二十六）染料製造程序（偶氮染料）。\n（二十七）煉焦相關程序，含焦碳製造之副產品程序、焦碳製造之蜂巢程序、流體焦碳製造程序、石油焦煉製程序等。\n四、戴奧辛：指以檢測 2,3,7,8- 四氯戴奧辛（2,3,7,8-Tetrachlorina-teddibenzo-p-dioxin,2,3,7,8-TeCDD），2,3,7,8-四氯呋喃（2,3,7,8-Tetrachlorinateddibenzofuran,2,3,7,8-TeCDF）及2,3,7,8-氯化之五氯（Penta-），六氯（Hexa-），七氯（Hepta-）與八氯（Octa-）戴奧辛及呋喃等共十七項化合物所得濃度，乘以國際毒性當量因子（InternationalToxicityEquivalencyFactor,I-TEF）之總和計算之，以總毒性當量（ToxicityEquivalencyQuantityof2,3,7,8-tetrachlorinated dibenzo-p-dioxin, TEQ）表示。\n五、總有機磷劑：指達馬松、美文松、滅賜松、普伏松、亞素靈、福瑞松、大滅松、托福松、大利松、大福松、二硫松、甲基巴拉松、亞特松、撲滅松、馬拉松、陶斯松、芬殺松、巴拉松、甲基溴磷松、賽達松、乙基溴磷松、滅大松、普硫松、愛殺松、三落松、加芬松、一品松、裕必松、谷速松計二十九種化合物之濃度總和。\n六、總氨基甲酸鹽：指滅必蝨、加保扶、納乃得、安丹、丁基滅必蝨、歐殺滅、得滅克、加保利、滅賜克計九種化合物之濃度總和。\n七、除草劑：指丁基拉草、巴拉刈、二、四－地、拉草、全滅草、嘉磷塞、二刈計七種化合物之濃度總和。\n八、七日平均值：指間隔每四至八小時採樣一次，每日共四個水樣，混合成一個水樣檢測分析，連續七日測值之算術平均。","headingPath":[]},{"type":"A","no":"第 6 條","text":"本標準各項目限值，除氫離子濃度指數為一範圍外，均為最大限值，其單位如下：\n一、氫離子濃度指數：無單位。\n二、真色色度：無單位。\n三、大腸桿菌群：每一百毫升水樣在濾膜上所產生之菌落數（CFU/100 mL）。\n四、戴奧辛：皮克－國際－總毒性當量／公升（pg I-TEQ/L）。\n五、其餘各項目：毫克／公升。","headingPath":[]},{"type":"A","no":"第 7 條","text":"本標準各項目限值，除水溫及氫離子濃度指數外，事業或污水下水道系統自水體取水作為冷卻或循環用途之未接觸冷卻水，如排放於原取水區位之地面水體，不適用本標準。","headingPath":[]},{"type":"A","no":"第 8 條","text":"事業、污水下水道系統及建築物污水處理設施，同時依本標準適用範圍，有二種以上不同業別或同一業別有不同製程，其廢水混合處理及排放者，應符合各該業別之放流水標準。相同之管制項目有不同管制限值者，應符合較嚴之限值標準。各業別中之一種業別廢水水量達總廢水量百分之七十五以上，並裝設有獨立專用累計型水量計測設施者，得向主管機關申請對共同管制項目以該業別放流水標準管制。\n前項廢水量所佔比例，以申請日前半年之紀錄計算之。","headingPath":[]},{"type":"A","no":"第 9 條","text":"本標準除另定施行日期者外，自發布日施行。","headingPath":[]}],"attachments":[{"name":"附表一  晶圓製造及半導體製造業放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380980","localPath":null},{"name":"附表二  光電材料及元件製造業放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380981","localPath":null},{"name":"附表三  石油化學業放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380982","localPath":"data/law-assets/O0040004/03.pdf","sha256":"a7c5d282a8f899e05459f65d24ffe3cbd4586893427eb17d6a08728860969bbb","size":127868},{"name":"附表四  化工業放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380983","localPath":"data/law-assets/O0040004/04.pdf","sha256":"74b10efe46d5090e2a39335c87063f119cc3ffac08cbf0aa0ef0c3d05511c561","size":141486},{"name":"附表五  金屬基本工業、金屬表面處理業、電鍍業和印刷電路板製造業放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380984","localPath":null},{"name":"附表六  發電廠放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380985","localPath":null},{"name":"附表七  海水淡化廠放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380986","localPath":null},{"name":"附表八  晶圓製造及半導體製造業、光電材料及元件製造業、石油化學業、化工業、金屬基本工業、金屬表面處理業、電鍍業、印刷電路板製造業、發電廠及海水淡化廠以外之事業放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380987","localPath":null},{"name":"附表九  科學工業園區專用污水下水道系統放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380988","localPath":null},{"name":"附表十  石油化學專業區專用污水下水道系統放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380989","localPath":null},{"name":"附表十一  其他工業區專用污水下水道系統放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380990","localPath":null},{"name":"附表十二：社區專用污水下水道系統放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000247698","localPath":null},{"name":"附表十三：其他指定地區或場所專用污水下水道系統放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000247699","localPath":null},{"name":"附表十四  公共污水下水道系統放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380991","localPath":null},{"name":"附表十五  建築物污水處理設施放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380992","localPath":null},{"name":"附表十六.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000247702","localPath":null},{"name":"附表七  海水淡化廠放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380986","localPath":null},{"name":"附表十  石油化學專業區專用污水下水道系統放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380989","localPath":null},{"name":"附表十一  其他工業區專用污水下水道系統放流水水質項目及限值.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000380990","localPath":null}],"attachmentNote":"附件／附表共 19 件；本版已離線收錄 2 件，其餘保留全國法規資料庫官方連結。"},"noise-act":{"id":"noise-act","pcode":"O0030001","name":"噪音管制法","foreword":"","histories":"1.中華民國七十二年五月十三日總統令制定公布全文 14 條\r\n2.中華民國八十一年二月一日總統（81）華總（一）義字第 637  號令修\r\n  正公布全文 26 條\r\n3.中華民國八十八年十二月二十二日總統（88）華總（一）義字第 88003\r\n  03450 號令修正公布第 3、5、21 條條文\r\n4.中華民國九十二年一月八日總統華總一義字第 09100255740  號令增訂\r\n  公布第 9-1、11-1、11-2、12-1、19-1、20-1  條條文\r\n5.中華民國九十七年十二月三日總統華總一義字第 09700253151  號令修\r\n  正公布全文 37 條；並自公布日施行\r\n6.中華民國一百十年一月二十日總統華總一義字第 11000004221  號令修\r\n  正公布第 15、17 條條文\r\n  中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公告\r\n  第 2  條、第 4  條序文、第 7  條、第 9  條第 1  項第 6  款、第\r\n  2 項、第 10 條、第 11 條第 1  項、第 3  項、第 12 條、第 13 條\r\n  、第 14 條第 2  項、第 15 條第 3  項、第 16 條第 1  項、第 3  \r\n  項、第 19 條第 1  項、第 3  項、第 20 條、第 24 條第 2  項第 5\r\n  款、第 29 條、第 33 條、第 34 條、第 35 條、第 36 條所列屬「行\r\n  政院環境保護署」之權責事項，自一百十二年八月二十二日起改由「環\r\n  境部」管轄\r\n7.中華民國一百十四年十二月二十六日總統華總一義字第 11400132291\r\n  號令修正公布第 2、26、28  條條文","amended":"20251226","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0030001","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-with-attachments","articles":[{"type":"C","no":"","text":"第 一 章 總則","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 1 條","text":"為維護國民健康及環境安寧，提高國民生活品質，特制定本法。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 2 條","text":"本法所稱主管機關：在中央為環境部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 3 條","text":"本法所稱噪音，指超過管制標準之聲音。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 4 條","text":"中央主管機關之主管事項如下：\n一、全國性噪音管制政策、方案與計畫之策劃、訂定及執行。\n二、全國性噪音管制法規之制（訂）定、研議及釋示。\n三、全國性噪音監測事項之訂定及防制技術之研究發展。\n四、噪音管制標準之訂定。\n五、噪音管制工作之監督、輔導及核定。\n六、涉及二以上直轄市、縣（市）噪音管制之協調或執行。\n七、涉及二以上直轄市、縣（市）噪音管制區之劃定。\n八、重大噪音糾紛之協調。\n九、噪音管制專業人員之訓練。\n十、噪音檢驗測定機構之管理。\n十一、機動車輛之噪音檢驗。\n十二、噪音管制之宣導。\n十三、噪音管制之國際合作。\n十四、對噪音源之檢查及鑑定。\n十五、其他有關全國性噪音管制。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 5 條","text":"直轄市、縣（市）主管機關之主管事項如下：\n一、直轄市、縣（市）噪音管制工作實施方案之規劃及執行。\n二、直轄市、縣（市）噪音管制之研究發展。\n三、直轄市、縣（市）噪音糾紛之協調。\n四、直轄市、縣（市）轄境內噪音管（防）制區之劃定。\n五、直轄市、縣（市）噪音之監測。\n六、直轄市、縣（市）噪音管制之宣導。\n七、對噪音源之檢查及鑑定。\n八、其他有關直轄市、縣（市）噪音管制。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 6 條","text":"製造不具持續性或不易量測而足以妨害他人生活安寧之聲音者，由警察機關依有關法規處理之。","headingPath":["第 一 章 總則"]},{"type":"C","no":"","text":"第 二 章 管制","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 7 條","text":"直轄市及縣（市）主管機關得視轄境內噪音狀況劃定公告各類噪音管制區，並應定期檢討，重新劃定公告之；其管制區之劃分原則、劃定程序及其他應遵行事項之準則，由中央主管機關定之。\n前項管制區有特殊需要者，由中央主管機關劃定並公告之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 8 條","text":"噪音管制區內，於直轄市、縣（市）主管機關公告之時間、地區或場所不得從事下列行為致妨害他人生活環境安寧：\n一、燃放爆竹。\n二、神壇、廟會、婚喪等民俗活動。\n三、餐飲、洗染、印刷或其他使用動力機械操作之商業行為。\n四、其他經主管機關公告之行為。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 9 條","text":"噪音管制區內之下列場所、工程及設施，所發出之聲音不得超出噪音管制標準：\n一、工廠（場）。\n二、娛樂場所。\n三、營業場所。\n四、營建工程。\n五、擴音設施。\n六、其他經主管機關公告之場所、工程及設施。\n前項各款噪音管制之音量及測定之標準，由中央主管機關定之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 10 條","text":"在指定管制區內之營建工程或其他公私場所使用經中央主管機關指定之易發生噪音設施，營建工程直接承包商或其他公私場所之設施所有人、操作人，應先向直轄市、縣（市）主管機關申請許可證後，始得設置或操作，並應依許可證內容進行設置或操作。\n前項營建工程或其他公私場所之種類、規模及其應申請許可證之類別，與易發生噪音設施之種類，由中央主管機關定之。\n第一項許可證之申請及審查程序、申請書與許可證應記載事項、許可證核（換、補）發、變更、撤銷、廢止及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 11 條","text":"機動車輛、民用航空器所發出之聲音，不得超過機動車輛、民用航空器噪音管制標準；其標準，由中央主管機關會同交通部定之。\n機動車輛供國內使用者，應符合前項噪音管制標準，始得進口、製造及使用。\n使用中機動車輛、民用航空器噪音管制項目、程序、限制、檢驗人員之資格及其他應遵行事項之辦法，由中央主管機關會同交通部定之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 12 條","text":"國內生產銷售之機動車輛，應取得中央主管機關核發之車型噪音審驗合格證明，始得申請牌照；總重量逾三千五百公斤之客車及進口機動車輛，應取得中央主管機關核發之車型噪音審驗合格證明，並經中央主管機關驗證核可，始得申請牌照。\n機動車輛經前項車型噪音審驗合格後，中央主管機關得辦理噪音抽驗。\n前二項車型噪音審驗合格證明之核發、廢止、噪音抽驗及檢驗處理之辦法，由中央主管機關會同交通部定之。\n第一項總重量逾三千五百公斤之客車及進口機動車輛噪音驗證核可資格、條件、應檢附資料及其他應遵行事項之準則，由中央主管機關定之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 13 條","text":"人民得向主管機關檢舉使用中機動車輛噪音妨害安寧情形，被檢舉之車輛經主管機關通知者，應於指定期限內至指定地點接受檢驗；其檢舉辦法，由中央主管機關定之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 14 條","text":"快速道路、高速公路、鐵路及大眾捷運系統等陸上運輸系統內，車輛行駛所發出之聲音，經直轄市、縣（市）主管機關量測該路段音量，超過陸上運輸系統噪音管制標準者，營運或管理機關（構）應自直轄市、縣（市）主管機關通知之日起一百八十日內，訂定該路段噪音改善計畫，其無法改善者得訂定補助計畫，送直轄市、縣（市）主管機關核定，並據以執行。但補助計畫以改善噪音防制設施並以一次為限。\n前項陸上運輸系統之噪音管制音量及測定之標準，由中央主管機關會同交通部定之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 15 條","text":"民用機場、民用塔台所轄軍民合用機場產生之航空噪音及其他交通產生之噪音，經直轄市、縣（市）主管機關監測，超過環境音量標準者，營運或管理機關（構）應自直轄市、縣（市）主管機關通知之日起一百八十日內，訂定該區域或路段噪音改善計畫，其無法改善者得訂定補助計畫，送直轄市、縣（市）主管機關核定，並據以執行。但補助計畫以改善噪音防制設施，得視需要分期、分階段辦理補助。\n軍用塔台所轄軍民合用機場之航空噪音，其軍用航空主管機關應會商民用航空營運或管理機關（構）、直轄市、縣（市）主管機關，對於各級航空噪音防制區之航空噪音影響程度，訂定航空噪音改善計畫。軍用航空主管機關及民用航空營運或管理機關（構）應採取適當之防制或補償措施。\n第一項環境音量之數值及測定之標準，由中央主管機關會同交通部定之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 16 條","text":"經中央主管機關公告之航空站，應設置自動監測設備，連續監測其所在機場周圍地區飛航噪音狀況。\n前項監測結果，應作成紀錄，並依規定向當地主管機關申報。\n第一項機場周圍地區航空噪音防制措施、防制區劃定原則、航空噪音日夜音量測定條件、申報資料、程序及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 17 條","text":"軍用航空主管機關應會商直轄市、縣（市）主管機關，就專供軍用航空器起降之航空站，對於各級航空噪音防制區之航空噪音影響程度，訂定航空噪音改善計畫，採取適當之防制或補償措施。\n第十五條第二項及前項軍用航空主管機關所採之防制或補償措施，其防制、補償經費分配、使用、補償方式對象及其他相關事項之辦法，由國防部定之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 18 條","text":"直轄市、縣（市）主管機關應依下列原則，檢討、規劃各級航空噪音防制區內之既有土地使用及開發計畫：\n一、第一級航空噪音防制區：應檢討現有土地使用及開發計畫。\n二、第二級航空噪音防制區：不得新建學校、圖書館及醫療機構。\n三、第三級航空噪音防制區：不得新建學校、圖書館、醫療機構及不得劃定為住宅區。\n前項學校、圖書館及醫療機構採用之防音建材，於新建完成後可使室內航空噪音日夜音量低於五十五分貝，並經當地主管機關許可者，不受前項不得新建規定之限制，且不得向各目的事業主管機關申請補助。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 19 條","text":"各級主管機關得指派人員並提示有關執行職務上證明文件或顯示足資辨別之標誌，進入發生噪音或有事實足認有發生噪音之虞之公、私場所檢查或鑑定噪音狀況。\n對於前項之檢查或鑑定，任何人不得以任何理由規避、妨礙或拒絕。\n前二項規定，於主管機關檢查機動車輛、民用航空器聲音狀況時，準用之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 20 條","text":"環境檢驗測定機構應取得中央主管機關核發之許可證後，始得辦理本法規定之檢驗測定。\n前項環境檢驗測定機構應具備之條件、設施、檢驗測定人員資格限制、許可證之申請、審查程序、核（換）發、撤銷或廢止許可證、停業、復業、查核、評鑑程序及其他應遵行事項之辦法，由中央主管機關定之。\n噪音檢驗測定方法及品質管制事項，由中央主管機關公告之。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 21 條","text":"警察機關依第六條規定進行查察時，知悉有違反第九條第一項所定情事者，應即通知直轄市、縣（市）主管機關處理。","headingPath":["第 二 章 管制"]},{"type":"A","no":"第 22 條","text":"各種噪音源之改善，應由各目的事業主管機關負責輔導。","headingPath":["第 二 章 管制"]},{"type":"C","no":"","text":"第 三 章 罰則","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 23 條","text":"違反第八條規定者，處新臺幣三千元以上三萬元以下罰鍰，並令其立即改善；未遵行者，按次處罰。","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 24 條","text":"違反第九條第一項規定，經限期改善仍未符合噪音管制標準者，得依下列規定按次或按日連續處罰，或令其停工、停業或停止使用，至符合噪音管制標準時為止；其為第十條第一項取得許可證之設施，必要時並得廢止其許可證：\n一、工廠（場）：處新臺幣六千元以上六萬元以下罰鍰。\n二、娛樂或營業場所：處新臺幣三千元以上三萬元以下罰鍰。\n三、營建工程：處新臺幣一萬八千元以上十八萬元以下罰鍰。\n四、擴音設施：處新臺幣三千元以上三萬元以下罰鍰。\n五、其他經公告之場所、工程及設施：處新臺幣三千元以上三萬元以下罰鍰。\n前項限期改善之期限規定如下：\n一、工廠（場）不得超過九十日。\n二、娛樂或營業場所不得超過三十日。\n三、營建工程不得超過四日。\n四、擴音設施不得超過十分鐘。\n五、依本法第九條第一項第六款公告之場所、工程及設施，其改善期限由主管機關於公告時定之，最長不得超過九十日。\n法人或非法人之場所、工程或設施有第一項各款情事之一者，除處罰其實際從事行為之自然人外，並對該法人或非法人之負責人處以各該款之罰鍰。","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 25 條","text":"未依第十條第一項規定取得許可證者，除依下列規定處罰並限期取得許可證外，應令其立即停工、停業或停止使用；未依許可證內容設置或操作者，依下列規定處罰並通知限期改善；屆期未完成改善者，得按次處罰，或令其停工、停業或停止使用，必要時，並得廢止其許可證：\n一、處營建工程直接承包商新臺幣一萬八千元以上十八萬元以下罰鍰。\n二、處公私場所設施所有人或操作人新臺幣四千五百元以上四萬五千元以下罰鍰。","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 26 條","text":"違反依第十一條第一項所定標準者，除民用航空器依民用航空法有關規定處罰外，處機動車輛所有人或使用人新臺幣三千六百元以上三萬六千元以下罰鍰，並通知限期改善；屆期仍未完成改善者，除按次處罰外，情節重大者，並得移請公路監理機關吊扣其牌照至改善完畢後發還。\n前項情形，於一年內再度違反者，得移請公路監理機關吊扣其牌照六個月。","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 27 條","text":"違反依第十二條第三項所定辦法中有關車型噪音審驗合格證明核發、換發及噪音抽測之管理規定者，處新臺幣一萬元以上十萬元以下罰鍰，並通知限期補正或改善；屆期仍未補正或完成改善者，按次處罰，必要時，並得廢止其合格證明。","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 28 條","text":"不依第十三條規定檢驗，或經檢驗不符合管制標準者，處機動車輛所有人或使用人新臺幣三千六百元以上三萬六千元以下罰鍰，並通知限期改善；屆期仍未完成改善者，按次處罰。","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 29 條","text":"違反第十四條第一項或第十五條第一項規定，未檢送噪音改善或補助計畫或未依噪音改善或補助計畫執行，經通知限期檢送或改善、補助，屆期仍未檢送或未依改善、補助計畫執行者，由直轄市、縣（市）主管機關報請中央主管機關處營運或管理機關（構）新臺幣十萬元以上五十萬元以下罰鍰。","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 30 條","text":"違反第十六條第一項規定，未設置自動監測設備者，處航空站新臺幣十五萬元以上三十萬元以下罰鍰，並通知限期設置；屆期仍未設置者，按次處罰。\n違反第十六條第二項規定或依同條第三項所定辦法中有關機場周圍地區航空噪音防制或航空噪音測定、申報之管理規定者，處新臺幣二萬元以上十萬元以下罰鍰，並通知限期申報或補正；屆期仍未遵行者，按次處罰。","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 31 條","text":"違反第十九條第二項或第三項規定，規避、妨礙或拒絕檢查或鑑定者，處規避、妨礙或拒絕之人新臺幣三千元以上三萬元以下罰鍰，並強制執行檢查或鑑定。","headingPath":["第 三 章 罰則"]},{"type":"A","no":"第 32 條","text":"環境檢驗測定機構違反第二十條第一項規定者，處新臺幣二萬元以上二十萬元以下罰鍰，並通知限期補正或改善；屆期仍未補正或完成改善者，按次處罰。\n經取得許可證之環境檢驗測定機構，違反依第二十條第二項所定辦法中有關檢驗測定機構許可證、檢測測定人員資格限制或檢驗測定業務執行之管理規定者，處新臺幣一萬元以上十萬元以下罰鍰，並通知限期補正或改善；屆期仍未補正或完成改善者，按日連續處罰；情節重大者，得命其停業；必要時，並得廢止其許可證。","headingPath":["第 三 章 罰則"]},{"type":"C","no":"","text":"第 四 章 附則","headingPath":["第 四 章 附則"]},{"type":"A","no":"第 33 條","text":"軍事機關及其所屬單位之場所、工程、設施及機動車輛、航空器等裝備之噪音管制辦法，由中央主管機關會同國防部定之。","headingPath":["第 四 章 附則"]},{"type":"A","no":"第 34 條","text":"各級主管機關依本法應收取規費之標準，由中央主管機關定之。","headingPath":["第 四 章 附則"]},{"type":"A","no":"第 35 條","text":"未於依本法所為通知補正或改善之期限屆滿前，檢具補正資料、符合噪音管制標準或其他符合本法規定之證明文件，向主管機關報請查驗者，視為未完成補正或改善。\n未於本法規定期限屆滿前完成補正或改善者，其按日連續處罰之起算日、暫停日、停止日、改善完成認定查驗方式、法規執行方式及其他應遵行事項之準則，由中央主管機關定之。","headingPath":["第 四 章 附則"]},{"type":"A","no":"第 36 條","text":"本法施行細則，由中央主管機關定之。","headingPath":["第 四 章 附則"]},{"type":"A","no":"第 37 條","text":"本法自公布日施行。","headingPath":["第 四 章 附則"]}],"attachments":[],"attachmentNote":""},"noise-standard":{"id":"noise-standard","pcode":"O0030006","name":"噪音管制標準","foreword":"","histories":"1.中華民國八十一年六月二十九日行政院環境保護署（81）環署空字第 1\r\n  6755  號令訂定發布全文 6  條\r\n2.中華民國八十五年九月十一日行政院環境保護署（85）環署空字第 494\r\n  88  號令修正發布第 6、7 條條文\r\n3.中華民國九十四年一月三十一日行政院環境保護署環署空字第 0940007\r\n  620 號令修正發布第 3、7 條條文；除已定施行日期者外，自發布日施\r\n  行\r\n4.中華民國九十五年十一月八日行政院環境保護署環署空字第 095008760\r\n  6 號令修正發布全文 7  條；除已另定施行日期者外，自發布日施行\r\n5.中華民國九十七年二月二十五日行政院環境保護署環署空字第 0970013\r\n  826 號令修正發布第 2、4 條條文；並增訂第 6-1  條條文   \r\n6.中華民國九十八年九月四日行政院環境保護署環署空字第 0980078173\r\n  號令修正發布全文 11 條；並自發布日施行    \r\n7.中華民國一百零二年八月五日行政院環境保護署環署空字第 102006514\r\n  3 號令修正發布全文 11 條；除第 4  條自發布後一年施行、第 5～8\r\n  條自發布後六個月施行外，自發布日施行                          \r\n  中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公告\r\n  第 3  條第 6  款第 1  目、第 3  目、第 4  目、第 8  款第 1  目\r\n  、第 9  款第 1  目序文、第 2  目、第 8  條第 1  項序文、第 2  \r\n  項所列屬「行政院環境保護署」之權責事項，自一百十二年八月二十二\r\n  日起改由「環境部」管轄","amended":"20130805","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0030006","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-text-partial-attachments","articles":[{"type":"A","no":"第 1 條","text":"本標準依噪音管制法第九條第二項規定訂定之。","headingPath":[]},{"type":"A","no":"第 2 條","text":"本標準用詞，定義如下：\n一、管制區：指噪音管制區劃定作業準則規定之第一類至第四類噪音管制區。\n二、音量：以分貝（dB（A ））為單位，括號中 A  指在噪音計上 A  權位置之測量值。\n三、背景音量：指除測量音源以外之音量。\n四、周界：指場所或設施所管理或使用之界線。其有明顯圍牆等實體分隔時，以之為界；無實體分隔時，以其財產範圍或公眾不常接近之範圍為界。\n五、時段區分：\n（一）日間：指各類管制區上午七時至晚上七時。\n（二）晚間：第一、二類管制區指晚上七時至晚上十時；第三、四類管制區指晚上七時至晚上十一時。\n（三）夜間：第一、二類管制區指晚上十時至翌日上午七時；第三、四類管制區指晚上十一時至翌日上午七時。\n六、均能音量：指特定時段內所測得音量之能量平均值。20Hz  至 20kHz之均能音量以Leq表示；20Hz至200Hz之均能音量以Leq,LF表示；其計算公式如下：\n（一）\n                          ╭    ╮2\n                    1   T │Ｐt │\n      Leq ＝ 10 log ─∫  │──│ dt\n                    T   0 │Ｐ0 │\n                          ╰    ╯\n      T ：測量時間，單位為秒。\n      Pt：測量音壓，單位為巴斯噶（Pa）。\n      P0：基準音壓為20μPa。\n（二）\n                          200 Hz       0.1×Leq，n\n      Leq ，LF＝ 10 ×log  Σ       10\n                          n =20 Hz\n      Leq,n ：以 1/3  八音度頻帶濾波器測得之各 1/3  八音度頻帶均能音量。\n      n ：20 Hz 至 200 Hz 之 1/3  八音度頻帶中心頻率。\n七、最大音量（Lmax）：測量期間中測得最大音量之數值。\n八、複合音量：指欲測量地點之音量由二個以上設施所產生並合成之音量。\n九、週期性變動：指音量產生之時間週期大致一定。\n十、間歇性變動：指音量產生之週期不規則。\n十一、百分率音壓位準（Lx）：顯示測量噪音期間 x％比例時間，其噪音值大於或等於該位準。\n十二、工廠（場）：指具有以人工或機械製造、加工或修理性質之場所。\n十三、娛樂場所、營業場所：指具有營業行為之商業、休閒、餐飲或消費之場所。\n十四、營建工程：在地面上下新建、增建、改建、修建、拆除構造物與其所屬設施及改變自然環境之施工行為。\n十五、擴音設施：具有接收音源音量裝置（含可外接麥克風、收音器之功能）及音量擴大功能之設備或設施。\n十六、整體音量：指包含欲測量音源音量及背景音量之總和。","headingPath":[]},{"type":"A","no":"第 3 條","text":"噪音音量測量應符合下列規定：\n一、測量儀器：\n    測量 20 Hz  至 20 kHz 範圍之噪音計使用中華民國國家標準規定之一型聲度表或國際電工協會標準IEC61672-1Class1噪音計；測量20Hz至200Hz範圍之噪音計使用中華民國國家標準規定之一型聲度表，且應符合國際電工協會標準 IEC 61260 Class 1  等級。\n二、測量高度：\n（一）測量地點在室外時，聲音感應器應置於離地面或測量樓層之樓板延伸線一．二至一．五公尺之間。\n（二）測量地點為室內時，聲音感應器應置於離地面或樓板一．二至一．五公尺之間。\n三、動特性：\n    噪音計上動特性之選擇，原則上使用快（Fast）特性。但音源發出之聲音變動不大時，例如馬達聲等，可使用慢（Slow）特性。\n四、背景音量之修正：\n（一）測量場所之背景音量，至少與欲測量音源之音量相差十分貝（dB（A））以上，如相差之數值未達十分貝（dB（A）），則欲測量音量以下列公式計算或以附表修正之。\n（二）欲測量音源之背景音量修正公式：\n                   0.1L1    0.1L2\n      L＝10 log（10     －10      ）\n      L ：指欲測量音源之測量值。\n      L1：指整體音量之測量值。\n      L2：指背景音量之測量值。\n（三）各場所與設施負責人或現場人員應配合進行背景音量之測量，並應修正背景音量之影響；進行背景音量之測量時，負責人或現場人員無法配合者，即不須修正背景音量，並加以註明。\n（四）欲測量場所之整體音量，與背景音量相差之數值小於三分貝 dB（A）時，應停止測量，另尋其他適合測量地點或排除、減低其他噪音源之音量，再重新測量之。\n（五）欲測量場所為工廠（場）且有二十四小時全年運轉之設備，除歲修外無法停機配合測量背景音量者，得向直轄市、縣（市）主管機關提出歲修背景音量監測計畫，經直轄市、縣（市）主管機關同意後，於歲修時測量其周界外直轄市、縣（市）主管機關核定地點連續二十四小時以上七十二小時以下之音量，報請直轄市、縣（市）主管機關核備，作為核備日起二年內，測量20Hz至20kHz頻率範圍時，該工廠（場）周界外任何地點測量之背景音量修正依據。\n五、測量時間：\n    選擇發生噪音最具代表之時刻或陳情人指定之時刻測量。\n六、測量地點：\n（一）測量工廠（場）、娛樂場所、營業場所、營建工程或其他經主管機關公告之場所、工程或設施（不含風力發電機組）音源20Hz至20kHz頻率範圍時，於陳情人所指定其居住生活之地點測量。但陳情人不指定於其居住生活之地點測量者，得由主管機關指定該工廠（場）、娛樂場所、營業場所、營建工程或其他經主管機關公告之場所、工程或設施（不含風力發電機組）周界外任何地點測量之，並應距離最近建築物牆面線一公尺以上。\n（二）測量風力發電機組音源 20 Hz  至 20 kHz 頻率範圍時，於陳情人所指定其居住生活之室內地點測量。\n      測點應距離最近建築物牆面線一公尺以上，室內門窗除複查時量測整體噪音時應關閉外，其他狀況應開啟，而其他噪音源若影響測量結果者，得將其關閉暫停使用。\n（三）測量工廠（場）、娛樂場所、營業場所、營建工程或其他經主管機關公告之場所、工程或設施音源20Hz至200Hz頻率範圍時，於陳情人所指定其居住生活之室內地點測量。\n      測點應距離最近建築物牆面線一公尺以上，但欲測量音源至聲音感應器前無遮蔽物，則不在此限。室內門窗應關閉，其他噪音源若影響測量結果者，得將其關閉暫停使用。\n（四）測量擴音設施時，以擴音設施音源水平投影距離三公尺以上，主管機關指定之位置測量之。若移動性擴音設施前進時，測量地點以與移動音源最近距離不少於三公尺之主管機關指定位置測量之。\n七、氣象條件：\n    測量時應無雨且風速不得大於每秒五公尺。但於室內測量噪音者，不在此限。\n八、噪音發生源操作條件：\n（一）測量時各場所、工程及設施負責人或現場人員應提供噪音發生源之運轉狀態供主管機關查驗並記錄。\n（二）經限期改善之場所、工程及設施，於複查時其噪音發生源之運轉狀態與初測不同時，應要求其恢復至初測時相同之狀態，始得進行複查。但以變更噪音發生源操作條件作為改善措施並承諾後續以此操作條件運作者，不在此限。\n九、評定方法：\n（一）屬工廠（場）、娛樂場所、營業場所或其他經主管機關公告之場所或設施（不含風力發電機組）音源者，依下列音源發聲特性，計算最大音量（Lmax）或均能音量（Leq或Leq,LF），其結果不得超過各噪音管制標準值表中數值。\n      1.週期性變動或間歇性變動之噪音，若與背景音量相差十分貝（dB（A））以上且呈現之最大音量差異不超過五分貝（dB（A））時，以連續十次變動之最大值（Lmax）平均之。如圖（1）所示，為規則性變動的聲音，其變動週期一定。又如圖（2）所示，為間歇性的規則變動聲音，其最大值大致一定，以讀取每次最大值，共十次取算術平均。\n      2.週期性變動或間歇性變動之噪音，若與背景音量相差十分貝（dB（A））以上且呈現之最大音量差異逾五分貝（dB（A）），則取至少二十個以上之最大值（Lmax）以計算其百分率音壓位準L5。\n      3.非屬週期性變動或間歇性變動噪音之情形則以均能音量表示。其連續測量取樣時間須至少二分鐘以上，取樣時距不得多於二秒，如圖（3）所示，在噪音計指示一定時，或指針變化僅一至二分貝（dB（A））之變動情形，以均能音量表示。又如圖（4）所示，聲音的大小及發生的間隔不一定之情形，亦以均能音量表示之。\n（二）屬營建工程及其他經主管機關公告之工程音源者，其連續測量取樣時間須至少二分鐘以上，取樣時距不得多於二秒，並記錄量測時間內之最大音量（Lmax）及均能音量（Leq及Leq,LF），其結果均不得超過其噪音管制標準值。\n（三）擴音設施音源評定方法，依下列音源發聲特性，計算最大音量（Lmax）或均能音量（Leq） ，其結果不得超過其噪音管制標準值：\n      1.移動性擴音設施，以其通過時測得之最大值（Lmax）決定之。\n      2.固定或停止移動之擴音設施，則以均能音量（Leq） 表示，其連續測量取樣時間須至少二分鐘以上，取樣時距不得多於二秒。\n（四）風力發電機組噪音評定方法，以均能音量（Leq） 表示，其連續測量取樣時間須至少二分鐘以上，取樣時距不得多於二秒。","headingPath":[]},{"type":"A","no":"第 4 條","text":"工廠（場）噪音管制標準值如下：\n┌─────┬────────────┬───────────┐\n│      頻率│20 Hz 至 200 Hz         │20 Hz 至 20 kHz       │\n│    時段  │                        │                      │\n│  音量    ├───┬───┬────┼───┬───┬───┤\n│管制區    │日  間│晚  間│夜  間  │日  間│晚  間│夜  間│\n├─────┼───┼───┼────┼───┼───┼───┤\n│第一類    │  39  │  39  │  36    │  50  │  45  │  40  │\n├─────┼───┼───┼────┼───┼───┼───┤\n│第二類    │  39  │  39  │  36    │  57  │  52  │  47  │\n├─────┼───┼───┼────┼───┼───┼───┤\n│第三類    │  44  │  44  │  41    │  67  │  57  │  52  │\n├─────┼───┼───┼────┼───┼───┼───┤\n│第四類    │  47  │  47  │  44    │  80  │  70  │  65  │\n└─────┴───┴───┴────┴───┴───┴───┘","headingPath":[]},{"type":"A","no":"第 5 條","text":"娛樂場所、營業場所噪音管制標準值如下：\n┌─────┬───────────┬───────────┐\n│      頻率│20 Hz 至 200 Hz       │20 Hz 至 20 kHz       │\n│    時段  │                      │                      │\n│  音量    ├───┬───┬───┼───┬───┬───┤\n│管制區    │日  間│晚  間│夜  間│日  間│晚  間│夜  間│\n├─────┼───┼───┼───┼───┼───┼───┤\n│第一類    │  32  │  32  │  27  │  55  │  50  │  40  │\n├─────┼───┼───┼───┼───┼───┼───┤\n│第二類    │  37  │  32  │  27  │  57  │  52  │  47  │\n├─────┼───┼───┼───┼───┼───┼───┤\n│第三類    │  37  │  37  │  32  │  67  │  57  │  52  │\n├─────┼───┼───┼───┼───┼───┼───┤\n│第四類    │  40  │  40  │  35  │  80  │  70  │  65  │\n└─────┴───┴───┴───┴───┴───┴───┘","headingPath":[]},{"type":"A","no":"第 6 條","text":"營建工程噪音管制標準值如下：\n┌──────────┬────────┬────────┐\n│              頻率  │20 Hz 至 200 Hz │20 Hz 至 20kHz  │\n│          時段      │                │                │\n│      音量          ├──┬──┬──┼──┬──┬──┤\n│管制區              │日間│晚間│夜間│日間│晚間│夜間│\n├────┬─────┼──┼──┼──┼──┼──┼──┤\n│        │第一類    │44  │44  │39  │67  │47  │47  │\n│        ├─────┼──┼──┼──┼──┼──┼──┤\n│均能音量│第二類    │44  │44  │39  │67  │57  │47  │\n│（Leq 或├─────┼──┼──┼──┼──┼──┼──┤\n│Leq,LF）│第三類    │46  │46  │41  │72  │67  │62  │\n│        ├─────┼──┼──┼──┼──┼──┼──┤\n│        │第四類    │49  │49  │44  │80  │70  │65  │\n├────┼─────┼──┴──┴──┼──┼──┼──┤\n│最大音量│第一、二類│                │100 │80  │70  │\n│（Lmax）├─────┤      －        ├──┼──┼──┤\n│        │第三、四類│                │100 │85  │75  │\n└────┴─────┴────────┴──┴──┴──┘","headingPath":[]},{"type":"A","no":"第 7 條","text":"擴音設施噪音管制標準值如下：\n┌───────┬───┬───┬───┐\n│          時段│      │      │      │\n│      音量    │日  間│晚  間│夜  間│\n│管制區        │      │      │      │\n├───────┼───┼───┼───┤\n│第一類        │  57  │  47  │  40  │\n├───────┼───┼───┼───┤\n│第二類        │  72  │  57  │  47  │\n├───────┼───┼───┼───┤\n│第三類        │  77  │  62  │  52  │\n├───────┼───┼───┼───┤\n│第四類        │  82  │  72  │  62  │\n└───────┴───┴───┴───┘","headingPath":[]},{"type":"A","no":"第 8 條","text":"其他經主管機關公告之場所及設施之噪音管制標準值如下：\n一、場所及風力發電機組以外之設施\n┌─────┬───────────┬───────────┐\n│      頻率│20 Hz 至 200 Hz       │20 Hz 至 20 kHz       │\n│    時段  │                      │                      │\n│  音量    ├───┬───┬───┼───┬───┬───┤\n│管制區    │日  間│晚  間│夜  間│日  間│晚  間│夜  間│\n├─────┼───┼───┼───┼───┼───┼───┤\n│第一類    │  32  │  32  │  27  │  55  │  50  │  35  │\n├─────┼───┼───┼───┼───┼───┼───┤\n│第二類    │  37  │  32  │  27  │  57  │  52  │  42  │\n├─────┼───┼───┼───┼───┼───┼───┤\n│第三類    │  37  │  37  │  32  │  67  │  57  │  47  │\n├─────┼───┼───┼───┼───┼───┼───┤\n│第四類    │  40  │  40  │  35  │  80  │  70  │  60  │\n└─────┴───┴───┴───┴───┴───┴───┘\n二、風力發電機組：\n（一）20Hz  至 200Hz  噪音管制標準值如下：\n      ┌─────┬───────────┐\n      │      頻率│20 Hz 至 200 Hz       │\n      │    時段  │                      │\n      │  音量    ├───┬───┬───┤\n      │管制區    │日  間│晚  間│夜  間│\n      ├─────┼───┼───┼───┤\n      │第一類    │  39  │  39  │  36  │\n      ├─────┼───┼───┼───┤\n      │第二類    │  39  │  39  │  36  │\n      ├─────┼───┼───┼───┤\n      │第三類    │  44  │  44  │  41  │\n      ├─────┼───┼───┼───┤\n      │第四類    │  47  │  47  │  44  │\n      └─────┴───┴───┴───┘\n（二）20 Hz 至 20 kHz 噪音管制標準值如下：\n      1.當整體音量日間或晚間超過五十分貝（dB（A ））或夜間超過四十分貝（dB（A））時，採噪音增量管制，風力發電機組運轉時其噪音增量不得超過背景音量五分貝（dB（A）） 。\n      2.經限期改善之風力發電機組，於複查時在室內關窗且噪音發生源運轉時之全頻噪音測量結果，若未逾開窗且噪音發生源關閉時之音量，視為完成改善。\n      3.改善方式應視實際需求採音源改善、傳播路徑阻隔及受體改善等。\n其他經主管機關公告之工程，其噪音管制標準值準用第六條規定。","headingPath":[]},{"type":"A","no":"第 9 條","text":"非屬同一行為人、法人或非法人之設施所產生複合音量超過前條噪音管制標準值時，非屬同一行為人、法人或非法人之各設施均應符合依下表修正後之噪音管制標準值：\n┌──────────────┬──────────────┐\n│非屬同一行為人、法人或非法人│各設施應符合之噪音管制標準修│\n│之音源數                    │正值                        │\n├──────────────┼──────────────┤\n│            2               │            -3              │\n├──────────────┼──────────────┤\n│            3               │            -4              │\n├──────────────┼──────────────┤\n│            4               │            -6              │\n├──────────────┼──────────────┤\n│            5               │            -7              │\n├──────────────┼──────────────┤\n│          6 以上            │            -8              │\n└──────────────┴──────────────┘","headingPath":[]},{"type":"A","no":"第 10 條","text":"直轄市、縣（市）主管機關依噪音管制區劃定作業準則所劃定公告各類噪音管制區之特定管制區，其噪音管制標準值依第四條至第八條規定之噪音管制標準值降低五分貝（dB（A） ）。\n測量地點為二以上噪音管制區交界處者，其音量不得超過其中任何一區之噪音管制標準值。","headingPath":[]},{"type":"A","no":"第 11 條","text":"本標準施行日期，除第四條自發布後一年施行、第五條至第八條自發布後六個月施行外，自發布日施行。","headingPath":[]}],"attachments":[{"name":"第 2 條完整條文.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000132708","localPath":"data/law-assets/O0030006/01.pdf","sha256":"4da467e08af9590db7e00368384ea6bbe91dd411619c9fbdee7b47371532eb9c","size":122048},{"name":"第 3 條完整條文.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000132709","localPath":null},{"name":"附表：背景音量修正表.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000235583","localPath":null},{"name":"附表：背景音量修正表.DOC","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000132710","localPath":null}],"attachmentNote":"附件／附表共 4 件；本版已離線收錄 1 件，其餘保留全國法規資料庫官方連結。"},"waste-act":{"id":"waste-act","pcode":"O0050001","name":"廢棄物清理法","foreword":"","histories":"1.中華民國六十三年七月二十六日總統（63）台統（一）義字第 3300 號\r\n  令制定公布全文 28 條\r\n2.中華民國六十九年四月九日總統（69）台統（一）義字第 1968 號令修\r\n  正公布第 5、6、11、15、18、21 條條文；並增訂第 24-1 條條文\r\n3.中華民國七十四年十一月二十日總統令修正公布全文 36 條\r\n4.中華民國七十七年十一月十一日總統（77）華總義字第 5191 號令修正\r\n  公布第 4、11、20  條條文；並增訂第 10-1、23-1 條條文\r\n5.中華民國八十六年三月二十八日總統華總（一）義字第 8600077350 號\r\n  令修正公布第 10-1、23-1、31 條條文\r\n6.中華民國八十八年七月十四日總統（88）華總（一）義字第 880015981\r\n  0 號令修正公布第 5、13、17、22、34  條條文；並增訂第 34-1 條條\r\n  文\r\n7.中華民國八十九年一月十九日總統（89）華總（一）義字第 890001196\r\n  0 號令修正公布第 4、35  條條文\r\n8.中華民國九十年十月二十四日總統（90）華總一義字第 9000206500 號\r\n  令修正公布全文 77 條；並自公布日施行\r\n9.中華民國九十三年六月二日總統華總一義字第 09300104251  號令修正\r\n  公布第 51 條條文\r\n10. 中華民國九十五年五月三十日總統華總一義字第 09500075791  號令\r\n    修正公布第 46、77 條條文；依第 77 條規定：第 46 條自九十五年\r\n    七月一日施行\r\n11. 中華民國一百零一年十一月二十八日總統華總一義字第 10100264201\r\n    號令修正公布第 71、77 條條文；依第 77 條規定：第 71 條自一百\r\n    零一年九月六日施行\r\n12. 中華民國一百零二年五月二十九日總統華總一義字第 10200101291  \r\n    號令增訂公布第 50-1 條條文\r\n13. 中華民國一百零六年一月十八日總統華總一義字第 10600005851  號\r\n    令修正公布第 2、14、28、30、31、39、41、45、46、48、52、53、\r\n    55、56、58  條條文；並增訂第 2-1、39-1、63-1  條條文\r\n14. 中華民國一百零六年六月十四日總統華總一義字第 10600072531  號\r\n    令修正公布第 38、53 條條文\r\n    中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公\r\n    告第 2  條第 1  項第 5  款、第 3  項、第 5  項、第 2-1  條第\r\n    1 款、第 4  條、第 5  條第 6  項、第 6  條、第 7  條、第 8  \r\n    條、第 9  條第 1  項、第 2  項序文、第 3  項、第 12 條第 1  \r\n    項、第 14 條第 2  項、第 15 條第 2  項、第 16 條第 1  項、第\r\n    2 項、第 4  項、第 5  項、第 17 條第 4  款、第 5  款、第 18 \r\n    條第 1  項、第 2  項、第 3  項、第 4  項、第 6  項、第 19 條\r\n    、第 20 條、第 21 條、第 22 條第 1  項、第 24 條第 2  項、第\r\n    5 項、第 27 條第 11 款、第 28 條第 1  項第 3  款第 1  目、第\r\n    4 目、第 4  款、第 2  項、第 3  項、第 5  項、第 6  項第 3  \r\n    款、第 8  項、第 9  項、第 29 條第 2  項、第 30 條第 2  項、\r\n    第 31 條第 1  項、第 2  項、第 3  項、第 34 條、第 35 條、第\r\n    36  條、第 37 條第 2  項、第 38 條第 1  項、第 2  項、第 3  \r\n    項、第 4  項序文、第 39 條、第 39-1 條第 1  項序文、第 3  款\r\n    、第 2  項、第 40 條、第 41 條第 1  項序文、第 3  款、第 7  \r\n    款、第 8  款、第 2  項、第 42 條、第 43 條、第 44 條、第 46 \r\n    條第 3  款、第 49 條第 1  款、第 50-1 條第 2  項、第 51 條第\r\n    2 項第 4  款、第 3  項、第 54 條、第 60 條第 5  款、第 61 條\r\n    、第 63 條、第 63-1 條第 1  項、第 3  項、第 67 條第 1  項、\r\n    第 2  項、第 4  項、第 68 條第 2  項、第 69 條第 2  項、第 \r\n    72  條第 1  項、第 3  項、第 73 條、第 74 條、第 75 條、第 \r\n    76  條所列屬「行政院環境保護署」之權責事項，自一百十二年八月\r\n    二十二日起改由「環境部」管轄\r\n15. 中華民國一百十五年七月十五日總統華總一義字第 11500064491  號\r\n    令修正公布第 4、15～18、20、28、39、39-1、41、43、44、46、50\r\n    、51～53、55、58、63、63-1、71、77  條條文及第二章章名；增訂\r\n    第 10-1、16-1、39-2～39-5、46-1、58-1、71-1、71-2 條條文；刪\r\n    除第 21、61、64 條條文；依第 77 條規定：第 39～39-5 條及第五\r\n    章有關上開條文之處罰規定，自公布後二年施行","amended":"20260715","effectiveDate":"20280715","effectiveNote":"一百十五年七月十五日修正公布之第 39～39-5 條及第五章有關上開條文\r\n之處罰規定，自公布後二年施行。","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0050001","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-with-attachments","articles":[{"type":"C","no":"","text":"第 一 章 總則","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 1 條","text":"為有效清除、處理廢棄物，改善環境衛生，維護國民健康，特制定本法；本法未規定者，適用其他有關法律之規定。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 2 條","text":"本法所稱廢棄物，指下列能以搬動方式移動之固態或液態物質或物品：\n一、被拋棄者。\n二、減失原效用、被放棄原效用、不具效用或效用不明者。\n三、於營建、製造、加工、修理、販賣、使用過程所產生目的以外之產物。\n四、製程產出物不具可行之利用技術或不具市場經濟價值者。\n五、其他經中央主管機關公告者。\n前項廢棄物，分下列二種：\n一、一般廢棄物：指事業廢棄物以外之廢棄物。\n二、事業廢棄物：指事業活動產生非屬其員工生活產生之廢棄物，包括有害事業廢棄物及一般事業廢棄物。\n（一）有害事業廢棄物：由事業所產生具有毒性、危險性，其濃度或數量足以影響人體健康或污染環境之廢棄物。\n（二）一般事業廢棄物：由事業所產生有害事業廢棄物以外之廢棄物。\n前項有害事業廢棄物認定標準，由中央主管機關會商中央目的事業主管機關定之。\n游離輻射之放射性廢棄物之清理，依原子能相關法令之規定。\n第二項之事業，係指農工礦廠（場）、營造業、醫療機構、公民營廢棄物清除處理機構、事業廢棄物共同清除處理機構、學校或機關團體之實驗室及其他經中央主管機關指定之事業。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 2-1 條","text":"事業產出物，有下列情形之一，不論原有性質為何，為廢棄物：\n一、經中央主管機關認定已失市場經濟價值，且有棄置或污染環境、危害人體健康之虞者。\n二、違法貯存或利用，有棄置或污染環境之虞者。\n三、再利用產品未依本法規定使用，有棄置或污染環境之虞者。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 3 條","text":"本法所稱指定清除地區，謂執行機關基於環境衛生需要，所公告指定之清除地區。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 4 條","text":"本法所稱主管機關：在中央為環境部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 5 條","text":"本法所稱執行機關，為直轄市政府環境保護局、縣（市）環境保護局及鄉（鎮、市）公所。\n執行機關應設專責單位，辦理一般廢棄物之回收、清除、處理及廢棄物稽查工作。\n執行機關應負責規劃一般廢棄物回收、清除、處理用地，並協同相關機關優先配合取得用地。\n一般廢棄物之回收、清除、處理，在直轄市由直轄市政府環境保護局為之；在省轄市由省轄市環境保護局為之；在縣由鄉（鎮、市）公所負責回收、清除，由縣環境保護局負責處理，必要時，縣得委託鄉（鎮、市）公所執行處理工作。\n中華民國九十三年七月十四日前，縣環境保護局應依前項規定完成一般廢棄物工作調整，由縣環境保護局統一處理。\n第二項一般廢棄物回收項目，由中央主管機關定之。但直轄市、縣（市）主管機關得視轄區內特殊需要，增訂其他一般廢棄物回收項目，報請中央主管機關備查。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 6 條","text":"主管機關或目的事業主管機關依本法規定規劃設置廢棄物清理設施時，其用地涉及都市計畫變更者，主管機關、目的事業主管機關應協調都市計畫主管機關，依都市計畫法第二十七條規定辦理變更；涉及非都市土地使用變更者，於報准徵收或撥用取得土地後，依法辦理變更編定。完成報編為廢棄物清理專區之土地，其屬公有者，得辦理撥用或出租、讓售與興辦人，不受土地法第二十五條規定之限制。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 7 條","text":"直轄市、縣（市）主管機關，為聯合設置廢棄物處理場，辦理廢棄物清除、處理工作，得擬訂設置管理辦法，報經中央主管機關核定，組設區域性聯合清除、處理單位。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 8 條","text":"因天然災害、重大事故或其他急迫之情事，致現有廢棄物貯存、回收、清除、處理設施能量不足，而有污染環境或影響人體健康之虞時，中央主管機關應會同中央目的事業主管機關及有關機關，並報請行政院核准後，得指定廢棄物緊急清理之方法、設施、處所及其期限，不受第二十八條、第三十一條第一項第一款、第三十六條、第三十九條、第四十一條、水污染防治法第十三條、空氣污染防制法第二十四條、環境影響評估法第十六條、公司法第十五條、商業登記法第八條及都市計畫法、區域計畫法、促進產業升級條例有關土地使用管制規定之限制。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 9 條","text":"主管機關得自行或委託執行機關派員攜帶證明文件，進入公私場所或攔檢廢棄物、剩餘土石方清除機具，檢查、採樣廢棄物貯存、清除、處理或再利用情形，並命其提供有關資料；廢棄物、剩餘土石方清除機具應隨車持有載明廢棄物、剩餘土石方產生源及處理地點之證明文件，以供檢查。\n主管機關或其委託之執行機關依前項規定為行政檢查時，有下列情形之一者，得扣留清除機具、處理設施或設備，並得命該清除機具、處理設施或設備之所有人或使用人限期清除處理。必要時，並得使用或限制使用其動產、不動產或斷絕其營業所必須之自來水、電力或其他能源之處分：\n一、公私場所之廢棄物、剩餘土石方或其清除機具、處理設施或設備有嚴重污染之虞。\n二、清除機具裝載之廢棄物、剩餘土石方有嚴重污染之虞。\n前項扣留清除機具、處理設施或設備作業相關規定，由中央主管機關定之。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 10 條","text":"依前條第二項規定扣留之清除機具、處理設施或設備，於其所貯存、清除、處理或再利用之廢棄物、剩餘土石方已無嚴重污染之虞，或該清除機具、處理設施或設備之所有人或使用人妥善清除處理其廢棄物、剩餘土石方，並於繳納清除機具、處理設施或設備拖吊及保管等相關費用後發還。\n扣留清除機具、處理設施或設備之期間，以一年為限。但情形特殊者，得報經上級主管機關核准延長一次。\n第一項之清除機具、處理設施或設備拖吊及保管等相關費用之收費方式及標準，由直轄市、縣（市）主管機關定之。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 10-1 條","text":"為掌握廢棄物流向，防止污染或危害環境案件發生，主管機關對於經常發生或經合理判斷可能發生非法清除、回填、堆置、再利用、處理廢棄物之道路或其他公共場所，得自行、協調相關機關（構）裝設或利用監視攝錄系統及其他科技工具蒐集、處理及利用資料。\n主管機關、執行機關或目的事業主管機關就本法規定事項所實施之檢查、查核、採樣及查證，得請求有關機關（構）、法人、團體協助或提供必要之資料。","headingPath":["第 一 章 總則"]},{"type":"C","no":"","text":"第 二 章 一般廢棄物及應回收廢棄物之清理","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 11 條","text":"一般廢棄物，除應依下列規定清除外，其餘在指定清除地區以內者，由執行機關清除之：\n一、土地或建築物與公共衛生有關者，由所有人、管理人或使用人清除。\n二、與土地或建築物相連接之騎樓或人行道，由該土地或建築物所有人、管理人或使用人清除。\n三、因特殊用途，使用道路或公共用地者，由使用人清除。\n四、火災或其他災變發生後，經所有人拋棄遺留現場者，由建築物所有人或管理人清除；無力清除者，由執行機關清除。\n五、建築物拆除後所遺留者，由原所有人、管理人或使用人清除。\n六、家畜或家禽在道路或其他公共場所便溺者，由所有人或管理人清除。\n七、化糞池之污物，由所有人、管理人或使用人清除。\n八、四公尺以內之公共巷、弄路面及水溝，由相對戶或相鄰戶分別各半清除。\n九、道路之安全島、綠地、公園及其他公共場所，由管理機構清除。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 12 條","text":"一般廢棄物回收、清除、處理之運輸、分類、貯存、排出、方法、設備及再利用，應符合中央主管機關之規定，其辦法，由中央主管機關定之。\n執行機關得視指定清除地區之特性，增訂前項一般廢棄物分類、貯存、排出之規定，並報其上級主管機關備查。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 13 條","text":"各級執行機關，應視實際需要，於適當地點及公共場所，設一般廢棄物回收、貯存設備。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 14 條","text":"一般廢棄物，應由執行機關負責清除，並作適當之衛生處理。但家戶以外所產生者，得由執行機關指定其清除方式及處理場所。\n前項一般廢棄物之清除、處理，執行機關得報經上級主管機關核准，委託公民營廢棄物清除處理機構或依中央主管機關公告或核准之方式辦理。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 15 條","text":"本章所稱應回收廢棄物，指為促進廢棄物循環利用，減輕物質生命週期對環境生態之影響，符合下列情形之一之廢棄物，經中央主管機關指定者：\n一、物品或其包裝、容器經食用或使用後，足以產生下列性質之一之廢棄物：\n（一）不易清除處理。\n（二）含長期不易腐化之成分。\n（三）含有害物質之成分。\n（四）具回收再利用之價值。\n二、經中央主管機關指定之再生能源發電設備經使用後產生之廢棄物。\n前項第一款應回收廢棄物，由該物品或其包裝、容器之製造、輸入、販賣或原料之製造、輸入、販賣業者負責回收、清除、處理；第二款應回收廢棄物，由再生能源發電設備之製造、輸入或設備設置者負責回收、清除、處理。\n第一項第一款物品或其包裝、容器、第二款再生能源發電設備之指定及前項應負責回收、清除、處理之業者（以下簡稱責任業者）範圍，由中央主管機關公告之。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 16 條","text":"前條第一項第一款應回收廢棄物之責任業者，應向中央主管機關辦理登記；製造業應按當期營業量，輸入業應按向海關申報進口量，販賣業應按當期銷售量，於每期營業稅申報繳納後十五日內，依中央主管機關核定之費率，繳納回收清除處理費。\n前項輸入業於向海關申報進口量時，應同時申報容器材質及其他經中央主管機關指定之物品或容器規格等資料。\n製造、輸入或販賣之物品或其包裝、容器，不在國內廢棄或使用後不產生廢棄物之責任業者，得檢具相關證明文件扣抵營業量、進口量、銷售量或辦理退費。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 16-1 條","text":"第十五條第一項第二款應回收廢棄物之責任業者，應向中央主管機關辦理登記；設備設置者應按當期購買量，製造業應按當期營業量扣抵設備設置者之購買量，輸入業應按向海關申報進口量扣抵當期設備設置者之購買量後，依中央主管機關核定之費率，繳納回收清除處理費。\n經目的事業主管機關全部或部分廢止同意備案或設備登記文件之再生能源發電設備設置者，應向中央主管機關提出回收計畫，並載明採自建回收鏈或依第十八條第四項規定申請補貼，經中央主管機關核准後據以執行；該設備設置者，於妥善清除處理應回收廢棄物後，得檢具相關紀錄及證明文件，向中央主管機關申請退費或補貼。\n第一項及前條第一項之回收清除處理費，應納入資源回收管理基金，委託金融機構收支保管，並按一定比例分別撥入信託基金及非營業基金；其一定比例與信託基金之收支、保管及運用之辦法，由中央主管機關定之。\n責任業者依第一項、第二項及前條規定辦理登記、申報、扣抵與回收清除處理費之繳費方式、流程、期限、回收計畫應記載事項、退費、管理及其他應遵行事項之辦法，由中央主管機關定之。\n第一項及前條第一項費率，由中央主管機關所設之資源回收費率審議會依材質、容積、重量、對環境之影響、再利用價值、回收清除處理成本、回收清除處理率、稽徵成本、基金財務狀況、回收獎勵金數額及其他相關因素審議，送中央主管機關核定公告；中央主管機關得訂定費率公式，依市場價格、物價變動指數及其他經資源回收費率審議會審定之相關因素，適時檢討費率並核定公告。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 17 條","text":"資源回收管理基金信託基金，應使用於回收清除處理補貼用途。\n資源回收管理基金非營業基金，應使用於下列用途：\n一、補助獎勵回收系統。\n二、執行機關代清理費用。\n三、依第十八條第五項執行稽核認證費用。\n四、其他經中央主管機關同意，與廢棄物資源回收有關之用途。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 18 條","text":"應回收廢棄物之回收、貯存、清除、處理方法及設施標準，由中央主管機關依其種類定之。\n應回收廢棄物之回收、處理業達一定規模者，應向直轄市、縣（市）主管機關辦理登記，並申報其回收、處理量及相關作業情形。\n前項回收、處理業之一定規模、登記、註銷、申報、管理及其他應遵行事項之辦法，由中央主管機關定之。\n責任業者及第二項回收、處理業符合第一項所定標準，且應回收廢棄物之回收處理量經中央主管機關稽核認證者，得向資源回收管理基金申請前條第一項之回收清除處理補貼。\n中央主管機關得委託法人（以下簡稱稽核認證團體）辦理前項稽核認證作業，並應定期對稽核認證團體進行作業成效之評鑑及考核；稽核認證作業之辦理方式、評鑑、考核及其他相關事項之辦法，由中央主管機關定之。\n第四項回收清除處理補貼之申請、審核、廢止、追償、管理及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 19 條","text":"中央主管機關指定公告責任業者，應於物品或其包裝、容器上標示回收相關標誌；其業者範圍、標誌圖樣大小、位置及其他應遵行事項，由中央主管機關定之。\n經中央主管機關指定公告之物品或其包裝、容器之販賣業者，應依中央主管機關之規定，設置資源回收設施，並執行回收工作；其業者範圍、設施設置、規格及其他應遵行事項，由中央主管機關定之。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 20 條","text":"主管機關得派員或委託專業人員攜帶證明文件進入責任業者與物品或其包裝、容器、再生能源發電設備使用業者之場所及第十八條第二項所定回收、處理業之回收、貯存、清除、處理場所，查核其營業量或進口量、物品或其包裝、容器及再生能源發電設備之銷售對象、銷售量、購買量或使用量、原料供應來源、回收相關標誌、應回收廢棄物回收處理量，並索取進貨、生產、銷貨、存貨憑證、帳冊、相關報表及其他產銷營運或輸出入之相關資料。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 21 條","text":"（刪除）","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 22 條","text":"中央主管機關得指定公告以回收獎勵金方式，回收應回收廢棄物之種類及其回收獎勵金數額。\n販賣業應依公告之回收獎勵金數額支付消費者，不得拒絕。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 23 條","text":"中華民國八十六年三月二十八日前，由責任業者組成之共同回收清除處理組織及依相關法規成立之基金會賸餘回收清除相關費用，應移撥資源回收管理基金，依規定運用。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 24 條","text":"直轄市、縣（市）主管機關為執行一般廢棄物之清除、處理，應依清除處理成本，向指定清除地區內家戶及其他非事業徵收費用。\n前項費用之徵收方式、計算方式、繳費流程、繳納期限及其他應遵行事項之徵收辦法，由中央主管機關定之。\n直轄市、縣（市）主管機關得衡酌實際作業需要，增訂前項以外之費用徵收相關規定及收費證明標誌。\n第一項徵收費用之數額，由直轄市、縣（市）主管機關訂定公告之。\n第三項所增訂費用徵收相關規定，應報中央主管機關備查。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 25 條","text":"前條第一項之一般廢棄物清除處理成本，包括一般廢棄物清除、處理業務之管理成本、人工成本、處理場（廠）土地使用成本、回饋金與各項清除處理機具或設備、設施之操作維護成本及依使用年限每年平均應負擔之購置成本、復育成本，並扣除代清除、處理一般事業廢棄物及其他收入。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 26 條","text":"前條之一般廢棄物清除處理成本，應依實際成本收費。但機具、設備、設施、復育成本，自中華民國九十年起分年徵收。\n直轄市、縣（市）主管機關針對民有民營一般廢棄物焚化廠之每公噸建設成本、復育成本，應自中華民國九十年起分年徵收。\n第一項之機具、設備、設施、復育成本及前項之建設成本，直轄市、縣（市）主管機關應自中華民國九十年起專款專儲，並於中華民國九十一年成立一般廢棄物清除處理基金。中華民國九十年專儲之清除處理費，應於基金成立後轉存。\n前項基金之設置運用及管理辦法，由直轄市、縣（市）主管機關定之。\n第三項設置之基金，應專款專用於一般廢棄物清除處理機具或設備、設施之重置及一般廢棄物處理場（廠）之復育。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"A","no":"第 27 條","text":"在指定清除地區內嚴禁有下列行為：\n一、隨地吐痰、檳榔汁、檳榔渣，拋棄紙屑、煙蒂、口香糖、瓜果或其皮、核、汁、渣或其他一般廢棄物。\n二、污染地面、池溏、水溝、牆壁、樑柱、電桿、樹木、道路、橋樑或其他土地定著物。\n三、於路旁、屋外或屋頂曝晒、堆置有礙衛生整潔之物。\n四、自廢棄物清除、處理及貯存工具、設備或處所中搜揀經廢棄之物。但搜揀依第五條第六項所定回收項目之一般廢棄物，不在此限。\n五、拋置熱灰燼、危險化學物品或爆炸性物品於廢棄物貯存設備。\n六、棄置動物屍體於廢棄物貯存設備以外處所。\n七、隨地便溺。\n八、於水溝棄置雜物。\n九、飼養禽、畜有礙附近環境衛生。\n十、張貼或噴漆廣告污染定著物。\n十一、其他經主管機關公告之污染環境行為。","headingPath":["第 二 章 一般廢棄物及應回收廢棄物之清理"]},{"type":"C","no":"","text":"第 三 章 事業廢棄物之清理","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 28 條","text":"事業廢棄物之清理，除再利用方式外，應以下列方式為之：\n一、自行清除、處理。\n二、共同清除、處理：由事業向目的事業主管機關申請許可設立清除、處理該類廢棄物之共同清除處理機構清除、處理。\n三、委託清除、處理：\n（一）委託經主管機關許可清除、處理該類廢棄物之公民營廢棄物清除處理機構清除、處理。\n（二）經執行機關同意，委託其清除、處理。\n（三）委託目的事業主管機關自行或輔導設置之廢棄物清除處理設施清除、處理。\n（四）委託主管機關指定之公營事業設置之廢棄物清除處理設施清除、處理。\n（五）委託依促進民間參與公共建設法與主辦機關簽訂投資契約之民間機構設置之廢棄物清除處理設施清除、處理。\n（六）委託依第二十九條第二項所訂管理辦法許可之事業之廢棄物處理設施處理。\n四、其他經中央主管機關許可之方式。\n經中央主管機關指定公告之事業，應置專業技術人員，其採自行清除、處理事業廢棄物之事業，其清除機具及處理設施或設備應具備之條件、許可、許可期限、廢止及其他應遵行事項之管理辦法，由中央主管機關會同中央目的事業主管機關定之。\n第一項第二款共同清除處理機構應具備之條件、分級、許可、許可期限、廢止、專業技術人員設置、營運、操作紀錄與其他應遵行事項之管理辦法，由中央目的事業主管機關會同中央主管機關定之。\n第一項第三款第三目所輔導設置之廢棄物清除處理設施應具備之專業技術人員設置、營運、操作紀錄與其他應遵行事項之管理辦法，由中央目的事業主管機關會商相關機關定之。\n第一項第三款第四目及第五目所設置之廢棄物清除處理設施應具備之專業技術人員設置、營運、操作紀錄與其他應遵行事項之管理辦法，由中央主管機關會商相關機關定之。\n第一項第三款第二目執行機關受託清除處理一般事業廢棄物，應於處理下列一般廢棄物後，仍有餘裕處理能量，始得為之，並依直轄市、縣（市）主管機關所定事業廢棄物代清除處理收費標準收費，並配合該事業依第三十一條第一項第二款規定辦理申報：\n一、屬指定清除地區內者。\n二、屬依第七條及地方制度法第二十四條之一規定之區域性聯合及跨區域合作處理者。\n三、屬中央主管機關統一調度者。\n一般廢棄物或一般事業廢棄物之清除處理設施，不得合併清除、處理有害事業廢棄物。\n中央主管機關於不影響執行機關處理第六項第一款及第二款一般廢棄物情形下，於必要時得統一調度使用現有廢棄物清除處理設施，被調度者不得拒絕。\n直轄市、縣（市）主管機關或執行機關受中央主管機關補助及依促進民間參與公共建設法興建、營運之廢棄物處理設施，經中央主管機關指定者，其受補助對象及主辦機關、民間機構應保留一定比例之餘裕處理量，供中央主管機關統籌調度，並納入委託操作及投資相關契約明定之。\n前二項統一調度之條件、方式、費用、指定之廢棄物處理設施、一定比例之餘裕處理量及其他相關事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 29 條","text":"事業之廢棄物處理設施之處理容量有餘裕時，得經處理設施所在地主管機關許可，提供其他事業使用，不受第三十一條第一項第一款、第四十一條之限制。\n前項餘裕處理量之提供條件、許可程序、許可期限及其他應遵行事項之管理辦法，由中央主管機關會商中央目的事業主管機關定之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 30 條","text":"事業委託清理其廢棄物，應與受託人就該廢棄物負連帶清理責任。如受託者未妥善清理，且委託事業未盡相當注意義務者，委託事業應與受託者就該廢棄物負連帶清理及環境改善責任。\n前項委託事業之相當注意義務之認定要件、注意事項、管理措施及其他相關事項之準則，由中央主管機關定之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 31 條","text":"經中央主管機關指定公告一定規模之事業，應於公告之一定期限辦理下列事項：\n一、檢具事業廢棄物清理計畫書，送直轄市、縣（市）主管機關或中央主管機關委託之機關審查核准後，始得營運；與事業廢棄物產生、清理有關事項變更時，亦同。\n二、依中央主管機關規定之格式、項目、內容、頻率，以網路傳輸方式，向直轄市、縣（市）主管機關申報其廢棄物之產出、貯存、清除、處理、再利用、輸出、輸入、過境或轉口情形。但中央主管機關另有規定以書面申報者，不在此限。\n三、中央主管機關指定公告之事業廢棄物清運機具，應依中央主管機關所定之規格，裝置即時追蹤系統並維持正常運作。\n前項第一款事業廢棄物清理計畫書之格式及應載明事項，由中央主管機關會商中央目的事業主管機關定之。\n第一項第一款事業廢棄物清理計畫書核准之審查作業、變更、撤銷、廢止及其他應遵行事項之辦法，由中央主管機關定之。\n第一項事業依規定應實施環境影響評估者，於提報環境影響評估相關文件時，得一併檢具事業廢棄物清理計畫書，送直轄市、縣（市）主管機關審查。俟環境影響評估審查通過後，由直轄市、縣（市）主管機關逕予核准。\n清除、處理第一項指定公告之事業所產生之事業廢棄物者，應依第一項第二款規定辦理申報。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 32 條","text":"新設工業區及科學園區之目的事業主管機關、開發單位或管理單位，應於區內或區外規劃設置事業廢棄物處理設施；並於事業廢棄物處理設施設置完成後，該工業區及科學園區始得營運。\n現有工業區及科學園區之目的事業主管機關、開發單位或管理單位，應於本法修正通過後六個月內，規劃完成事業廢棄物之處理設施，經中央目的事業主管機關核准後，最遲於中華民國九十三年十二月三十一日完成設置。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 33 條","text":"事業無法自行處理其所產生之事業廢棄物，亦無事業廢棄物處理機構可供委託處理時，事業應妥善貯存其所產生之事業廢棄物。必要時，目的事業主管機關得向事業收取費用，自行或輔導設置事業廢棄物處理設施處理或暫時貯存之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 34 條","text":"事業無法自行清理其所產生之事業廢棄物，亦無事業廢棄物處理機構可供委託處理時，中央目的事業主管機關得會商中央主管機關，指定公告特定地區之事業，應將其事業廢棄物，送至中央目的事業主管機關自行或輔導設置之事業廢棄物處理設施處理。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 35 條","text":"中央主管機關，對於需經特殊技術處理之有害事業廢棄物，得會同中央目的事業主管機關，設置適當設施，代為貯存、清除或處理，並收取必要費用。\n前項有害事業廢棄物，由中央主管機關會同中央目的事業主管機關公告之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 36 條","text":"事業廢棄物之貯存、清除或處理方法及設施，應符合中央主管機關之規定。\n前項事業廢棄物之貯存、清除、處理方法及設施標準，由中央主管機關定之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 37 條","text":"事業對於有害事業廢棄物貯存、清除、處理之操作及檢測，應作成紀錄妥善保存三年以上，以供查核。\n前項檢測之項目、方法、頻率及其他應遵行事項之管理辦法，由中央主管機關定之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 38 條","text":"事業廢棄物之輸入、輸出、過境、轉口，應向直轄市、縣（市）主管機關申請核發許可文件，始得為之；其屬有害事業廢棄物者，並應先經中央主管機關之同意。但經中央主管機關會商目的事業主管機關公告屬產業用料需求者，不在此限。\n有害事業廢棄物應以國內處理或再利用為原則，並僅限輸出至經濟合作暨發展組織會員國、依據國際公約與我國簽署有害廢棄物越境轉移雙邊協定國家或其他經中央主管機關公告之國家、地區，且接受國處理機構應具有妥善處理及再利用能力。\n前二項之事業廢棄物輸入、輸出、過境、轉口之申請資格、文件、審查、許可、許可期限、廢止及其他應遵行事項之管理辦法，由中央主管機關定之。\n事業廢棄物有下列情形之一者，禁止輸入；其種類，由中央主管機關會商中央目的事業主管機關公告之：\n一、有嚴重危害人體健康或生活環境之事實。\n二、於國內無適當處理技術及設備。\n三、直接固化處理、掩埋、焚化或海拋。\n四、於國內無法妥善清理。\n五、對國內廢棄物處理有妨礙。\n屬國際公約列管之一般廢棄物之輸入、輸出、過境、轉口，準用前四項規定辦理。\n第二項規定自中華民國一百零六年五月二十六日修正之條文公布後一年施行。但修正公布前，已取得第一項許可文件者，其有效期限至原核准許可期限屆至為止。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 39 條","text":"事業廢棄物之再利用，應以下列方式為之：\n一、事業依規定自行再利用：\n（一）送回原生產製程當作原料。\n（二）於原廠（場）內。\n（三）送至同一事業之其他分廠（場）。\n二、前款各目依中央主管機關指定之再利用種類及管理方式，事業應依第三十一條第一項規定，檢具事業廢棄物清理計畫書，送直轄市、縣（市）主管機關審查核准後，進行再利用。但前款第一目與原生產製程原料之特性、性質相符者，得逕行再利用。\n三、第一款第一目非屬前款情形，事業應檢具事業廢棄物清理計畫書，送直轄市、縣（市）主管機關審查核准後，進行再利用。\n四、由收受事業廢棄物再利用之廠（場）（以下簡稱再利用機構）依規定進行再利用，不適用第四十一條規定：\n（一）經中央主管機關指定再利用種類及管理方式之事業廢棄物，再利用機構應向直轄市、縣（市）主管機關申請檢核通過後，進行再利用。\n（二）前目以外之事業廢棄物，再利用機構應向中央主管機關申請取得再利用許可及向直轄市、縣（市）主管機關申請檢核通過後，依許可文件及檢核內容進行再利用。\n依前項規定進行再利用之事業及再利用機構（以下合稱再利用事業），屬第三十一條第一項所定事業者，就其廢棄物之產出、貯存、清除、處理、再利用、輸出、輸入、過境或轉口情形，應依該條第一項至第三項規定辦理。\n再利用事業應記錄及申報再利用營運情形、再利用產品流向、數量；並應就中央主管機關指定之再利用產品，記錄及申報其使用情形。\n第一項事業廢棄物再利用種類、管理方式之指定、事業廢棄物清理計畫書之提送、審查、核准、再利用檢核之申請、再利用許可之申請、審查、許可事項、廢止、前項再利用產品之指定、記錄與申報之事項、頻率、管理及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 39-1 條","text":"經中央主管機關指定之再利用產品，其使用者應記錄與申報再利用產品流向、數量及實際使用地點；有下列情形之一者，必要時，應實施環境監測，並保存使用證明以供查核：\n一、用於填海或填築土地。\n二、有不當利用、污染環境或危害人體健康之虞。\n三、其他經中央主管機關認定須加強管制。\n前項應實施環境監測之再利用產品使用者，應檢具環境監測計畫書報直轄市、縣（市）主管機關核准，並應將其採樣情形及監測結果作成紀錄，檢具環境監測結果報告報直轄市、縣（市）主管機關備查後，於中央主管機關指定之網站公開產品流向及監測結果。\n第一項再利用產品之指定、記錄與申報之項目、頻率及使用證明保存、前項環境監測計畫書應記載事項、申請、審查、核准、採樣與監測結果紀錄、環境監測結果報告之備查、產品流向與監測結果之公開及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 39-2 條","text":"中央主管機關得考量事業廢棄物或再利用產品之用途、成分、特性、數量、棄置風險及其他相關因素，指定產源事業、再利用事業及再利用產品使用者，採取下列全部或一部之管理措施：\n一、簽訂再利用委託或再利用產品銷售契約書及記載中央主管機關指定事項。\n二、進行再利用產品或再利用製程之驗證。\n三、進行再利用產品檢測。\n四、限制再利用產品銷售對象。\n五、限制再利用產品使用用途或方式。\n六、設置中央主管機關指定之設備。\n七、設置專業技術人員。\n八、設置閉路電視錄影監視系統及瀏覽伺服，供主管機關檢視。\n九、其他經中央主管機關指定之管理措施。\n前項產源事業、再利用事業及再利用產品使用者之指定、契約書應記載事項、驗證事項、產品檢測事項、檢測報告應具備之內容、銷售對象、使用用途或方式、設備設置、專業技術人員設置、監視系統及瀏覽伺服規格、其他管理措施之指定及相關應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 39-3 條","text":"再利用事業生產經中央主管機關指定之再利用產品，應符合產品品質規範，並於產品或其包裝、容器、銷售相關文件明顯處，標示使用限制、警語及供料履歷。\n再利用事業依前條第一項第二款規定，應進行再利用產品或再利用製程之驗證者，其生產之再利用產品應經中央主管機關認可之驗證機構或認證機關（構）認證之驗證機構驗證後，始得出廠（場）。\n第一項再利用產品之指定、再利用產品品質規範、標示、使用限制、警語、供料履歷，及前項驗證機構與認證機關（構）資格、驗證與認證程序、驗證與認證事項、廢止、管理及其他應遵行事項之辦法，由中央主管機關定之。\n中央目的事業主管機關應輔導再利用事業進行生產之改善及推廣再利用產品，並得委託或委辦其他機關（構）、法人或團體辦理。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 39-4 條","text":"再利用事業有下列情形之一者，主管機關得令其停止收受事業廢棄物進廠（場）：\n一、未於一定期限內完成廢棄物再利用作業。\n二、再利用設備故障或異常，未能於一定期限內完成修復。\n三、再利用產品貯存量超過一定期間之累積產出量或銷售量。\n四、規避、妨礙、拒絕主管機關依第九條第一項規定之檢查或提供再利用有關資料。\n五、其他經主管機關認定與再利用行為相關之違法情形。\n再利用事業有下列情形之一者，主管機關得令其停止再利用運作：\n一、未依第三十九條第一項所定方式進行再利用。\n二、未依第三十九條之二第一項第二款規定進行再利用產品或製程驗證。\n三、未依第三十九條之二第一項第三款規定進行再利用產品檢測。\n四、未依第三十九條之二第一項第六款規定設置中央主管機關指定之設備。\n五、有前項第四款或第五款規定情形。\n再利用事業有下列情形之一者，主管機關得令其停止銷售或運送再利用產品出廠（場）：\n一、未依第三十九條之二第一項第四款規定銷售再利用產品；或生產第三十九條之三第一項所定再利用產品，不符合產品品質規範。\n二、提供不實之再利用產品檢測報告或驗證證明文件。\n三、明知再利用產品之使用者未依第三十九條之二第一項第五款規定使用再利用產品，仍繼續銷售或運送。\n四、有第一項第四款或第五款規定情形。\n經主管機關作成前三項處分，再利用事業應檢具改善證明文件報請主管機關核准後，始得恢復再利用相關行為。\n第一項之一定期限及期間、前四項停止收受廢棄物進廠（場）、停止再利用運作、停止銷售或運送再利用產品出廠（場）之情形、改善證明文件應記載事項、核准之申請及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 39-5 條","text":"加工再製中央主管機關指定之再利用產品者（以下簡稱加工再製事業），應依第三十一條第一項至第三項規定，於事業廢棄物清理計畫書載明加工再製流程，送直轄市、縣（市）主管機關或中央主管機關委託之機關審查核准後，始得為之。\n加工再製事業記錄、申報加工再製之再利用產品及產品品質規範、標示事項、驗證、專業技術人員設置與停止加工再製運作、銷售、運送與恢復加工再製相關行為及中央主管機關得對其採取之管理措施，準用第三十九條第三項、第四項、第三十九條之二至前條規定。\n經中央主管機關指定加工再製之再利用產品，其使用者記錄、申報、使用證明保存、檢具環境監測報告書申請核准與環境監測結果報告之備查、產品流向及監測結果之公開，準用第三十九條之一規定。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"A","no":"第 40 條","text":"事業於貯存、清除或處理事業廢棄物，危害人體健康或農、漁業時，主管機關應立即命其改善，並採取緊急措施。必要時，得命其停工或停業。","headingPath":["第 三 章 事業廢棄物之清理"]},{"type":"C","no":"","text":"第 四 章 公民營廢棄物清除處理機構及廢棄物檢驗測定機構之管理","headingPath":["第 四 章 公民營廢棄物清除處理機構及廢棄物檢驗測定機構之管理"]},{"type":"A","no":"第 41 條","text":"從事廢棄物清除、處理業務者，應向直轄市、縣（市）主管機關或中央主管機關委託之機關申請核發公民營廢棄物清除處理機構許可文件後，始得受託清除、處理廢棄物業務。但有下列情形之一者，不在此限：\n一、執行機關依第五條第二項、第六項、第十二條第一項辦理一般廢棄物之回收、清除、處理、再利用。\n二、依第八條規定緊急清理廢棄物所指定之設施或設備。\n三、依第十四條第二項規定依中央主管機關公告或核准之方式清除、處理一般廢棄物。\n四、依第十八條第一項所定標準回收、貯存、清除、處理廢棄物。\n五、第二十八條第一項第二款、第三款第二目至第五目、第四款之清除機具、處理設施或設備。\n六、目的事業主管機關依第三十三條、第三十四條規定自行或輔導設置之處理設施。\n七、中央主管機關會同中央目的事業主管機關依第三十五條第一項設置之設施。\n八、其他經中央主管機關公告者。\n前項公民營廢棄物清除處理機構許可文件之核發，應副知中央主管機關。","headingPath":["第 四 章 公民營廢棄物清除處理機構及廢棄物檢驗測定機構之管理"]},{"type":"A","no":"第 42 條","text":"前條第一項規定之公民營廢棄物清除處理機構應具備之條件、自有設施、分級、專業技術人員設置、許可、許可期限、廢止許可、停工、停業、歇業、復業及其他應遵行事項之管理辦法，由中央主管機關定之。","headingPath":["第 四 章 公民營廢棄物清除處理機構及廢棄物檢驗測定機構之管理"]},{"type":"A","no":"第 43 條","text":"廢棄物之檢驗測定，除經中央主管機關核准外，應由取得中央主管機關核發許可證之檢驗測定機構辦理。\n前項檢驗測定機構應具備之條件、設施、檢驗測定人員資格限制、許可證之申請、審查程序、許可事項、廢止、許可證核（換）發、停業、復業、查核、評鑑程序、管理及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 四 章 公民營廢棄物清除處理機構及廢棄物檢驗測定機構之管理"]},{"type":"A","no":"第 44 條","text":"第二十八條第二項至第五項、第三十九條之二第一項第七款、第三十九條之五第二項、第四十二條所定專業技術人員之資格、合格證書取得、廢止、訓練、執行業務、管理及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 四 章 公民營廢棄物清除處理機構及廢棄物檢驗測定機構之管理"]},{"type":"C","no":"","text":"第 五 章 獎勵及處罰","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 45 條","text":"違反第十二條、第十八條第一項、第二十八條第一項、第七項、第三十六條第一項、第三十八條第一項、第三十九條或第四十一條第一項規定，因而致人於死者，處無期徒刑或七年以上有期徒刑，得併科新臺幣三千萬元以下罰金；致重傷者，處三年以上十年以下有期徒刑，得併科新臺幣二千五百萬元以下罰金；致危害人體健康導致疾病者，處一年以上七年以下有期徒刑，得併科新臺幣二千萬元以下罰金。\n偽造、變造第二十四條第三項收費證明標誌者，處二年以上七年以下有期徒刑，得併科新臺幣一千萬元以下罰金。\n販賣前項收費證明標誌者，處一年以上七年以下有期徒刑，得併科新臺幣一千萬元以下罰金。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 46 條","text":"有下列情形之一者，處一年以上七年以下有期徒刑，得併科新臺幣一千五百萬元以下罰金：\n一、任意棄置有害事業廢棄物。\n二、事業負責人或相關人員未依本法規定之方式貯存、清除、處理或再利用廢棄物，足以生污染環境。\n三、未經主管機關許可，提供土地回填、堆置廢棄物。\n四、未依第三十九條第一項第四款第二目或第四十一條第一項規定取得許可文件，從事廢棄物清除、處理或再利用。\n五、未依第三十九條第一項所定再利用方式或未依第四十一條第一項取得之廢棄物清除、處理許可文件內容貯存、清除、處理或再利用，足以生污染環境。\n於中央主管機關公告之生態、資源利用環境敏感地區內，犯前項之罪者，加重其刑至二分之一。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 46-1 條","text":"有下列情形之一者，處六月以上五年以下有期徒刑，得併科新臺幣一千萬元以下罰金：\n一、執行機關之人員委託非法清除、處理或再利用業者，清除、處理或再利用廢棄物；或明知受託人非法清除、處理或再利用而仍委託。\n二、公民營廢棄物處理機構、共同處理機構、再利用機構或第二十八條第一項第三款第三目至第六目之處理設施負責人或相關人員、執行機關之人員未處理或再利用廢棄物，開具虛偽證明。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 47 條","text":"法人之負責人、法人或自然人之代理人、受僱人或其他從業人員，因執行業務犯前二條之罪者，除處罰其行為人外，對該法人或自然人亦科以各該條之罰金。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 48 條","text":"依本法規定有申報義務，明知為不實之事項而申報不實或於業務上作成之文書為虛偽記載者，處三年以下有期徒刑、拘役或科或併科新臺幣一千萬元以下罰金。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 49 條","text":"有下列情形之一者，處新臺幣六萬元以上三十萬元以下罰鍰，並得沒入清除機具、處理設施或設備：\n一、清除機具、處理設施或設備之所有人或使用人未於主管機關依第九條第二項所定期限內清除處理其廢棄物、剩餘土石方。\n二、清除廢棄物、剩餘土石方者，未隨車持有載明一般廢棄物、一般事業廢棄物、剩餘土石方產生源及處理地點之證明文件。\n三、清除有害事業廢棄物者，未隨車持有載明有害事業廢棄物產生源及處理地點之證明文件。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 50 條","text":"有下列情形之一者，處新臺幣一千二百元以上十萬元以下罰鍰，並得通知限期改善，屆期仍未完成改善者，按次處罰：\n一、不依第十一條第一款至第七款規定清除一般廢棄物。\n二、違反依第十二條第一項所定辦法有關一般廢棄物回收、清除、處理之運輸、分類、貯存、排出、方法、設備或再利用之規定；或同條第二項之分類、貯存、排出規定。\n三、為第二十七條各款行為之一。\n動力車輛駕駛人或乘客有前項第二款、第三款情形，處罰行為人或車輛所有人。但車輛所有人於執行機關或直轄市、縣（市）主管機關通知期限內檢附相關資料證明應歸責之人；或客運業於載客時已盡告知義務，乘客仍違反該規定者，車輛所有人免予處罰。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 50-1 條","text":"違反第二十七條第一款之隨地吐檳榔汁、檳榔渣之規定者，應接受四小時之戒檳班講習。\n前項戒檳班講習及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 51 條","text":"未依第十六條之一第四項所定辦法，於期限內繳納回收清除處理費者，每逾一日按滯納之金額加徵百分之零點五滯納金，一併繳納；逾期三十日仍未繳納者，移送強制執行。其應繳納之回收清除處理費，應自滯納期限屆滿之次日起，至繳納之日止，依繳納當日郵政儲金一年期定期存款固定利率按日加計利息。\n依第十六條第一項及第十六條之一第一項規定應繳納回收清除處理費，有偽造、變造或其他不正當方式短報或漏報與回收清除處理費計算有關資料者，中央主管機關得逕依查核結果，以回收清除處理費費率之二倍計算其應繳費額。中央主管機關除依前項計算及徵收逃漏之回收清除處理費外，並追繳最近五年內之應繳費額；起徵未滿五年者，自起徵日起計算追繳應繳費額。其追繳應繳費額，應自中央主管機關通知限期繳納截止日之次日或逃漏回收清除處理費發生日起，至繳納之日止，依繳納當日郵政儲金一年期定期存款固定利率按日加計利息。\n有下列情形之一者，處新臺幣六萬元以上三十萬元以下罰鍰，並得通知限期改善，屆期仍未完成改善者，按次處罰；情節重大者，並得處一個月以上一年以下停業處分，或令其部分或全部停工：\n一、違反依第十六條之一第四項或第十八條第三項所定辦法有關登記、申報或管理之規定。\n二、違反依第十八條第一項所定標準有關方法或設施之規定。\n三、違反依第十八條第五項所定辦法有關稽核認證之規定。\n四、違反依第十九條第一項所定公告有關回收標誌或標示之規定。\n五、違反依第十九條第二項所定公告有關回收設施設置或回收工作執行之規定。\n六、規避、妨礙或拒絕依第二十條之查核或提供資料。\n七、違反依第二十二條第一項所定公告有關回收獎勵金支付規定。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 52 條","text":"有下列情形之一者，處新臺幣六千元以上三百萬元以下罰鍰，並得通知限期改善，屆期仍未完成改善者，按次處罰：\n一、未依第二十八條第一項規定方式清理事業廢棄物。\n二、違反依第二十九條第二項所定辦法有關提供條件、許可事項、期限或管理之規定。\n三、未依第三十一條第一項第一款、第三十九條第一項第三款、同條第二項、第三十九條之五第一項規定，取得事業廢棄物清理計畫書之核准或變更；違反第三十一條第三項所定辦法有關核准事項或變更之規定。\n四、違反第三十一條第一項第二款或同條第五項申報規定。\n五、未依第三十一條第一項第三款規定裝置即時追蹤系統或維持正常運作。\n六、未依第三十四條規定處理事業廢棄物。\n七、違反依第三十六條第二項所定標準有關貯存、清除或處理方法、設施之規定。\n八、違反依第三十九條第四項、第三十九條之五第二項準用第三十九條第四項所定辦法有關管理方式、檢核、許可事項、記錄、申報或管理之規定。\n九、違反依第三十九條之一第三項、第三十九條之五第三項準用第三十九條之一第三項所定辦法有關再利用產品之記錄與申報項目、頻率、使用證明保存、環境監測計畫書核准事項、採樣與監測結果紀錄或環境監測結果報告備查之規定。\n十、違反依第三十九條之二第二項、第三十九條之五第二項準用第三十九條之二第二項所定辦法有關契約書應記載事項、驗證事項、檢測事項、檢測報告應具備內容、銷售對象、使用用途或方式、設備與人員設置、監視系統及瀏覽伺服規格或其他管理措施之規定。\n十一、違反依第三十九條之三第三項、第三十九條之五第二項準用第三十九條之三第三項所定辦法有關產品品質規範、標示、使用限制、警語、供料履歷、驗證、認證事項或管理之規定。\n十二、違反依第三十九條之四第五項、第三十九條之五第二項準用第三十九條之四第五項所定辦法有關停止收受、再利用運作、銷售、運送、核准事項之規定。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 53 條","text":"有下列情形之一者，處新臺幣六萬元以上一千萬元以下罰鍰，並得通知限期改善，屆期仍未完成改善者，按次處罰；情節重大者，並得令其停工或停業：\n一、貯存、清除、處理、再利用有害事業廢棄物或其再利用產品使用、加工再製，有前條各款情形之一。\n二、清除、處理有害事業廢棄物，違反第二十八條第七項規定。\n三、輸入、輸出、過境、轉口事業廢棄物，未依第三十八條第一項規定取得許可，或違反同條第二項有害事業廢棄物輸出規定、同條第三項所定辦法有關許可、許可期限或管理之規定或同條第四項禁止輸入規定；或國際公約列管之一般廢棄物違反第三十八條第五項準用同條第一項至第四項規定。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 54 條","text":"事業不遵行依本法所為停工或停業處分者，當地主管機關得報請中央主管機關轉請目的事業主管機關，予以歇業處分。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 55 條","text":"有下列情形之一者，處新臺幣六千元以上三百萬元以下罰鍰，並得通知限期改善，屆期仍未完成改善者，按次處罰：\n一、公民營廢棄物清除處理機構違反依第十二條第一項所定辦法有關一般廢棄物回收、清除、處理之運輸、分類、貯存、方法、設備或再利用規定，或同條第二項之分類、貯存規定或違反依第四十二條所定辦法有關自有設施、專業技術人員設置、許可、許可期限或管理之規定。\n二、指定公告之事業未依第二十八條第二項規定置專業技術人員；或自行清除處理事業廢棄物違反依第二十八條第二項所定辦法有關清除機具、處理設施或設備應具備之條件、許可、許可期限或管理之規定。\n三、廢棄物共同清除處理機構，清除處理設施所屬之公營事業或民間機構違反依第二十八條第三項至第五項所定辦法有關許可、許可期限、專業技術人員設置、營運、操作紀錄或管理之規定。\n四、有害事業廢棄物貯存、清除、處理之操作及檢測違反依第三十七條第二項所定辦法有關檢測之項目、方法、頻率或管理之規定。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 56 條","text":"違反第三十七條第一項規定或無故規避、妨礙或拒絕第九條第一項之攔檢、檢查、採樣或命令提供有關資料者，處新臺幣三萬元以上五百萬元以下罰鍰。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 57 條","text":"從事廢棄物貯存、清除或處理業務，違反第四十一條第一項規定者，處新臺幣六萬元以上三十萬元以下罰鍰，並命其停止營業。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 58 條","text":"有下列情形之一者，由中央主管機關處新臺幣六萬元以上一百萬元以下罰鍰，並得通知限期改善，屆期仍未完成改善者，按次處罰：\n一、未依第四十三條第一項規定取得許可證，逕行辦理檢驗測定。\n二、違反依第四十三條第二項所定辦法有關檢驗測定機構應具備之條件、設施、檢驗測定人員資格限制、許可事項或管理之規定。\n廢棄物專業技術人員違反依第四十四條所定辦法有關資格、合格證書、訓練、執行業務或管理之規定，處新臺幣一萬元以上十萬元以下罰鍰。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 58-1 條","text":"有下列情形之一者，處新臺幣六萬元以上三十萬元以下罰鍰，並得通知限期改善；屆期仍未完成改善者，按次處罰：\n一、違反直轄市、縣（市）主管機關或執行機關依第七十一條第一項規定所為命令，屆期不為清除、處理、改善環境，或屆期未提出處置計畫書、未補正、經補正後仍不符規定或未依核定期程、內容執行。\n二、無正當理由規避、妨礙或拒絕第七十一條之二第一項規定應配合事項。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 59 條","text":"執行稽查人員請求違反本法之人提示身分證明，無故拒絕者，處新臺幣六百元以上三千元以下罰鍰。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 60 條","text":"本法第五十一條第三項、第五十三條所稱情節重大，係指有下列情形之一者：\n一、違反本法同一規定，一年內經二次限期改善，仍繼續違反本法規定者。\n二、非法棄置有害事業廢棄物者。\n三、回收、貯存、清除、處理、再利用廢棄物，嚴重污染環境者。\n四、申請及申報文件虛偽不實者。\n五、其他經主管機關認定者。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 61 條","text":"（刪除）","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 62 條","text":"依本法限期改善或申報，其改善或申報期間，不得超過九十日。但情形特殊者，得申請直轄市、縣（市）主管機關准予延長。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 63 條","text":"本法所定之處罰，除另有規定外，由執行機關為之；執行機關應作為而不作為時，得由上級主管機關為之。\n主管機關或執行機關得於中央主管機關指定之網站，公開對事業、公民營廢棄物清除處理機構或設施、專業技術人員、檢驗測定機構查核、處分之個別及統計資訊。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 63-1 條","text":"依本法處罰鍰者，其額度應依污染程度、特性及危害程度裁處；其裁罰準則，由中央主管機關定之。\n違反本法義務行為而有所得利益者，除應依本法規定裁處一定金額之罰鍰外，並得於所得利益之範圍內，予以追繳。\n為他人利益而實施行為，致使他人違反本法上義務應受處罰者，該行為人因其行為受有財產上利益而未受處罰時，得於其所受財產上利益價值範圍內，予以追繳。\n行為人違反本法上義務應受處罰，他人因該行為受有財產上利益而未受處罰時，得於其所受財產上利益價值範圍內，予以追繳。\n前三項追繳，由裁處機關以行政處分為之；所稱利益得包括積極利益及應支出而未支出或減少支出之消極利益，其核算及推估之辦法，由中央主管機關定之。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 64 條","text":"（刪除）","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 65 條","text":"依本法所處之罰鍰拒不繳納者，移送強制執行。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 66 條","text":"未依第二十四條規定繳納一般廢棄物清除處理費者，經限期繳納，屆期仍未繳納者，移送強制執行。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 67 條","text":"對於違反本法之行為，民眾得敘明事實或檢具證據資料，向所在地執行機關或主管機關檢舉。\n主管機關或執行機關對於前項檢舉，經查證屬實並處以罰鍰者，其罰鍰金額達一定數額時，得以實收罰鍰總金額收入之一定比例，提充檢舉獎金予檢舉人。\n前項檢舉及獎勵辦法，由直轄市、縣（市）主管機關定之。\n主管機關或執行機關為前項查證時，對檢舉人之身分應予保密。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 68 條","text":"事業清理廢棄物所支出之費用，應予財稅減免。\n事業遵守本法有關規定，辦理廢棄物清理及資源減量、回收再利用績效優良者，應予獎勵；其獎勵辦法，由中央主管機關會商中央目的事業主管機關定之。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"A","no":"第 69 條","text":"執行機關執行廢棄物回收工作，變賣所回收廢棄物之所得款項，應專款專用於辦理廢棄物回收工作，並得提撥一定比例作為從事廢棄物回收工作人員之獎勵金。\n前項回收廢棄物變賣所得款項提撥比例及運用辦法，由中央主管機關定之。\n政府機關、公立學校辦理一般廢棄物回收所得款項，應於公庫設置專戶，妥為管理運用。","headingPath":["第 五 章 獎勵及處罰"]},{"type":"C","no":"","text":"第 六 章 附則","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 70 條","text":"執行機關、公民營廢棄物清除處理機構、共同清除處理機構處理或依第二十九條第一項提供處理設施之事業，得清理轄區以外之廢棄物，直轄市、縣（市）主管機關不得限制之。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 71 條","text":"直轄市、縣（市）主管機關或執行機關發現不依規定清除、處理之廢棄物，得以書面令下列處置義務人限期清除、處理及改善環境，並載明不依限履行將代為清除、處理、改善環境（以下簡稱代履行）之意旨及估計之代履行費用數額；必要時，得以書面限期令處置義務人提出處置計畫書及依直轄市、縣（市）主管機關或執行機關核定之期程、內容執行，並載明上開不依限履行之相關事項：\n一、事業。\n二、受託清除、處理廢棄物者。\n三、仲介非法清除、處理廢棄物者。\n四、容許或因重大過失致廢棄物遭非法回填、堆置於其土地之所有人、管理人或使用人。\n為避免污染危害發生或防止污染擴大，直轄市、縣（市）主管機關或執行機關得於前項處分作成前，逕行採取應變措施；所生採樣、檢測、清除、處理等必要費用，得以書面令處置義務人負擔。\n直轄市、縣（市）主管機關或執行機關得於前二項書面行政處分送達後，免提供擔保向行政法院聲請假扣押；實施假扣押後，有下列情形之一者，直轄市、縣（市）主管機關或執行機關應辦理該保全措施之解除：\n一、處置義務人已自行或由第三人提供相當擔保。\n二、處置義務人已清除、處理及改善環境或依核准之處置計畫書執行達一定程度。\n處置義務人有下列情形之一者，直轄市、縣（市）主管機關或執行機關得逕為代履行：\n一、無處置意願或能力。\n二、未於直轄市、縣（市）主管機關或執行機關依第一項所定期限內完成清除、處理及改善環境，或未於期限內提出處置計畫書。\n三、提出之處置計畫書不符規定或內容有欠缺，經直轄市、縣（市）主管機關或執行機關通知限期補正，屆期未補正或補正後仍不符規定。\n四、未依直轄市、縣（市）主管機關或執行機關核定之處置計畫書期程、內容執行。\n第一項、第二項及前項代履行費用之估算、應變措施必要費用之範圍、處置計畫書之格式、應載明事項、應檢附文件、補正、審查、核定、廢止、管理、第三項聲請假扣押之裁量基準、擔保之方式、數額與清除、處理及改善環境或依核准之處置計畫書執行達一定程度之認定及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 71-1 條","text":"土地遭非法回填、堆置廢棄物之處置義務人有數人者，應就該廢棄物負連帶清除、處理及改善環境責任，並就代履行費用、應變措施必要費用負連帶清償責任。\n處置義務人為公司組織者，直轄市、縣（市）主管機關或執行機關得限期令其負責人、持有超過其已發行有表決權之股份總數或資本總額半數或直接或間接控制其人事、財務或業務經營之公司或股東繳納前條代履行及應變措施必要費用；處置義務人因合併、分割或其他事由消滅時，亦同。\n除因容許致廢棄物遭非法回填、堆置於其土地者外，土地所有人、管理人或使用人支出前條代履行及應變措施必要費用，得向其他處置義務人求償。\n代履行及應變措施必要費用之債權，優先於一切債權及抵押權受償，且不受扣押禁止處分效力之拘束；該債權請求權因十年間不行使而消滅。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 71-2 條","text":"土地所有人、管理人或使用人應配合直轄市、縣（市）主管機關或執行機關代履行、採取應變措施、進行採樣、檢測等相關措施，及處置義務人依處置計畫書執行之行為，不得規避、妨礙或拒絕。\n直轄市、縣（市）主管機關或執行機關代履行或採取應變措施，得委託適當廢棄物清除、處理、再利用機構或清除處理設施為之；該廢棄物清除、處理、再利用機構或清除處理設施經原核發許可或同意之機關核准後，得不受其許可或同意、指定文件項目、數量之限制；屬依環境影響評估法審查通過者，亦不受環境影響說明書、環境影響評估書及審查結論記載之限制。\n直轄市、縣（市）主管機關或執行機關得公開遭非法回填、堆置廢棄物之土地位置、廢棄物種類、數量及其他受污染情形，並囑託土地登記主管機關於相關地籍資料註記；於廢棄物經妥善清理後，囑託塗銷註記。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 72 條","text":"公私場所違反本法或依本法授權訂定之相關命令，而主管機關疏於執行時，受害人民或公益團體得敘明疏於執行之具體內容，以書面告知主管機關。主管機關於書面告知送達之日起六十日內仍未依法執行者，受害人民或公益團體得以該主管機關為被告，對其怠於執行職務之行為，直接向高等行政法院提起訴訟，請求判令其執行。\n高等行政法院為前項判決時，得依職權判命被告機關支付適當律師費用、偵測鑑定費用或其他訴訟費用予對有效清除、處理廢棄物有具體貢獻之原告。\n第一項之書面告知格式，由中央主管機關會商有關機關定之。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 73 條","text":"各級主管機關依本法核（換）發許可文件、證照、受理審查、檢驗，應收取許可費、證照費、審查費或檢驗費。\n前項收費標準，由中央主管機關會商有關機關定之。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 74 條","text":"主管機關、目的事業主管機關得指定或委託專責機構、相關機關，辦理廢棄物研究、訓練及管理之有關事宜。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 75 條","text":"廢棄物檢測方法及品質管制事項，由中央主管機關定之。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 76 條","text":"本法施行細則，由中央主管機關定之。","headingPath":["第 六 章 附則"]},{"type":"A","no":"第 77 條","text":"本法自公布日施行。\n本法中華民國九十五年五月五日修正之條文，自九十五年七月一日施行。\n本法中華民國一百零一年十一月十三日修正之條文，自一百零一年九月六日施行。\n本法中華民國一百十五年六月十六日修正之第三十九條至第三十九條之五及第五章有關上開條文之處罰規定，自公布後二年施行。","headingPath":["第 六 章 附則"]}],"attachments":[],"attachmentNote":""},"waste-rules":{"id":"waste-rules","pcode":"O0050036","name":"廢棄物清理法施行細則","foreword":"","histories":"1.中華民國九十年五月三十日行政院環境保護署（90）環署廢字第 00298\r\n  15  號令訂定發布全文 20 條\r\n2.中華民國九十一年十一月二十日行政院環境保護署環署廢字第 0910075\r\n  942 號令修正發布全文 20 條；並自發布日施行\r\n3.中華民國一百零八年十一月六日行政院環境保護署環署廢字第 1080081\r\n  526 號令修正發布第 4、10、11、17  條條文\r\n  中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公告\r\n  第 2  條序文、第 6  條第 1  項、第 7  條、第 8  條、第 9  條第\r\n  1 項第 3  款、第 3  項、第 11 條第 1  項第 4  款、第 12 條第 2\r\n  項、第 3  項、第 13 條序文、第 7  款、第 14 條第 2  項、第 15 \r\n  條、第 19 條所列屬「行政院環境保護署」之權責事項，自一百十二年\r\n  八月二十二日起改由「環境部」管轄","amended":"20191106","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0050036","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-with-attachments","articles":[{"type":"A","no":"第 1 條","text":"本細則依廢棄物清理法（以下簡稱本法）第七十六條規定訂定之。","headingPath":[]},{"type":"A","no":"第 2 條","text":"本法所定中央主管機關之主管事項如下：\n一、全國性廢棄物清理政策、方案與計畫之策劃、訂定及督導。\n二、全國性廢棄物清理法規之訂定及釋示。\n三、全國性廢棄物清理工作之督導、獎勵、稽查及核定。\n四、全國性廢棄物清理人員之訓練及管理。\n五、公民營廢棄物清除處理機構管理政策之訂定及督導。\n六、廢棄物檢驗測定機構之許可及管理。\n七、全國性廢棄物清理之研究發展及宣導。\n八、廢棄物清理之國際合作及科技交流。\n九、廢棄物輸入、輸出、過境及轉口之督導。\n十、有害事業廢棄物輸入、輸出、過境及轉口之同意。\n十一、資源回收管理基金之管理及運作。\n十二、涉及二直轄市、縣（市）以上廢棄物清理之協調及督導。\n十三、其他有關全國性廢棄物清理事項。","headingPath":[]},{"type":"A","no":"第 3 條","text":"本法所定直轄市或縣（市）主管機關之主管事項如下：\n一、直轄市或縣（市）廢棄物清理方案與計畫之規劃、訂定及執行。\n二、直轄市或縣（市）廢棄物清理自治法規之訂定及釋示。\n三、直轄市或縣（市）廢棄物清理工作之督導、獎勵、稽查及核定。\n四、直轄市或縣（市）一般廢棄物清除處理費徵收之規劃、訂定及公告。\n五、直轄市或縣（市）一般廢棄物清理人員之訓練及管理。\n六、直轄市或縣（市）公民營廢棄物清除處理機構許可文件之核發與督導、查核及管理。\n七、直轄市或縣（市）廢棄物清理之研究發展及宣導。\n八、直轄市或縣（市）一般廢棄物清除機具之統籌及調度。\n九、直轄市或縣（市）一般廢棄物清理之協調及督導。\n十、直轄市或縣（市）廢棄物清理之監測、調查、檢驗分析及統計資料之製作。\n十一、廢棄物之輸入、輸出、過境、轉口許可文件之核發與督導、查核、管制及管理。\n十二、應回收廢棄物回收處理業之登記及管理。\n十三、其他有關直轄市或縣（市）廢棄物清理事項。","headingPath":[]},{"type":"A","no":"第 4 條","text":"本法所定執行機關之執行事項如下：\n一、直轄市政府環境保護局：\n（一）公告指定直轄市之清除地區。\n（二）直轄市一般廢棄物回收、清除、處理用地之規劃及取得。\n（三）直轄市一般廢棄物回收、清除、處理工作之規劃及執行。\n（四）直轄市一般廢棄物清除處理費徵收之執行。\n（五）直轄市一般廢棄物清理設施之設置及操作管理。\n（六）直轄市廢棄物之稽查及處分。\n（七）直轄市受託清除、處理一般事業廢棄物之規劃及執行。\n（八）直轄市一般廢棄物性質之檢驗與種類及數量之調查。\n（九）直轄市執行占用道路廢棄車輛之查報、認定、張貼、移置及公告。\n（十）直轄市指定或委託辦理廢棄物研究與清理人員之訓練及管理。\n（十一）直轄市其他有關一般廢棄物清理事項。\n二、市環境保護局：\n（一）公告指定市之清除地區。\n（二）市一般廢棄物回收、清除、處理用地之規劃及取得。\n（三）市一般廢棄物回收、清除、處理工作之規劃及執行。\n（四）市一般廢棄物清除處理費徵收之執行。\n（五）市一般廢棄物清理設施之設置及操作管理。\n（六）市廢棄物之稽查及處分。\n（七）市受託清除、處理一般事業廢棄物之規劃及執行。\n（八）市一般廢棄物性質之檢驗與種類及數量之調查。\n（九）市執行占用道路廢棄車輛之查報、認定、張貼、移置及公告。\n（十）市指定或委託辦理廢棄物研究與清理人員之訓練及管理。\n（十一）市其他有關一般廢棄物清理事項。\n三、縣環境保護局：\n（一）縣一般廢棄物回收、清除、處理用地之規劃及取得。\n（二）縣一般廢棄物回收、清除、處理工作之規劃及執行。\n（三）縣一般廢棄物清理設施之設置及操作管理。\n（四）縣一般廢棄物清除處理費徵收之執行。\n（五）縣廢棄物之稽查及處分。\n（六）縣受託處理一般事業廢棄物之規劃及執行。\n（七）縣一般廢棄物性質之檢驗與種類、數量調查之統籌、協調及督導。\n（八）縣執行占用道路廢棄車輛之查報、認定、張貼、移置及公告。\n（九）縣指定或委託辦理廢棄物研究與清理人員之訓練及管理。\n（十）縣其他有關一般廢棄物清理事項。\n四、鄉（鎮、市）公所：\n（一）公告指定鄉（鎮、市）之清除地區。\n（二）鄉（鎮、市）一般廢棄物清理自治法規之訂定及釋示。\n（三）鄉（鎮、市）一般廢棄物回收、清除工作之規劃及執行。\n（四）鄉（鎮、市）一般廢棄物清除處理費徵收之執行。\n（五）鄉（鎮、市）一般廢棄物回收、清除、處理用地之規劃及取得。\n（六）鄉（鎮、市）廢棄物之稽查及處分。\n（七）鄉（鎮、市）受託清除一般事業廢棄物之規劃及執行。\n（八）鄉（鎮、市）執行占用道路廢棄車輛之查報、認定及張貼。\n（九）鄉（鎮、市）依本法第五條第四項受託處理一般廢棄物，及其他有關一般廢棄物清除事項。","headingPath":[]},{"type":"A","no":"第 5 條","text":"縣環境保護局依本法第五條第五項規定完成一般廢棄物工作調整前，鄉（鎮、市）應自行設置一般廢棄物處理設施，並將處理方法及地點，報縣環境保護局核准後，自行處理所轄之一般廢棄物。但經縣環境保護局指定處理場所者，鄉（鎮、市）公所應備置適當之一般廢棄物清除車輛，清除一般廢棄物至縣環境保護局指定之場所處理。","headingPath":[]},{"type":"A","no":"第 6 條","text":"縣環境保護局依本法第五條第五項規定辦理一般廢棄物工作調整，應於中華民國九十二年七月十四日前，檢具工作調整計畫，報請中央主管機關備查。\n前項工作調整計畫內容，包括下列事項：\n一、調整之時程。\n二、人員、機具、設施之調整。\n三、財務計畫。\n四、其他事項。","headingPath":[]},{"type":"A","no":"第 7 條","text":"執行機關應公告一般廢棄物與依本法第五條第六項所定一般廢棄物回收項目之清除時間、作業及回收方式，並於每月十五日前將前一個月之一般廢棄物清除、處理及回收量，報送各該上級主管機關彙總層報中央主管機關備查。\n執行機關受託清除、處理一般事業廢棄物時，應於每月十五日前將前一個月之一般事業廢棄物清除、處理及回收量，報送上級主管機關彙總層報中央主管機關備查。","headingPath":[]},{"type":"A","no":"第 8 條","text":"執行機關依前條規定收集之廢棄物，經分類後之廢塑膠、廢鋁、廢鐵、廢玻璃、廢紙等物質，得交付回收業、處理業或依中央主管機關指定之方式進行回收、再利用。","headingPath":[]},{"type":"A","no":"第 9 條","text":"本法第九條第一項所定廢棄物產生源之證明文件為下列之一：\n一、依本法第三十一條第一項第二款申報廢棄物情形所列印之遞送聯單。\n二、依事業廢棄物貯存清除處理方法及設施標準規定所填具有害事業廢棄物之遞送聯單。\n三、其他主管機關所定或認定之格式或文件。\n本法第九條第一項所定廢棄物處理地點之證明文件，為廢棄物產生源與處理者所簽訂之合約文件影本。處理者為執行機關者，得為其所出具之同意處理文件影本。\n本法第九條第一項所定剩餘土石方產生源及處理地點證明文件及其格式，由中央目的事業主管機關會商中央主管機關定之。","headingPath":[]},{"type":"A","no":"第 10 條","text":"依本法第二十六條第三項規定成立之一般廢棄物清除處理基金收入來源，為下列收入中屬本法第二十六條第一項、第二項規定之成本：\n一、向指定清除地區內家戶及其他產生源所徵收一般廢棄物清除、處理費用之收入。\n二、代清除、處理一般事業廢棄物及其他收入。","headingPath":[]},{"type":"A","no":"第 11 條","text":"本法第二十八條第一項第一款所稱自行清除、處理，指下列情形之一：\n一、以自有設施清除、處理其所產生之事業廢棄物。\n二、以自有設施合併清除、處理該法人所屬各事業所產生之事業廢棄物。\n三、租用合法運輸業車輛清除其所產生之事業廢棄物。\n四、其他經中央主管機關認定者。\n依前項第三款自行清除之事業，應隨車派員監控管理，並攜帶屬該事業員工之證明文件；所定運輸業車輛，應符合事業廢棄物貯存清除處理方法及設施標準之規定。\n本法第二十八條第一項第三款第二目所稱事業廢棄物經執行機關同意委託其處理，指經直轄市政府環境保護局、縣（市）環境保護局同意者。\n縣環境保護局依本法第五條第四項規定委託鄉（鎮、市）公所執行一般廢棄物處理工作者，認有必要時，得就一般事業廢棄物之處理，委託已受託執行一般廢棄物處理工作之鄉（鎮、市）公所執行一般事業廢棄物處理工作。\n本法第二十八條第六項所稱餘裕處理能量，於焚化處理設施指每年焚化設施可處理量扣除每年焚化設施操作保留量及指定清除地區內一般廢棄物處理量後剩餘之數量，直轄市政府環境保護局、縣（市）環境保護局應合併轄內焚化處理設施，統一計算。\n前項每年焚化設施可處理量指前一年焚化處理設施扣除當年計畫性停爐期間之實際可處理量。\n第五項每年焚化設施操作保留量，以當年焚化設施可處理量之百分之十計算。但屬下列情形者，不在此限：\n一、於處理指定清除地區內一般廢棄物後，焚化設施操作保留量小於百分之十者，以剩餘之數量作為焚化設施操作保留量。\n二、於中華民國一百零八年十一月六日前已依本法第七條及地方制度法第二十四條之一規定提供之區域性聯合及跨區域合作處理量大於焚化設施可處理量之百分之十者，以該既有提供之處理量作為焚化設施操作保留量。","headingPath":[]},{"type":"A","no":"第 12 條","text":"本法第三十一條第一項第一款所稱與事業廢棄物產生、清理有關事項變更，係指下列情形之一：\n一、新增或改變產品製造過程、作業流程或處理流程。\n二、廢棄物回收、貯存、清除、處理、再利用方法或設施改變者。\n三、原物料使用量及產品產量或營運擴增及其他改變，足致廢棄物性質改變或數量增加者。\n事業廢棄物清理計畫書所載基本資料、原物料、產品或營運資料異動或產品製造過程、作業流程或處理流程新增或改變，而未致廢棄物性質改變或數量增加逾百分之十者，免依本法第三十一條第一項第一款規定辦理變更。但應於事實發生後十五日內，填寫異動申請書，報請直轄市、縣（市）主管機關或中央主管機關委託之機關備查。\n因天然災害、重大事故或不可抗力產生之非經常性廢棄物，於清理前提出處置計畫書，載明廢棄物產生源、種類、數量、特性、貯存、清除、處理方式、流向及清理期程，經主管機關核准者，免依本法第三十一條第一項第一款規定辦理變更。屬經常性廢棄物，因特定目的之清理需要，於提出試運轉計畫（書），經主管機關核准者，亦同。","headingPath":[]},{"type":"A","no":"第 13 條","text":"本法第三十八條第一項但書所定之產業用料需求，得由用料需求之事業或公會，檢具下列文件，分送中央主管機關及中央目的事業主管機關會商後公告之：\n一、產生源、主要成分及有害成分說明。\n二、國內使用現況，包括相關事業、料源、用途及使用量。\n三、過去三年進口量之統計。\n四、未來三年需求量之評估。\n五、替代用料及其料源之評估。\n六、污染防治設施。\n七、其他經中央主管機關或中央目的事業主管機關指定之文件或資料。","headingPath":[]},{"type":"A","no":"第 14 條","text":"本法第三十九條所定中央目的事業主管機關，應依事業廢棄物產生源所屬業別或屬性認定之；所定再利用用途目的事業主管機關，應依事業廢棄物再利用機構所屬業別或屬性認定之。\n前項目的事業主管機關之認定產生爭議時，由中央主管機關報請行政院指定之。","headingPath":[]},{"type":"A","no":"第 15 條","text":"事業經執行機關或主管機關（以下簡稱處分機關）依本法規定命其停工或停業者，應於復工、復業前，檢具完成改善證明文件、事業廢棄物清理計畫書或經處分機關指定之文件，向處分機關申請；經處分機關審查核准後，始得復工、復業。","headingPath":[]},{"type":"A","no":"第 16 條","text":"前條復工、復業之申請，如涉及製程改變或處理設施新置或變更者，應先提出試車計畫，向處分機關申請試車。試車期間以三十日為限，但必要時得申請延長之，展延期限不得超過六十日。\n經處分機關核定試車之事業，應於試車期限屆滿前，檢具試車報告及處分機關指定之文件，向處分機關申請復工、復業。\n處分機關除審查要求事業補正資料之期間外，應於三十日內審查完成前項事業所提試車報告，併前條規定審查。","headingPath":[]},{"type":"A","no":"第 17 條","text":"本法第四十六條第四款所稱廢棄物清除、處理許可文件，指依公民營廢棄物清除處理機構許可管理辦法核發之清除許可證、處理許可證。","headingPath":[]},{"type":"A","no":"第 18 條","text":"處分機關依本法所作成之處分書，其涉及跨區違法者，除將處分書送達受處分人外，應將處分書副知當地主管機關及違法行為者所在地主管機關。","headingPath":[]},{"type":"A","no":"第 19 條","text":"本法及本細則所定之告發單、處分書及移送書或其他書表之格式，除另有規定者外，由中央主管機關定之。","headingPath":[]},{"type":"A","no":"第 20 條","text":"本細則自發布日施行。","headingPath":[]}],"attachments":[],"attachmentNote":""},"air-act":{"id":"air-act","pcode":"O0020001","name":"空氣污染防制法","foreword":"","histories":"1.中華民國六十四年五月二十三日總統（64）台統（一）義字第 2265 號\r\n  令制定公布全文 21 條\r\n2.中華民國七十一年五月七日總統令修正公布全文 27 條\r\n3.中華民國八十一年二月一日總統（81）華總（一）義字第 636  號令修\r\n  正公布全文 55 條\r\n4.中華民國八十八年一月二十日總統（88）華總一義字第 8800013200 號\r\n  令修正公布全文 78 條\r\n5.中華民國九十一年六月十九日總統華總一義字第 09100121440  號令修\r\n  正公布全文 86 條；並自公布日施行\r\n6.中華民國九十四年五月十八日總統華總一義字第 09400072561  號令修\r\n  正公布第 18 條條文\r\n7.中華民國九十五年五月三十日總統華總一義字第 09500075781  號令修\r\n  正公布第 59、86 條條文；依第 86 條規定：第 59 條自九十五年七月\r\n  一日施行\r\n8.中華民國一百年四月二十七日總統華總一義字第 10000079411  號令修\r\n  正公布第 2、13、34 條條文；增訂第 34-1、63-1  條條文\r\n9.中華民國一百零一年十二月十九日總統華總一義字第 10100279791  號\r\n  令修正公布第 34-1 條條文\r\n10. 中華民國一百零七年八月一日總統華總一義字第 10700080891  號令\r\n    修正公布全文 100  條；並自公布日施行\r\n    中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公\r\n    告第 2  條、第 4  條、第 5  條第 1  項、第 3  項、第 6  條第\r\n    4 項、第 7  條第 1  項、第 2  項、第 8  條第 1  項、第 3  項\r\n    、第 5  項、第 9  條第 1  項第 4  款、第 2  項、第 12 條、第\r\n    13  條、第 14 條第 1  項、第 2  項、第 3  項、第 4  項、第 \r\n    15  條第 2  項、第 3  項、第 16 條第 1  項序文、第 1  款、第\r\n    2 項、第 17 條、第 18 條第 1  項第 1  款、第 2  項、第 4  項\r\n    、第 5  項、第 19 條第 2  項、第 20 條第 2  項、第 4  項、第\r\n    21  條、第 22 條、第 23 條第 2  項、第 24 條、第 25 條第 2  \r\n    項、第 27 條第 3  項、第 28 條、第 29 條第 2  項、第 3  項、\r\n    第 30 條第 1  項序文、第 2  項、第 3  項、第 4  項序文、第 \r\n    31  條、第 32 條第 1  項第 6  款、第 3  項、第 33 條第 4  項\r\n    、第 34 條、第 35 條、第 36 條第 2  項、第 4  項、第 37 條、\r\n    第 38 條、第 39 條、第 40 條第 1  項、第 3  項、第 41 條、第\r\n    42  條、第 43 條、第 44 條第 2  項、第 3  項、第 45 條、第 \r\n    46  條、第 47 條、第 48 條第 1  項、第 4  項、第 49 條、第 \r\n    50  條、第 55 條第 2  項、第 56 條、第 69 條第 2  項、第 75 \r\n    條第 1  項序文、第 1  款、第 3  款、第 2  項、第 3  項、第 \r\n    77  條第 1  項、第 81 條第 2  項、第 82 條第 1  項、第 2  項\r\n    、第 83 條、第 85 條第 2  項、第 86 條第 4  項、第 87 條序文\r\n    、第 2  款、第 90 條第 1  項第 4  款、第 91 條、第 92 條、第\r\n    93  條第 1  項、第 3  項、第 95 條第 1  項、第 5  項、第 6  \r\n    項、第 7  項、第 96 條第 2  項、第 97 條第 2  項、第 98 條、\r\n    第 99 條所列屬「行政院環境保護署」之權責事項，自一百十二年八\r\n    月二十二日起改由「環境部」管轄","amended":"20180801","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0020001","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-with-attachments","articles":[{"type":"C","no":"","text":"第 一 章 總則","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 1 條","text":"為防制空氣污染，維護生活環境及國民健康，以提高生活品質，特制定本法。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 2 條","text":"本法所稱主管機關：在中央為行政院環境保護署；在直轄市為直轄市政府；在縣（市）為縣（巿）政府。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 3 條","text":"本法用詞，定義如下：\n一、空氣污染物：指空氣中足以直接或間接妨害國民健康或生活環境之物質。\n二、污染源：指排放空氣污染物之物理或化學操作單元，其類別如下：\n（一）移動污染源：指因本身動力而改變位置之污染源。\n（二）固定污染源：指移動污染源以外之污染源。\n三、汽車：指在道路上不依軌道或電力架設，而以原動機行駛之車輛，包括機車。\n四、生活環境：指與人之生活有密切關係之財產、動、植物及其生育環境。\n五、排放標準：指排放廢氣所容許混存各種空氣污染物之最高濃度、總量或單位原（物）料、燃料、產品之排放量。\n六、空氣品質標準：指室外空氣中空氣污染物濃度限值。\n七、空氣污染防制區（以下簡稱防制區）：指視地區土地利用對於空氣品質之需求，或依空氣品質現況，劃定之各級防制區。\n八、自然保護（育）區：指生態保育區、自然保留區、野生動物保護區及國有林自然保護區。\n九、總量管制：指在一定區域內，為有效改善空氣品質，對於該區域空氣污染物總容許排放數量所作之限制措施。\n十、總量管制區：指依地形及氣象條件，按總量管制需求劃定之區域。\n十一、控制技術：指固定污染源為減少空氣污染物所採取之污染減量技術，主要類別如下：\n  （一）最佳可行控制技術：指考量能源、環境、經濟之衝擊後，污染源應採取之已商業化並可行污染排放最大減量技術。\n  （二）最低可達成排放率控制技術：指考量能源、環境、經濟、健康等衝擊後，並依據科學方法，污染源應採取之減少污染物排放至最低排放率之技術。\n十二、怠速：指汽車停車時，維持引擎持續運轉之情形。\n十三、空氣品質維護區：指為維護空氣品質，得限制或禁止移動污染源使用之特定區域。\n十四、含揮發性有機物化學製品：指經使用有排放揮發性有機物之任何物質、產品或物品。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 4 條","text":"各級主管機關得指定或委託（任）專責機關（構），辦理空氣污染訓練及防制之有關事宜。","headingPath":["第 一 章 總則"]},{"type":"C","no":"","text":"第 二 章 空氣品質維護","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 5 條","text":"中央主管機關應視土地用途對於空氣品質之需求或空氣品質狀況劃定直轄市、縣（市）各級防制區並公告之。\n前項防制區分為下列三級：\n一、一級防制區：國家公園及自然保護（育）區等依法劃定之區域。\n二、二級防制區：一級防制區外，符合空氣品質標準之區域。\n三、三級防制區：一級防制區外，未符合空氣品質標準之區域。\n前項空氣品質標準，由中央主管機關會商有關機關定之，並應至少每四年檢討一次。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 6 條","text":"一級防制區內，除維繫區內住戶民生需要之設施、國家公園經營管理必要設施或國防設施外，不得新設或變更固定污染源。\n二級防制區內，新設或變更之固定污染源污染物排放量達一定規模者，其污染物排放量須經模式模擬證明不超過污染源所在地之防制區及空氣品質同受影響之鄰近防制區污染物容許增量限值。\n三級防制區內，既存之固定污染源應削減污染物排放量；新設或變更之固定污染源污染物排放量達一定規模者，應採用最佳可行控制技術，其屬特定大型污染源者，應採用最低可達成排放率控制技術，且新設或變更之固定污染源污染物排放量應經模式模擬證明不超過污染源所在地之防制區及空氣品質同受影響之鄰近防制區污染物容許增量限值。\n二、三級防制區之污染物排放量規模、污染物容許增量限值、空氣品質模式模擬規範、三級防制區特定大型污染源之種類及規模、最佳可行控制技術、最低可達成排放率控制技術及既存固定污染源應削減污染物排放量之準則，由中央主管機關定之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 7 條","text":"中央主管機關應訂定空氣污染防制方案，並應每四年檢討修正。\n直轄市、縣（巿）主管機關應依前條規定及前項方案擬訂空氣污染防制計畫，報中央主管機關核定後公告之，並應每四年檢討修正。\n前項空氣污染防制計畫之擬訂，直轄市、縣（市）主管機關應考量空氣污染物流通性質，會商鄰近直轄市、縣（市）主管機關定之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 8 條","text":"中央主管機關得依地形、氣象條件，將空氣污染物互相流通之一個或多個直轄市、縣（巿）指定為總量管制區，訂定總量管制計畫，公告實施總量管制。\n符合空氣品質標準之總量管制區，新設或變更之固定污染源污染物排放量達一定規模者，須經模式模擬證明不超過該區之污染物容許增量限值。\n未符合空氣品質標準之總量管制區，既存之固定污染源應向直轄市、縣（巿）主管機關申請認可其污染物排放量，並依中央主管機關按空氣品質需求指定之目標與期限削減；新設或變更之固定污染源污染物排放量達一定規模者，應採用最佳可行控制技術，其屬特定大型污染源者，應採用最低可達成排放率控制技術，且新設或變更之固定污染源應取得足供抵換污染物增量之排放量。\n既存之固定污染源因採行防制措施致實際削減量較指定為多者，其差額經直轄市、縣（巿）主管機關認可後，得保留、抵換或交易。但無法達成指定削減目標者，應取得抵換之排放量。\n第二項污染物容許增量限值、第二項、第三項污染物排放量規模、第三項既存固定污染源污染物排放量認可之準則、新設或變更之特定大型污染源種類及規模、最佳可行控制技術、最低可達成排放率控制技術、前項實際削減量差額認可、保留、抵換及交易之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 9 條","text":"前條第三項新設或變更之固定污染源供抵換污染物增量、第四項既存之固定污染源抵換之排放量，應自下列來源取得，並以較低之比例抵換：\n一、固定污染源依規定保留之實際削減量差額。\n二、交易或拍賣取得之排放量。\n三、改善移動污染源所減少之排放量。\n四、其他經中央主管機關認可之排放量。\n前項拍賣由各級主管機關辦理者，其拍賣辦法由中央主管機關定之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 10 條","text":"符合空氣品質標準之總量管制區，其總量管制計畫應包括污染物容許增量限值、避免空氣品質惡化措施、新設或變更固定污染源審核原則、運作方式及其他事項。\n未符合空氣品質標準之總量管制區，其總量管制計畫應包括污染物種類、減量目標、減量期程、區內各直轄市、縣（巿）主管機關須執行污染物削減量與期程、前條第一項污染物抵換之比例、新設或變更固定污染源審核原則、運作方式及其他事項。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 11 條","text":"總量管制區內之直轄市、縣（巿）主管機關，應依前條總量管制計畫訂定及修正空氣污染防制計畫。\n前項空氣污染防制計畫於未符合空氣品質標準之總量管制區者，直轄市、縣（巿）主管機關應依前條須執行污染物削減量與期程之規定，指定削減污染物排放量之固定污染源、削減量及期程。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 12 條","text":"第八條至前條關於總量管制之規定，應於建立污染源排放量查核系統及排放交易制度後，由中央主管機關會商經濟部報請行政院分期分區核定公告實施之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 13 條","text":"中央主管機關應於石化工業區所在之鄉鎮市區、各級主管機關應選定適當地點，設置空氣品質監測站，定期公布空氣品質狀況及其原始資料。\n前項空氣品質監測站設置及監測之準則，由中央主管機關定之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 14 條","text":"因氣象變異或其他原因，致空氣品質有嚴重惡化之虞時，各級主管機關及公私場所應即採取緊急防制措施；各級主管機關應發布空氣品質惡化警告，並得禁止或限制交通工具之使用、公私場所空氣污染物之排放及機關、學校之活動。\n電業為執行前項緊急防制措施，或配合各級主管機關降低燃煤發電，調整發電使用之燃料種類，致增加燃氣發電之燃料用量及空氣污染物排放量，其增量得報經中央目的事業主管機關審核，並送中央主管機關核可後，不受依第二十四條第四項所定辦法核發之許可證登載之年許可燃料用量及排放量之限制；屬依環境影響評估法審查通過者，亦不受環境影響說明書或環境影響評估書所載之內容及審查結論記載年許可燃料用量及排放量之限制。\n前項調整增加之空氣污染物排放量，應低於執行緊急防制措施或降低燃煤發電所減少之空氣污染物排放量；屬因執行緊急防制措施而調整者，中央主管機關核可之增量期間，應限於緊急狀況存續期間。\n第一項空氣品質嚴重惡化之警告發布、緊急防制措施及第二項核可程序之辦法，由中央主管機關會商有關機關報請行政院核定公告實施之。\n中華民國一百零七年六月二十五日修正之第二項及第三項規定，施行至一百十四年十二月三十一日止。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 15 條","text":"特殊性工業區開發者，應於區界內之四周規劃設置緩衝地帶及適當地區設置空氣品質監測設施。\n前項特殊性工業區之類別、緩衝地帶、空氣品質監測狀況記錄、申報、監測設施設置規範、記錄及申報之標準，由中央主管機關定之。\n中央主管機關應定期公布前項申報狀況及其原始資料。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 16 條","text":"各級主管機關得對排放空氣污染物之固定污染源及移動污染源徵收空氣污染防制費，其徵收對象如下：\n一、固定污染源：依其排放空氣污染物之種類及數量，向污染源之所有人徵收，其所有人非使用人或管理人者，向實際使用人或管理人徵收；其為營建工程者，向營建業主徵收；經中央主管機關指定公告之物質，得依該物質之銷售數量，向銷售者或進口者徵收。\n二、移動污染源：依其排放空氣污染物之種類及數量，向銷售者或使用者徵收，或依油燃料之種類成分與數量，向銷售者或進口者徵收。\n空氣污染防制費徵收方式、計算方式、申報、繳費流程、繳納期限、繳費金額不足之追補繳、收費之污染物排放量計算方法及其他應遵行事項之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 17 條","text":"前條空氣污染防制費除營建工程由直轄市、縣（市）主管機關徵收外，由中央主管機關徵收。中央主管機關由固定污染源所收款項，應以百分之六十比率將其撥交該固定污染源所在直轄市、縣（市）主管機關；由移動污染源所收款項，應以百分之二十比率將其撥交該移動污染源使用者設籍地或油燃料銷售地所在直轄市、縣（市）主管機關。但直轄市、縣（市）主管機關執行空氣品質維護或改善計畫成果，經中央主管機關認定不佳或未依第十八條規定使用者，中央主管機關得酌減撥交之款項。\n前項收費費率，由中央主管機關會商有關機關依空氣品質現況、污染源、污染物、油燃料種類及污染防制成本定之。\n前項費率施行滿一年後，得定期由總量管制區內之直轄市、縣（巿）主管機關考量該管制區環境空氣品質狀況，依前項費率增減百分之三十範圍內，提出建議收費費率，由中央主管機關核定公告之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 18 條","text":"空氣污染防制費專供空氣污染防制之用，其支用項目如下：\n一、關於各級主管機關執行空氣污染防制工作事項。\n二、關於空氣污染源查緝及執行成效之稽核事項。\n三、關於補助及獎勵各類污染源辦理空氣污染改善工作事項。\n四、關於委託或補助檢驗測定機構辦理汽車排放空氣污染物檢驗事項。\n五、關於委託或補助專業機構辦理固定污染源之檢測、輔導及評鑑事項。\n六、關於空氣污染防制技術之研發及策略之研訂事項。\n七、關於涉及空氣污染之國際環保工作事項。\n八、關於空氣品質監測及執行成效之稽核事項。\n九、關於徵收空氣污染防制費之相關費用事項。\n十、執行空氣污染防制相關工作所需人力之聘僱事項。\n十一、關於空氣污染之健康風險評估及管理相關事項。\n十二、關於潔淨能源使用推廣及研發之獎勵事項。\n十三、關於空氣污染檢舉獎金事項。\n十四、其他有關空氣污染防制工作事項。\n前項空氣污染防制費，各級主管機關得成立基金管理運用，並成立基金管理會監督運作，其中學者、專家及環保團體代表等，應占管理會名額三分之二以上，並不得由相關產業之大股東擔任，且環保團體代表不得低於管理會名額六分之一。\n前項基金管理會代表就審議案件之利益迴避，準用行政程序法第三十二條及第三十三條規定。\n第一項空氣污染防制費支用項目實際支用情形，應公開於中央主管機關指定之網站。\n第一項空氣污染防制費應優先運用於空氣污染嚴重地區，其有關各款獎勵及補助之對象、申請資格、審查程序、獎勵及補助之撤銷、廢止與追償及其他相關事項之辦法，由各級主管機關定之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"A","no":"第 19 條","text":"公私場所固定污染源，因採行污染防制減量措施，能有效減少污染排放量達一定程度者，得向直轄市、縣（巿）主管機關申請獎勵；其已依第十六條第一項規定繳納空氣污染防制費者，得向直轄市、縣（巿）主管機關申請減免空氣污染防制費。\n前項空氣污染防制費之減免與獎勵之對象、申請資格、審查程序、撤銷、廢止與追償及其他相關事項之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 二 章 空氣品質維護"]},{"type":"C","no":"","text":"第 三 章 防制","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 20 條","text":"公私場所固定污染源排放空氣污染物，應符合排放標準。\n前項排放標準，由中央主管機關依特定業別、設施、污染物項目或區域會商有關機關定之。直轄市、縣（市）主管機關得因特殊需要，擬訂個別較嚴之排放標準，報請中央主管機關會商有關機關核定之。\n第一項排放標準應含有害空氣污染物，其排放標準值應依健康風險評估結果及防制技術可行性訂定之。\n前項有害空氣污染物之種類及健康風險評估作業方式，由中央主管機關公告之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 21 條","text":"公私場所具有經中央主管機關指定公告之固定污染源者，應按季於每年一月、四月、七月及十月底前，向直轄市、縣（巿）主管機關申報其固定污染源前一季空氣污染物排放量。\n前項固定污染源空氣污染物季排放量之計算、記錄、申報內容、程序與方式、查核及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 22 條","text":"公私場所具有經中央主管機關指定公告之固定污染源者，應於規定期限內完成設置自動監測設施，連續監測其操作或空氣污染物排放狀況，並向直轄市、縣（巿）主管機關申請認可；其經指定公告應連線者，其監測設施應於規定期限內完成與直轄市、縣（巿）主管機關連線，並公開於直轄市、縣（巿）主管機關網站。\n前項以外之污染源，各級主管機關認為必要時，得指定公告其應自行或委託檢驗測定機構實施定期檢驗測定。\n前二項監測或檢驗測定結果，應作成紀錄，並依規定向直轄市、縣（巿）主管機關申報；監測或檢驗測定結果之記錄、申報、保存、連線作業規範、完成設置或連線期限及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 23 條","text":"公私場所應有效收集各種空氣污染物，並維持其空氣污染防制設施或監測設施之正常運作；其固定污染源之最大操作量，不得超過空氣污染防制設施之最大處理容量。\n固定污染源及其空氣污染物收集設施、防制設施或監測設施之規格、設置、操作、檢查、保養、記錄及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 24 條","text":"公私場所具有經中央主管機關指定公告之固定污染源，應於設置或變更前，檢具空氣污染防制計畫，向直轄市、縣（市）主管機關或中央主管機關委託之機關申請及取得設置許可證，並依許可證內容進行設置或變更。\n前項固定污染源設置或變更後，應檢具符合本法相關規定之證明文件，向直轄市、縣（市）主管機關或經中央主管機關委託之機關申請及取得操作許可證，並依核發之許可證內容進行操作。\n直轄市、縣（市）主管機關或經中央主管機關委託之機關，應於前二項許可證核發前，將申請資料登載於公開網站，供民眾查詢並表示意見，作為核發許可證之參考。\n固定污染源設置與操作許可證之申請、審查程序、審查原則、公開內容、核發、撤銷、廢止、中央主管機關委託或終止委託及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 25 條","text":"公私場所因遷移或變更產業類別，應重新申請核發設置及操作許可證。\n已取得操作許可證之公私場所，因中央主管機關公告實施總量管制或主管機關據以核發操作許可證之排放標準有修正，致其操作許可證內容不符規定者，應於中央主管機關公告之期限內，向直轄市、縣（市）主管機關或中央主管機關委託之機關重新申請核發操作許可證。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 26 條","text":"第二十四條第一項之空氣污染防制計畫及同條第二項之證明文件，應經依法登記執業之環境工程技師或其他相關專業技師簽證。\n政府機關、公營事業機構或公法人於前項情形，得由其內依法取得前項技師證書者辦理簽證。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 27 條","text":"同一公私場所，有數排放相同空氣污染物之固定污染源者，得向直轄市、縣（市）主管機關申請改善其排放空氣污染物總量及濃度，經審查核准後，其個別污染源之排放，得不受依第二十條第一項及第二項所定排放標準之限制。\n前項公私場所應以直轄市、縣（市）主管機關核准之空氣污染物總量及濃度限值為其排放標準。\n第一項排放空氣污染物之總量及濃度之申請、審查程序、核准、撤銷、廢止及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 28 條","text":"公私場所固定污染源所使用之燃料及輔助燃料，含生煤或其他中央主管機關指定公告者，應符合中央主管機關所定燃料種類混燒比例及成分之標準，並申請及取得直轄市、縣（市）主管機關核發之使用許可證，始得為之；其使用情形，應作成紀錄，並依規定向直轄市、縣（市）主管機關申報。\n前項燃料種類混燒比例與成分之標準，及其使用許可證之申請、審查程序、許可條件、核發、撤銷、廢止、記錄、申報及其他應遵行事項之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 29 條","text":"使用易致空氣污染之物質者，應先檢具有關資料，向直轄市、縣（市）主管機關申請許可，經審查合格核發許可證後，始得為之；其使用情形，應作成紀錄，並依規定向直轄市、縣（巿）主管機關申報。\n前項易致空氣污染之物質，由中央主管機關會商有關機關公告之。\n第一項使用許可證之申請、審查程序、許可條件、核發、撤銷、廢止、記錄、申報及其他應遵行事項之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 30 條","text":"依第二十四條第一項、第二項、第二十八條第一項及前條第一項核發之許可證，其有效期間為五年；期滿仍須繼續使用者，應於屆滿前三至六個月內，向直轄市、縣（市）主管機關或中央主管機關委託之機關提出許可證之展延申請，經核准展延之許可證，其有效期間為三年以上五年以下。但有下列情形之一者，每次展延有效期間得縮減至未滿三年：\n一、原許可證有效期間內，違反本法規定情節重大經處分確定。\n二、固定污染源設置操作未達五年。\n三、固定污染源位於總量管制區。\n公私場所申請許可證展延之文件不符規定或未能補正者，直轄市、縣（市）主管機關或中央主管機關委託之機關應於許可證期限屆滿前駁回其申請；未於許可證期限屆滿前三至六個月內申請展延者，直轄市、縣（市）主管機關或中央主管機關委託之機關於其許可證期限屆滿日尚未作成准駁之決定時，應於許可證期限屆滿日起停止設置、變更、操作或使用；未於許可證期限屆滿前申請展延者，於許可證期限屆滿日起其許可證失其效力，如需繼續設置、變更、操作或使用者，應重新申請設置、操作或使用許可證。\n公私場所固定污染源於第一項規定期間，向直轄市、縣（市）主管機關或中央主管機關委託之機關申請展延，因該機關之審查致許可證期限屆滿前無法完成展延准駁者，公私場所固定污染源於許可證屆滿後至完成審查期間內，得依原許可證內容設置、操作或使用。\n直轄市、縣（市）主管機關或中央主管機關委託之機關審查展延許可證，非有下列情形之一者，不得變更原許可證內容：\n一、三級防制區內之既存固定污染源，依第六條第四項既存固定污染源應削減污染物排放量之準則規定削減。\n二、屬第七條第二項所定空氣污染防制計畫指定削減污染物排放量之污染源，依規定期程計算之削減量。\n三、公私場所使用燃料之種類、成分標準或混燒比例變更。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 31 條","text":"中央主管機關得禁止或限制國際環保公約管制之易致空氣污染物質及利用該物質製造或填充產品之製造、輸入、輸出、販賣或使用。\n前項物質及產品，由中央主管機關會商有關機關公告；其製造、輸入、輸出、販賣或使用之許可申請、審查程序、廢止、記錄、申報及其他應遵行事項之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 32 條","text":"在各級防制區或總量管制區內，不得有下列行為：\n一、從事燃燒、融化、煉製、研磨、鑄造、輸送或其他操作，致產生明顯之粒狀污染物，散布於空氣或他人財物。\n二、從事營建工程、粉粒狀物堆置、運送工程材料、廢棄物或其他工事而無適當防制措施，致引起塵土飛揚或污染空氣。\n三、置放、混合、攪拌、加熱、烘烤物質、管理不當產生自燃或從事其他操作，致產生異味污染物或有毒氣體。\n四、使用、輸送或貯放有機溶劑或其他揮發性物質，致產生異味污染物或有毒氣體。\n五、餐飲業從事烹飪，致散布油煙或異味污染物。\n六、其他經各級主管機關公告之空氣污染行為。\n前項空氣污染行為，係指未經排放管道排放之空氣污染行為。\n第一項執行行為管制之準則，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 33 條","text":"公私場所之固定污染源因突發事故，大量排放空氣污染物時，負責人應立即採取緊急應變措施，並至遲於一小時內通報直轄市、縣（巿）主管機關。\n前項情形，直轄市、縣（巿）主管機關除令公私場所採取必要措施或得令其停止該固定污染源之操作外，並應發布空氣品質惡化警告及採取因應措施。\n公私場所應擬訂空氣污染突發事故緊急應變措施計畫，並定期檢討，報經直轄市、縣（市）主管機關核定後切實執行。\n第二項之惡化警告發布、通知方式及因應措施、前項空氣污染突發事故緊急應變措施計畫之應記載內容及執行方法之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 34 條","text":"經中央主管機關指定公告之公私場所，應設置空氣污染防制專責單位或人員。\n經中央主管機關指定公告排放有害空氣污染物之公私場所，應設置健康風險評估專責人員。\n前二項專責人員，應符合中央主管機關規定之資格，並經訓練取得合格證書。\n專責單位或人員之設置、專責人員之資格、訓練、合格證書之取得、撤銷、廢止及其他應遵行事項之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 35 條","text":"公私場所應將直轄市、縣（市）主管機關核發之固定污染源設置與操作許可證，其應含空氣污染防制計畫及空氣污染防制設施說明書；燃料使用許可證及依本法申報之資料，與環境工程技師、空氣污染防制專責人員及環境檢驗測定機構之證號資料，以及突發事故緊急應變措施計畫，公開於中央主管機關指定之網站。但涉及國防機密或經公私場所向直轄市、縣（市）主管機關申請核准之工商機密者，不在此限。\n各級主管機關得於中央主管機關指定之網站，公開公私場所、環境工程技師、空氣污染防制專責人員、環境檢驗測定機構查核、處分之個別及統計資訊。\n前二項資訊公開方式及工商機密審查之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 36 條","text":"移動污染源排放空氣污染物，應符合排放標準。\n前項排放標準，由中央主管機關會商有關機關定之；並得視空氣品質需求，加嚴出廠十年以上交通工具原適用之排放標準。\n使用中汽車無論國產或進口，均需逐車完成檢驗，並符合第一項之排放標準。\n前項使用中汽車之認定及檢驗實施方式，由中央主管機關公告之。\n汽車之製造者或進口商禁止安裝任何影響交通工具排放空氣污染物之減效裝置。但該減效裝置有下列情形之一者，不在此限：\n一、具備保護或防止損壞，避免意外事故所必備之功能。\n二、使引擎起動及暖車後不再作動之機制。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 37 條","text":"移動污染源使用人或所有人應維持其空氣污染防制設備之有效運作，並不得拆除或不得改裝非經中央主管機關認證之空氣污染防制設備。\n前項移動污染源空氣污染防制設備種類、規格、效能確認方式、標識、認證、撤銷、廢止及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 38 條","text":"汽車於一定場所、地點、氣候條件以怠速停車時，其怠速時間應符合中央主管機關之規定。\n前項汽車之種類、一定場所、地點、氣候條件與停車怠速時間及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 39 條","text":"製造、進口、販賣或使用供移動污染源用之燃料，應符合中央主管機關所定燃料種類及成分之標準。但專供出口者，不在此限。\n前項燃料製造者應取得中央主管機關核發之許可，其生產之燃料始得於國內販賣；進口者應取得中央主管機關核發之許可文件，始得向石油業目的事業主管機關申請輸入同意文件。製造或進口者應對每批（船）次燃料進行成分之檢驗分析，並作成紀錄，向中央主管機關申報。\n第一項燃料種類與成分之標準，及前項販賣、進口之許可、撤銷、廢止、記錄、申報及其他應遵行事項之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 40 條","text":"各級主管機關得視空氣品質需求及污染特性，因地制宜劃設空氣品質維護區，實施移動污染源管制措施。\n前項移動污染源管制得包括下列措施：\n一、禁止或限制特定汽車進入。\n二、禁止或限制移動污染源所使用之燃料、動力型式、操作條件、運行狀況及進入。\n三、其他可改善空氣品質之管制措施。\n第一項移動污染源管制措施由直轄市、縣（市）主管機關擬訂，報中央主管機關核定後公告之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 41 條","text":"中央主管機關抽驗使用中汽車空氣污染物排放情形，經研判其無法符合移動污染源空氣污染物排放標準，因設計或裝置不良所致者，應責令製造者或進口商將已出售之汽車限期召回改正；屆期仍不遵行者，應停止其製造、進口及銷售。\n汽車召回改正之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 42 條","text":"汽車應取得中央主管機關核發之車型排氣審驗合格證明，並經中央主管機關驗證核章，始得申請牌照。\n前項汽車車型排氣審驗合格證明之核發、撤銷、廢止及其他應遵行事項之辦法，由中央主管機關定之。\n第一項汽車空氣污染物驗證核章之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 43 條","text":"中央主管機關得委託其他機關辦理汽車排氣定期檢驗，並支付委託費用，其費用得由汽車排氣檢驗費扣抵。\n交通工具排放空氣污染物檢驗、處理、委託及其他應遵行事項之辦法，由中央主管機關會商中央交通主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 44 條","text":"汽車應實施排放空氣污染物定期檢驗，檢驗不符合第三十六條第二項所定排放標準之車輛，應於檢驗日起一個月內修復，並申請複驗。\n前項檢驗實施之對象、區域、頻率及期限，由中央主管機關公告之。\n汽車排放空氣污染物檢驗站設置之條件、設施、電腦軟體、檢驗人員資格、檢驗站之設置認可、撤銷、廢止、查核、停止檢驗及其他應遵行事項之辦法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 45 條","text":"各級主管機關得於車（場）站、機場、道路、港區、水域或其他適當地點實施使用中移動污染源排放空氣污染物不定期檢驗或檢查，或通知有污染之虞交通工具於指定期限至指定地點接受檢驗。\n使用中移動污染源排放空氣污染物不定期檢驗之辦法，由中央主管機關會商有關機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 46 條","text":"使用中之汽車排放空氣污染物，經直轄市、縣（市）主管機關之檢查人員目測、目視或遙測不符合第三十六條第二項所定排放標準或中央主管機關公告之遙測篩選標準者，應於直轄市、縣（市）主管機關通知之期限內修復，並至指定地點接受檢驗。\n人民得向各級主管機關檢舉使用中汽車排放空氣污染物情形，被檢舉之車輛經各級主管機關通知者，應於指定期限內至指定地點接受檢驗。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 47 條","text":"製造、進口、販賣經中央主管機關指定公告含揮發性有機物之化學製品，應符合該化學製品之含揮發性有機物成分標準。但專供出口者，不在此限。\n前項含揮發性有機物化學製品成分之標準，由中央主管機關會商有關機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 48 條","text":"各級主管機關得派員攜帶證明文件，檢查或鑑定公私場所或移動污染源空氣污染物排放狀況、空氣污染物收集設施、防制設施、監測設施或產製、儲存、使用之燃料成分、製造、進口、販賣含揮發性有機物化學製品成分，並令提供有關資料。\n依前項規定令提供資料時，其涉及軍事機密者，應會同軍事機關為之。\n對於前二項之檢查、鑑定及命令，不得規避、妨礙或拒絕。\n公私場所應具備便於實施第一項檢查及鑑定之設施；其規格，由中央主管機關公告之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 49 條","text":"檢驗測定機構應取得中央主管機關核給之許可證後，始得辦理本法規定之檢驗測定。\n前項檢驗測定機構應具備之條件、設施、檢驗測定人員資格限制、許可之申請、審查程序、撤銷、廢止、許可證核（換）發、停業、復業、查核、評鑑程序及其他應遵行事項之辦法，由中央主管機關定之。\n本法各項檢驗測定方法，由中央主管機關定之。","headingPath":["第 三 章 防制"]},{"type":"A","no":"第 50 條","text":"各種污染源之改善，由各目的事業主管機關輔導之，相關輔導成果，應每年公開於中央主管機關指定之網站，並定期檢討之。","headingPath":["第 三 章 防制"]},{"type":"C","no":"","text":"第 四 章 罰則","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 51 條","text":"違反第三十三條第一項未立即採取緊急應變措施或不遵行直轄市、縣（市）主管機關依第三十三條第二項所為之命令，因而致人於死者，處無期徒刑或七年以上有期徒刑，得併科新臺幣三千萬元以下罰金；致重傷者，處三年以上十年以下有期徒刑，得併科新臺幣二千五百萬元以下罰金；致危害人體健康導致疾病者，處六月以上五年以下有期徒刑，得併科新臺幣二千萬元以下罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 52 條","text":"違反第三十一條第二項所定辦法中有關輸入或輸出限制規定者，處六月以上五年以下有期徒刑，得併科新臺幣三十萬元以上一百五十萬元以下罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 53 條","text":"公私場所固定污染源排放管道排放空氣污染物違反第二十條第二項所定標準之有害空氣污染物排放限值，足以生損害於他人之生命、身體健康者，處七年以下有期徒刑，得併科新臺幣一百萬元以上一千五百萬元以下罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 54 條","text":"依本法規定有申請或申報義務，明知為不實之事項而申請、申報不實或於業務上作成之文書為虛偽記載者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上五百萬元以下罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 55 條","text":"無空氣污染防制設備或空氣污染防制設備未運作而燃燒易生特殊有害健康之物質者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上五百萬元以下罰金。\n前項易生特殊有害健康之物質，由中央主管機關公告之。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 56 條","text":"公私場所不遵行主管機關依本法所為停工或停業之命令者，處負責人三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上五百萬元以下罰金。\n不遵行主管機關依第三十三條第二項、第六十七條第二項所為停止操作、或依第六十七條第二項所為停止作為之命令者，處一年以下有期徒刑、拘役或科或併科新臺幣二十萬元以上一百萬元以下罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 57 條","text":"法人之代表人、法人或自然人之代理人、受僱人或其他從業人員因執行業務，犯第五十一條至第五十四條、第五十五條第一項或第五十六條之罪者，除依各該條規定處罰其行為人外，對該法人或自然人亦科以各該條十倍以下之罰金。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 58 條","text":"特殊性工業區開發者有下列情形之一者，處新臺幣五十萬元以上二千萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者，按次處罰：\n一、違反第十五條第一項規定，未設置緩衝地帶或適當地區設置空氣品質監測設施。\n二、違反第十五條第二項所定標準有關緩衝地帶設置、空氣品質監測設施設置規範、記錄、申報及管理事項之規定。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 59 條","text":"公私場所有下列情形之一者，處新臺幣十萬元以上二千萬元以下罰鍰；情節重大者，得令其停工或停業，必要時，並得廢止其操作許可或勒令歇業：\n一、違反第三十三條第一項規定，未採取緊急應變措施或未依規定通報直轄市、縣（市）主管機關。\n二、不遵行直轄市、縣（市）主管機關依第三十三條第二項所為採取必要措施之命令。\n三、違反第三十三條第三項規定，未切實執行空氣污染突發事故緊急應變措施計畫。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 60 條","text":"公私場所違反第六條第一項規定者，處新臺幣二萬元以上一百萬元以下罰鍰；其違反者為工商廠、場，處新臺幣十萬元以上二千萬元以下罰鍰，並令停工。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 61 條","text":"公私場所有下列情形之一者，處新臺幣二萬元以上一百萬元以下罰鍰；其違反者為工商廠、場，處新臺幣十萬元以上二千萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰；情節重大者，得令其停工或停業，必要時，並得廢止其操作許可或勒令歇業：\n一、未依第八條第三項規定削減污染物排放量。\n二、違反第八條第五項所定辦法有關實際削減量差額認可、保留、抵換、交易及管理事項之規定。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 62 條","text":"公私場所有下列情形之一者，處新臺幣二萬元以上一百萬元以下罰鍰；其違反者為工商廠、場，處新臺幣十萬元以上二千萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰；情節重大者，得令其停工或停業，必要時，並得廢止其操作許可或勒令歇業：\n一、違反第二十條第一項規定。\n二、違反第二十一條第一項規定或依同條第二項所定辦法有關空氣污染物季排放量之記錄、申報及管理事項之規定。\n三、違反第二十二條第一項、第二項規定或依同條第三項所定辦法有關監測或檢驗測定結果之記錄、申報、保存、連線作業規範、完成設置或連線期限及管理事項之規定。\n四、違反第二十三條第一項規定或同條第二項所定辦法有關空氣污染物收集、防制或監測設施之規格、設置、操作、檢查、保養、記錄及管理事項之規定。\n五、違反第二十四條第一項、第二項規定未依許可證內容設置、變更或操作及第四項所定辦法有關設置與操作許可管理事項之規定。\n六、違反第二十五條規定，未重新申請核發設置或操作許可證。\n七、違反第二十七條第二項規定或依同條第三項所定辦法有關空氣污染物總量及濃度之核准內容及管理規定。\n八、違反第三十三條第三項規定，未定期提報空氣污染突發事故緊急應變措施計畫或提報之空氣污染突發事故緊急應變措施計畫未符合同條第四項規定，經直轄市、縣（市）主管機關令限期補正而屆期未完成補正。\n前項情形，於同一公私場所有數固定污染源或同一固定污染源排放數空氣污染物者，應分別處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 63 條","text":"公私場所未依第二十四條第一項或第二項規定取得許可證，逕行設置、變更或操作者，處新臺幣二萬元以上一百萬元以下罰鍰；其違反者為工商廠、場，處新臺幣十萬元以上二千萬元以下罰鍰，並令停工及限期申請取得設置或操作許可證。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 64 條","text":"公私場所有下列情形之一者，處新臺幣二萬元以上一百萬元以下罰鍰；其違反者為工商廠、場，處新臺幣十萬元以上二千萬元以下罰鍰，並通知限期補正或申報，屆期仍未遵行者，按次處罰；情節重大者，得令其停工或停業，必要時，並得廢止其使用許可或勒令歇業：\n一、違反第二十八條第一項規定或依同條第二項所定辦法有關使用許可證之許可條件、記錄、申報及管理事項之規定。\n二、違反第二十九條第一項規定或依同條第三項所定辦法有關使用許可證之許可條件、記錄、申報及管理事項之規定。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 65 條","text":"公私場所違反第十四條第一項規定或依同條第四項所定辦法中有關採取緊急防制措施之管理規定者，處新臺幣二萬元以上一百萬元以下罰鍰；其違反者為工商廠、場，處新臺幣十萬元以上二千萬元以下罰鍰；情節重大者，並得令其停工或停業。\n違反第十四條第一項規定或依同條第四項所定辦法中有關禁止或限制交通工具使用之管理規定者，處交通工具使用人或所有人新臺幣一千五百元以上三萬元以下罰鍰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 66 條","text":"有下列情形之一者，處使用人或所有人新臺幣一千五百元以上六萬元以下罰鍰，並通知限期改善，屆期仍未完成改善者，按次處罰：\n一、違反第三十六條第一項規定。\n二、違反第三十七條第一項規定或依同條第二項所定辦法有關空氣污染防制設備種類、規格、效能、標識、認證及管理事項之規定。\n製造者或進口商違反第三十六條第五項規定者，按每輛汽車處新臺幣十萬元以上五百萬元以下罰鍰，並撤銷其汽車車型排氣審驗合格證明。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 67 條","text":"違反第三十二條第一項各款情形之一者，處新臺幣一千二百元以上十萬元以下罰鍰；其違反者為工商廠、場，處新臺幣十萬元以上五百萬元以下罰鍰。\n依前項處罰鍰者，並通知限期改善，屆期仍未完成改善者，按次處罰；情節重大者，得令其停止作為或污染源之操作，或令停工或停業，必要時，並得廢止其操作許可或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 68 條","text":"違反第三十一條第二項所定辦法有關製造、販賣或使用之許可、記錄、申報及管理事項之規定者，處新臺幣十萬元以上二百萬元以下罰鍰，並通知限期補正或申報，屆期仍未遵行者，按次處罰；情節重大者，得令其停工或停業，必要時，並得廢止其販賣或使用許可或勒令歇業。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 69 條","text":"公私場所有下列情形之一者，處新臺幣二十萬元以上二百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰：\n一、違反第三十四條第一項、第二項規定或依同條第四項所定辦法有關專責單位或人員之設置條件及管理事項之規定。\n二、違反第三十五條第一項規定。\n空氣污染防制專責人員及健康風險評估專責人員違反依第三十四條第四項所定辦法有關訓練及執行業務之規定者，處新臺幣一萬元以上十萬元以下罰鍰，必要時，中央主管機關並得廢止其專責人員之資格。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 70 條","text":"有下列情形之一者，處新臺幣二十萬元以上一百萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰；情節重大者，得令其停業，必要時，並得廢止其許可或勒令歇業：\n一、違反第四十九條第一項規定。\n二、違反第四十九條第二項所定辦法有關檢驗測定機構應具備之條件、設施、檢驗測定人員資格、許可內容及管理事項之規定。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 71 條","text":"規避、妨礙或拒絕依第四十八條第一項之檢查、鑑定或命令，或未依第四十八條第四項具備設施者，處公私場所新臺幣二十萬元以上一百萬元以下罰鍰；處移動污染源使用人或所有人新臺幣五千元以上十萬元以下罰鍰，並得按次處罰及強制執行檢查、鑑定。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 72 條","text":"違反第四十七條第一項規定者，處製造、進口或販賣者新臺幣十萬元以上一百萬元以下罰鍰，並通知限期改善，屆期未完成改善者，按次處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 73 條","text":"有下列情形之一者，處製造、販賣或進口者新臺幣十萬元以上一百萬元以下罰鍰，並通知限期改善，屆期未完成改善者，按次處罰：\n一、違反第三十九條第一項或第二項規定。\n二、違反第三十九條第三項所定辦法有關販賣、進口之許可內容、記錄、申報及管理事項之規定。\n違反第三十九條第一項規定，處使用人新臺幣五千元以上十萬元以下罰鍰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 74 條","text":"未依第十六條第二項所定辦法，於期限內繳納費用者，每逾一日按滯納之金額加徵百分之零點五滯納金，一併繳納；逾期三十日仍未申報或繳納者，處新臺幣一千五百元以上六萬元以下罰鍰；其為工商廠、場者，處新臺幣十萬元以上一百萬元以下罰鍰，並限期繳納。\n前項應繳納費用，應自滯納期限屆滿之次日，至繳納之日止，依繳納當日郵政儲金一年期定期存款固定利率按日加計利息。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 75 條","text":"公私場所依第十六條第一項繳納空氣污染防制費，有偽造、變造或其他不正當方式短報或漏報與空氣污染防制費計算有關資料者，各級主管機關應依下列規定辦理：\n一、移動污染源：中央主管機關得逕依移動污染源空氣污染防制費收費費率之二倍計算其應繳費額。\n二、營建工程：直轄市、縣（市）主管機關得逕依查驗結果或相關資料，以營建工程空氣污染防制費收費費率之二倍計算其應繳費額。\n三、營建工程以外固定污染源：中央主管機關得逕依排放係數或質量平衡核算該污染源排放量之二倍計算其應繳費額。\n公私場所以前項之方式逃漏空氣污染防制費者，各級主管機關除依前條計算及徵收逃漏之空氣污染防制費外，並追溯五年內之應繳費額。但應徵收空氣污染防制費之空氣污染物起徵未滿五年者，自起徵日起計算追溯應繳費額。\n前項追溯應繳費額，應自各級主管機關通知限期繳納截止日之次日或逃漏空氣污染防制費發生日起，至繳納之日止，依繳納當日郵政儲金一年期定期存款固定利率按日加計利息。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 76 條","text":"違反第三十八條第二項所定辦法有關怠速停車限制之規定者，處汽車使用人或所有人新臺幣一千五百元以上六萬元以下罰鍰，並得令其改善；未改善者，得按次處罰至改善為止。\n違反第四十條第三項直轄市、縣（市）主管機關公告之移動污染源管制措施者，處汽車使用人或所有人新臺幣五百元以上六萬元以下罰鍰；處汽車以外其他移動污染源使用人、所有人新臺幣五千元以上一百萬元以下罰鍰，並得令其改善，未改善者，得按次處罰至改善為止。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 77 條","text":"製造者或進口商違反第四十一條第一項規定，不遵行中央主管機關限期召回改正之命令者，按每輛汽車處新臺幣十萬元罰鍰。\n違反第四十一條第二項所定辦法有關召回改正之管理規定者，處新臺幣五千元以上二十萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 78 條","text":"有下列情形之一者，處新臺幣五千元以上二十萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰：\n一、違反依第四十二條第二項所定辦法有關汽車車型排氣審驗合格證明之核發及管理事項之規定。\n二、違反第四十三條第二項所定辦法有關交通工具排放空氣污染物之檢驗、處理管理事項之規定。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 79 條","text":"不依第四十五條第一項、第四十六條第一項、第二項規定檢驗，或經檢驗不符合排放標準者，處移動污染源使用人或所有人新臺幣一千五百元以上六萬元以下罰鍰，並通知限期改善，屆期未完成改善者，按次處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 80 條","text":"未依第四十四條第一項規定實施排放空氣污染物定期檢驗者，處汽車所有人新臺幣五百元以上一萬五千元以下罰鍰。\n經定期檢驗不符合排放標準之車輛，未於檢驗日起一個月內修復並複驗，或於期限屆滿後之複驗不合格者，處新臺幣一千五百元以上三萬元以下罰鍰。\n逾應檢驗日起六個月仍未實施定期檢驗、未依規定申請複驗或複驗仍不合格者，經直轄市、縣（巿）主管機關通知限期改善，屆期未完成改善者，處新臺幣三千元以上六萬元以下罰鍰；經直轄市、縣（巿）主管機關再通知限期改善，屆期仍未完成改善者，得移請公路監理機關註銷其牌照。\n違反第四十四條第三項所定辦法有關檢驗站設置之條件、設施、電腦軟體、檢驗人員資格、檢驗站之設置認可及管理事項之規定者，處新臺幣一萬五千元以上六萬元以下罰鍰，並通知限期補正或改善，屆期仍未補正或完成改善者，按次處罰；情節重大者，令其停止檢驗業務，並得廢止其認可。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 81 條","text":"未於依本法通知改善之期限屆滿前，檢具已規劃、設置緩衝地帶及空氣品質監測設施、符合排放標準、燃料成分標準、含揮發性有機物化學製品成分標準或其他規定之證明文件，向直轄市、縣（市）主管機關報請查驗者，視為未完成改善。\n本法所定屆期仍未補正、申報或完成改善之按次處罰，其限期改善或補正之期限、改善完成認定查驗方式、法令執行方式及其他管理事項之準則，由中央主管機關定之。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 82 條","text":"依本法通知限期補正、改善或申報者，其補正、改善或申報期間，以九十日為限。因天災或其他不可抗力事由致未能於改善期限內完成改善者，應於其原因消滅後繼續進行改善，並於十五日內，以書面敘明理由，檢具相關資料，向各級主管機關申請核定改善期限。\n公私場所未能於前項期限內完成改善者，得於接獲通知之日起三十日內提出具體改善計畫，向各級主管機關申請延長，各級主管機關應依實際狀況核定改善期限，最長以一年為限，必要時得再延長一年；未確實依改善計畫執行，經查屬實者，各級主管機關得立即終止其改善期限，並從重處罰。\n固定污染源及移動污染源於改善期間，排放之空氣污染物種類超過原據以處罰之排放濃度或排放量者，應按次處罰。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 83 條","text":"本法所定之處罰，在中央由行政院環境保護署為之；在直轄市、縣（市）由直轄市、縣（市）政府為之。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 84 條","text":"汽車所有人或使用人，拒不繳納罰鍰時，得由直轄市、縣（市）主管機關移請公路監理機關配合停止其辦理車輛異動。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 85 條","text":"依本法處罰鍰者，其額度應依污染源種類、污染物項目、程度、特性及危害程度裁處，其違規情節對學校有影響者，應從重處罰。\n前項裁罰之準則，由中央主管機關定之。","headingPath":["第 四 章 罰則"]},{"type":"A","no":"第 86 條","text":"違反本法義務行為而有所得利益者，除應依本法規定裁處一定金額之罰鍰外，並得於所得利益之範圍內，予以追繳。\n為他人利益而實施行為，致使他人違反本法上義務應受處罰者，該行為人因其行為受有財產上利益而未受處罰時，得於其所受財產上利益價值範圍內，予以追繳。\n行為人違反本法上義務應受處罰，他人因該行為受有財產上利益而未受處罰時，得於其所受財產上利益價值範圍內，予以追繳。\n前三項追繳，由為裁處之各級主管機關以行政處分為之；所稱利益得包括積極利益及應支出而未支出或減少支出之消極利益，其核算及推估辦法，由中央主管機關定之。","headingPath":["第 四 章 罰則"]},{"type":"C","no":"","text":"第 五 章 附則","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 87 條","text":"各級主管機關依第十八條第二項設置之特種基金，其來源除第十六條第一項徵收之空氣污染防制費外，應包括下列收入：\n一、第九條第一項第二款交易或拍賣所得。\n二、各級主管機關依前條追繳之所得利益。\n三、違反本法罰鍰之部分提撥。\n四、依本法科處並繳納之罰金，及因違反本法規定沒收或追徵之現金或變賣所得。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 88 條","text":"公私場所具有依第二十四條第一項指定公告之固定污染源，且該固定污染源，係於公告前設立者，應自公告之日起二年內，依第二十四條第二項申請操作許可證。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 89 條","text":"固定污染源之相關設施故障致違反本法規定時，公私場所立即採取因應措施，並依下列規定處理者，得免依本法處罰：\n一、故障發生後一小時內，向直轄市、縣（市）主管機關報備。\n二、故障發生後二十四小時內修復或停止操作。\n三、故障發生後十五日內，向直轄市、縣（市）主管機關提出書面報告。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 90 條","text":"公私場所從事下列行為前，已逐案向直轄市、縣（市）主管機關申請並經審查核可者，免依本法處罰：\n一、消防演練。\n二、緊急防止傳染病擴散而燃燒受感染之動植物。\n三、取得山林田野引火燃燒許可從事燃燒者。\n四、其他經中央主管機關公告之行為。\n氣象條件不利於污染物擴散、空氣品質有明顯惡化之趨勢或公私場所未依核可內容實施時，直轄市、縣（市）主管機關得令暫緩或停止實施前項核可行為。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 91 條","text":"各級主管機關依本法規定所為之檢驗及核發許可證、證明或受理各項申請之審查、許可，應收取審查費、檢驗費或證書費等規費。\n前項收費標準，由中央主管機關會商有關機關定之。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 92 條","text":"空氣污染物受害人，得向各級主管機關申請鑑定其受害原因；各級主管機關得會同有關機關查明原因後，令排放空氣污染物者立即改善，受害人並得請求適當賠償。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 93 條","text":"公私場所違反本法或依本法授權訂定之相關命令而各級主管機關疏於執行時，受害人民或公益團體得敘明疏於執行之具體內容，以書面告知各級主管機關。各級主管機關於書面告知送達之日起六十日內仍未依法執行者，受害人民或公益團體得以該主管機關為被告，對其怠於執行職務之行為，直接向行政法院提起訴訟，請求判令其執行。\n行政法院為前項判決時，得依職權判命被告機關支付適當律師費用、偵測鑑定費用或其他訴訟費用予對維護空氣品質有具體貢獻之原告。\n第一項之書面告知格式，由中央主管機關會商有關機關定之。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 94 條","text":"人民或團體得敘明事實或檢具證據資料，向直轄市、縣（市）主管機關檢舉公私場所違反本法規定之行為，或使用中汽車排放空氣污染物情形。\n前項檢舉及獎勵之辦法，由直轄市、縣（市）主管機關定之。\n被檢舉對象屬公私場所，且經查證檢舉屬實並處以罰鍰者，其罰鍰金額達一定數額時，得以實收罰鍰總金額收入之一定比例，提充獎金獎勵檢舉人。\n直轄市、縣（市）主管機關對於第一項檢舉人之身分應予保密。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 95 條","text":"公私場所不得因空氣污染防制專責人員或其他受僱人，向各級主管機關或司法機關揭露違反本法之行為、擔任訴訟程序之證人或拒絕參與違反本法之行為，而予解僱、降調、減薪或其他不利之處分。\n公私場所或其行使管理權之人，為前項規定所為之解僱、降調、減薪或其他不利之處分者，無效。\n公私場所之空氣污染防制專責人員或其他受僱人，因第一項規定之行為受有不利處分者，公私場所對於該不利處分與第一項規定行為無關之事實，負舉證責任。\n公私場所之空氣污染防制專責人員或其他受僱人因其揭露行為有犯刑法、特別刑法之妨害秘密罪或背信罪者，減輕或免除其刑。\n公私場所之空氣污染防制專責人員或其他受僱人曾參與依本法應負刑事責任之行為，而向各級主管機關揭露或司法機關自白或自首，因而查獲其他正犯或共犯者，減輕或免除其刑。\n公私場所之空氣污染防制專責人員或其他受僱人因第一項規定受有不利處分者，各級主管機關應提供必要之法律扶助。\n前項法律扶助之申請資格、扶助範圍、審核方式及委託辦理等事項之辦法，由中央主管機關定之。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 96 條","text":"第三十條第一項第一款、第五十九條、第六十一條、第六十二條第一項、第六十四條、第六十五條第一項、第六十七條第二項及第六十八條所稱之情節重大，指有下列情形之一者：\n一、未經合法登記或許可之污染源，違反本法之規定。\n二、經處分後，自報停工改善，經查證非屬實。\n三、一年內經二次限期改善，仍繼續違反本法規定。\n四、大量排放空氣污染物，嚴重影響附近地區空氣品質。\n五、排放之空氣污染物中含有害空氣污染物質，有危害公眾健康之虞。\n六、以未經固定污染源操作許可證核定之排放管道排放空氣污染物，或調整廢氣排放流向，致空氣污染物未經許可證核定之收集或處理設施排放。\n七、其他嚴重影響附近地區空氣品質之行為。\n各級主管機關應公開依前項規定認定情節重大之公私場所，由提供優惠待遇之目的事業主管機關或各該法律之主管機關停止並追回其違規行為所屬年度之優惠待遇，並於其後三年內不得享受政府之優惠待遇。\n前項所稱優惠待遇，包含中央或地方政府依法律或行政行為所給予該事業獎勵、補助、捐助或減免之租稅、租金、費用或其他一切優惠措施。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 97 條","text":"公私場所經直轄市、縣（巿）主管機關依第五十九條、第六十一條、第六十二條第一項、第六十四條、第六十五條第一項、第六十七條第二項或第六十八條令停止污染源之操作、停工（業）或經直轄市、縣（巿）主管機關令改善而自報停工（業）者，應於恢復污染源操作或復工（業）前，檢具試車計畫，向直轄市、縣（巿）主管機關申請試車，經直轄市、縣（巿）主管機關核准後，始得進行試車；並於試車期限屆滿前，檢具符合排放標準之證明文件，報經直轄市、縣（巿）主管機關評鑑合格後，始得恢復操作或復工（業）。\n前項試車、評鑑及管理事項之辦法，由中央主管機關定之。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 98 條","text":"公私場所應將依前條第一項所提出之試車計畫，登載於中央主管機關所指定之公開網站，供民眾查詢。\n直轄市、縣（巿）主管機關為前條第一項核准前，應給予利害關係人及公益團體表示意見，作為直轄市、縣（巿）主管機關核准之參考；以會議方式審查者，於會議後應作成會議紀錄，並公開登載於中央主管機關指定之網站。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 99 條","text":"本法施行細則，由中央主管機關定之。","headingPath":["第 五 章 附則"]},{"type":"A","no":"第 100 條","text":"本法自公布日施行。","headingPath":["第 五 章 附則"]}],"attachments":[],"attachmentNote":""},"air-behavior-guideline":{"id":"air-behavior-guideline","pcode":"O0020036","name":"空氣污染行為管制執行準則","foreword":"","histories":"1.中華民國八十九年四月十九日行政院環境保護署（89）環署空字第 001\r\n  9553  號令訂定發布全文 13 條；並自八十九年五月一日起施行\r\n2.中華民國九十一年十月九日行政院環境保護署環署空字第 0910067756\r\n  號令修正發布第 1  條條文\r\n3.中華民國九十一年十二月十一日行政院環境保護署環署空字第 0910084\r\n  483 號令修正發布第 6～9、13 條條文\r\n4.中華民國一百零八年七月二十五日行政院環境保護署環署空字第 10800\r\n  52898 號令修正發布第 1、4、6～9 條條文\r\n  中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公告\r\n  第 2  條、第 3  條、第 4  條序文、第 5  條序文、第 6  條序文、\r\n  第 7  條序文、第 8  條序文、第 9  條序文、第 10 條序文、第 11 \r\n  條序文、第 12 條所列屬「行政院環境保護署」之權責事項，自一百十\r\n  二年八月二十二日起改由「環境部」管轄","amended":"20190725","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0020036","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-with-attachments","articles":[{"type":"A","no":"第 1 條","text":"本準則依空氣污染防制法（以下簡稱本法）第三十二條第三項規定訂定之。","headingPath":[]},{"type":"A","no":"第 2 條","text":"本準則適用於主管機關執行未經排放管道排放空氣污染物之空氣污染行為管制。","headingPath":[]},{"type":"A","no":"第 3 條","text":"主管機關執行空氣污染行為管制之判定位置，應於廠房外、周界或周界外，並能明確判定污染物係由受稽查污染源所逸散。","headingPath":[]},{"type":"A","no":"第 4 條","text":"主管機關執行空氣污染行為管制時，應符合下列規定：\n一、判定粒狀污染物逸散行為時，應以目視確認明顯可見粒狀污染物排放，倘其逸散之廢氣含有水蒸氣，應於稽查紀錄中敘明執行判定時排除水蒸氣干擾之情形。\n二、判定異味污染物污染行為時，應繪製或記錄判定異味發生源之相關位置，並描述現場聞到之氣味。\n三、判定有毒氣體逸散行為時，應確認污染源所使用之原料、燃料、物料或其產出物含有毒性物質。","headingPath":[]},{"type":"A","no":"第 5 條","text":"主管機關執行空氣污染行為管制時，應填載稽查工作紀錄表，其內容應包括下列事項：\n一、公私場所名稱、負責人或行為人之姓名。\n二、污染源名稱及位置。\n三、稽查時間。\n四、稽查判定位置及與污染發生源位置之相關性。\n五、發生污染行為之具體事實及判定方式。\n六、污染源及污染防制設施設置及操作情形。\n七、判定污染行為之相關佐證資料。\n八、其他必要之稽查事項。","headingPath":[]},{"type":"A","no":"第 6 條","text":"主管機關執行本法第三十二條第一項第一款行為管制時，除確認污染源有明顯之粒狀污染物散布於空氣中或他人財物外，並應確認其符合下列情形之一：\n一、未裝置粒狀污染物收集及處理設備。\n二、雖裝置粒狀污染物收集及處理設備，但廢氣未完全有效收集及處理。\n三、由污染源與受污染財物之地理位置及污染發生當時氣象條件，可判定其具有關聯性。","headingPath":[]},{"type":"A","no":"第 7 條","text":"主管機關執行本法第三十二條第一項第二款行為管制時，除確認污染源有引起塵土飛揚或污染空氣行為外，並應確認其符合下列情形之一：\n一、施工區、施工道路、運輸道路或工地出入口未有效灑水或清掃。\n二、施工區周界未設置有效防止粒狀物質飛散之防塵罩網、靜電幕、防塵屏、圍籬或防風柵等設施。\n三、施工道路或工材運輸路線未舖設有效防止粒狀物質飛散之鋼板、瀝青、混凝土礫石或簡易瀝青混凝土等舖面。\n四、裸露地面未灑水、栽植、造林、植生被覆或噴灑化學藥劑等有效防制粒狀污染物飛散之措施。\n五、營建工地、土石開挖堆置場、棄土場或廢棄物掩埋場等易致車身或機具挾帶廢土之場所，其出入口未設置專用清洗設施，或未確實清洗車輪上之殘留泥沙。\n六、土石粒料運輸車輛之車斗為洩漏型式，或車斗未覆蓋防塵罩，或防塵罩之邊緣未綑紮牢固。\n七、於開挖、鑽孔、爆破或拆除等產生大量粒狀污染物之作業，未設置有效防制粒狀污染物逸散之設施。\n八、雖有其他防制設施，但仍無法有效抑制塵土飛揚。","headingPath":[]},{"type":"A","no":"第 8 條","text":"主管機關執行本法第三十二條第一項第三款及第四款之行為管制時，除確認污染源有產生異味污染物或有毒氣體外，並應確認其符合下列情形之一：\n一、未裝置異味污染物或有毒氣體收集及處理設備。\n二、雖裝置異味污染物或有毒氣體收集及處理設備，但異味污染物或有毒氣體未被完全有效收集及處理。\n三、貯放或輸送設施未密封或加蓋。","headingPath":[]},{"type":"A","no":"第 9 條","text":"主管機關執行本法第三十二條第一項第五款之行為管制時，除確認污染源有散布油煙或產生異味污染物之行為外，並應確認其符合下列情形之一：\n一、未裝置油煙或異味污染物收集及處理設備。\n二、雖裝置收集及處理設備，但油煙或異味污染物未被完全有效收集及處理。","headingPath":[]},{"type":"A","no":"第 10 條","text":"主管機關執行礦物、土石或其他粒狀物之堆置場之空氣污染行為管制時，除確認污染源有明顯粒狀污染物逸散於空氣中外，並應確認其符合下列情形之一：\n一、未設置有效防止粒狀物質飛散之密閉式堆置場。\n二、未設置有效防止粒狀物質飛散之灑水系統，或未定時於堆置物質表面灑水，抑制粒狀污染物飛散。\n三、未覆蓋有效防止粒狀物質飛散之防塵布或防塵罩網。\n四、未於堆置物質表面噴灑化學穩定劑或將其壓實防止粒狀污染物飛散。\n五、未設置有效防止粒狀物質飛散之圍籬、擋風牆或靜電幕。\n六、雖有其他防制設施，但仍無法有效防制粒狀物之逸散。","headingPath":[]},{"type":"A","no":"第 11 條","text":"主管機關執行管制礦物、土石或其他粒狀物質輸送系統之空氣污染行為時，除應確認污染源有明顯粒狀污染物逸散於空氣中外，並應確認其符合下列情形之一：\n一、未設置有效防止粒狀物質飛散之密閉輸送系統。\n二、開放式之輸送系統，未設置有效防止粒狀物質飛散之灑水設備。\n三、開放式之輸送系統，未覆蓋有效防止粒狀物質飛散之防塵罩網。\n四、接駁點或裝卸作業，未裝置粒狀污染物收集及處理設施。\n五、雖有其他防制設施，但仍無法有效防制粒狀物之逸散。","headingPath":[]},{"type":"A","no":"第 12 條","text":"主管機關執行空氣污染行為管制，於必要時，得會同陳情人或污染源附近之居民為之。","headingPath":[]},{"type":"A","no":"第 13 條","text":"本準則自八十九年五月一日施行。\n本準則修正條文自發布日施行。","headingPath":[]}],"attachments":[],"attachmentNote":""},"construction-air-reg":{"id":"construction-air-reg","pcode":"O0020058","name":"營建工程空氣污染防制設施管理辦法","foreword":"","histories":"1.中華民國九十二年五月二十八日行政院環境保護署環署空字第 0920036\r\n  945 號令訂定發布全文 18 條；並自九十三年七月一日起施行\r\n2.中華民國九十六年十月二十四日行政院環境保護署環署空字第 0960079\r\n  904 號令修正發布第 2、18  條條文；增訂第 13-1 條條文；並自發布\r\n  日施行\r\n3.中華民國一百零二年十二月二十四日行政院環境保護署環署空字第 102\r\n  0111983 號令修正發布第 2、4、13-1、18 條條文；並自一百零三年一\r\n  月一日施行\r\n4.中華民國一百十年十月十八日行政院環境保護署環署空字第 110114119\r\n  4 號令修正發布全文 20 條；並自一百十一年十一月一日施行\r\n  中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公告\r\n  第 3  條第 1  項第 3  款所列屬「行政院環境保護署」之權責事項，\r\n  自一百十二年八月二十二日起改由「環境部」管轄","amended":"20211018","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0020058","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-text-partial-attachments","articles":[{"type":"A","no":"第 1 條","text":"本辦法依空氣污染防制法（以下簡稱本法）第二十三條第二項規定訂定之。","headingPath":[]},{"type":"A","no":"第 2 條","text":"本辦法用詞，定義如下：\n一、營建工程工地（以下簡稱營建工地）：指營建工程基地、施工或堆置物料之區域。\n二、全阻隔式圍籬：指全部使用非鏤空材料製作之圍籬。\n三、半阻隔式圍籬：指離地高度八十公分以上使用網狀鏤空材料，其餘使用非鏤空材料製作之圍籬。\n四、簡易圍籬：指以金屬、混凝土、塑膠等材料製作，至少離地高度八十公分以內使用非鏤空材料製作之拒馬或紐澤西護欄等實體隔離設施。\n五、防溢座：指設置於營建工地圍籬下方或洗車設備四周，防止廢水溢流之設施。\n六、防塵布：指以布料、帆布或塑膠布等材料製作，防止粉塵逸散之設施。\n七、防塵網：指以網狀材料製作，防止粉塵逸散之設施。\n八、粗級配：指舖設地面，防止粉塵逸散之骨材。\n九、粒料：指礫石、碎石或其他防止粉塵逸散之粒狀物質。\n十、路面色差：指道路表面因沙土等粒狀污染物附著，造成與乾淨路面有顏色差異之情形。","headingPath":[]},{"type":"A","no":"第 3 條","text":"本辦法適用對象，指應依本法第十六條第一項第一款規定繳納空氣污染防制費業主之營建工程。但下列營建工程，不在此限：\n一、應申報繳納空氣污染防制費，其費額未達新臺幣二千元，且施工面積未達一萬平方公尺、工期未達一年者。\n二、依空氣污染防制費收費辦法規定得免繳納空氣污染防制費者。\n三、其他經中央主管機關指定公告者。\n前項第一款費額之試算，以營建工程空氣污染防制費收費費率第三級費率為基準。","headingPath":[]},{"type":"A","no":"第 4 條","text":"本辦法所稱營建工程，依施工規模分為第一級營建工程及第二級營建工程。\n第一級營建工程之工程類別及施工規模如附表一。第一級以外之營建工程，屬第二級營建工程。","headingPath":[]},{"type":"A","no":"第 5 條","text":"營建業主於營建工程進行期間，應設置工地標示牌。\n前項標示牌內容，應載明營建工程空氣污染防制費徵收管制編號、工地負責人姓名、電話及當地環保機關公害檢舉電話號碼。","headingPath":[]},{"type":"A","no":"第 6 條","text":"營建業主於營建工程進行期間，應於營建工地周界設置定著地面之全阻隔式圍籬及防溢座，圍籬高度規定如附表二。但道路轉角或轉彎處十公尺以內者，得設置半阻隔式圍籬。\n道路、隧道、管線或橋樑工程臨接道路寬度八公尺以下或施工工期未滿三個月者，得設置連接之簡易圍籬。\n前二項營建工程之工地周界臨接山坡地、河川或湖泊等天然屏障或其他具有與圍籬相同效果者，報請直轄市、縣（市）主管機關同意後，得免設置圍籬。","headingPath":[]},{"type":"A","no":"第 7 條","text":"營建業主於營建工程進行期間，其所使用具粉塵逸散性之工程材料、砂石、土石方或廢棄物，且其堆置於營建工地者，應採行下列有效抑制粉塵之防制設施之一：\n一、覆蓋防塵布。\n二、覆蓋防塵網。\n三、配合定期噴灑化學穩定劑。","headingPath":[]},{"type":"A","no":"第 8 條","text":"營建業主於營建工程進行期間，應於營建工地內之車行路徑，舖設下列有效抑制粉塵之防制設施之一：\n一、鋼板。\n二、混凝土。\n三、瀝青混凝土。\n四、粗級配或粒料。\n前項防制設施須達車行路徑面積之百分之七十以上；屬第一級營建工程者，須達車行路徑面積之百分之九十以上。\n洗車設施至主要道路之車行路徑，應符合第一項之規定。","headingPath":[]},{"type":"A","no":"第 9 條","text":"營建業主於營建工程進行期間，應於營建工地內之裸露區域，採行下列有效抑制粉塵之防制設施之一：\n一、覆蓋防塵布、防塵網或稻草（蓆）。\n二、舖設鋼板、混凝土或瀝青混凝土。\n三、舖設粗級配或粒料。\n四、植生綠化。\n五、地表壓實且配合每日至少灑水二次，每次灑水範圍應涵蓋裸露區域，並記錄用水量備查。\n六、配合定期噴灑化學穩定劑。\n七、設置自動灑水設備，灑水範圍應涵蓋裸露區域。\n前項防制設施應達裸露區域面積之百分之七十以上；屬第一級營建工程者，應達裸露區域面積之百分之九十以上。裸露區域扣除採行前項防制設施之剩餘部分，須配合定期灑水，灑水頻率每日至少二次。\n前項剩餘部分須配合定期灑水之規定，於經濟部核定第三及第四階段停止及限制供水措施區域內之營建工程，不適用之。","headingPath":[]},{"type":"A","no":"第 10 條","text":"營建業主於營建工程進行期間，應於營建工地運送具粉塵逸散性之工程材料、砂石、土方或廢棄物之車行出入口，設置洗車台，且應符合下列規定：\n一、洗車台四周應設置防溢座或其他防制設施，防止洗車廢水溢出工地。\n二、設置廢水收集坑。\n三、設置具有效沉砂作用之沉砂池。\n前項營建工程無設置洗車台空間時，得以加壓沖洗設備清洗，並妥善處理洗車廢水。\n第一項洗車設施於車輛離開營建工地時，應有效清洗車體及輪胎，其表面不得附著污泥，或造成工地出入口及其延伸之道路有路面色差。\n屬區域開發工程、疏濬工程者，應洗掃鄰接道路，並設置自動洗車設備，其項目及規格如附表三。","headingPath":[]},{"type":"A","no":"第 11 條","text":"營建業主於營建工程進行期間，應於營建工地結構體施工架外緣或結構體上設置下列可抑制粉塵之設施之一：\n一、防塵網。\n二、防塵布。\n三、自動灑水設備，灑水範圍應涵蓋結構體。","headingPath":[]},{"type":"A","no":"第 12 條","text":"營建業主於營建工程進行期間，將營建工地內上層具粉塵逸散性之工程材料、砂石、土方或廢棄物輸送至地面或地下樓層，應採行下列可抑制粉塵逸散之方式之一：\n一、以電梯孔道輸送。\n二、以建築物內部管道輸送。\n三、以密閉輸送管道輸送。\n四、以人工搬運。\n前項第一款至第三款管（孔）道出口，應設置抑制粉塵逸散之圍籬並灑水。","headingPath":[]},{"type":"A","no":"第 13 條","text":"營建業主於營建工程進行期間，運輸具粉塵逸散性之工程材料、砂石、土方或廢棄物之車輛應使用密閉式貨廂，或以防塵布、防塵網緊密覆蓋貨廂，並捆紮牢靠，邊緣應延伸覆蓋至貨廂上緣以下至少十五公分。運輸車輛貨廂應具有防止載運物料滴落污水、污泥之功能或設施。","headingPath":[]},{"type":"A","no":"第 14 條","text":"營建業主於營建工程進行拆除期間，應採行下列有效抑制粉塵之防制設施之一：\n一、設置加壓噴水設施，並於拆除作業期間持續噴水。\n二、於結構體包覆防塵布。\n三、於結構體四周設置高度達二．四公尺之阻隔設施。\n前項屬第一級營建工程者，應至少同時採行第一款、第二款之防制設施。","headingPath":[]},{"type":"A","no":"第 15 條","text":"營建業主於營建工程進行期間，應於具有排放粒狀污染物質之排氣井或排風口，設置旋風分離器、袋式集塵器或其他有效之集塵設備。","headingPath":[]},{"type":"A","no":"第 16 條","text":"營建業主於營建工程進行期間，從事具粉塵逸散性之開挖、回填、搬運、裝卸、夯實、篩分或其他易致粉塵逸散之作業前，應灑水保持濕潤。\n前項規定，於經濟部核定第三及第四階段停止及限制供水措施區域內之營建工程，不適用之。","headingPath":[]},{"type":"A","no":"第 17 條","text":"營建業主於營建工程進行期間，從事破（粉）碎、研磨、切割、刨除或其他易致粉塵逸散之操作，應設置或採行下列有效收集或抑制粉塵逸散設施之一：\n一、設置局部集氣系統，將粒狀污染物質收集及處理後排放。\n二、設置加壓噴水設施，並於操作期間持續噴水。","headingPath":[]},{"type":"A","no":"第 18 條","text":"營建工程施工規模達下列條件之一者，營建業主應依附表四及附表五規定，設置空氣污染防制設施之監測儀表及攝錄影監視系統（至少須具備二支以上攝影鏡頭），並依表列項目及頻率進行記錄，記錄之影像及資料應保存一個月備查：\n一、工地面積達一萬平方公尺且工期達一年者。\n二、外運土石體積（鬆方）達一萬立方公尺者。","headingPath":[]},{"type":"A","no":"第 19 條","text":"營建業主未能依本辦法規定設置或採行空氣污染防制設施、監測設施者，得提出同等防制效率或功能之替代方法，報請直轄市、縣（市）主管機關同意後為之。","headingPath":[]},{"type":"A","no":"第 20 條","text":"本辦法自中華民國一百十一年十一月一日施行。","headingPath":[]}],"attachments":[{"name":"附表一  第一級營建工程施工規模.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000301865","localPath":null},{"name":"附表二  圍籬高度規定.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000301866","localPath":null},{"name":"附表三  自動洗車設備項目及規格.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000301867","localPath":null},{"name":"附表四  空氣污染防制設施之監測儀表、記錄項目、記錄頻率及其他規定.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000301868","localPath":null},{"name":"附表五  攝錄影監視系統功能規範.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000301869","localPath":null}],"attachmentNote":"附件／附表共 5 件；本版已離線收錄 0 件，其餘保留全國法規資料庫官方連結。"},"restaurant-air-reg":{"id":"restaurant-air-reg","pcode":"O0020127","name":"餐飲業空氣污染防制設施管理辦法","foreword":"","histories":"1.中華民國一百十年二月五日行政院環境保護署環署空字第 1101012137 \r\n  號令訂定發布全文 8  條；並自發布日施行\r\n2.中華民國一百十年八月二十四日行政院環境保護署環署空字第 1101112\r\n  863 號令修正發布第 4、7 條條文","amended":"20210824","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0020127","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-text-partial-attachments","articles":[{"type":"A","no":"第 1 條","text":"本辦法依空氣污染防制法第二十三條第二項規定訂定之。","headingPath":[]},{"type":"A","no":"第 2 條","text":"本辦法用詞，定義如下：\n一、餐飲業：指從事餐食調理、餐飲承包或提供作業場所從事烘、烤、煎、炒、油炸、煮等餐食調理作業之行業。\n二、營業面積：指餐飲業經營所使用之樓地板面積，包括烹飪作業區及座位區等。\n三、新設列管餐飲業：指本辦法發布日起設立之餐飲業，且達適用符合條件及規模之餐飲業。\n四、既存列管餐飲業：指本辦法發布日前已設立或設立中之餐飲業，且達適用符合條件及規模之餐飲業。\n五、污染防制設施：包含集氣系統、油煙處理設備、監測設施、排氣管線。\n六、集氣系統：指可將油煙、異味污染物捕集並防止污染物逸散之系統，包含氣罩、連接裝置及風車。\n七、油煙處理設備：指可將油煙、異味污染物去除及處理之設備，其類型為靜電集塵器、濕式洗滌器、活性碳吸附裝置、臭氧處理設備或其他處理設備。\n八、排氣管線：指與集氣系統或污染防制設施相連接，用於輸送氣體之管線。\n九、氣罩面積：指氣罩收集面之面積。\n十、集氣面積：指氣罩收集面中實際開口集氣面積之總和。\n十一、集氣風量：指集氣流速與面積之乘積，其類別如下：\n（一）上吸式氣罩集氣風量：指氣罩收集面集氣流速與氣罩面積之乘積。\n（二）側吸式氣罩集氣風量：指氣罩收集面集氣流速與氣罩集氣面積之乘積。","headingPath":[]},{"type":"A","no":"第 3 條","text":"本辦法所稱列管對象，指依附表所列行政區域內，達適用條件及規模之餐飲業。","headingPath":[]},{"type":"A","no":"第 4 條","text":"列管餐飲業應設置集氣系統並與排氣管線連接，及維持系統正常運作。\n前項集氣系統設置應符合下列規定之一：\n一、採上吸式氣罩者：氣罩收集面應自烹飪設施垂直投影面向外延伸十五公分，且與烹飪鍋具上緣之垂直距離不得大於一百二十公分。\n二、採側吸式氣罩者：氣罩收集面前緣與烹飪設施實際烹飪區域中心點或對角線交叉點之水平距離不得大於四十五公分，且氣罩面積應為實際烹飪區域面積之百分之三十以上。\n第一項集氣系統之氣罩面速度應符合下列規定之一：\n一、採上吸式氣罩者，其氣罩面集氣流速應達每秒零點五公尺以上。\n二、採側吸式氣罩者，其氣罩收集面集氣流速應達每秒三公尺以上。\n三、屬既存列管餐飲業之集氣系統，其氣罩收集面集氣流速未能達前二款規定者，應於直轄市、縣（市）主管機關通知改善之期限內完成改善，改善期限以三十日為上限。\n前二項集氣系統之操作條件或數值，得有百分之十之容許差值。\n列管餐飲業因情形特殊無法依第二項及第三項規定設置集氣系統者，得提出替代方案報請直轄市、縣（市）主管機關同意後，據以實施。","headingPath":[]},{"type":"A","no":"第 5 條","text":"列管餐飲業應設置油煙處理設備，其設計處理風量不得小於集氣系統實際集氣風量，並應維持設備正常運作。\n前項油煙處理設備應依下列規定記錄操作、清潔或保養情形。但設置位置不易記錄者，得報經直轄市、縣（市）主管機關同意以記錄水表、電表替代：\n一、每日油煙處理設備操作情形：\n（一）使用靜電集塵器之油煙處理設備，應記錄操作時間及電壓或電流等主要操作參數。\n（二）使用濕式洗滌器之油煙處理設備，應記錄操作時間、進水用量等主要操作參數；有添加化學藥劑者，應記錄使用藥劑之種類及加藥量。\n（三）使用活性碳吸附裝置之油煙處理設備，應記錄操作時間及壓差等主要操作參數。\n（四）使用臭氧處理設備之油煙處理設備，應記錄操作時間及操作電壓或電流等主要操作參數。\n（五）使用前四目以外之其他油煙處理設備，應記錄操作時間或該設備之主要操作參數。\n二、每月至少清潔或保養一次，並記錄執行項目及執行方式。\n前項第一款油煙處理設備操作參數與第二款執行清潔或保養之紀錄，及其相關憑證資料應保存二年備查。","headingPath":[]},{"type":"A","no":"第 6 條","text":"列管餐飲業設置之污染防制設施，應具備可顯示前條第一項第一款各目主要操作參數之監控儀表或監測設施，並應設置於可供直轄市、縣（市）主管機關查核之處。\n直轄市、縣（市）主管機關得命列管餐飲業所設置之污染防制設施設置獨立電表或水表，並記錄每日用電量或用水量資訊，紀錄應保存二年備查。","headingPath":[]},{"type":"A","no":"第 7 條","text":"新設列管餐飲業應自中華民國一百十一年一月一日起符合本辦法規定；既存列管餐飲業應自一百十一年二月一日起符合本辦法規定。\n因不可歸責於既存列管餐飲業之事由，致無法於前項期限內符合本辦法規定者，得於期限屆滿前二個月，檢具證明文件及相關資料，向直轄市、縣（市）主管機關申請展延，展延期限不得逾一百十一年七月一日。","headingPath":[]},{"type":"A","no":"第 8 條","text":"本辦法自發布日施行。","headingPath":[]}],"attachments":[{"name":"附表.ODT","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000286706","localPath":null}],"attachmentNote":"附件／附表共 1 件；本版已離線收錄 0 件，其餘保留全國法規資料庫官方連結。"},"fixed-permit-reg":{"id":"fixed-permit-reg","pcode":"O0020012","name":"固定污染源設置操作及燃料使用許可證管理辦法","foreword":"","histories":"1.中華民國八十二年五月七日行政院環境保護署（82）環署空字第 21232\r\n  號令訂定發布全文 25 條\r\n2.中華民國八十六年五月二十八日行政院環境保護署（86）環署空字第 2\r\n  7725  號令修正發布全文 27 條\r\n3.中華民國八十八年六月十六日行政院環境保護署（88）環署空字第 003\r\n  3720  號令修正發布全文 22 條\r\n4.中華民國九十年十一月七日行政院環境保護署（90）環署空字第 00678\r\n  06  號令修正發布全文 28 條；並自發布日施行\r\n5.中華民國九十二年一月二十二日行政院環境保護署環署空字第 0920005\r\n  303 號令修正發布名稱及全文 34 條；並自發布日施行\r\n  （原名稱：固定污染源設置變更及操作許可辦法；新名稱：固定污染源\r\n  設置與操作許可證管理辦法）\r\n6.中華民國九十六年十一月二十一日行政院環境保護署環署空字第 09600\r\n  87681 號令修正發布全文 36 條；並自發布日施行   \r\n7.中華民國一百零六年二月十三日行政院環境保護署環署空字第 1060010\r\n  310 號令修正發布第 3、4、9、10、14、16、19、27、32、34、35  條\r\n  條文         \r\n8.中華民國一百零八年九月二十六日行政院環境保護署環署空字第 10800\r\n  70285 號令修正發布名稱及全文 63 條；並自發布日施行\r\n  （原名稱：固定污染源設置與操作許可證管理辦法；新名稱：固定污染\r\n  源設置操作及燃料使用許可證管理辦法）      \r\n  中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公告\r\n  第 2  條、第 3  條、第 4  條第 1  項第 3  款第 5  目、第 6  條\r\n  第 1  項第 2  款、第 3  款、第 4  款、第 5  款、第 7  條第 2  \r\n  項、第 10 條、第 11 條第 1  項、第 13 條第 12 款、第 15 條第 4\r\n  款、第 16 條第 3  款第 8  目、第 18 條第 1  項第 7  款、第 19 \r\n  條第 10 款、第 21 條第 1  項第 3  款?、第 3  項、第 22 條第 5 \r\n  款、第 23 條第 4  項、第 6  項、第 24 條第 1  項第 5  款、第 \r\n  25  條第 1  項第 3  款第 4  目、第 3  項、第 26 條、第 30 條第\r\n  3 款、第 31 條第 4  項、第 32 條第 2  項第 3  款、第 42 條第 2\r\n  款、第 3  款、第 4  款、第 5  款、第 49 條第 1  項第 2  款、第\r\n  2 項、第 56 條第 2  項第 5  款、第 57 條第 3  款、第 58 條第 1\r\n  項、第 59 條第 4  款、第 61 條第 1  項所列屬「行政院環境保護署\r\n  」之權責事項，自一百十二年八月二十二日起改由「環境部」管轄","amended":"20190926","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0020012","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-with-attachments","articles":[{"type":"C","no":"","text":"第 一 章 總則","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 1 條","text":"本辦法依空氣污染防制法（以下簡稱本法）第二十四條第四項及第二十八條第二項規定訂定之。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 2 條","text":"公私場所固定污染源經中央主管機關依本法第二十四條第一項指定公告者，應申請設置或操作許可證。\n中央主管機關得依固定污染源製程、設備之種類、規模，將前項依本法第二十四條第一項指定公告之固定污染源分為第一類固定污染源、第二類固定污染源或第三類可簡化申請之固定污染源，並指定公告之。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 3 條","text":"公私場所固定污染源使用生煤或其他經中央主管機關依本法第二十八條第一項指定公告之燃料（以下合稱燃料），應申請燃料使用許可證。但僅使用石油煉製業煉製販售符合國家標準之石油製品或每年總設計、實際燃料使用量低於五百公斤或五百公升者，不在此限。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 4 條","text":"本法第二十四條第一項及第二項所稱變更，指固定污染源設備之更換或擴增、製程、原（物）料、燃料或產品之改變，致有下列情形之一者：\n一、增加空氣污染物排放種類。\n二、任一空氣污染物年排放量推估較許可證記載之年許可排放量增加達百分之二十及五公噸以上。\n三、空氣污染物年排放量推估較許可證記載之年許可排放量增加達下列情形之一：\n（一）氮氧化物達五公噸以上。\n（二）硫氧化物達十公噸以上。\n（三）揮發性有機物達五公噸以上。\n（四）粒狀物達十公噸以上。\n（五）其他經中央主管機關指定之情形。\n公私場所固定污染源因增設空氣污染防制設施，致增加空氣污染物達第一項變更規定者，得依操作許可證異動申請程序規定辦理。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 5 條","text":"本法第八十八條所稱設立，指固定污染源已建造完成、建造中、已完成工程招標程序或未經招標程序已訂立工程施作契約者。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 6 條","text":"本辦法所稱之空氣污染物年許可排放量，其推估依據之順序如下：\n一、公私場所固定污染源連續自動監測設施一年以上之監測資料。\n二、公私場所依第二十條第一項執行之試車檢測報告數據、主管機關或公私場所自行或委託執行三次以上之檢測報告數據。\n三、經中央主管機關認可之空氣污染物自廠係數。\n四、中央主管機關公告之空氣污染物排放係數、控制效率、質量平衡計量方式。\n五、其他經中央主管機關認可之排放係數或替代計算方式。\n公私場所固定污染源之空氣污染物排放量應依前項第三款至第五款規定推估排放量。但其固定污染源採密閉集氣系統收集空氣污染物至排放管道者，得以前項第一款或第二款推估排放量。\n公私場所固定污染源空氣污染物年許可排放量，得作為設置許可證及操作許可證變更之依據，其增加量或增加百分比計算，應以相同推估依據計算之。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 7 條","text":"許可證記載與空氣污染物排放有關之原（物）料、燃料用量及產品產量推估與核定方式如下：\n一、單位時間用（產）量應以固定污染源最大設計量估算與核定之。\n二、年用（產）量得以公私場所申請固定污染源最大操作量估算與核定之。但申請之最大操作量不得大於固定污染源最大設計量。\n前項第二款之年用（產）量，得依本法第七條第二項經中央主管機關核定後公告之空氣污染防制計畫核定。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 8 條","text":"許可證記載之空氣污染防制設施處理效率及操作條件之核定方式如下：\n一、設計操作條件。\n二、無前款設計操作條件時，以試車檢測或實際運轉經驗之空氣污染防制設施操作條件為依據。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 9 條","text":"許可證記載之各項許可條件或數值，於未超過固定污染源空氣污染防制設施最大處理容量，且符合排放標準及本法相關管制規定者，得有百分之十之容許差值。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 10 條","text":"公私場所固定污染源申請固定污染源設置、操作或燃料使用許可證者，應依中央主管機關公告之電子網路傳輸方式辦理。","headingPath":["第 一 章 總則"]},{"type":"A","no":"第 11 條","text":"本辦法所定審核機關，於公私場所依本法第二十四條第一項或第二項規定申請固定污染源設置或操作許可證時，指直轄市、縣（市）主管機關或中央主管機關委託之機關；於公私場所依本法第二十八條第一項規定申請燃料使用許可證時，指直轄市、縣（市）主管機關。\n直轄市、縣（市）主管機關得委託其他機關辦理燃料使用許可證之申請審查及核發事項。\n前項受委託之機關，屬第一項所定之審核機關。","headingPath":["第 一 章 總則"]},{"type":"C","no":"","text":"第 二 章 設置許可證","headingPath":["第 二 章 設置許可證"]},{"type":"A","no":"第 12 條","text":"公私場所依本法第二十四條第一項規定申請固定污染源設置許可證，應填具申請表，並檢具空氣污染防制計畫，向審核機關為之。\n公私場所固定污染源設置於經環境影響評估且具排放總量規定之區域者，於申請固定污染源設置許可證時，應同時檢具該區域管理單位核定之排放量分配證明文件。","headingPath":["第 二 章 設置許可證"]},{"type":"A","no":"第 13 條","text":"前條第一項所稱之空氣污染防制計畫，其內容應包括下列事項：\n一、計畫目標。\n二、污染源廠場周界外二公里範圍內之環境座落圖說。\n三、廠場設施平面配置圖說。\n四、生產製程流程圖說及產製期程。\n五、與空氣污染物排放有關之原（物）料、燃料之種類、成分及用量，產品種類及生產量。\n六、與空氣污染物排放有關之原（物）料、燃料之輸送、貯存及堆置方式。\n七、排放空氣污染物之種類、成分及濃度。\n八、預估需核定之硫氧化物、氮氧化物、粒狀污染物及揮發性有機物之年排放量。\n九、空氣污染收集及排放管道設施、監測設施、防制設施或儀表之種類、構造、效能、流程、使用狀況及其設計圖說。\n十、空氣污染收集及排放管道設施、防制設施之設置經費及進度。\n十一、公私場所設立施工期間採取之污染防制設施。\n十二、其他經中央主管機關指定之事項。","headingPath":["第 二 章 設置許可證"]},{"type":"A","no":"第 14 條","text":"公私場所新設或變更固定污染源依本法第六條第二項、第三項或第八條第二項規定應經模式模擬證明其污染物排放量不超過容許增量限值者，於申請固定污染源設置許可證時，應同時檢具符合空氣品質模式模擬規範及污染物容許增量限值之證明文件。","headingPath":["第 二 章 設置許可證"]},{"type":"A","no":"第 15 條","text":"公私場所新設或變更固定污染源依本法第六條第三項或第八條第三項規定，應採用最佳可行控制技術或最低可達成排放率控制技術，而未採用公告最佳可行控制技術附表所列可行控制技術或最低可達成排放率控制技術附表所列可達成排放率控制技術者，於申請固定污染源設置許可證時，應同時檢具下列文件：\n一、採用低污染性原（物）料、燃料、低污染製程或空氣污染控制設施之污染減量說明資料。\n二、空氣污染減量措施或控制設施之相關操作參數、紀錄方式及頻率。\n三、空氣污染物質能平衡或其他計算說明資料。\n四、其他經中央主管機關指定之資料。","headingPath":["第 二 章 設置許可證"]},{"type":"A","no":"第 16 條","text":"設置許可證應記載事項如下：\n一、設置許可證之有效期間及證書字號。\n二、基本資料：\n（一）公私場所名稱及地址。\n（二）公私場所負責人姓名、身分證明文件字號及住址。\n三、設置許可內容：\n（一）固定污染源之名稱、製程流程圖說、與空氣污染物排放有關之主要原（物）料、燃料種類、成分、用量或產品產量、設計操作條件、設計操作期程。\n（二）空氣污染防制方法及設施之名稱、型式、設計處理容量、設計操作條件及處理效率；依本法規定應採用最佳可行控制技術或最低可達成排放率控制技術者之相關規定。\n（三）空氣污染物之收集排放方式、排放管道口徑、排放口位置及監測設施或儀表。\n（四）空氣污染物之排放種類。\n（五）核定之硫氧化物、氮氧化物、粒狀污染物及揮發性有機物之年許可排放量。\n（六）空氣污染物之年許可排放量推估依據。\n（七）固定污染源許可公告批次及專責單位或人員應符合設置之規定。\n（八）其他經中央主管機關指定之許可事項。","headingPath":["第 二 章 設置許可證"]},{"type":"A","no":"第 17 條","text":"公私場所應於取得固定污染源設置許可證後，始得進行固定污染源設備安裝或建造，並應依許可證內容進行設置或變更。","headingPath":["第 二 章 設置許可證"]},{"type":"C","no":"","text":"第 三 章 操作許可證","headingPath":["第 三 章 操作許可證"]},{"type":"A","no":"第 18 條","text":"公私場所依本法第二十四條第二項規定，申請固定污染源操作許可證，應填具申請表，並檢具下列文件，向審核機關為之：\n一、目的事業主管機關核准設立、登記或營運之相關證明文件影本。\n二、空氣污染防制計畫差異說明書。\n三、試車計畫書，其內容如下：\n（一）試車步驟或程序及達到申請最大產能操作條件所需日數。\n（二）推估各試車步驟或程序之空氣污染物產生情形及防範污染排放超過標準或限制範圍之措施。\n（三）空氣污染物排放檢測計畫。\n四、符合燃料成分標準之證明文件。\n五、屬應實施環境影響評估之公私場所，應檢具環境影響評估法審查通過之書件所載內容及審查結論。\n六、屬本法第八條第三項新設或變更之固定污染源者，應檢具足供抵換污染物增量之排放量證明文件。\n七、其他經中央主管機關指定之文件。\n公私場所依本法第八十八條規定，申請固定污染源操作許可證者，應填具申請表並檢具前項第一款、第四款至第七款申請文件與空氣污染防制設施說明書及空氣污染物排放檢測計畫，向審核機關為之。","headingPath":["第 三 章 操作許可證"]},{"type":"A","no":"第 19 條","text":"前條第二項所稱之空氣污染防制設施說明書，其內容應包括下列事項：\n一、防制目標。\n二、污染源廠場周界外二公里範圍內之環境座落圖說。\n三、廠場設施平面配置圖說。\n四、生產製程流程圖說及產製期程。\n五、與空氣污染物排放有關之原（物）料、燃料之種類、成分及用量，產品種類及生產量。\n六、與空氣污染物排放有關之原（物）料與燃料之輸送、貯存及堆置方式。\n七、排放空氣污染物之種類、成分及濃度。\n八、預估需核定之硫氧化物、氮氧化物、粒狀污染物及揮發性有機物之年排放量。\n九、空氣污染收集及排放管道設施、監測設施、防制設施或儀表之種類、構造、效能、流程、使用狀況及其設計圖說。\n十、其他經中央主管機關指定之事項。","headingPath":["第 三 章 操作許可證"]},{"type":"A","no":"第 20 條","text":"公私場所於審核機關依第三十三條通知試車或空氣污染物排放檢測後，應依下列程序辦理：\n一、公私場所接到試車通知者，應依試車計畫書完成試車，並於核准試車期限屆滿前十五日內，向審核機關提送空氣污染物排放檢測報告或足供認定符合本法相關規定之證明文件，且其檢測結果符合排放標準者，得繼續進行試車。\n二、公私場所應於接到空氣污染物排放檢測通知後六十日內，依核定之空氣污染物排放檢測計畫完成檢測，並向審核機關提送空氣污染物排放檢測報告。\n前項第一款之核准試車期限，不得超過一百日。公私場所無法於核准試車期限內依試車計畫書完成試車者，得於核准試車期限屆滿前向審核機關申請展延，展延申請次數不得超過二次，且含原核准試車期限之試車總日數不得超過一百九十日。但經審核機關核准者，不在此限。\n公私場所於試車期限屆滿十五日前申請展延者，因審核機關審查致試車期限屆滿前無法作成展延之准駁，公私場所得於試車期限屆滿後至試車展延作成准駁期間內，依試車計畫書內容繼續試車；未於試車期限屆滿十五日前申請展延者，審核機關於試車期限屆滿未作成展延之准駁，公私場所應停止試車。\n公私場所於試車期間有修正試車計畫書內容之必要者，應檢具修正後經環境工程技師或其他相關專業技師簽證之試車計畫書，經審核機關核准後，依核准內容進行試車。未經審核機關核准前，得依原試車計畫內容繼續試車。","headingPath":["第 三 章 操作許可證"]},{"type":"A","no":"第 21 條","text":"操作許可證應記載事項如下：\n一、操作許可證之有效期間及證書字號。\n二、基本資料：\n（一）公私場所名稱及地址。\n（二）公私場所負責人姓名、身分證明文件字號及住址。\n三、操作許可內容：\n（一）固定污染源名稱、製程流程圖說、與空氣污染物排放有關之主要原（物）料、燃料種類、成分、用量、產品產量及其操作條件、操作期程。\n（二）空氣污染防制方法及設施之名稱、型式、處理容量、處理效率及操作條件。\n（三）空氣污染物之收集排放方式、排放管道口徑及排放口位置。\n（四）空氣污染物之排放種類。\n（五）核定之硫氧化物、氮氧化物、粒狀污染物及揮發性有機物之年許可排放量。\n（六）空氣污染物之年許可排放量推估依據。\n（七）空氣污染物排放之監測、定期檢測、紀錄、申報及其他應遵行事項之規定。\n（八）固定污染源及空氣污染防制設施操作紀錄之規定。\n（九）固定污染源、空氣污染防制設施、監測設施或採樣設施之檢查、保養、維修之紀錄及其他應遵行事項之規定。\n（十）固定污染源許可公告批次及專責單位或人員應符合設置之規定。\n（十一）其他經中央主管機關指定之許可事項。\n前項第三款第七目至第九目所列之紀錄，應保存六年備查。\n前項備查資料應建立電子化紀錄，未能執行電子化紀錄者，經主管機關同意後，得以紙本紀錄代之。","headingPath":["第 三 章 操作許可證"]},{"type":"A","no":"第 22 條","text":"公私場所預計得於三個月內完成固定污染源設備安裝或建造者，得填具申請表，連同下列文件，向審核機關同時申請設置許可證及操作許可證：\n一、空氣污染防制計畫及試車計畫書。\n二、依第十四條或第十五條規定之文件。\n三、符合燃料成分標準之證明文件。\n四、屬應實施環境影響評估之公私場所，應檢具環境影響評估法審查通過之書件所載內容及審查結論。\n五、其他經中央主管機關指定之事項。","headingPath":["第 三 章 操作許可證"]},{"type":"A","no":"第 23 條","text":"公私場所應於取得固定污染源操作許可證後，始得操作，並應依許可證核定內容操作。\n公私場所依本法第九十條規定，逐案向直轄市、縣（市）主管機關申請並經審查核可之行為，得不受前項操作許可證核定內容限制。公私場所從事經核可之行為，應詳實建立紀錄，保存六年備查。\n公私場所固定污染源使用非屬操作許可證核定記載事項之原（物）料或燃料進行試驗者，應先檢具符合第十八條第一項第三款規定之試車計畫書，逐案向審核機關提出申請，經審核機關核准者，於核准試驗期間依試車計畫書試驗，不受第一項之限制。公私場所從事經核准之試驗，應詳實建立紀錄，保存六年備查。且試驗期間內公私場所不得以同一固定污染源，再申請其他試驗。\n前項試驗使用再利用之原（物）料或燃料，屬中央目的事業主管機關公告再利用或廠（場）內自行再利用之項目者，應另檢具直轄市、縣（市）主管機關或中央主管機關委託之機關核發之事業廢棄物清理計畫書；非屬公告再利用之項目者，應另檢具中央目的事業主管機關核發之再利用許可，或直轄市、縣（市）主管機關核定之土壤地下水污染控制計畫、整治計畫及應變必要措施計畫等文件，向審核機關申請試驗。\n審核機關核准第三項試驗，涉及公私場所檢具試車計畫書之空氣污染物排放檢測計畫之檢測項目，審核機關得依公私場所申請試驗之項目核准，不適用第四十九條第一項及第二項規定。審核機關核准試驗期間最長以三十日為限，必要時得展延一次，展延日數不得超過三十日；審核機關應於試驗期間進行現場勘查。\n公私場所依第三項規定進行試驗，不得異動或變更經核准試驗之試車計畫書內容。未依試車計畫書進行試驗者，審核機關應令公私場所停止試驗；有違反本法規定者，主管機關應按其違規情節依本法相關規定處分，經處分之公私場所，自處分確定之日起一年內不得申請試驗。","headingPath":["第 三 章 操作許可證"]},{"type":"C","no":"","text":"第 四 章 燃料使用許可證","headingPath":["第 四 章 燃料使用許可證"]},{"type":"A","no":"第 24 條","text":"公私場所依本法第二十八條第一項規定，申請燃料使用許可證時，應填具申請表，並檢具下列文件，向審核機關為之：\n一、目的事業主管機關核准設立、登記或營運之相關證明文件影本。\n二、燃料之種類、成分及用量。\n三、生產製程流程圖說。\n四、空氣污染收集設施、防制設施之種類及流程。\n五、其他經中央主管機關指定之文件。\n公私場所同時符合第二條及第三條規定者，應於申請固定污染源操作許可證時，一併提出前項燃料使用許可證申請，其應檢具文件或資料相同者，得不重複。","headingPath":["第 四 章 燃料使用許可證"]},{"type":"A","no":"第 25 條","text":"固定污染源之燃料使用許可證應記載事項如下：\n一、燃料使用許可證之有效期間及證書字號。\n二、基本資料：\n（一）公私場所名稱及地址。\n（二）公私場所負責人姓名、身分證明文件字號及住址。\n三、燃料使用許可內容：\n（一）固定污染源名稱、製程流程圖說、與空氣污染物排放有關之燃料種類、成分、用量及其操作期程。\n（二）空氣污染防制方法及設施之名稱及型式。\n（三）燃料使用紀錄之規定。\n（四）其他經中央主管機關指定之許可事項。\n前項第三款第三目所列之紀錄，應保存六年備查。\n前項備查資料應建立電子化紀錄，未能執行電子化紀錄者，經主管機關同意後，得以紙本紀錄代之。","headingPath":["第 四 章 燃料使用許可證"]},{"type":"A","no":"第 26 條","text":"公私場所領有燃料使用許可證者，其使用燃料之紀錄，應依中央主管機關規定之電子網路傳輸方式，於每年一月、四月、七月及十月底前，向直轄市、縣（市）主管機關申報前季燃料之使用量。","headingPath":["第 四 章 燃料使用許可證"]},{"type":"C","no":"","text":"第 五 章 異動、換補發及展延程序","headingPath":["第 五 章 異動、換補發及展延程序"]},{"type":"A","no":"第 27 條","text":"公私場所因操作內容異動而與操作許可證記載內容不符，未涉及本法第二十四條所稱之變更者，應依下列規定重新申請操作許可證：\n一、製程、設施或操作條件異動者，應於異動前，依操作許可證申請及核發程序辦理。但推估未增加空氣污染物排放量者，得不重新進行檢測。\n二、改用低污染性原（物）料或燃料、拆除或停止使用產生空氣污染之設施、增設防制設施或提升防制效率者，應於事實發生後三十日內檢具相關證明文件，向審核機關提出申請。\n固定污染源操作條件異動，未涉及原許可之製程及設施正常運作功能、防制效率及排放量改變者，應報請審核機關備查，取代原許可證操作條件。審核機關認有必要，得令公私場所進行空氣污染物排放檢測，確認符合應遵循之排放標準後，始得予以備查。\n依第一項第一款規定重新申請操作許可證者，應填具申請表，並檢具空氣污染防制設施差異說明書、試車計畫書及異動所需之工程期程等相關文件。\n公私場所依第一項第一款申請操作許可證異動者，其取得操作許可證後申請之總異動排放量累計達第四條第一項第二款或第三款規定者，應依本法第二十四條第一項規定辦理許可證變更。經辦理變更程序取得操作許可證者，其總異動排放量之累計，自完成變更之日起，重新計算。","headingPath":["第 五 章 異動、換補發及展延程序"]},{"type":"A","no":"第 28 條","text":"公私場所因燃料使用異動而與燃料使用許可證記載內容不符，應依下列規定重新申請燃料使用許可證：\n一、燃料之使用種類或使用量異動者，應於異動前，依燃料使用許可證之申請及核發程序辦理。\n二、改用低污染性燃料、增設、拆除或停止使用產生空氣污染之設施或防制設施者，應於事實發生後三十日內檢附相關證明文件，向審核機關提出申請。\n依前項第一款規定重新申請燃料使用許可證者，應填具申請表，並檢具異動所需之工程期程等相關文件。","headingPath":["第 五 章 異動、換補發及展延程序"]},{"type":"A","no":"第 29 條","text":"許可證於有效期間內因毀損、滅失或其記載之基本資料有改變者，公私場所得於事實發生後六十日內檢具目的事業主管機關核准設立、登記或營運之相關證明文件影本，向審核機關申請換發或補發。\n逾前項期間，經審核機關通知換發或補發許可證者，應於審核機關通知翌日起十日內檢具前項證明文件影本，向審核機關申請換發或補發。\n第一項換發或補發，於公私場所固定污染源設置完成並已取得操作許可證者，免申請設置許可證之換發或補發。\n審核機關受理第一項或第二項之申請，應於十四日內完成審查及證書製作，並通知審查符合規定者，於十四日內繳納證書費及領取許可證。","headingPath":["第 五 章 異動、換補發及展延程序"]},{"type":"A","no":"第 30 條","text":"公私場所依本法第三十條規定申請許可證展延者，應填具申請表，並檢具下列文件，向審核機關為之：\n一、申請展延設置許可證者，應檢具設置工程進度變更說明表。\n二、申請展延操作許可證或燃料使用許可證者，應檢具一年內最近一次之檢測報告，或其他足以說明符合本法相關規定之證明文件。但因停工（業）無法檢具一年內最近一次檢測報告者，得報經審核機關同意，以替代證明文件辦理。\n三、其他經中央主管機關指定之文件。","headingPath":["第 五 章 異動、換補發及展延程序"]},{"type":"C","no":"","text":"第 六 章 許可證審查原則","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 31 條","text":"審核機關受理第十二條、第十八條、第二十四條、第二十七條、第二十八條及第三十條規定之申請，應依下列程序完成審查，且審查範圍不得及於申請項目或內容以外之事項，並將審查結果作成准駁決定：\n一、形式審查：審核機關應於收到網路申請及書面資料後，就申請文件內容進行書面完整性審查，並自收件日起七日內完成審查及通知公私場所於七日內繳納審查費。\n二、實質審查：審核機關應自公私場所完成繳費翌日起三十五日內完成實質審查、諮詢及通知審查結果。\n前項審查於必要時，審核機關得延長實質審查期限十五日；受理第一類固定污染源設置、操作許可證之申請，其實質審查期間得延長三十日；受理符合第十四條或第十五條規定固定污染源之設置許可證申請，其實質審查期間得延長四十五日。\n審核機關實質審查下列申請，應進行現場勘查：\n一、許可證展延。\n二、依第二十七條第一項第一款不需重新進行檢測或同條項第二款操作許可證異動。\n三、依第二十八條第一項重新申請燃料使用許可證。\n第一項申請屬設置或操作許可證者，審核機關應於公私場所完成繳費翌日起，將申請資料公開於中央主管機關指定之網站七日，於資訊公開結束翌日，開始實質審查。但因許可證異動重新申請或許可證展延者，不在此限。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 32 條","text":"審核機關受理固定污染源設置及操作許可證申請時，下列申請文件應經環境工程技師或其他相關專業技師簽證，且經簽證後得免再審查：\n一、第十二條第一項之空氣污染防制計畫。\n二、第十八條第一項第二款之空氣污染防制計畫差異說明書及同條項第三款試車計畫書。\n三、第十八條第二項之空氣污染防制設施說明書及空氣污染排放檢測計畫。\n四、第二十條第四項之修正試車計畫書。\n前項經環境工程技師查核之簽證文件，核發機關免再審查之規定，有下列情形之一，審核機關仍應審查：\n一、公私場所於許可證有效期間內，有違反本法第九十六條第一項所稱之情節重大。\n二、依本法第九十七條第一項規定申請試車後復工（業）。\n三、辦理簽證之環境工程技師或其他相關專業技師，五年內經主管機關或技師公會報請技師懲戒委員會處理。但經技師懲戒委員會確定毋須懲戒者，不在此限。\n四、簽證後經懲戒廢止執業執照或廢止技師證書。\n五、其他經審核機關認定有審查必要之情形。\n審核機關得調閱依環境工程技師簽證規則規定彙訂而成之工作底稿影本。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 33 條","text":"審核機關依第三十一條第一項第二款通知公私場所審查結果，屬申請操作許可證或燃料使用許可證者，審核機關應併同通知辦理下列程序：\n一、依第十八條第一項申請操作許可證者，應通知進行試車。\n二、依第十八條第二項申請操作許可證者，應通知進行空氣污染物排放檢測。\n三、依第二十七條第一項第一款申請操作許可證且須重新進行空氣污染物排放檢測者，應通知進行檢測。\n審核機關應於公私場所依前項通知執行試車或空氣污染物排放檢測期間進行現場勘查。\n審核機關應於收到公私場所提報空氣污染物排放檢測報告後十五日內完成審查，必要時得延長十日。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 34 條","text":"審核機關受理各項許可證申請文件，經審查符合第三十一條至第三十三條規定者，應於完成審查後十四日內完成證書製作並通知公私場所繳納證書費及領取許可證。\n審核機關依前項規定通知公私場所領取操作許可證者，應令公私場所檢具目的事業主管機關核准設立、登記或營運之許可文件，始得核發。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 35 條","text":"審核機關受理各項許可證申請案件，經認定應補正資料者，其審查意見應一次性提出，除因公私場所補正文件而新增之審查意見外，後續通知限期補正時，不應有前次通知限期補正未列明之審查意見。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 36 條","text":"審核機關受理各項許可證申請、變更、異動或展延，經審查公私場所有下列情形之一者，應即通知公私場所限期補正：\n一、形式審查之資料、文件有欠缺或不完整。\n二、未繳納審查費。\n三、設置許可證申請文件內容不合規定。\n四、操作許可證申請文件內容、現場勘查結果或空氣污染排放檢測報告不合規定。\n五、燃料使用許可證之申請文件內容不合規定。\n六、許可證展延之申請文件內容不合規定。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 37 條","text":"審核機關受理設置及操作許可證之合併申請，應依第三十一條及第三十二條規定審查，經審查通過後，通知公私場所領取設置許可證，並於公私場所檢具目的事業主管機關核准設立、登記或營運之相關證明文件影本後，通知公私場所進行試車，再依第二十條、第三十三條及第三十四條規定審查及通知領取操作許可證。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 38 條","text":"審核機關受理第二十四條第二項申請，應依操作許可證之申請、審查及核發程序規定辦理，並將燃料使用許可證應記載事項合併於固定污染源操作許可證記載，其相同應記載事項得不重複核定。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 39 條","text":"審核機關受理公私場所依第二十九條規定申請補發、換發許可證或改變許可證應記載事項之基本資料者，應依公私場所申請事項及其檢具之證明文件核實記載，不得於許可證基本資料改變、補發或換發申請事項以外，任意變更其他應記載事項。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 40 條","text":"審核機關除發現核發之許可證有誤寫、誤算或其他類此未符合本法規定之顯然錯誤者，應即更正並限期公私場所換領證書外，不得依職權變更許可證應記載事項。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 41 條","text":"公私場所依第二十條規定進行試車或檢測時，審核機關核定操作許可證與空氣污染物排放有關之操作條件，應依下列原則辦理：\n一、主要原（物）料及燃料使用量達申請之百分之八十以上者，應依申請內容作為操作許可證之核定內容。\n二、主要原（物）料及燃料使用量無法達申請之百分之八十以上者，應以試車或檢測時之實際操作條件之一．二倍，作為操作許可證之核定內容。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 42 條","text":"審核機關應依下列規定確實審核，據以核定操作許可證內容，不得以任何形式之處分增加法規所未明定之義務：\n一、非屬本法第二十條第二項所定排放標準之適用對象，逕予指定適用該排放標準。\n二、非屬中央主管機關指定公告應設置自動監測設施之固定污染源，指定設置自動監測設施；亦不得將非經指定公告應連線者，指定其監測設施與直轄市、縣（巿）主管機關連線。\n三、非屬主管機關指定公告應自行或委託檢驗測定機構實施定期檢驗測定之固定污染源，指定實施定期檢驗。\n四、非屬中央主管機關所定燃料種類混燒比例及成分之標準，逕予指定公私場所適用之。\n五、其他非經中央主管機關依法規明定之義務。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 43 條","text":"審核機關審查許可證展延，應依本法第三十條規定辦理，除符合本法第三十條第四項規定情形得據以變更外，不得變更第二十一條第一項第三款操作許可內容及第二十五條第一項第三款燃料使用許可內容。\n前項變更，包含審核機關以任何形式之處分規範公私場所，增加或減少操作許可內容所記載主要原（物）料、燃料之種類、成分及用量、產品產量及其操作條件、操作期程、空氣污染防制設施之種類、處理容量、處理效率及操作條件、主要污染物之核定年許可排放量、監測、定期檢測及申報之頻率及項目；及增加或減少燃料使用許可內容所記載之主要原（物）料、燃料之種類、成分及用量、產品產量及其操作條件、操作期程、空氣污染防制設施之處理容量、處理條件及操作條件等許可內容。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 44 條","text":"審核機關受理下列申請時，應依原許可證期限核定：\n一、依第二十七條申請操作許可證或第二十八條申請燃料使用許可證者。\n二、依第二十九條申請操作許可證換發或補發者。\n前項申請期間於原許可證期限屆滿前三至六個月內者，公私場所得併同提送許可證展延申請，審查與補正日數分別計算。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 45 條","text":"審核機關依第三十六條通知公私場所限期補正，屆期未補正或超過總補正日數者，應駁回其申請。屬第三十六條第三款至第六款規定文件，公私場所於期限內已補正而仍不合規定者，審核機關得再通知限期補正，總補正次數以三次為限，屆滿三次仍不合規定者，應駁回其申請。\n審核機關依第三十六條規定命補正日數不算入許可證審查期間內，且其總補正日數規定如下：\n一、符合第三十六條第一款或第二款情形之總補正日數不得超過十四日。\n二、符合第三十六條第三款至第五款情形之總補正日數不得超過九十日。\n三、符合第三十六條第六款情形之總補正日數不得超過三十日。\n審核機關受理公私場所依第二十九條第一項許可證換發或補發之申請，其申請文件不合規定或內容有欠缺者，應駁回其申請。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 46 條","text":"審核機關審查，有下列情形之一者，應予以駁回：\n一、公私場所申請設置許可證，其固定污染源設置於不得設置生產設施之處所或用地。\n二、公私場所申請設置許可證，其固定污染源經目的事業主管機關認定有違法而不得設置。\n三、公私場所申請許可證變更、異動或展延，其固定污染源設置許可證核定之任一空氣污染物年許可排放量未達本法第六條所定污染物排放量規模，於申請操作許可證之任一空氣污染物年排放量估算結果，大於本法第六條所定污染物排放量規模。\n四、公私場所申請許可證變更、異動或展延，其固定污染源符合第二十七條第四項規定，取得操作許可證後申請之總異動排放量累計達第四條第一項第二款或第三款規定，未提出設置許可證之申請。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 47 條","text":"公私場所執行試車計畫或空氣污染物排放檢測計畫期間有下列情形之一者，審核機關應令公私場所改善、停止試車或檢測：\n一、依試車計畫或空氣污染物排放檢測計畫內容進行試車或檢測而有違反本法規定。\n二、未依試車計畫或空氣污染物排放檢測計畫內容進行試車或檢測。\n有前項第一款情形，經公私場所改善完成者，得繼續試車。有前項第二款情形且違反本法規定者，直轄市、縣（巿）主管機關應按其違規情節，依本法相關規定處分；經令停止試車或檢測者，審核機關應駁回其操作許可證申請。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 48 條","text":"審核機關辦理公私場所二以上固定污染源合由同一排放管道排放空氣污染物，其任一固定污染源依本法第二十四條或第八十八條規定申請核發許可證時，經審核機關認定與申請者之空氣污染物排放有關之固定污染源，審核機關得要求其併同申請。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 49 條","text":"審核機關審查公私場所依第十八條規定提出之空氣污染物排放檢測計畫時，其檢測應以下列項目為限：\n一、預估需核定之硫氧化物、氮氧化物、粒狀污染物及揮發性有機物。\n二、主管機關依本法第二十條第二項訂定特定業別或設施空氣污染物排放標準規範之空氣污染物。\n非屬前項規定之空氣污染物項目，審核機關得依中央主管機關認可之自廠係數、公告係數或替代計算方式推估確認應符合之排放標準。\n第一項空氣污染物排放檢測計畫有下列情形之一者，經審核機關同意後，得免實施檢測：\n一、固定污染源因故未能依本法第四十八條第四項設置檢查或鑑定設施，致不能實施採樣。\n二、公私場所檢具使用原（物）料、燃料未含特定空氣污染物成分或足供證明無特定空氣污染物排放之證明文件。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 50 條","text":"審核機關核定許可證中有關固定污染源與防制設施之操作條件，應依其設計或實際操作情形，核定足供監控符合實際運作情形之操作條件、紀錄項目及頻率，並指定公私場所固定污染源設置足供查驗符合操作條件之監測儀表。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 51 條","text":"審核機關受理公私場所固定污染源許可證之申請，屬應實施環境影響評估者，其許可證內容，應納入經環境影響評估法審查通過之書件所載內容及審查結論。\n前項納入許可證內容事項，不受第四十二條規定之限制。","headingPath":["第 六 章 許可證審查原則"]},{"type":"A","no":"第 52 條","text":"公私場所固定污染源有下列情形之一者，審核機關得撤銷或廢止其許可證：\n一、申請文件有虛偽不實。\n二、新設公私場所已停止設置固定污染源設備，或經目的事業主管機關認定無繼續設廠（場）事實。\n三、公私場所停工或停業一年以上。但有正當理由無法復工或復業，報經目的事業主管機關核准者，不在此限。\n四、公私場所主要生產設施已搬遷，經目的事業主管機關認定無繼續生產、製造、加工之事實。\n五、公私場所改變生產製程、燃料或空氣污染防制設施，致非屬公告應申請設置、變更及操作許可證之固定污染源或使用非屬指定公告燃料。\n六、非屬公告應申請設置、變更及操作許可證之固定污染源或使用非屬指定公告燃料，已取得許可證。\n七、公私場所歇業、繳銷工廠登記證或經目的事業主管機關公告註銷。\n八、違反本辦法相關規定並具有本法第九十六條第一項第二款至第七款情形之一。","headingPath":["第 六 章 許可證審查原則"]},{"type":"C","no":"","text":"第 七 章 附則","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 53 條","text":"公私場所執行本辦法規定之空氣污染物檢測作業時，應於執行檢測前七日通知審核機關。\n前項檢測作業，公私場所有二個以上固定污染源，其型式、規模、操作條件及污染防制設施均相同者，得準用固定污染源自行或委託檢測及申報管理辦法規定，報經審核機關核准，擇一定數量污染源進行檢測作業。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 54 條","text":"公私場所固定污染源依本法第二十二條規定實施定期檢驗測定期間，適逢固定污染源因操作內容異動，且已重新申請操作許可證者，得於試車進行之空氣污染物排放檢測替代。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 55 條","text":"公私場所具有第二條指定公告之第三類固定污染源者，得向審核機關申請同意設置，審核機關經確認固定污染源製程符合公告條件後，得函復同意其設置。\n公私場所應於前項固定污染源完成設置後三十日內，依第十八條規定向審核機關提出操作許可證申請。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 56 條","text":"公私場所固定污染源因產能或產品變動快速，須持續申請許可產能異動或變更者，得一次申請未來五年內將達成之產能條件許可或與空氣污染物排放有關之主要原（物）料、燃料使用量之最大操作條件許可。其進行試車或檢測時，得以一定製程條件作為操作條件，不受第四十一條規定之限制。\n公私場所依前項申請設置及操作許可證時，應檢具第十二條或第十八條規定之文件及下列資料，向審核機關為之：\n一、自申請日起五年內之預定產能資料或與空氣污染物排放有關之原（物）料、燃料操作條件。\n二、申請未來最大產能條件或最大操作條件下預估之污染物排放量。\n三、產能或產品快速變動之說明。\n四、固定污染源設置之主要空氣污染物濃度連續自動監測設施計畫，或其他報請審核機關認可，足以證明其排放污染物符合本法相關規定之替代監測方案，及空氣污染物排放之監測、檢測、申報之作業因應方式。\n五、其他經中央主管機關指定之文件。\n審核機關受理前項許可證之申請，得以其未來五年內最大產能條件或最大操作條件，作為設置及操作許可證核發之依據。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 57 條","text":"公私場所依前條規定取得操作許可證者，其操作應符合下列規定，且不受第九條所定百分之十容許差值之限制：\n一、產能變動快速者：\n（一）操作條件之產品產量、與空氣污染物排放有關之原（物）料或燃料達許可使用量後，每增加許可核定量百分之二十時，應於一個月內依規定完成檢測。檢測時操作條件之產品產量、與空氣污染物排放有關之原（物）料或燃料使用量應達實際操作條件百分之八十以上。\n（二）定期記錄與空氣污染物排放有關之原（物）料、燃料、產品及防制設施相關操作事項，並依規定進行檢測及申報作業。\n（三）前目之操作及檢測記錄，除另有規定外，應於每年一月、四月、七月及十月之月底前向直轄市、縣（市）主管機關申報上一季之紀錄。\n二、產品變動快速者：\n（一）每日記錄與空氣污染物排放有關之原（物）料、燃料及防制設施相關操作事項。\n（二）至少每半年進行一次空氣污染物之檢測。\n（三）前二目之操作及檢測紀錄，應每半年定期向直轄市、縣（市）主管機關申報。\n三、其他經中央主管機關指定之事項。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 58 條","text":"公私場所依本辦法規定應由審核機關將申請資料公開於中央主管機關指定網站者，得依固定污染源管理資訊公開及工商機密審查辦法申請工商機密審查。\n依前項規定經審查通過之核准（定）文件，應作為公私場所依第十二條、第十八條或第三十七條申請許可證檢具之文件。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 59 條","text":"第三十二條所指申請文件應經環境工程技師或其他相關專業技師簽證之內容，應包含下列項目：\n一、第十三條第四款至第十一款之空氣污染防制計畫內容。\n二、第十八條第一項第二款及第三款。\n三、第十九條第四款至第九款之空氣污染防制設施說明書內容。\n四、其他經中央主管機關指定之項目。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 60 條","text":"公私場所依本辦法規定提出之各項許可證申請資料，應由該公私場所設置之空氣污染防制專責人員確認申請內容並簽章。\n前項公私場所未設置空氣污染防制專責單位或人員者，得由公私場所負責人或其指定代理人為之。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 61 條","text":"經中央主管機關委託之機關有下列情形之一者，中央主管機關得公告停止部分或全部委託：\n一、受委託機關無法配合中央與直轄市、縣（市）主管機關執行許可管制業務，經中央主管機關認定。\n二、直轄市、縣（市）主管機關提出受委託機關不宜繼續接受委託之理由，報經中央主管機關認可。\n三、主管機關依法實施總量管制，另有相關規定。\n四、受委託機關提出不再繼續接受委託理由，報經中央主管機關同意。\n五、其他經中央主管機關認無委託之必要。\n前項規定於直轄市、縣（市）主管機關依第十一條第二項委託之機關，辦理燃料使用許可證之申請審查及核發事項，準用之。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 62 條","text":"本辦法發布前公私場所已使用燃料者，應自公私場所固定污染源燃料混燒比例及成分標準發布日起一年內，依本辦法申請燃料使用許可證。\n本辦法發布前，已依生煤、石油焦或其他易致空氣污染之物質販賣或使用許可證管理辦法領有生煤使用許可證之公私場所，得於該許可證有效期限屆滿前繼續使用，並於有效期限屆滿前三至六個月內，申請展延並換發燃料使用許可證。\n前項公私場所申請生煤使用許可證展延換發為燃料使用許可證，審核機關應依生煤使用許可證內容，以操作許可證之製程為單位，分別核定各製程之燃料使用量，並於對應製程之操作許可證有效期限屆滿、異動或變更申請時，一併納入製程之燃料使用許可證。","headingPath":["第 七 章 附則"]},{"type":"A","no":"第 63 條","text":"本辦法自發布日施行。","headingPath":["第 七 章 附則"]}],"attachments":[],"attachmentNote":""},"fixed-emission-standard":{"id":"fixed-emission-standard","pcode":"O0020006","name":"固定污染源空氣污染物排放標準","foreword":"","histories":"1.中華民國八十一年四月十日行政院環境保護署（81）環署空字第 01345\r\n  9 號令訂定發布全文 14 條\r\n2.中華民國八十三年四月二十日行政院環境保護署（83）環署空字第 166\r\n  68  號令修正發布全文 14 條\r\n3.中華民國八十八年六月三十日行政院環境保護署（88）環署空字第 003\r\n  9205  號令修正發布第 1 條條文及第 2  條條文之附表\r\n4.中華民國九十年十二月十九日行政院環境保護署（90）環署空字第 007\r\n  4780  號令修正發布第 2  條附表、 12 條條文\r\n5.中華民國九十一年七月三日行政院環境保護署環署空字第 0910038996\r\n  號令修正發布第 2  條條文之附表\r\n6.中華民國九十六年九月十一日行政院環境保護署環署空字第 096006813\r\n  1 號令修正發布第 2  條條文之附表\r\n7.中華民國一百年一月五日行政院環境保護署環署空字第 0990119639 號\r\n  令修正發布第 2、8、9、14  條條文；並自發布日施行\r\n8.中華民國一百零二年四月二十五日行政院環境保護署環署空字第 10200\r\n  32301 號令修正發布第 2  條條文附表一\r\n9.中華民國一百十年六月二十九日行政院環境保護署環署空字第 1101079\r\n  351 號令修正發布第 3、5、8  條條文及第 2  條條文之附表一、附表\r\n  二\r\n10. 中華民國一百十二年六月十四日行政院環境保護署環署空字第 11210\r\n    64054D  號令修正發布第 2、3 條條文\r\n    中華民國一百十二年八月十八日行政院院臺規字第 1121028221 號公\r\n    告第 3  條第 28 款、第 9  條第 2  項、第 10 條、第 12 條、第\r\n    13  條第 2  項所列屬「行政院環境保護署」之權責事項，自一百十\r\n    二年八月二十二日起改由「環境部」管轄","amended":"20230614","effectiveDate":"","effectiveNote":"","sourceName":"全國法規資料庫（法務部）","sourceUrl":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=O0020006","sourceUpdateDate":"2026/9/11 上午 12:00:00","downloadedAt":"2026-09-23T04:42:30.233845Z","snapshotStatus":"complete-official-api-text-partial-attachments","articles":[{"type":"A","no":"第 1 條","text":"本標準依空氣污染防制法第二十條第二項規定訂定之。","headingPath":[]},{"type":"A","no":"第 2 條","text":"本標準適用於新設立或變更、或既存之固定污染源（分別簡稱為新污染源、既存污染源）；其標準如附表。但特定業別、區域或設施另訂有排放標準者，應優先適用該標準。","headingPath":[]},{"type":"A","no":"第 3 條","text":"本標準專用名詞及符號定義如下：\n一、周界：指公私場所所使用或管理之界線。\n二、mg：毫克，相等於零‧零零一公克。\n三、μg：微克，相等於零‧零零一毫克。\n四、K：凱氏絕對溫度，K=273+℃。\n五、Nm³：凱氏溫度二百七十三度及一大氣壓下每立方公尺體積；m³係指每立方公尺體積。\n六、ppm：百萬分之一。\n七、q：任一污染源所屬各獨立排放管道單元，各污染物之「單位時間最高許可排放量」，其單位為公克／秒（g／s）。\n八、a1,a2：各污染物之換算常數。\n九、k：污染物排放之擴散係數，單位為公克／秒‧平方公尺（g／s‧㎡）。\n十、h：排放管道出口之實際高度，單位為公尺（m）。\n十一、△h：排放管道出口之煙流上升高度，單位為公尺（m）。\n十二、he：排放管道出口之有效高度he=h＋△h，單位為公尺（m）。\n十三、Qh：排放管道排氣之熱排放速率，單位為卡／秒（cal／s）。\n十四、Vs：排放管道出口排氣速度，單位為公尺／秒（m／s）。\n十五、ds：排放管道出口處之內徑，單位為公尺（m）。\n十六、ρ：排氣密度，單位為公克／公升（g／l）。\n十七、Cp：排氣之恆壓比熱，單位為卡／公克‧凱氏絕對溫度（cal／g‧K）。\n十八、Ts：排放管道出口之排氣溫度，單位為凱氏絕對溫度（K）。\n十九、T：排放管道出口周圍之大氣溫度，單位為凱氏絕對溫度（K）。\n二十、u ：排放管道出口高度之年平均風速，單位為公尺／秒（m／s）。\nu =u 0（h／10）0.2\n二十一、u 0：地面十公尺高度之平均風速，單位為公尺／秒（m／s）。本標準以年平均風速三‧五公尺／秒（m／s）為計算之參考基準。\n二十二、Q：經校正或不需校正之排氣量，單位為立方公尺／分（Nm³／min）。\n二十三、Qs：依照測定方法測得之排氣量，單位為立方公尺／分（Nm³／min）。\n二十四、C：經校正或不需校正之污染物排放濃度，單位為ppm或mg／Nm³。\n二十五、Cs：依照測定方法測得之污染物排放濃度，單位為ppm或mg／Nm³。\n二十六、On：排氣中含氧百分率之參考基準值，單位為％。\n二十七、Os：排氣中含氧百分率之實測值，單位為％，如超過20％，則以20％計算之。\n二十八、影像判煙：指檢查人員依中央主管機關規定之方法，以數位影像拍攝設備及辨識軟體進行固定污染源排放管道排放口廢氣不透光率之判定。","headingPath":[]},{"type":"A","no":"第 4 條","text":"本標準所稱既存污染源、新污染源之認定，除另有規定外，其原則如左：\n一、八十一年四月十一日以前設立之污染源為既存污染源。\n二、八十一年四月十二日以後設立之污染源為新污染源。\n三、八十一年四月十二日以後因有關設備更新或其他任何理化性或操作方法改變而增加空氣污染物之排放潛量，或排放新增空氣污染物之污染源為新污染源。\n前項第一款、第二款所稱設立，係指固定污染源已完成建造、建造中或已完成工程發包。","headingPath":[]},{"type":"A","no":"第 5 條","text":"周界測定係在公私場所周界外任何地點，能判定污染物由欲測之公私場所排放所為之測定。如在公私場所周界外無法選定測點時（例如堤防、河川、湖泊、窪谷等）得在其廠界內三公尺處選定適當地點測定。公私場所污染源之所有人或代表人對周界之認定如有異議，應於該污染源於第一次被告發之次日起三十日內檢具書面資料向當地主管機關申請周界之再認定。","headingPath":[]},{"type":"A","no":"第 6 條","text":"周界測定之取樣時間，粒狀污染物為一小時；氣體污染物中，硫氧化物取樣時間為一小時，其餘表列之氣體污染物，其採樣時間以三十分鐘為原則。但測定方法如已明訂採樣時間者則依該測定方法為之。","headingPath":[]},{"type":"A","no":"第 7 條","text":"排放標準中未列排放管道排放標準之氣體污染物，應依左列方法計算其排放管道之排放標準：\n一、低排放管道，即h≦6m（公尺）時。\n    q=a2‧b2\n    b ：污染源之排放管道口至該污染源周界之最短水平距離，其單位為m（公尺）。\n二、較高排放管道，即h>6m時。\n（一）b≧5（h-6）\n      q=a2‧b2\n      b ：污染源之排放管道口至該污染源周界線上垂直高度 6m（公尺）處之最短距離，其單位為 m（公尺）。\n（二）b<5（h-6）\n      q=a2‧b2\n      b ：以污染源之排放管道口中心為頂點向下十二度俯角所形成之圓錐與他人建築物（無人留守之倉庫除外）相交時，自該排放管道口中心至該建築物之最短距離，其單位為m（公尺）。\n（三）b<5（h-6）且無前述 2. 之狀況，即污染源距離建築物甚遠或建築物低於6m（公尺），致以污染源之排放管道口中心為頂點向下十二度俯角所形成之圓錐與他人建築物並無相交時。\n      q=a2‧25‧（h-6）^2","headingPath":[]},{"type":"A","no":"第 8 條","text":"排放標準中列有排放管道排放標準之空氣污染物，新污染源之排放管道高度應依下列公式計算之。","headingPath":[]},{"type":"A","no":"第 9 條","text":"新污染源排放之污染物，於附表中列有換算常數值者，應依第七條至第八條所定計算方法分別計算排放管道高度之較高者，為其排放管道高度。\n主管機關於處理對既存污源之陳情案件時，得命該既存污染源改善其排放濃度或準用前項規定變更其排放管道高度。","headingPath":[]},{"type":"A","no":"第 10 條","text":"各公私場所對污染源採多重污染防制措施者，應檢具書面資料報請當地主管機關核准後，始得建築低於第九條所規定高度之排放管道。前項情形，應以實際排放管道高度依第九條或中央主管機關認可之計算公式計算之最高許可排放量為排放標準，其最高許可排放量並不得超過本標準之排放管道排放標準。","headingPath":[]},{"type":"A","no":"第 11 條","text":"各種污染物之濃度計算均以凱氏溫度二七三度及一大氣壓下未經稀釋之乾燥排氣體積為計算基準。燃燒過程排氣中之氧氣百分率如無特別規定則以６％氧氣為參考基準，非燃燒過程則以未經稀釋之乾燥排氣體積為計算基準。但對特定行業標準另有規定者，則採該項規定中之排氣含氧百分率為參考基準。\n污染物濃度Ｃ及排氣量Ｑ校正計算公式如左：\nC=[（21-On）/（21-Os）]*Cs\nQ=[（21-Os）/（21-On）]*Qs","headingPath":[]},{"type":"A","no":"第 12 條","text":"本標準相關之檢測方法及品質管制事項，依中央主管機關之規定。","headingPath":[]},{"type":"A","no":"第 13 條","text":"固定污染源依規定設置空氣污染物連續自動監測設施者，其每日量測值應符合左列規定：\n一、粒狀污染物不透光率之監測數據，其六分鐘紀錄值高於排放標準值之累積時間不得超過四小時。\n二、氣狀污染物之監測數據，其一小時紀錄值高於排放標準值之累積時間不得超過二小時。\n前項固定污染源於建立粒狀污染物排放濃度與粒狀污染物不透光率換算關係報經主管機關核可者，得以其粒狀污染物排放標準值換算之粒狀污染物不透光率值為其不透光率標準值。","headingPath":[]},{"type":"A","no":"第 14 條","text":"本標準自發布日施行。","headingPath":[]}],"attachments":[{"name":"附表.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000343678","localPath":"data/law-assets/O0020006/01.pdf","sha256":"816516ce2f3d3399abae88441aa6f488c886e8736362feed341492a2f49ad4d0","size":520251},{"name":"第 3 條完整條文.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000343679","localPath":"data/law-assets/O0020006/02.pdf","sha256":"cf25dd5f80fa0a9adce75bb5f5b95742f8f0b9198d2da30280ca9e389893b46e","size":82170},{"name":"第 7 條完整條文.PDF","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000046998","localPath":null},{"name":"第 8 條完整條文.ODT","sourceUrl":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000294586","localPath":null}],"attachmentNote":"附件／附表共 4 件；本版已離線收錄 2 件，其餘保留全國法規資料庫官方連結。"}}});})(window);
